            //Earth Dragon Balls
            ModAPIPlus.CreateObject(
                "Bowling Ball",
                "Earth Dragon Balls",
                "Shenron, grant me a wish!",
                "DragonBalls",
                (Instance) =>
                {
                    UnityEngine.GameObject.Destroy(Instance.GetComponent<RandomSpriteBehaviour>());
                    var StarsList = new List<int>();
                    int Stars;

                    foreach (var DB in UnityEngine.GameObject.FindObjectsOfType<EarthDB>())
                    {
                        StarsList.Add(DB.Stars);
                    }

                    if (StarsList.Count >= 7)
                    {
                        ModAPI.Notify("You've already found all the Dragon Balls!");
                        UnityEngine.GameObject.Destroy(Instance.gameObject);
                    }

                    else
                    {
                        Instance.AddComponent<EarthDB>();
                        Stars = UnityEngine.Random.Range(1, 8);

                        while (StarsList.Contains(Stars))
                        {
                            Stars = UnityEngine.Random.Range(1, 8);
                        }

                        Instance.GetComponent<EarthDB>().Stars = Stars;
                        SpriteRenderer spriteRenderer = Instance.GetComponent<SpriteRenderer>();
                        spriteRenderer.sprite = ModAPI.LoadSprite("Assets/Sprites/Items/DB_" + Stars.ToString() + ".png");
                        Instance.transform.localScale = new Vector2(0.5f, 0.5f);
                        Instance.gameObject.name = Stars.ToString() + (Stars > 1 ? " Stars" : " Star") + " Dragon Ball";
                    }

                    foreach (var ObjectColliders in Instance.GetComponents<Collider2D>())
                    {
                        GameObject.Destroy(ObjectColliders);
                    }

                    int TimesActivated = 0;

                    Instance.gameObject.AddComponent<UseEventTrigger>().Action = () =>
                    {
                        TimesActivated += 1;

                        if (TimesActivated == 10000) ModAPI.Notify("Ok, now you are cheating, no way you activated the Dragon Ball 10000 Times... There's more content in the mod to explore you know...");

                        else if (TimesActivated == 1000) ModAPI.Notify("I have no idea why you have activated it so many times, but uh... Congrats! I guess... You've activated it 1000 Times!");

                        else if (TimesActivated == 100) ModAPI.Notify("It's clear that you got here just to find all the different messages, so congrats! You've tried to activate the Dragon Ball 100 Times!");

                        else if (TimesActivated == 10) ModAPI.Notify("It didn't work the first time, why would you try another 10?");

                        else
                        {
                            if (TimesActivated > 10)
                            {
                                int rand = UnityEngine.Random.Range(0, 11);

                                if (rand == 0) ModAPI.Notify("This doesn't work yet buddy. Wait for a future Update!");

                                else if (rand == 1) ModAPI.Notify("The Dragon isn't feeling good today. Try again later.");

                                else if (rand == 2) ModAPI.Notify("Knock Knock. Who's there? Not the Dragon!");

                                else if (rand == 3) ModAPI.Notify("<i>*You try to summon the Dragon, but nothing happens</i>");

                                else if (rand == 4) ModAPI.Notify("It seems that this Dragon Ball has a malfunction! Please contact the Namekians for technical help.");

                                else if (rand == 5) ModAPI.Notify("Well, this didn't work, maybe another try could solve it?");

                                else if (rand == 6) ModAPI.Notify("Balls!");

                                else if (rand == 7) ModAPI.Notify("Weird... it doesn't seem to do anything? Maybe we should wait for the Dragon to be added");

                                else if (rand == 8) ModAPI.Notify("What does a Dragon Ball say to the another when activated? It says 'WHERE THE HECK IS THAT DRAGON??'");

                                else if (rand == 9) ModAPI.Notify("Wait... something is happening... SOMETHING IS HAPPENING- oh wait... nah, it still doesn't work");

                                else if (rand == 10) ModAPI.Notify("I must agree, activating the Dragon Ball over an over again it's the best feature of this mod!");
                            }

                            else
                            {
                                int rand = UnityEngine.Random.Range(0, 9);

                                if (rand == 0) ModAPI.Notify("This doesn't work yet buddy. Wait for a future Update!");

                                else if (rand == 1) ModAPI.Notify("The Dragon isn't feeling good today. Try again later.");

                                else if (rand == 2) ModAPI.Notify("Knock Knock. Who's there? Not the Dragon!");

                                else if (rand == 3) ModAPI.Notify("<i>*You try to summon the Dragon, but nothing happens</i>");

                                else if (rand == 4) ModAPI.Notify("It seems that this Dragon Ball has a malfunction! Please contact the Namekians for technical help.");

                                else if (rand == 5) ModAPI.Notify("Well, this didn't work, maybe another try could solve it?");

                                else if (rand == 6) ModAPI.Notify("Balls!");

                                else if (rand == 7) ModAPI.Notify("Weird... it doesn't seem to do anything? Maybe we should wait for the Dragon to be added");

                                else if (rand == 8) ModAPI.Notify("What does a Dragon Ball say the another when activated? It says 'WHERE THE HECK IS THAT DRAGON??'");
                            }
                        }
                    };

                    Instance.AddComponent<CircleCollider2D>();
                    Instance.GetComponent<PhysicalBehaviour>().colliders = Instance.GetComponentsInChildren<Collider2D>();
                },
                "Items",
                UniqueTag + ItemsTag + "003");


