    public class CharacterTransformations : MonoBehaviour
    {
        public class Transformations
        {
            public class TransformationStats
            {
                public float PowerMultiplier { get; set; }
                public float Size { get; set; }
                public Sprite HairSprite { get; set; }
                public bool UseHairLocalPosition { get; set; }
                public Vector3 HairLocalPosition { get; set; }
                public Sprite HeadSprite { get; set; }
                public float KiDrainRate { get; set; }
                public string AuraID { get; set; }
                public AudioClip BurstSFX { get; set; } = DBPU.Aura_Burst_Basic;
                public Color requiredKiColor { get; set; } = Color.clear;

                public List<Type> SpecialBehaviours { get; set; } = new List<Type>();

                public PhyAccessoryData PhyAccessory { get; set; }
                public List<(SpriteRenderer spriteRenderer, bool Visible)> SituationalAccessories { get; set; }
                public List<Sprite> RequiredSkin { get; set; } = null;
                public string RequiredSkin_Suffix { get; set; } = "";

                public Dictionary<string, Dictionary<string, List<Sprite>>> DamageSkins { get; set; }
                public float SkinDamageAmount { get; set; } = 0;
                public string CutsceneID { get; set; } = null;

                public Sprite Icon { get; set; }
                public Sprite Illustration { get; set; }
                public string Name { get; set; }
                public string Description { get; set; }

                public string ID { get; set; }

                public LimbLayoutData LimbLayout { get; set; }
            }

            public class LimbLayoutData
            {
                public float HeadScale = 1f;
                public Dictionary<string, Vector3> Positions { get; set; }
                public Dictionary<string, Vector2> Anchors { get; set; }
            }

            public class PhyAccessoryData
            {
                public Transform objForAttach { get; set; }
                public Vector2 connectedAnchor { get; set; }
                public string layerName { get; set; }
                public int order { get; set; }
                public Sprite[] sprites { get; set; }
                public float minAngleFirstPiece { get; set; }
                public float maxAngleFirstPiece { get; set; }
                public float minAngle { get; set; }
                public float maxAngle { get; set; }
                public float pieceMass { get; set; }
                public float pieceInertia { get; set; }
                public string Name { get; set; }
                public bool HasCollision { get; set; }
                public bool CollideJustWithGround { get; set; } = true;
            }

            public Dictionary<string, TransformationStats> TransformationData { get; private set; } = new Dictionary<string, TransformationStats>();
            public List<string> FormOrder = new List<string>();

            public CharacterTransformations Owner;

            public void AddTransformation(string key, TransformationStats transformationStats)
            {
                if (!TransformationData.ContainsKey(key))
                {
                    TransformationData[key] = transformationStats;
                    if (!FormOrder.Contains(key))
                        FormOrder.Add(key);
                    if (Owner != null) Owner.NotifyFormRegistered(key, transformationStats);
                }
            }

            public List<KeyValuePair<string, TransformationStats>> GetOrderedEntries()
            {
                var result = new List<KeyValuePair<string, TransformationStats>>();
                var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                if (FormOrder != null)
                {
                    for (int i = 0; i < FormOrder.Count; i++)
                    {
                        string id = FormOrder[i];
                        if (string.IsNullOrEmpty(id) || !seen.Add(id)) continue;
                        if (!TransformationData.TryGetValue(id, out var stats) || stats == null) continue;
                        result.Add(new KeyValuePair<string, TransformationStats>(id, stats));
                    }
                }
                foreach (var kvp in TransformationData)
                {
                    if (kvp.Value == null || string.IsNullOrEmpty(kvp.Key) || !seen.Add(kvp.Key)) continue;
                    result.Add(kvp);
                    if (FormOrder != null && !FormOrder.Contains(kvp.Key))
                        FormOrder.Add(kvp.Key);
                }
                return result;
            }

            public bool MoveForm(string formId, int direction)
            {
                if (string.IsNullOrEmpty(formId) || FormOrder == null || direction == 0) return false;
                GetOrderedEntries();
                int index = FormOrder.FindIndex(id => string.Equals(id, formId, StringComparison.OrdinalIgnoreCase));
                if (index < 0) return false;
                int target = index + (direction < 0 ? -1 : 1);
                if (target < 0 || target >= FormOrder.Count) return false;
                string temp = FormOrder[target];
                FormOrder[target] = FormOrder[index];
                FormOrder[index] = temp;
                return true;
            }

            public void ApplyFormOrder(IList<string> order)
            {
                if (FormOrder == null) FormOrder = new List<string>();
                FormOrder.Clear();
                var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                if (order != null)
                {
                    for (int i = 0; i < order.Count; i++)
                    {
                        string id = order[i];
                        if (string.IsNullOrEmpty(id) || !seen.Add(id)) continue;
                        if (TransformationData != null && TransformationData.ContainsKey(id))
                            FormOrder.Add(id);
                    }
                }
                if (TransformationData == null) return;
                foreach (var kvp in TransformationData)
                {
                    if (kvp.Value == null || string.IsNullOrEmpty(kvp.Key) || !seen.Add(kvp.Key)) continue;
                    FormOrder.Add(kvp.Key);
                }
            }
        }

        public Transformations transformations = new Transformations();

        void Awake()
        {
            transformations.Owner = this;
        }

        public void NotifyFormRegistered(string key, Transformations.TransformationStats stats)
        {
            var identity = transform.GetComponent<DbpuCharacterIdentity>();
            if (identity == null || string.IsNullOrEmpty(identity.CharacterId) || stats == null) return;
            CharacterPowerCatalog.RegisterForm(identity.CharacterId, identity.DisplayName, key, stats);
        }

        public float GetEffectivePower(string formId, float defaultPower)
        {
            var identity = transform.GetComponent<DbpuCharacterIdentity>();
            string characterId = identity != null ? identity.CharacterId : null;
            return CharacterPowerCatalog.GetEffectivePower(characterId, formId, defaultPower);
        }

        public float GetEffectivePower(Transformations.TransformationStats stats)
        {
            if (stats == null) return 1f;
            return GetEffectivePower(stats.ID, stats.PowerMultiplier);
        }

        public void AddTransformation(string key, Transformations.TransformationStats transformationStats)
        {
            transformations.AddTransformation(key, transformationStats);
        }

        public void AddTransformationContextButtons(PersonBehaviour person, GameObject referenceLimb)
        {
            var pb = referenceLimb.GetComponent<PhysicalBehaviour>();

            if (pb == null) return;

            foreach (var kvp in transformations.GetOrderedEntries())
            {
                string formName = kvp.Key;
                pb.ContextMenuOptions.Buttons.Add(new ContextMenuButton(formName, formName, formName, new UnityEngine.Events.UnityAction[1]
                {
                () =>
                    {
                        ApplyTransformation(person, formName);
                        }
                    }));
            }
        }

        public void ApplyTransformation(PersonBehaviour person, string transformationKey, bool IsOnKiDepleted = false)
        {
            var menu = person != null && person.Limbs != null && person.Limbs.Length > 0 && person.Limbs[0] != null
                ? person.Limbs[0].GetComponent<TransformationContextMenu>() : null;
            var ki = person != null ? person.GetComponent<KiSystem>() : null;
            string previous = ki != null && !string.IsNullOrEmpty(ki.CurrentForm) ? ki.CurrentForm : (menu != null ? menu.Form : null);
            var transition = person != null ? person.GetComponent<KiFormTransition>() : null;
            if (IsOnKiDepleted && transition != null) transition.Cancel();
            if (!IsOnKiDepleted && KiFormTransition.Begin(this, person, previous, transformationKey,
                () => ApplyTransformationImmediate(person, transformationKey, false, previous))) return;
            if (transition != null && transition.Busy && !transition.Committing) transition.Cancel();
            ApplyTransformationImmediate(person, transformationKey, IsOnKiDepleted, previous);
        }

        private void ApplyTransformationImmediate(PersonBehaviour person, string transformationKey, bool IsOnKiDepleted, string previousOverride)
        {
            if (!transformations.TransformationData.ContainsKey(transformationKey))
            {
                Debug.LogWarning($"transformation '{transformationKey}' not found.");
                return;
            }

            var t = transformations.TransformationData[transformationKey];

            var personBehaviour = gameObject.GetComponent<PersonBehaviour>();
            TransformationContextMenu transformationMenu = null;
            if (personBehaviour != null && personBehaviour.Limbs != null && personBehaviour.Limbs.Length > 0 && personBehaviour.Limbs[0] != null)
                transformationMenu = personBehaviour.Limbs[0].gameObject.GetComponent<TransformationContextMenu>();
            if (transformationMenu == null)
            {
                var headMenuTf = person != null ? person.transform.root.Find("Head") : transform.Find("Head");
                if (headMenuTf != null)
                    transformationMenu = headMenuTf.GetComponent<TransformationContextMenu>();
            }

            string previousFormKey = !string.IsNullOrEmpty(previousOverride) ? previousOverride :
                (transformationMenu != null && !string.IsNullOrEmpty(transformationMenu.Form) ? transformationMenu.Form : transformationKey);
            if (!transformations.TransformationData.ContainsKey(previousFormKey))
                previousFormKey = transformationKey;

            var t2 = transformations.TransformationData[previousFormKey];

            var identity = person.transform.root.GetComponent<DbpuCharacterIdentity>();
            string characterId = identity != null ? identity.CharacterId : null;

            float newPower = CharacterPowerCatalog.GetEffectivePower(characterId, t.ID, t.PowerMultiplier);
            float ratio = newPower;

            float ratio2 = CharacterPowerCatalog.GetEffectivePower(characterId, t2.ID, t2.PowerMultiplier);

            var kiSystem = person.GetComponent<KiSystem>();
            if (kiSystem != null)
            {
                kiSystem.EnsureReadyForTransforms();
                kiSystem.ResetValues();
            }

            var root = person.transform.root.gameObject;
            if (!root.GetComponent<MultipliersAndStuffs>()) root.AddComponent<MultipliersAndStuffs>();
            root.GetComponent<MultipliersAndStuffs>().FormMultiplier = newPower;

            if (IsOnKiDepleted == true && transformationMenu != null)
            {
                transformationMenu.PreviousMultiplier = newPower;
                transformationMenu.Form = t.ID;
                transformationMenu.CurrentAuraID = t.AuraID;

                transformationMenu.FormSelected = transformationMenu.OriginalFormSelected;
                transformationMenu.PositionSelectedFrame = transformationMenu.OriginalSelectedFrame;

                if (gameObject.GetComponent<AuraHandler>()) gameObject.GetComponent<AuraHandler>().DestroyAura();
                if (gameObject.GetComponent<AuraHandler>()) gameObject.GetComponent<AuraHandler>().AuraActive = false;
            }

            foreach (var limb in person.Limbs)
            {
                if (limb == null) continue;
                if (IsOnKiDepleted == true)
                {
                    if (!GogitoVitality.Scale(limb, ratio / ratio2))
                    {
                        if (!float.IsInfinity(limb.InitialHealth * (ratio / ratio2))) limb.InitialHealth *= ratio / ratio2;
                        if (!float.IsInfinity(limb.Health * (ratio / ratio2))) limb.Health *= ratio / ratio2;
                    }
                    if (!float.IsInfinity(limb.BreakingThreshold * ratio)) limb.BreakingThreshold *= ratio;
                }
            }

            var head = person.transform.root.Find("Head");
            if (head == null) return;

            var humanController = head.gameObject.GetComponent<HumanController>();
            bool sameForm = string.Equals(previousFormKey, transformationKey, StringComparison.Ordinal);
            bool powerChanged = Mathf.Abs(newPower - ratio2) > 0.0001f;
            if (humanController != null && (!sameForm || powerChanged || IsOnKiDepleted))
                humanController.StartChangeWeight();

            if (head.transform.root.gameObject.GetComponent<AuraHandler>())
            {
                head.transform.root.gameObject.GetComponent<AuraHandler>().CurrentAuraID = t.AuraID;
            }

            if (transformationMenu != null)
                transformationMenu.Form = t.ID;

            if (head != null)
            {
                var headMenu = head.GetComponent<TransformationContextMenu>();
                if (headMenu != null && headMenu != transformationMenu)
                {
                    headMenu.Form = t.ID;
                    headMenu.CurrentAuraID = t.AuraID;
                }
            }

            if (!sameForm || IsOnKiDepleted)
            {
                if (head.gameObject.GetComponent<SkinContextMenu>())
                {
                    var skinsMenu = head.gameObject.GetComponent<SkinContextMenu>();
                    CharacterSkins CSkins = gameObject.GetComponent<CharacterSkins>();

                    if (CSkins != null && skinsMenu.CurrentSkin != null && CSkins.skins.SkinData.ContainsKey(skinsMenu.CurrentSkin))
                    {
                        if (t.RequiredSkin_Suffix != "") skinsMenu.Skin_Suffix = t.RequiredSkin_Suffix;
                        else skinsMenu.Skin_Suffix = "";

                        int CurrentDamage = skinsMenu.CurrentDamage;

                        int SkinDamageVariantCount = CSkins.GetSkinDamageVariantCount(skinsMenu.CurrentSkin, skinsMenu.Skin_Suffix);

                        if (SkinDamageVariantCount > 0)
                        {
                            if (CurrentDamage > SkinDamageVariantCount - 1)
                            {
                                CurrentDamage = SkinDamageVariantCount - 1;
                            }

                            if (t.SkinDamageAmount > 0 && skinsMenu.SkinDamage == true)
                            {
                                int DamageAmount = (int)UnityEngine.Random.Range(0, t.SkinDamageAmount + 1);

                                if (CurrentDamage + DamageAmount < SkinDamageVariantCount) CurrentDamage += DamageAmount;
                                else CurrentDamage = SkinDamageVariantCount - 1;
                            }
                        }

                        skinsMenu.CurrentDamage = CurrentDamage;

                        CSkins.ApplySkin(person, skinsMenu.CurrentSkin, skinsMenu.Skin_Suffix, CurrentDamage);
                    }

                    else if (t.RequiredSkin != null)
                    {
                        if (skinsMenu != null) skinsMenu.Skin_Suffix = "";
                        person.ChangeSkin(t.RequiredSkin);
                    }
                }

                else if (t.RequiredSkin != null)
                {
                    person.ChangeSkin(t.RequiredSkin);
                }
            }

            if (t.HeadSprite != null) head.gameObject.ChangeLimbSprite(t.HeadSprite, LimbsStorage.FHead, LimbsStorage.BHead, LimbsStorage.DHead);

            var eyeGlow = head.gameObject.GetComponent<TransformationEyeGlow>();
            if (eyeGlow == null) eyeGlow = head.gameObject.AddComponent<TransformationEyeGlow>();
            eyeGlow.SetForm(t.ID);

            if (t.Size > 0f)
            {
                var giantForm = person.GetComponent<PiccoloGiantForm>();
                if (giantForm != null) giantForm.SyncAfterTransformation(t.Size);
                else
                {
                    float currentMeters = Mathf.Abs(person.transform.localScale.y) * 1.68f;
                    if (Mathf.Abs(currentMeters - t.Size) > 0.02f)
                    {
                        GameObject sizeLimb = null;
                        if (person.Limbs != null && person.Limbs.Length > 2 && person.Limbs[2] != null)
                            sizeLimb = person.Limbs[2].gameObject;
                        else if (person.Limbs != null)
                        {
                            for (int i = 0; i < person.Limbs.Length; i++)
                            {
                                if (person.Limbs[i] != null && person.Limbs[i].name.IndexOf("Middle", StringComparison.OrdinalIgnoreCase) >= 0)
                                {
                                    sizeLimb = person.Limbs[i].gameObject;
                                    break;
                                }
                            }
                        }
                        if (sizeLimb != null)
                        {
                            person.transform.root.transform.SetHeight(person, sizeLimb, t.Size);
                            person.ForceAllLimbsClearViaExit();
                        }
                    }
                }
            }

            var limbLayoutHandler = person.GetComponent<PersonLimbLayout>();
            if (t.LimbLayout != null)
            {
                if (limbLayoutHandler == null) limbLayoutHandler = person.gameObject.AddComponent<PersonLimbLayout>();
                limbLayoutHandler.Apply(t.LimbLayout);
            }
            else if (limbLayoutHandler != null && limbLayoutHandler.CustomLayoutActive)
            {
                limbLayoutHandler.Restore();
            }

            if (t.PhyAccessory != null && t.PhyAccessory.objForAttach != null)
            {
                foreach (Transform child in t.PhyAccessory.objForAttach)
                {
                    if (child != null && child.name == t.PhyAccessory.Name)
                    {
                        GameObject.Destroy(child.gameObject);
                    }
                }

                PHY.Cro.CreatePhysicalCloth(t.PhyAccessory.objForAttach, t.PhyAccessory.connectedAnchor, t.PhyAccessory.layerName, t.PhyAccessory.order, t.PhyAccessory.sprites, t.PhyAccessory.minAngleFirstPiece, t.PhyAccessory.maxAngleFirstPiece, t.PhyAccessory.minAngle, t.PhyAccessory.maxAngle, t.PhyAccessory.pieceMass, t.PhyAccessory.pieceInertia, t.PhyAccessory.Name, t.PhyAccessory.HasCollision, t.PhyAccessory.CollideJustWithGround);
            }

            if (t.SituationalAccessories != null)
            {
                foreach (var Accessory in t.SituationalAccessories)
                {
                    if (Accessory.spriteRenderer == null) continue;
                    if (Accessory.Visible == false) Accessory.spriteRenderer.color = Color.clear;

                    else Accessory.spriteRenderer.color = Color.white;
                }
            }

            if (head != null && t.HairSprite != null)
            {
                var hairObject = head.Find("Hair");
                Transform hairTransform;
                var headSr = head.gameObject.GetComponent<SpriteRenderer>();

                if (hairObject == null)
                {
                    var newHairObject = new GameObject("Hair");
                    newHairObject.transform.SetParent(head);
                    newHairObject.transform.localScale = Vector3.one;

                    var hairSprite = newHairObject.AddComponent<SpriteRenderer>();
                    hairSprite.sprite = t.HairSprite;
                    if (headSr != null)
                    {
                        hairSprite.sortingLayerName = headSr.sortingLayerName;
                        hairSprite.sortingOrder = headSr.sortingOrder + 1;
                    }
                    hairTransform = newHairObject.transform;
                }

                else
                {
                    var hairSprite = hairObject.GetComponent<SpriteRenderer>();

                    if (hairSprite != null)
                    {
                        hairSprite.sprite = t.HairSprite;
                    }

                    hairTransform = hairObject;
                }

                hairTransform.localPosition = t.UseHairLocalPosition ? t.HairLocalPosition : Vector3.zero;

                var hairGlow = hairTransform.GetComponent<TransformationHairGlow>();
                if (hairGlow == null) hairGlow = hairTransform.gameObject.AddComponent<TransformationHairGlow>();
                hairGlow.SetForm(t.ID);
            }

            else if (head != null)
            {
                var hairObject = head.Find("Hair");
                if (hairObject != null)
                {
                    var hairGlow = hairObject.GetComponent<TransformationHairGlow>();
                    if (hairGlow == null) hairGlow = hairObject.gameObject.AddComponent<TransformationHairGlow>();
                    hairGlow.SetForm(t.ID);
                }
            }

            if (!string.IsNullOrEmpty(characterId))
            {
                var formDto = CustomTransformationCatalog.GetForm(characterId, transformationKey);
                if (formDto != null)
                {
                    if (CustomTransformationCatalog.BakeVirtualSpritePaths(formDto, root))
                        CustomTransformationCatalog.UpsertForm(characterId, null, formDto);
                    CustomTransformationCatalog.ApplyLimbSpritePaths(person, formDto);
                    if (!string.IsNullOrEmpty(formDto.HairSpritePath))
                    {
                        Sprite hairSrc = CustomTransformationCatalog.ResolveSpriteReference(formDto.HairSpritePath, root, true);
                        if (hairSrc != null && head != null)
                        {
                            TmHairApply.ApplyHair(
                                head,
                                hairSrc,
                                new Color(formDto.HairColorR, formDto.HairColorG, formDto.HairColorB, 1f),
                                new Vector3(formDto.HairLocalX, formDto.HairLocalY, formDto.HairLocalZ),
                                formDto.UseHairLocalPosition);
                        }
                    }
                    var formTint = root.GetComponent<CustomFormHairTintBehaviour>();
                    if (formTint == null) formTint = root.AddComponent<CustomFormHairTintBehaviour>();
                    formTint.CharacterId = characterId;
                    formTint.NotifyFormApplied(transformationKey);
                }
            }

            if (kiSystem != null)
            {
                kiSystem.ApplyTransformation(transformationKey);
                if (t.requiredKiColor != Color.clear) kiSystem.requiredColor = t.requiredKiColor;
                else kiSystem.requiredColor = Color.clear;
            }

            if (transformationKey != previousFormKey)
            {
                if (t2.SpecialBehaviours != null)
                {
                    foreach (Type oldType in t2.SpecialBehaviours)
                    {
                        if (oldType == null || (t.SpecialBehaviours != null && t.SpecialBehaviours.Contains(oldType))) continue;

                        var existing = root.GetComponent(oldType);
                        if (existing) GameObject.Destroy(existing);
                    }
                }

                if (t.SpecialBehaviours != null)
                {
                    foreach (Type newType in t.SpecialBehaviours)
                    {
                        if (newType == null || root.GetComponent(newType)) continue;

                        root.AddComponent(newType);
                    }
                }
            }

            bool targetExponential = t.SpecialBehaviours != null && t.SpecialBehaviours.Contains(typeof(ExponentialGrowth));
            var exponentialGrowth = root.GetComponent<ExponentialGrowth>();
            if (targetExponential)
            {
                if (exponentialGrowth == null) exponentialGrowth = root.AddComponent<ExponentialGrowth>();
                else exponentialGrowth.Kickstart();
            }
            else if (exponentialGrowth != null)
            {
                GameObject.Destroy(exponentialGrowth);
            }

            Debug.Log($"{person.name} transformed into {transformationKey}");
        }

        void CopyValues(Component origin, Component target)
        {
            System.Type type = origin.GetType();
            BindingFlags flags = BindingFlags.Public | BindingFlags.Instance;

            foreach (PropertyInfo prop in type.GetProperties(flags))
            {
                if (prop.CanWrite && prop.CanRead && prop.Name != "name")
                {
                    try
                    {
                        prop.SetValue(target, prop.GetValue(origin));
                    }

                    catch { }
                }
            }

            foreach (FieldInfo field in type.GetFields(flags))
            {
                try
                {
                    field.SetValue(target, field.GetValue(origin));
                }

                catch { }
            }
        }
    }

    public class CharacterPowers : MonoBehaviour
    {
        public static class PowerGroups
        {
            public const string KiBlast = "KiBlast";
            public const string Beam = "Beam";
            public const string Solar = "Solar";
            public const string Shield = "Shield";
            public const string FinalExplosion = "FinalExplosion";
            public const string Hellzone = "Hellzone";
            public const string Ball = "Ball";
            public const string GogetaSpecial = "GogetaSpecial";
            public const string StraightBeam = "StraightBeam";
            public const string Growth = "Growth";
            public const string DisasterRay = "DisasterRay";
            public const string EyeLaser = "EyeLaser";
            public const string BeerusSpecial = "BeerusSpecial";
        }

        public class PowerStats
        {
            public string ID { get; set; }
            public string Name { get; set; }
            public string Description { get; set; }
            public Sprite Icon { get; set; }
            public Sprite Illustration { get; set; }
            public string PowerType { get; set; }
            public bool Active { get; set; }
            public Func<bool> IsActive { get; set; }
            public Func<string> GetStatusText { get; set; }
            public Action Apply { get; set; }
            public Action Disable { get; set; }
            public Func<bool> GetModeBarrage { get; set; }
            public Action<bool> SetModeBarrage { get; set; }
            public bool Passive { get; set; }
        }

        public Dictionary<string, PowerStats> PowerData = new Dictionary<string, PowerStats>();
        public List<string> PowerOrder = new List<string>();

        public void AddPower(PowerStats stats)
        {
            if (PowerData.ContainsKey(stats.ID)) return;
            PowerData[stats.ID] = stats;
            PowerOrder.Add(stats.ID);
        }

        public void InsertPowerAtStart(PowerStats stats)
        {
            if (PowerData.ContainsKey(stats.ID)) return;
            PowerData[stats.ID] = stats;
            PowerOrder.Insert(0, stats.ID);
        }

        public void MovePowerBlockToStart(IReadOnlyList<string> idsInOrder)
        {
            if (idsInOrder == null || idsInOrder.Count == 0) return;
            var present = new List<string>();
            for (int i = 0; i < idsInOrder.Count; i++)
            {
                string id = idsInOrder[i];
                if (PowerData.ContainsKey(id)) present.Add(id);
            }
            if (present.Count == 0) return;
            for (int i = 0; i < idsInOrder.Count; i++)
                PowerOrder.Remove(idsInOrder[i]);
            PowerOrder.InsertRange(0, present);
        }

        public void HarvestPowerStates()
        {
            foreach (var id in PowerOrder)
            {
                if (!PowerData.ContainsKey(id)) continue;
                var stats = PowerData[id];
                if (stats.Passive) continue;
                if (stats.IsActive != null) stats.Active = stats.IsActive();
            }
        }

        public void ApplyPower(string id)
        {
            if (!PowerData.ContainsKey(id)) return;
            var power = PowerData[id];
            if (power.Passive) return;

            HarvestPowerStates();
            bool wasActive = power.Active;
            power.Apply?.Invoke();
            HarvestPowerStates();

            if (power.Active && !wasActive && !string.IsNullOrEmpty(power.PowerType))
            {
                foreach (var otherId in PowerOrder)
                {
                    if (otherId == id) continue;
                    if (!PowerData.TryGetValue(otherId, out var other)) continue;
                    if (other.Passive || other.PowerType != power.PowerType) continue;
                    if (!other.Active) continue;
                    other.Disable?.Invoke();
                }
                HarvestPowerStates();
            }
            KiHandLoadout.NotifyPowerApplied(this, id);
        }

        public List<PowerStats> GetOrderedPowers()
        {
            var list = new List<PowerStats>();
            foreach (var id in PowerOrder)
                if (PowerData.ContainsKey(id)) list.Add(PowerData[id]);
            return list;
        }

        public string GetStatus(PowerStats stats)
        {
            if (stats.Passive) return "Always active";
            if (stats.GetStatusText != null) return stats.GetStatusText();
            return stats.Active ? "Enabled" : "Disabled";
        }
    }

    public static class PowerSetup
    {
        public class CombatRefs
        {
            public BlastBehaviour Blast;
            public BeamBehaviour Beam;
            public SolarFlare Solar;
            public KiShield Shield;
            public FinalExplosion FinalExplosion;
            public HellzoneGranade Hellzone;
            public BallBehaviour Ball;
            public StardustFall StardustFall;
            public MeteorExplosion MeteorExplosion;
            public GodPunisher GodPunisher;
            public StardustBreaker StardustBreaker;
            public StraightBeamBehaviour StraightBeam;
            public GodsWrathBehaviour GodsWrath;
            public CataclysmicOrbBehaviour CataclysmicOrb;

            public static CombatRefs From(GameObject instance)
            {
                return new CombatRefs
                {
                    Blast = instance.GetComponent<BlastBehaviour>(),
                    Beam = instance.GetComponent<BeamBehaviour>(),
                    Solar = instance.GetComponent<SolarFlare>(),
                    Shield = instance.GetComponent<KiShield>(),
                    FinalExplosion = instance.GetComponent<FinalExplosion>(),
                    Hellzone = instance.GetComponent<HellzoneGranade>(),
                    Ball = instance.GetComponent<BallBehaviour>(),
                    StardustFall = instance.GetComponent<StardustFall>(),
                    MeteorExplosion = instance.GetComponent<MeteorExplosion>(),
                    GodPunisher = instance.GetComponent<GodPunisher>(),
                    StardustBreaker = instance.GetComponent<StardustBreaker>(),
                    StraightBeam = instance.GetComponent<StraightBeamBehaviour>(),
                    GodsWrath = instance.GetComponent<GodsWrathBehaviour>(),
                    CataclysmicOrb = instance.GetComponent<CataclysmicOrbBehaviour>()
                };
            }

            public bool VegetaBlocked => (FinalExplosion != null && FinalExplosion.stillActive) || (Beam != null && Beam.StillActive);
            public bool BeamStillBlocked => Beam != null && Beam.StillActive;
        }

        public class PowerBuilder
        {
            public GameObject Head;
            public PersonBehaviour Person;
            public GameObject Instance;
            public CharacterPowers Powers;

            public CombatRefs Refs => CombatRefs.From(Instance);

            public void Grant(string powerId, PowerCatalog.Overrides overrides = null) =>
                PowerCatalog.Add(Powers, Instance, Person, powerId, overrides);

            public void GrantMany(PowerCatalog.Overrides shared, params string[] powerIds) =>
                PowerCatalog.AddMany(Powers, Instance, Person, shared, powerIds);

            public void GrantMany(params string[] powerIds) =>
                PowerCatalog.AddMany(Powers, Instance, Person, powerIds);

            public void Finish() => FinishPowers(Head, Person, Instance, Powers);
        }

        public static PowerBuilder BeginPowers(GameObject head, PersonBehaviour person, GameObject instance)
        {
            if (instance.GetComponent<KiSystem>() == null) instance.AddComponent<KiSystem>();
            if (instance.GetComponent<MultipliersAndStuffs>() == null) instance.AddComponent<MultipliersAndStuffs>();

            var characterPowers = instance.GetComponent<CharacterPowers>();
            if (characterPowers == null) characterPowers = instance.AddComponent<CharacterPowers>();

            var powerCM = head.GetComponent<PowerContextMenu>();
            if (powerCM == null) powerCM = head.AddComponent<PowerContextMenu>();
            powerCM.PowersData = characterPowers;
            powerCM.person = person;

            return new PowerBuilder
            {
                Head = head,
                Person = person,
                Instance = instance,
                Powers = characterPowers
            };
        }

        public static void FinishPowers(GameObject head, PersonBehaviour person, GameObject instance, CharacterPowers powers)
        {
            EnsureKickPowerComponents(person);
            RegisterUniversalPhysicalPowers(powers, person);
            ApplyAutoEnablePunchKick(person);
            powers.HarvestPowerStates();

            var beam = instance.GetComponent<BeamBehaviour>();
            if (beam != null) ScheduleBeamTriggers(beam);
        }

        public static void CompletePhysicalPowers(GameObject instance, PersonBehaviour person)
        {
            var powers = instance.GetComponent<CharacterPowers>();
            if (powers == null || person == null) return;
            EnsureKickPowerComponents(person);
            RegisterUniversalPhysicalPowers(powers, person);
            ApplyAutoEnablePunchKick(person);
            powers.HarvestPowerStates();
        }

        public static void ApplyAutoEnablePunchKick(PersonBehaviour person)
        {
            if (!DBPU.AutoEnablePunchKick || person == null) return;
            EnsurePunchPowerComponents(person);
            EnsureKickPowerComponents(person);
            SetAllPunchPowerActive(person, true);
            SetAllKickPowerActive(person, true);
        }

        public static void ApplyAutoEnablePunchKickToAllAlive()
        {
            if (!DBPU.AutoEnablePunchKick) return;
            foreach (var person in UnityEngine.Object.FindObjectsOfType<PersonBehaviour>())
            {
                if (person == null || !person.IsAlive()) continue;
                if (person.transform.root.GetComponent<DbpuCharacterIdentity>() == null
                    && person.GetComponentInChildren<PunchPower>(true) == null
                    && person.GetComponentInChildren<KickPower>(true) == null)
                    continue;
                ApplyAutoEnablePunchKick(person);
                var powers = person.GetComponent<CharacterPowers>();
                if (powers == null) powers = person.transform.root.GetComponent<CharacterPowers>();
                if (powers != null)
                {
                    RegisterUniversalPhysicalPowers(powers, person);
                    powers.HarvestPowerStates();
                }
            }
        }

        public static void WireCombatMenu(GameObject head, PersonBehaviour person, GameObject instance, Action<CharacterPowers, GameObject> register)
        {
            var pw = BeginPowers(head, person, instance);
            register(pw.Powers, instance);
            pw.Finish();
        }

        public static void WireCharacterAtSpawn(GameObject head, PersonBehaviour person, GameObject instance, Action<CharacterPowers, GameObject> register) =>
            WireCombatMenu(head, person, instance, register);

        public static void WireCharacterAtSpawn(GameObject head, PersonBehaviour person, GameObject instance, Action<PowerBuilder> register)
        {
            var pw = BeginPowers(head, person, instance);
            register(pw);
            pw.Finish();
        }

        static void ToggleBeamPower(BeamBehaviour beam, BlastBehaviour blast, SolarFlare solar, KiShield shield, string effectId)
        {
            if (beam.StillActive) return;

            if (beam.Active && beam.EffectID == effectId)
            {
                beam.Active = false;
                beam.CancelBeamState();
                return;
            }

            beam.CancelBeamState();
            beam.EffectID = effectId;
            beam.Active = true;
            blast.Active = false;
            if (solar != null) solar.Active = false;
            if (shield != null) shield.Active = false;
        }

        static void ToggleLegacyBeam(CombatRefs r, string effectId, Func<bool> blockWhen, Action onBeamOn)
        {
            if (blockWhen != null && blockWhen()) return;
            var beam = r.Beam;
            if (!beam.Active)
            {
                beam.EffectID = effectId;
                beam.Active = true;
            }
            else if (beam.EffectID == effectId)
                beam.Active = !beam.Active;
            else
                beam.EffectID = effectId;

            if (beam.Active)
                onBeamOn?.Invoke();
        }

        static bool HasPunchPower(PersonBehaviour person) =>
            person != null && person.GetComponentInChildren<PunchPower>(true) != null;

        static bool HasKickPower(PersonBehaviour person) =>
            person != null && person.GetComponentInChildren<KickPower>(true) != null;

        public static void EnsurePunchPowerComponents(PersonBehaviour person)
        {
            if (person == null) return;
            if (person.Limbs.Length > 13)
            {
                AddPunchPowerIfMissing(person.Limbs[11]);
                AddPunchPowerIfMissing(person.Limbs[13]);
                return;
            }
            if (person.Limbs.Length > 12)
            {
                AddPunchPowerIfMissing(person.Limbs[10]);
                AddPunchPowerIfMissing(person.Limbs[12]);
                return;
            }
            foreach (var limb in person.Limbs)
            {
                if (!limb.name.Contains("LowerArm")) continue;
                AddPunchPowerIfMissing(limb);
            }
        }

        static void AddPunchPowerIfMissing(LimbBehaviour limb)
        {
            if (limb == null || limb.GetComponent<PunchPower>() != null) return;
            limb.gameObject.AddComponent<PunchPower>();
        }

        public static void EnsureKickPowerComponents(PersonBehaviour person)
        {
            if (person == null) return;
            foreach (var limb in person.Limbs)
            {
                if (!IsKickLimb(limb.name)) continue;
                if (limb.GetComponent<KickPower>() == null)
                    limb.gameObject.AddComponent<KickPower>();
            }
        }

        static void SetAllPunchPowerActive(PersonBehaviour person, bool active)
        {
            if (person == null) return;
            foreach (var limb in person.Limbs)
            {
                var pp = limb.GetComponent<PunchPower>();
                if (pp != null) pp.Active = active;
            }
        }

        static void SetAllKickPowerActive(PersonBehaviour person, bool active)
        {
            if (person == null) return;
            foreach (var limb in person.Limbs)
            {
                if (!IsKickLimb(limb.name)) continue;
                var kp = limb.GetComponent<KickPower>();
                if (kp != null) kp.Active = active;
            }
        }

        static bool AnyPunchPowerActive(PersonBehaviour person)
        {
            if (person == null) return false;
            foreach (var limb in person.Limbs)
            {
                var pp = limb.GetComponent<PunchPower>();
                if (pp != null && pp.Active) return true;
            }
            return false;
        }

        static bool AnyKickPowerActive(PersonBehaviour person)
        {
            if (person == null) return false;
            foreach (var limb in person.Limbs)
            {
                if (!IsKickLimb(limb.name)) continue;
                var kp = limb.GetComponent<KickPower>();
                if (kp != null && kp.Active) return true;
            }
            return false;
        }

        public static void AddPunchPowerMenu(CharacterPowers powers, PersonBehaviour person, string name = null, string desc = null, Sprite icon = null)
        {
            icon = icon ?? DBPU.Icon_PunchPower;
            if (HasPowerEntry(powers, "PunchPower")) return;
            powers.InsertPowerAtStart(new CharacterPowers.PowerStats
            {
                ID = "PunchPower",
                Name = name ?? "Punch Power",
                Description = desc ?? "Melee enhancement on arm contact.",
                Icon = icon,
                Illustration = icon,
                IsActive = () => AnyPunchPowerActive(person),
                Disable = () => SetAllPunchPowerActive(person, false),
                Apply = () => SetAllPunchPowerActive(person, !AnyPunchPowerActive(person))
            });
        }

        public static void AddKickPowerMenu(CharacterPowers powers, PersonBehaviour person, string name = null, string desc = null, Sprite icon = null)
        {
            icon = icon ?? DBPU.Icon_KickPower;
            if (HasPowerEntry(powers, "KickPower")) return;
            powers.InsertPowerAtStart(new CharacterPowers.PowerStats
            {
                ID = "KickPower",
                Name = name ?? "Kick Power",
                Description = desc ?? "Melee enhancement on leg contact.",
                Icon = icon,
                Illustration = icon,
                IsActive = () => AnyKickPowerActive(person),
                Disable = () => SetAllKickPowerActive(person, false),
                Apply = () => SetAllKickPowerActive(person, !AnyKickPowerActive(person))
            });
        }

        public static void EnsureBarrageComponent(PersonBehaviour person)
        {
            if (person == null || person.GetComponentInChildren<Barrage>(true) != null) return;

            LimbBehaviour host = null;
            if (person.Limbs.Length > 1)
                host = person.Limbs[1];
            if (host == null)
            {
                foreach (var limb in person.Limbs)
                {
                    if (limb.name.Contains("UpperBody"))
                    {
                        host = limb;
                        break;
                    }
                }
            }
            if (host == null)
            {
                foreach (var limb in person.Limbs)
                {
                    if (limb.name.Contains("MiddleBody") || limb.name.Contains("UpperBody"))
                    {
                        host = limb;
                        break;
                    }
                }
            }
            if (host != null)
                host.gameObject.AddComponent<Barrage>();
        }

        static bool HasBarrage(PersonBehaviour person) =>
            person != null && person.GetComponentInChildren<Barrage>(true) != null;

        static bool HasFlight(PersonBehaviour person) =>
            person != null && person.GetComponentInChildren<Flight>(true) != null;

        public static bool IsKickLimb(string limbName) =>
            limbName != null && (limbName.Contains("LowerLeg") || limbName.Contains("Foot"));

        public static void AddBarrageMenu(CharacterPowers powers, PersonBehaviour person, string name = null, string desc = null, Sprite icon = null)
        {
            icon = icon ?? DBPU.Icon_Barrage;
            if (HasPowerEntry(powers, "Barrage")) return;
            powers.InsertPowerAtStart(new CharacterPowers.PowerStats
            {
                ID = "Barrage",
                Name = name ?? "Barrage",
                Description = desc ?? "Rapid projectile barrage (hold H).",
                Icon = icon,
                Illustration = icon,
                IsActive = () => AnyBarrageEnabled(person),
                Disable = () => SetAllBarrageEnabled(person, false),
                Apply = () => SetAllBarrageEnabled(person, !AnyBarrageEnabled(person))
            });
        }

        static void SetAllBarrageEnabled(PersonBehaviour person, bool enabled)
        {
            if (person == null) return;
            foreach (var barrage in person.GetComponentsInChildren<Barrage>(true))
            {
                if (barrage == null) continue;
                barrage.Enabled = enabled;
            }
        }

        static bool AnyBarrageEnabled(PersonBehaviour person)
        {
            if (person == null) return false;
            foreach (var barrage in person.GetComponentsInChildren<Barrage>(true))
            {
                if (barrage != null && barrage.Enabled) return true;
            }
            return false;
        }

        public static void AddPassiveMenuPower(CharacterPowers powers, string id, string name, string desc, Sprite icon = null)
        {
            icon = icon ?? (id == "Barrage" ? DBPU.Icon_Barrage : id == "Flight" ? DBPU.Icon_Flight : DBPU.PIconTemplate);
            powers.InsertPowerAtStart(new CharacterPowers.PowerStats
            {
                ID = id,
                Name = name,
                Description = desc,
                Icon = icon,
                Illustration = icon,
                Passive = true
            });
        }

        public static void RegisterUniversalPhysicalPowers(CharacterPowers powers, PersonBehaviour person)
        {
            if (powers == null || person == null) return;
            if (HasKickPower(person)) AddKickPowerMenu(powers, person);
            if (HasPunchPower(person)) AddPunchPowerMenu(powers, person);
            if (HasBarrage(person)) AddBarrageMenu(powers, person);
            if (HasFlight(person)) AddPassiveMenuPower(powers, "Flight", "Flight", "Passive flight ability on the lower body.");
            powers.MovePowerBlockToStart(PhysicalPowerMenuOrder);
        }

        static readonly string[] PhysicalPowerMenuOrder = { "KickPower", "PunchPower", "Barrage", "Flight" };

        public static void AddKiBlast(CharacterPowers powers, CombatRefs r, Func<bool> blockWhen, Action onEnable)
        {
            if (!powers.PowerData.ContainsKey("KiBlast"))
            {
                powers.AddPower(new CharacterPowers.PowerStats
                {
                    ID = "KiBlast",
                    Name = "Ki Blast",
                    Description = "Single-shot ki projectiles from the arms.",
                    Icon = DBPU.Icon_KiBlast,
                    Illustration = DBPU.Icon_KiBlast,
                    PowerType = CharacterPowers.PowerGroups.KiBlast,
                    IsActive = () => r.Blast.Active && !r.Blast.IsBarrage,
                    Disable = () => { if (!r.Blast.IsBarrage) r.Blast.Active = false; },
                    Apply = () =>
                    {
                        if (blockWhen != null && blockWhen()) return;
                        if (r.Blast.Active && !r.Blast.IsBarrage)
                        {
                            r.Blast.Active = false;
                            return;
                        }
                        r.Blast.IsBarrage = false;
                        r.Blast.Active = true;
                        onEnable?.Invoke();
                    }
                });
            }

            AddKiBlastBarrage(powers, r, blockWhen, onEnable);
        }

        static void AddKiBlastBarrage(CharacterPowers powers, CombatRefs r, Func<bool> blockWhen, Action onEnable)
        {
            if (powers.PowerData.ContainsKey("KiBlastBarrage")) return;

            powers.AddPower(new CharacterPowers.PowerStats
            {
                ID = "KiBlastBarrage",
                Name = "Ki Blast Barrage",
                Description = "Continuous rapid ki blasts from the arms.",
                Icon = DBPU.Icon_KiBlastBarrage,
                Illustration = DBPU.Icon_KiBlastBarrage,
                PowerType = CharacterPowers.PowerGroups.KiBlast,
                IsActive = () => r.Blast.Active && r.Blast.IsBarrage,
                Disable = () =>
                {
                    if (r.Blast.IsBarrage)
                    {
                        r.Blast.Active = false;
                        r.Blast.IsBarrage = false;
                    }
                },
                Apply = () =>
                {
                    if (blockWhen != null && blockWhen()) return;
                    if (r.Blast.Active && r.Blast.IsBarrage)
                    {
                        r.Blast.Active = false;
                        r.Blast.IsBarrage = false;
                        return;
                    }
                    r.Blast.IsBarrage = true;
                    r.Blast.Active = true;
                    onEnable?.Invoke();
                }
            });
        }

        public static void AddGokuStyleBeam(CharacterPowers powers, CombatRefs r, string id, string name, string effectId, Sprite icon)
        {
            powers.AddPower(new CharacterPowers.PowerStats
            {
                ID = id,
                Name = name,
                Description = "Beam attack.",
                Icon = icon,
                Illustration = icon,
                PowerType = CharacterPowers.PowerGroups.Beam,
                IsActive = () => r.Beam.EffectID == effectId && r.Beam.Active,
                Disable = () =>
                {
                    if (r.Beam.Active && r.Beam.EffectID == effectId)
                    {
                        r.Beam.Active = false;
                        r.Beam.CancelBeamState();
                    }
                },
                Apply = () => ToggleBeamPower(r.Beam, r.Blast, r.Solar, r.Shield, effectId)
            });
        }

        public static void AddLegacyBeam(CharacterPowers powers, CombatRefs r, string id, string name, string effectId, Func<bool> blockWhen, Action onBeamOn, Sprite icon = null)
        {
            icon = icon ?? DBPU.KiBlast_Sprite;
            powers.AddPower(new CharacterPowers.PowerStats
            {
                ID = id,
                Name = name,
                Description = "Beam attack.",
                Icon = icon,
                Illustration = icon,
                PowerType = CharacterPowers.PowerGroups.Beam,
                IsActive = () => r.Beam.EffectID == effectId && r.Beam.Active,
                Disable = () =>
                {
                    if (r.Beam.Active && r.Beam.EffectID == effectId)
                    {
                        r.Beam.Active = false;
                        r.Beam.CancelBeamState();
                    }
                },
                GetStatusText = () => (r.Beam.EffectID == effectId && r.Beam.Active) ? "Enabled" : "Disabled",
                Apply = () => ToggleLegacyBeam(r, effectId, blockWhen, onBeamOn)
            });
        }

        public static void AddLegacyBeamWithType(CharacterPowers powers, CombatRefs r, string id, string name, string effectId, string beamType, Func<bool> blockWhen, Action onBeamOn, Sprite icon = null)
        {
            AddLegacyBeam(powers, r, id, name, effectId, blockWhen, () =>
