    static class DbpuInputUtil
    {
        public static bool Down(string inputId, KeyCode fallback)
        {
            if (KiFistInput.BlocksAction(inputId, fallback)) return false;
            if (CombatAbilityWheel.AnyMenuCaptured) return false;
            if (InputSystem.Has(inputId))
                return InputSystem.Down(inputId);

            return Input.GetKeyDown(fallback);
        }

        public static bool Held(string inputId, KeyCode fallback)
        {
            if (KiFistInput.BlocksAction(inputId, fallback)) return false;
            if (CombatAbilityWheel.AnyMenuCaptured) return false;
            if (InputSystem.Has(inputId))
                return InputSystem.Held(inputId);

            return Input.GetKey(fallback);
        }

        public static bool Up(string inputId, KeyCode fallback)
        {
            if (KiFistInput.BlocksAction(inputId, fallback)) return true;
            // UI capture releases held abilities so their cleanup cannot lose a physical key-up edge.
            if (CombatAbilityWheel.AnyMenuCaptured) return true;
            if (InputSystem.Has(inputId))
                return InputSystem.Up(inputId);

            return Input.GetKeyUp(fallback);
        }
    }

    static class DbpuInputRegistration
    {
        public static void RegisterAll()
        {
            Register("Open powers menu", DBPU.OpenPowerMenuActionId, DBPU.OpenPowerMenuDefaultKey);
            Register("Quick transform", DBPU.QuickTransformActionId, KeyCode.H);
            ModAPI.RegisterInput("Combat transformation wheel (hold)", CombatTransformationWheel.ActionId, CombatTransformationWheel.DefaultKey);
            ModAPI.RegisterInput("Combat hand ability wheel (hold)", CombatAbilityWheel.ActionId, CombatAbilityWheel.DefaultKey);
            ModAPI.RegisterInput("Ki output on head (Shift reverses)", CombatPowerController.ActionId, CombatPowerController.DefaultKey);
            ModAPI.RegisterInput("Ki Fist mode (tap) / charge (hold)", KiFistInput.ActionId, KiFistInput.DefaultKey);
            Register("Barrage", DBPU.BarrageActionId, KeyCode.H);
            Register("Kaioken", DBPU.KaiokenActionId, KeyCode.K);
            Register("Instant transmission", DBPU.InstantTransmissionActionId, KeyCode.R);
            Register("Cell Max scream", DBPU.CellMaxScreamActionId, KeyCode.R);
            Register("Ki charge hold", DBPU.KiChargeHoldActionId, KeyCode.R);
            Register("Ki output cycle", DBPU.KiOverdriveOutputActionId, DBPU.KiOverdriveOutputDefaultKey);
        }

        static void Register(string label, string id, KeyCode defaultKey)
        {
            ModAPI.RegisterInput(label, id, defaultKey);
            FixLegacyDefaultKey(id, defaultKey);
        }

        public static KeyCode GetActionKey(string id, KeyCode fallback)
        {
            if (InputSystem.Actions.TryGetValue(id, out var active))
                return active.Key;
            return fallback;
        }

        public static string GetActionKeyLabel(string id, KeyCode fallback)
        {
            KeyCode key = GetActionKey(id, fallback);
            return key == KeyCode.None ? "Unbound" : key.ToString();
        }

        public static void SetActionKey(string id, KeyCode key)
        {
            var moddedField = AccessTools.Field(typeof(InputSystem), "Modded");
            var modded = moddedField?.GetValue(null) as Dictionary<string, InputAction>;
            if (modded != null && modded.TryGetValue(id, out var registered))
            {
                registered.Key = key;
                modded[id] = registered;
            }

            if (InputSystem.Actions.TryGetValue(id, out var active))
            {
                active.Key = key;
                InputSystem.Actions[id] = active;
            }

            AccessTools.Field(typeof(ControlSchemeEditorBehaviour), "ShouldReinitialise")?.SetValue(null, true);
        }

        public static void ApplyLegacyConfigKeybinds()
        {
            if (ModConfigs.configurations == null) return;

            if (ModConfigs.configurations.DBPUConfigVersion < 4)
            {
                if (ModConfigs.configurations.KiOverdriveOutputKey != KeyCode.None)
                    SetActionKey(DBPU.KiOverdriveOutputActionId, ModConfigs.configurations.KiOverdriveOutputKey);
                if (ModConfigs.configurations.KiChargeHoldKey != KeyCode.None)
                    SetActionKey(DBPU.KiChargeHoldActionId, ModConfigs.configurations.KiChargeHoldKey);

                ModConfigs.configurations.DBPUConfigVersion = 4;
                ModConfigs.configurations.KiOverdriveOutputKey = GetActionKey(DBPU.KiOverdriveOutputActionId, DBPU.KiOverdriveOutputDefaultKey);
                ModConfigs.configurations.KiChargeHoldKey = GetActionKey(DBPU.KiChargeHoldActionId, KeyCode.R);
                ModConfigs.Save();
            }
        }

        static void FixLegacyDefaultKey(string id, KeyCode defaultKey)
        {
            var moddedField = AccessTools.Field(typeof(InputSystem), "Modded");
            var modded = moddedField?.GetValue(null) as Dictionary<string, InputAction>;
            if (modded != null && modded.TryGetValue(id, out var registered) && registered.Key == KeyCode.L)
            {
                registered.Key = defaultKey;
                modded[id] = registered;
            }

            if (InputSystem.Actions.TryGetValue(id, out var active) && active.Key == KeyCode.L)
            {
                active.Key = defaultKey;
                InputSystem.Actions[id] = active;
            }

            AccessTools.Field(typeof(ControlSchemeEditorBehaviour), "ShouldReinitialise")?.SetValue(null, true);
        }
    }

    static class DbpuControlsMenuPatch
    {
        const string SectionTitle = "Dragon Ball: Singularity";
        static Harmony _harmony;
        static bool _applied;

        public static void Apply()
        {
            if (_applied) return;
            _harmony = new Harmony("DBPU.Controls");
            _harmony.Patch(
                AccessTools.Method(typeof(ControlSchemeEditorBehaviour), nameof(ControlSchemeEditorBehaviour.InitialiseControlScheme)),
                prefix: new HarmonyMethod(typeof(DbpuControlsMenuPatch), nameof(Prefix)));
            _applied = true;
        }

        static void CreateSectionHeader(GameObject headerPrefab, Transform container, string title, Sprite icon = null)
        {
            var headerGo = UnityEngine.Object.Instantiate(headerPrefab, container);
            var text = headerGo.GetComponentInChildren<TextMeshProUGUI>();
            if (text == null)
                return;

            text.text = title;
            if (icon == null)
                return;

            var headerRt = headerGo.GetComponent<RectTransform>();
            if (headerRt == null)
                headerRt = headerGo.AddComponent<RectTransform>();

            var iconGo = new GameObject("SectionIcon");
            iconGo.transform.SetParent(headerGo.transform, false);
            var iconRt = iconGo.AddComponent<RectTransform>();
            iconRt.anchorMin = new Vector2(0.5f, 0.5f);
            iconRt.anchorMax = new Vector2(0.5f, 0.5f);
            iconRt.pivot = new Vector2(0.5f, 0.5f);

            float iconSize = headerRt.rect.height > 1f ? headerRt.rect.height * 0.82f : 16f;
            iconRt.sizeDelta = new Vector2(iconSize, iconSize);

            var iconImg = iconGo.AddComponent<Image>();
            iconImg.sprite = icon;
            iconImg.preserveAspect = true;
            iconImg.raycastTarget = false;

            iconGo.AddComponent<LayoutElement>().ignoreLayout = true;

            iconRt.localScale = new Vector3(0.9f, 0.9f, 1f);
            iconRt.localPosition = new Vector3(-514f, 0f, 0f);
        }

        public static bool Prefix(ControlSchemeEditorBehaviour __instance)
        {
            var container = AccessTools.Field(typeof(ControlSchemeEditorBehaviour), "Container").GetValue(__instance) as Transform;
            var headerPrefab = AccessTools.Field(typeof(ControlSchemeEditorBehaviour), "HeaderPrefab").GetValue(__instance) as GameObject;
            var controlPrefab = AccessTools.Field(typeof(ControlSchemeEditorBehaviour), "ControlPrefab").GetValue(__instance) as GameObject;

            foreach (Transform child in container)
                UnityEngine.Object.Destroy(child.gameObject);

            foreach (ActionCategory category in Enum.GetValues(typeof(ActionCategory)))
            {
                if (category == ActionCategory.MapEditor)
                    continue;

                if (category == ActionCategory.Modded)
                {
                    var dbpuActions = InputSystem.Actions
                        .Where(action => action.Value.Category == ActionCategory.Modded
                            && !action.Value.InvisibleInMenu
                            && action.Key.StartsWith("dbpu.", StringComparison.OrdinalIgnoreCase))
                        .OrderBy(action => action.Value.Name)
                        .ToList();

                    var otherModded = InputSystem.Actions
                        .Where(action => action.Value.Category == ActionCategory.Modded
                            && !action.Value.InvisibleInMenu
                            && !action.Key.StartsWith("dbpu.", StringComparison.OrdinalIgnoreCase))
                        .ToList();

                    if (dbpuActions.Count > 0)
                    {
                        CreateSectionHeader(headerPrefab, container, SectionTitle, DBPU.ControlsSectionIcon);
                        foreach (var action in dbpuActions)
                            CreateControlObject(controlPrefab, container, action.Key, action.Value);
                    }

                    if (otherModded.Count > 0)
                    {
                        UnityEngine.Object.Instantiate(headerPrefab, container).GetComponentInChildren<TextMeshProUGUI>().text = "Modded";
                        foreach (var action in otherModded)
                            CreateControlObject(controlPrefab, container, action.Key, action.Value);
                    }

                    continue;
                }

                var categoryActions = InputSystem.Actions
                    .Where(action => action.Value.Category == category && !action.Value.InvisibleInMenu)
                    .ToList();

                if (categoryActions.Count == 0)
                    continue;

                UnityEngine.Object.Instantiate(headerPrefab, container).GetComponentInChildren<TextMeshProUGUI>().text =
                    Regex.Replace(category.ToString(), "(\\B[A-Z])", " $1");

                foreach (var action in categoryActions)
                    CreateControlObject(controlPrefab, container, action.Key, action.Value);
            }

            return false;
        }

        static void CreateControlObject(GameObject controlPrefab, Transform container, string key, InputAction action)
        {
            var control = UnityEngine.Object.Instantiate(controlPrefab, container).GetComponent<ActionControlBehaviour>();
            control.Action.text = action.Name;
            var trigger = control.Trigger.GetComponent<TriggerEditorBehaviour>();
            trigger.InputActionKey = key;
            trigger.InputAction = action;
        }
    }

