    public class QuickTransformKeybindInput : MonoBehaviour
    {
        static QuickTransformKeybindInput _instance;

        public static void Ensure()
        {
            if (_instance != null) return;
            var go = new GameObject("QuickTransformKeybindInput");
            UnityEngine.Object.DontDestroyOnLoad(go);
            _instance = go.AddComponent<QuickTransformKeybindInput>();
        }

        static bool PointerOverUi()
        {
            return EventSystem.current != null && EventSystem.current.IsPointerOverGameObject();
        }

        static TransformationContextMenu FindTransformMenuFromPhysical(PhysicalBehaviour pb)
        {
            if (pb == null) return null;

            var person = pb.GetComponent<PersonBehaviour>() ?? pb.transform.root.GetComponent<PersonBehaviour>();
            if (person == null) return null;

            Transform head = person.transform.Find("Head");
            if (head == null)
            {
                foreach (var limb in person.Limbs)
                {
                    if (limb != null && limb.name.IndexOf("Head", StringComparison.OrdinalIgnoreCase) >= 0)
                    {
                        head = limb.transform;
                        break;
                    }
                }
            }

            if (head == null && person.Limbs.Length > 2)
                head = person.Limbs[2].transform;

            return head != null ? head.GetComponent<TransformationContextMenu>() : null;
        }

        static TransformationContextMenu GetForSelectedCharacter()
        {
            var selection = SelectionController.Main;
            if (selection != null && selection.SelectedObjects != null)
            {
                foreach (PhysicalBehaviour selected in selection.SelectedObjects)
                {
                    var menu = FindTransformMenuFromPhysical(selected);
                    if (menu != null) return menu;
                }
            }

            var tool = Global.main?.ToolControllerBehaviour?.CurrentTool;
            if (tool != null && tool.ActiveSingleSelected != null)
            {
                var menu = FindTransformMenuFromPhysical(tool.ActiveSingleSelected);
                if (menu != null) return menu;
            }

            if (selection != null && selection.CurrentlyUnderMouse != null)
                return FindTransformMenuFromPhysical(selection.CurrentlyUnderMouse);

            return null;
        }

        void Update()
        {
            if (!QuickTransformInputUtil.Down() || PointerOverUi()) return;

            var menu = GetForSelectedCharacter();
            if (menu == null) return;

            menu.QuickToggleTransform();
        }
    }

    public static class PowerGiverUI
    {
        const int RowsPerPage = 6;
        const float RowScale = 0.78f;
        const float TitleY = 54f;
        const float CloseX = 0f;
        const float CloseY = -66f;
        const float SearchY = 35f;
        const float NavY = -52f;
        const float ListTopY = 24f;
        static float RowStep => MenuUI.SpritePixels(DBPU.PConfigTextSlider).y * RowScale + 1f;
        static GameObject _canvasRoot;
        static TMP_FontAsset _font;
        static bool _uiBlocked;

        public static bool IsOpen => _canvasRoot != null;

        static TMP_FontAsset Font
        {
            get
            {
                if (_font == null)
                    _font = ModAPI.FindSpawnable("Holographic Display").Prefab.transform.Find("Text").GetComponent<TextMeshPro>().font;
                return _font;
            }
        }

        public static void Open()
        {
            if (IsOpen) return;

            PowerGiverState.Disarm();
            CharacterPowerPickerState.Disarm();
            AuraTunePickerState.Disarm();
            PowerGiverInput.Ensure();

            _canvasRoot = new GameObject("PowerGiverCanvas");
            _canvasRoot.transform.SetParent(GameObject.Find("Canvas").transform, false);
            var canvasRt = _canvasRoot.AddComponent<RectTransform>();
            canvasRt.anchoredPosition = new Vector2(-120f, 40f);
            canvasRt.localScale = new Vector3(8.5f, 8.5f, 1f);

            GameObject panel = new GameObject("Panel");
            panel.transform.SetParent(_canvasRoot.transform, false);
            Image panelImg = panel.AddComponent<Image>();
            panelImg.sprite = DBPU.PCanvas;
            panelImg.color = Color.white;
            RectTransform panelRt = panel.GetComponent<RectTransform>();
            panelRt.anchoredPosition = Vector2.zero;
            panelRt.sizeDelta = MenuUI.SpritePixels(DBPU.PCanvas);
            panelRt.localScale = Vector3.one;

            GameObject titleGo = new GameObject("Title");
            titleGo.transform.SetParent(panel.transform, false);
            RectTransform titleRt = titleGo.AddComponent<RectTransform>();
            titleRt.anchoredPosition = new Vector2(0f, TitleY);
            titleRt.sizeDelta = new Vector2(80f, 12f);
            TextMeshProUGUI titleTmp = titleGo.AddComponent<TextMeshProUGUI>();
            titleTmp.text = "Power Giver";
            titleTmp.font = Font;
            titleTmp.fontSize = 8f;
            titleTmp.alignment = TextAlignmentOptions.Center;
            titleTmp.color = Color.black;
            MenuUI.ConfigureTitleDragArea(titleGo, canvasRt, new Vector2(80f, 12f));

            string searchFilter = "";
            int page = 0;
            List<PowerGrantCatalog.Entry> filtered = new List<PowerGrantCatalog.Entry>(PowerGrantCatalog.Entries);
            string selectedId = PowerGiverState.SelectedPowerId;

            GameObject listHolder = new GameObject("ListHolder");
            listHolder.transform.SetParent(panel.transform, false);
            listHolder.AddComponent<RectTransform>();

            Action applyFilter = () =>
            {
                filtered.Clear();
                string q = (searchFilter ?? "").Trim().ToLowerInvariant();
                foreach (var e in PowerGrantCatalog.Entries)
                {
                    if (string.IsNullOrEmpty(q)
                        || e.Name.ToLowerInvariant().Contains(q)
                        || e.Category.ToLowerInvariant().Contains(q)
                        || e.Description.ToLowerInvariant().Contains(q)
                        || e.Id.ToLowerInvariant().Contains(q))
                        filtered.Add(e);
                }
                page = 0;
            };

            TextMeshProUGUI pageLabel = null;
            GameObject pageLabelGo = new GameObject("PageLabel");
            pageLabelGo.transform.SetParent(panel.transform, false);
            RectTransform pageLabelRt = pageLabelGo.AddComponent<RectTransform>();
            pageLabelRt.anchoredPosition = new Vector2(0f, NavY);
            pageLabelRt.sizeDelta = new Vector2(30f, 8f);
            pageLabel = pageLabelGo.AddComponent<TextMeshProUGUI>();
            pageLabel.font = Font;
            pageLabel.fontSize = 3.5f;
            pageLabel.alignment = TextAlignmentOptions.Center;
            pageLabel.color = Color.black;

            Action rebuildList = null;
            rebuildList = () =>
            {
                for (int i = listHolder.transform.childCount - 1; i >= 0; i--)
                    GameObject.Destroy(listHolder.transform.GetChild(i).gameObject);

                int totalPages = Mathf.Max(1, Mathf.CeilToInt(filtered.Count / (float)RowsPerPage));
                if (page >= totalPages) page = totalPages - 1;
                if (page < 0) page = 0;
                int start = page * RowsPerPage;
                int end = Mathf.Min(start + RowsPerPage, filtered.Count);
                float y = ListTopY;

                for (int i = start; i < end; i++)
                {
                    var entry = filtered[i];
                    string capId = entry.Id;
                    bool isSel = capId == selectedId;

                    GameObject row = new GameObject("Row_" + entry.Id);
                    row.transform.SetParent(listHolder.transform, false);
                    MenuUI.ApplyImage(row, DBPU.PConfigTextSlider, new Vector2(0f, y), RowScale);

                    if (isSel)
                    {
                        GameObject selGo = new GameObject("SelectFrame");
                        selGo.transform.SetParent(row.transform, false);
                        MenuUI.ApplyImage(selGo, DBPU.PConfigTextSliderSel, Vector2.zero, 1f);
                        MenuUI.DisableRaycast(selGo.GetComponent<Image>());
                        selGo.transform.SetAsLastSibling();
                    }

                    GameObject labelGo = new GameObject("Label");
                    labelGo.transform.SetParent(row.transform, false);
                    RectTransform labelRt = labelGo.AddComponent<RectTransform>();
                    labelRt.anchoredPosition = Vector2.zero;
                    labelRt.sizeDelta = new Vector2(76f, 11f);
                    TextMeshProUGUI label = labelGo.AddComponent<TextMeshProUGUI>();
                    label.text = entry.Name + "  <size=70%><color=#444>" + entry.Category;
                    label.font = Font;
                    label.fontSize = 4.5f;
                    label.alignment = TextAlignmentOptions.MidlineLeft;
                    label.color = Color.black;
                    label.raycastTarget = false;
                    label.margin = new Vector4(6f, 0f, 0f, 0f);

                    row.AddComponent<Button>().onClick.AddListener(() =>
                    {
                        var sel = PowerGrantCatalog.Find(capId);
                        PowerGiverState.SelectedPowerId = capId;
                        PowerGiverState.SelectedPowerName = sel != null ? sel.Name : capId;
                        PowerGiverState.Armed = true;
                        Close();
                    });

                    y -= RowStep;
                }

                pageLabel.text = filtered.Count == 0 ? "0 / 0" : (page + 1) + " / " + totalPages;
            };

            GameObject searchGo = new GameObject("SearchField");
            searchGo.transform.SetParent(panel.transform, false);
            RectTransform searchRt = searchGo.AddComponent<RectTransform>();
            searchRt.anchoredPosition = new Vector2(0f, SearchY);
            searchRt.sizeDelta = new Vector2(72f, 9f);
            Image searchBg = searchGo.AddComponent<Image>();
            searchBg.color = new Color(0.95f, 0.95f, 0.95f, 1f);

            GameObject textArea = new GameObject("TextArea");
            textArea.transform.SetParent(searchGo.transform, false);
            RectTransform taRt = textArea.AddComponent<RectTransform>();
            taRt.anchorMin = Vector2.zero;
            taRt.anchorMax = Vector2.one;
            taRt.offsetMin = new Vector2(3f, 1f);
            taRt.offsetMax = new Vector2(-3f, -1f);

            GameObject phGo = new GameObject("Placeholder");
            phGo.transform.SetParent(textArea.transform, false);
            RectTransform phRt = phGo.AddComponent<RectTransform>();
            phRt.anchorMin = Vector2.zero;
            phRt.anchorMax = Vector2.one;
            phRt.offsetMin = Vector2.zero;
            phRt.offsetMax = Vector2.zero;
            TextMeshProUGUI phTmp = phGo.AddComponent<TextMeshProUGUI>();
            phTmp.text = "Search...";
            phTmp.font = Font;
            phTmp.fontSize = 3.5f;
            phTmp.color = new Color(0.45f, 0.45f, 0.45f);
            phTmp.alignment = TextAlignmentOptions.MidlineLeft;

            GameObject textGo = new GameObject("Text");
            textGo.transform.SetParent(textArea.transform, false);
            RectTransform textRt = textGo.AddComponent<RectTransform>();
            textRt.anchorMin = Vector2.zero;
            textRt.anchorMax = Vector2.one;
            textRt.offsetMin = Vector2.zero;
            textRt.offsetMax = Vector2.zero;
            TextMeshProUGUI inputTmp = textGo.AddComponent<TextMeshProUGUI>();
            inputTmp.font = Font;
            inputTmp.fontSize = 3.5f;
            inputTmp.color = Color.black;
            inputTmp.alignment = TextAlignmentOptions.MidlineLeft;

            TMP_InputField searchInput = searchGo.AddComponent<TMP_InputField>();
            searchInput.textViewport = taRt;
            searchInput.textComponent = inputTmp;
            searchInput.placeholder = phTmp;
            searchInput.onValueChanged.AddListener(v =>
            {
                searchFilter = v;
                applyFilter();
                rebuildList();
            });
            searchInput.onSelect.AddListener(_ =>
            {
                try { if (!_uiBlocked) { Global.main.AddUiBlocker(); _uiBlocked = true; } } catch { }
            });
            searchInput.onDeselect.AddListener(_ =>
            {
                try { if (_uiBlocked) { Global.main.RemoveUiBlocker(); _uiBlocked = false; } } catch { }
            });

            Sprite prevSprite = DBPU.PPrevious != null ? DBPU.PPrevious : DBPU.TPrevious;
            Sprite nextSprite = DBPU.PNext != null ? DBPU.PNext : DBPU.TNext;

            GameObject prevBtn = new GameObject("Prev");
            prevBtn.transform.SetParent(panel.transform, false);
            MenuUI.ApplyImage(prevBtn, prevSprite, new Vector2(-22f, NavY), 0.45f);
            prevBtn.AddComponent<Button>().onClick.AddListener(() => { if (page > 0) { page--; rebuildList(); } });

            GameObject nextBtn = new GameObject("Next");
            nextBtn.transform.SetParent(panel.transform, false);
            MenuUI.ApplyImage(nextBtn, nextSprite, new Vector2(22f, NavY), 0.45f);
            nextBtn.AddComponent<Button>().onClick.AddListener(() =>
            {
                int totalPages = Mathf.Max(1, Mathf.CeilToInt(filtered.Count / (float)RowsPerPage));
                if (page < totalPages - 1) { page++; rebuildList(); }
            });

            GameObject closeBtn = new GameObject("Close");
            closeBtn.transform.SetParent(panel.transform, false);
            MenuUI.ApplyImage(closeBtn, DBPU.PCloseButton, new Vector2(CloseX, CloseY), 0.55f);
            closeBtn.AddComponent<Button>().onClick.AddListener(() =>
            {
                PowerGiverState.Disarm();
                Close();
            });

            MenuUI.AttachResizeHandle(panel.transform, () => canvasRt.localScale.x, u => canvasRt.localScale = new Vector3(u, u, 1f), 5f, 14f, 8f);

            applyFilter();
            rebuildList();
            searchInput.ActivateInputField();
            searchInput.Select();
        }

        public static void Close()
        {
            if (_uiBlocked)
            {
                try { Global.main.RemoveUiBlocker(); } catch { }
                _uiBlocked = false;
            }
            if (_canvasRoot != null)
            {
                GameObject.Destroy(_canvasRoot);
                _canvasRoot = null;
            }
        }
    }

    public abstract class PowerMenuConfigEntry
    {
        public string ID;
        public string Name;
        public string Description;

        public abstract float GetRowHeight(PowerMenuLayoutConfig layout);
        public abstract bool IsToggle { get; }
        public abstract bool IsSlider { get; }
    }

    public class PowerMenuConfigToggleEntry : PowerMenuConfigEntry
    {
        public Func<bool> GetValue;
        public Action<bool> SetValue;

        public override float GetRowHeight(PowerMenuLayoutConfig layout) => MenuUI.SpritePixels(DBPU.PConfigTextToggle).y;
        public override bool IsToggle => true;
        public override bool IsSlider => false;

        public void Toggle()
        {
            if (GetValue == null || SetValue == null) return;
            SetValue(!GetValue());
        }
    }

    public class PowerMenuConfigSliderEntry : PowerMenuConfigEntry
    {
        public Func<float> GetValue;
        public Action<float> SetValue;
        public Func<float> GetDisplayValue;
        public Action<float> SetDisplayValue;
        public float Min;
        public float Max;
        public bool ShowAsPercent;

        public override float GetRowHeight(PowerMenuLayoutConfig layout)
        {
            float gap = Mathf.Max(0f, layout.configSliderNameBarGap);
            return MenuUI.SpritePixels(DBPU.PConfigTextSlider).y
                + gap
                + MenuUI.SpritePixels(DBPU.PSliderValue).y;
        }
        public override bool IsToggle => false;
        public override bool IsSlider => true;

        public float ReadDisplay()
        {
            if (GetDisplayValue != null) return GetDisplayValue();
            return GetValue != null ? GetValue() : 0f;
        }

        public void WriteDisplay(float v)
        {
            if (SetDisplayValue != null) SetDisplayValue(v);
            else SetValue?.Invoke(v);
        }

        public string FormatDisplay(float display)
        {
            if (ShowAsPercent)
            {
                float pct = display <= 1.01f && display >= 0f ? display * 100f : display;
                return Mathf.Round(pct) + "%";
            }
            return display.ToString("0.##", CultureInfo.InvariantCulture);
        }
    }

    public class PowerMenuConfigActionEntry : PowerMenuConfigEntry
    {
        public Action OnClick;

        public override float GetRowHeight(PowerMenuLayoutConfig layout) => MenuUI.SpritePixels(DBPU.PConfigTextToggle).y;
        public override bool IsToggle => false;
        public override bool IsSlider => false;
    }

    static class PowerMenuConfigData
    {
        static List<List<PowerMenuConfigEntry>> WrapPage(List<PowerMenuConfigEntry> entries)
        {
            return new List<List<PowerMenuConfigEntry>> { entries ?? new List<PowerMenuConfigEntry>() };
        }

        static void AddSlider(List<PowerMenuConfigEntry> list, string id, string name, string desc, Func<float> get, Action<float> set, float min, float max, bool percent = false)
        {
            list.Add(new PowerMenuConfigSliderEntry { ID = id, Name = name, Description = desc, GetValue = get, SetValue = set, Min = min, Max = max, ShowAsPercent = percent });
        }

        static void AddSliderAsPercentOfMax(List<PowerMenuConfigEntry> list, string id, string name, string desc, Func<float> get, Action<float> set, float min, float max)
        {
            float range = Mathf.Max(max - min, 0.0001f);
            list.Add(new PowerMenuConfigSliderEntry
            {
                ID = id,
                Name = name,
                Description = desc,
                GetValue = get,
                SetValue = set,
                GetDisplayValue = () => Mathf.Clamp((get() - min) / range, 0.0001f, 1f),
                SetDisplayValue = v => set(Mathf.Clamp(min + v * range, min, max)),
                Min = 0.0001f,
                Max = 1f,
                ShowAsPercent = true
            });
        }

        static void AddToggle(List<PowerMenuConfigEntry> list, string id, string name, string desc, Func<bool> get, Action<bool> set)
        {
            list.Add(new PowerMenuConfigToggleEntry { ID = id, Name = name, Description = desc, GetValue = get, SetValue = set });
        }

        static PunchPower GetPunchPower(PersonBehaviour person)
        {
            if (person == null) return null;
            foreach (var limb in person.Limbs)
            {
                if (limb.name.Contains("LowerArm"))
                {
                    var pp = limb.GetComponent<PunchPower>();
                    if (pp != null) return pp;
                }
            }
            return null;
        }

        static void SetAllPunchPower(PersonBehaviour person, Action<PunchPower> apply)
        {
            if (person == null || apply == null) return;
            foreach (var limb in person.Limbs)
            {
                var pp = limb.GetComponent<PunchPower>();
                if (pp != null) apply(pp);
            }
        }

        static KickPower GetKickPower(PersonBehaviour person)
        {
            if (person == null) return null;
            foreach (var limb in person.Limbs)
            {
                if (PowerSetup.IsKickLimb(limb.name))
                {
                    var kp = limb.GetComponent<KickPower>();
                    if (kp != null) return kp;
                }
            }
            return null;
        }

        static void SetAllKickPower(PersonBehaviour person, Action<KickPower> apply)
        {
            if (person == null || apply == null) return;
            foreach (var limb in person.Limbs)
            {
                if (PowerSetup.IsKickLimb(limb.name))
                {
                    var kp = limb.GetComponent<KickPower>();
                    if (kp != null) apply(kp);
                }
            }
        }

        const float BlastKnockbackMax = 5f;
        const float BeamKnockbackMax = 1f;
        const float BarrageSpeedMax = 1f;

        static void AddDamageOutputPercent(List<PowerMenuConfigEntry> list, Func<float> get, Action<float> set)
        {
            AddSlider(list, "DamageOutput", "Damage Output", "Damage output multiplier.", get, v => set(Mathf.Clamp(v, 0.0001f, 1f)), 0.0001f, 1f, true);
        }

        static void AddKnockbackPercent(List<PowerMenuConfigEntry> list, Func<float> get, Action<float> set, float max = 1f)
        {
            float range = Mathf.Max(max, 0.0001f);
            AddSlider(list, "Knockback", "Knockback", "Knockback strength multiplier.", get, v => set(Mathf.Clamp(v, 0f, max)), 0f, max, true);
        }

        static void AddSpeedPercent(List<PowerMenuConfigEntry> list, Func<float> get, Action<float> set, float max = 1f)
        {
            AddSlider(list, "Speed", "Speed", "Speed multiplier.", get, v => set(Mathf.Clamp(v, 0.0001f, max)), 0.0001f, max, true);
        }

        static void AddBlastKiConfigs(List<PowerMenuConfigEntry> list, BlastBehaviour blast)
        {
            if (blast == null) return;
            AddDamageOutputPercent(list, () => blast.DamageOutput, v => blast.DamageOutput = v);
            AddKnockbackPercent(list, () => blast.KnockbackMultiplier / BlastKnockbackMax, v => blast.KnockbackMultiplier = v * BlastKnockbackMax, 1f);
        }

        static void AddBeamKiConfigs(List<PowerMenuConfigEntry> list, BeamBehaviour beam, bool damageOutput = true)
        {
            if (beam == null) return;
            if (damageOutput)
                AddDamageOutputPercent(list, () => beam.DamageOutput, v => beam.DamageOutput = v);
            AddKnockbackPercent(list, () => beam.KnockbackOutput, v => beam.KnockbackOutput = v, BeamKnockbackMax);
        }

        static void AddBarrageConfigs(List<PowerMenuConfigEntry> list, PersonBehaviour person)
        {
            var barrage = person != null ? person.GetComponentInChildren<Barrage>(true) : null;
            if (barrage == null) return;
            AddDamageOutputPercent(list, () => barrage.damageOutput, v => barrage.damageOutput = v);
            AddSpeedPercent(list, () => barrage.speedOutput, v => barrage.speedOutput = v, BarrageSpeedMax);
        }

        static void AddMeleePowerConfigs(List<PowerMenuConfigEntry> list, PersonBehaviour person, PunchPower punch, KickPower kick)
        {
            if (punch != null)
            {
                AddDamageOutputPercent(list, () => punch.DamageOutput, v => SetAllPunchPower(person, p => p.DamageOutput = v));
                AddKnockbackPercent(list, () => punch.knockbackOutput, v => SetAllPunchPower(person, p => p.knockbackOutput = v), 1f);
                AddToggle(list, "NukeShockwave", "Nuke Shockwave", "Enable shockwave on heavy hits.", () => punch.enableNuclearExplosion, v => SetAllPunchPower(person, p => p.enableNuclearExplosion = v));
            }
            else if (kick != null)
            {
                AddDamageOutputPercent(list, () => kick.DamageOutput, v => SetAllKickPower(person, k => k.DamageOutput = v));
                AddKnockbackPercent(list, () => kick.knockbackOutput, v => SetAllKickPower(person, k => k.knockbackOutput = v), 1f);
                AddToggle(list, "NukeShockwave", "Nuke Shockwave", "Enable shockwave on heavy hits.", () => kick.enableNuclearExplosion, v => SetAllKickPower(person, k => k.enableNuclearExplosion = v));
            }
        }

        static void AddFinalExplosionConfigs(List<PowerMenuConfigEntry> list, FinalExplosion fx)
        {
            if (fx == null) return;
            AddDamageOutputPercent(list, () => fx.DamageOutput, v => fx.DamageOutput = v);
            AddKnockbackPercent(list, () => fx.KnockbackOutput, v => fx.KnockbackOutput = v, 1f);
        }

        static void AddSolarConfigs(List<PowerMenuConfigEntry> list, SolarFlare solar)
        {
            if (solar == null) return;
            AddSlider(list, "Time", "Time", "Solar flare duration in seconds.", () => solar.flareDuration, v => solar.flareDuration = Mathf.Clamp(v, 0.5f, 15f), 0.5f, 15f);
            AddSlider(list, "Brightness", "Brightness", "Solar flare brightness.", () => solar.brightnessOutput, v => solar.brightnessOutput = Mathf.Clamp(v, 0.0001f, 1f), 0.0001f, 1f, true);
        }

        static void AddShieldConfigs(List<PowerMenuConfigEntry> list, KiShield shield)
        {
            if (shield == null) return;
            AddSlider(list, "Diameter", "Barrier size", "Barrier size; automatically kept large enough for this fighter.", () => shield.shieldDiameterMeters, v => shield.shieldDiameterMeters = Mathf.Clamp(v, 5f, 60f), 5f, 60f);
        }

        static void AddGrowthConfigs(List<PowerMenuConfigEntry> list, PiccoloGiantForm growth)
        {
            if (growth == null) return;
            AddSlider(list, "TargetSize", "Target Size", "Giant form target height in meters.", () => growth.targetSizeMeters, v => growth.targetSizeMeters = Mathf.Clamp(v, 3f, 40f), 3f, 40f);
            AddSlider(list, "Speed", "Speed", "Growth transition time in seconds.", () => growth.HeightSmoothTime, v => growth.HeightSmoothTime = Mathf.Clamp(v, 0.05f, 5f), 0.05f, 5f);
        }

        static void AddKaiokenConfigs(List<PowerMenuConfigEntry> list, Kaioken kaioken)
        {
            if (kaioken == null) return;
            float max = Mathf.Max(DBPU.KaiokenMaxMultiplier, 1f);
            AddSlider(list, "Multiplier", "Multiplier", "Kaioken power multiplier.", () => kaioken.Multiplier, v => kaioken.ApplyConfiguredMultiplier(v), 1f, max);
        }

        static void AddHellzoneConfigs(List<PowerMenuConfigEntry> list, HellzoneGranade hz)
        {
            if (hz == null) return;
            AddDamageOutputPercent(list, () => hz.DamageOutput, v => hz.DamageOutput = v);
            AddKnockbackPercent(list, () => hz.KnockbackMultiplier / BlastKnockbackMax, v => hz.KnockbackMultiplier = v * BlastKnockbackMax, 1f);
            AddSlider(list, "BlastsAmount", "Blasts Amount", "Number of trap blasts.", () => hz.blastsAmount, v => hz.blastsAmount = Mathf.RoundToInt(Mathf.Clamp(v, 10f, 200f)), 10f, 200f);
        }

        static void AddBallKiConfigs(List<PowerMenuConfigEntry> list, BallBehaviour ball)
        {
            if (ball == null) return;
            AddDamageOutputPercent(list, () => ball.DamageOutput, v => ball.DamageOutput = v);
            AddKnockbackPercent(list, () => ball.KnockbackOutput, v => ball.KnockbackOutput = v, 1f);
        }

        static void AddGogetaSpecialConfigs(List<PowerMenuConfigEntry> list, Func<float> getDamageOutput, Action<float> setDamageOutput, Func<float> getKnockbackOutput, Action<float> setKnockbackOutput, Func<int> getBlastsAmount = null, Action<int> setBlastsAmount = null, Func<float> getDuration = null, Action<float> setDuration = null)
        {
            AddDamageOutputPercent(list, getDamageOutput, setDamageOutput);
            AddKnockbackPercent(list, getKnockbackOutput, setKnockbackOutput, 1f);
            if (getBlastsAmount != null && setBlastsAmount != null)
                AddSlider(list, "BlastsAmount", "Blasts Amount", "Number of projectiles.", () => getBlastsAmount(), v => setBlastsAmount(Mathf.RoundToInt(Mathf.Clamp(v, 10f, 300f))), 10f, 300f);
            if (getDuration != null && setDuration != null)
                AddSlider(list, "Duration", "Duration", "Attack duration in seconds.", getDuration, v => setDuration(Mathf.Clamp(v, 0.5f, 10f)), 0.5f, 10f);
        }

        public static List<List<PowerMenuConfigEntry>> GetPowerPages(CharacterPowers.PowerStats power, GameObject instance, PersonBehaviour person)
        {
            var entries = new List<PowerMenuConfigEntry>();
            if (power == null || instance == null) return WrapPage(entries);

            string id = power.ID;
            string type = power.PowerType;

            if (id == "Barrage")
                AddBarrageConfigs(entries, person);
            else if (id == "KiBlast" || id == "KiBlastBarrage")
                AddBlastKiConfigs(entries, instance.GetComponent<BlastBehaviour>());
            else if (id == "FullForceKamehameha")
                AddBeamKiConfigs(entries, instance.GetComponent<BeamBehaviour>(), false);
            else if (type == CharacterPowers.PowerGroups.Beam)
                AddBeamKiConfigs(entries, instance.GetComponent<BeamBehaviour>());
            else if (id == "FinalExplosion")
                AddFinalExplosionConfigs(entries, instance.GetComponent<FinalExplosion>());
            else if (id == "SolarFlare")
                AddSolarConfigs(entries, instance.GetComponent<SolarFlare>());
            else if (id == "KiShield")
                AddShieldConfigs(entries, instance.GetComponent<KiShield>());
            else if (id == "HellzoneGranade")
                AddHellzoneConfigs(entries, instance.GetComponent<HellzoneGranade>());
            else if (type == CharacterPowers.PowerGroups.Ball || id == "GiganticCrusher")
                AddBallKiConfigs(entries, instance.GetComponent<BallBehaviour>());
            else if (id == "StardustFall")
            {
                var c = instance.GetComponent<StardustFall>();
                if (c != null)
                    AddGogetaSpecialConfigs(entries, () => c.DamageOutput, v => c.DamageOutput = v, () => c.KnockbackOutput, v => c.KnockbackOutput = v, () => c.blastsAmount, v => c.blastsAmount = v, () => c.durationSeconds, v => c.durationSeconds = v);
            }
            else if (id == "GodPunisher")
            {
                var c = instance.GetComponent<GodPunisher>();
                if (c != null)
                    AddGogetaSpecialConfigs(entries, () => c.DamageOutput, v => c.DamageOutput = v, () => c.KnockbackOutput, v => c.KnockbackOutput = v, () => c.blastsAmount, v => c.blastsAmount = v);
            }
            else if (id == "MeteorExplosion")
            {
                var c = instance.GetComponent<MeteorExplosion>();
                if (c != null)
                    AddGogetaSpecialConfigs(entries, () => c.DamageOutput, v => c.DamageOutput = v, () => c.KnockbackOutput, v => c.KnockbackOutput = v);
            }
            else if (id == "StardustBreaker")
            {
                var c = instance.GetComponent<StardustBreaker>();
                if (c != null)
                    AddGogetaSpecialConfigs(entries, () => c.DamageOutput, v => c.DamageOutput = v, () => c.KnockbackOutput, v => c.KnockbackOutput = v);
            }
            else if (id == "PunchPower")
                AddMeleePowerConfigs(entries, person, GetPunchPower(person), null);
            else if (id == "KickPower")
                AddMeleePowerConfigs(entries, person, null, GetKickPower(person));
            else if (id == "GreatNamekianGrowth" || type == CharacterPowers.PowerGroups.Growth)
                AddGrowthConfigs(entries, instance.GetComponent<PiccoloGiantForm>());
            else if (id == "Kaioken")
                AddKaiokenConfigs(entries, instance.GetComponent<Kaioken>());

            return WrapPage(entries);
        }
    }

    public class PowerMenuConfigSliderInteractor : MonoBehaviour, IPointerDownHandler, IDragHandler, IPointerUpHandler
    {
        public RectTransform trackRt;
        public RectTransform handleRt;
        public TextMeshProUGUI valueText;
        public float min;
        public float max;
        public float trackHalfW;
        public Func<float> readDisplay;
        public Action<float> writeDisplay;
        public Func<string> formatDisplay;
        public Action persist;

        bool _dirty;

        public void RefreshVisual()
        {
            if (readDisplay == null) return;
            float display = readDisplay();
            float t = max > min ? Mathf.Clamp01((display - min) / (max - min)) : 0f;
            if (handleRt != null)
                handleRt.anchoredPosition = new Vector2(-trackHalfW + t * trackHalfW * 2f, handleRt.anchoredPosition.y);
            if (valueText != null && formatDisplay != null)
                valueText.text = formatDisplay();
        }

        void ApplyFromEvent(PointerEventData e)
        {
            if (trackRt == null || writeDisplay == null) return;
            RectTransformUtility.ScreenPointToLocalPointInRectangle(trackRt, e.position, e.pressEventCamera, out Vector2 local);
            float half = Mathf.Max(0.5f, trackHalfW);
            float t = Mathf.Clamp01((local.x + half) / (half * 2f));
            writeDisplay(Mathf.Lerp(min, max, t));
            _dirty = true;
            RefreshVisual();
        }

        public void OnPointerDown(PointerEventData eventData) => ApplyFromEvent(eventData);
        public void OnDrag(PointerEventData eventData) => ApplyFromEvent(eventData);

        public void OnPointerUp(PointerEventData eventData)
        {
            if (!_dirty) return;
            _dirty = false;
            persist?.Invoke();
        }
    }

    static class PowerMenuConfigUI
    {
        static TMP_FontAsset _configFont;

        static List<PowerMenuConfigEntry> OrderPageEntries(List<PowerMenuConfigEntry> page)
        {
            var ordered = new List<PowerMenuConfigEntry>();
            if (page == null) return ordered;
            for (int i = 0; i < page.Count; i++)
                if (!(page[i] is PowerMenuConfigActionEntry))
                    ordered.Add(page[i]);
            for (int i = 0; i < page.Count; i++)
                if (page[i] is PowerMenuConfigActionEntry)
                    ordered.Add(page[i]);
            return ordered;
        }

        static float GetRenderedRowHeight(PowerMenuConfigEntry entry, PowerMenuLayoutConfig layout, float rowScale)
        {
            if (entry is PowerMenuConfigSliderEntry)
                return GetSliderStackHeight(layout, rowScale);
            return entry.GetRowHeight(layout) * rowScale;
        }

        static float SliderNameBarGap(PowerMenuLayoutConfig layout, float rowScale)
        {
            return Mathf.Max(0f, layout.configSliderNameBarGap) * rowScale;
        }

        static float GetConfigRowStep(PowerMenuConfigEntry entry, PowerMenuLayoutConfig layout, float rowScale)
        {
            return GetRenderedRowHeight(entry, layout, rowScale) + layout.configRowGap;
        }

        static float GetConfigRowsMaxHeight(PowerMenuLayoutConfig layout, float rowScale)
        {
            float panelHalfH = layout.illustration.targetH * 0.5f;
            float navScale = layout.configNavScale > 0.01f ? layout.configNavScale : 0.55f;
            Sprite navSprite = DBPU.PPrevious != null ? DBPU.PPrevious : DBPU.TPrevious;
            float navTop = layout.configNavY;
            if (navSprite != null)
                navTop += MenuUI.SpritePixels(navSprite).y * navScale * 0.5f;
            float bottomLimit = Mathf.Max(-panelHalfH, navTop + layout.configRowGap);
            return Mathf.Max(20f, layout.configTopY - bottomLimit - layout.configRowGap * 2f);
        }

        static void AddEntryToRowPages(List<List<PowerMenuConfigEntry>> result, ref List<PowerMenuConfigEntry> current, ref float currentH, PowerMenuConfigEntry entry, float step, float maxH)
        {
            if (current.Count > 0 && currentH + step > maxH)
            {
                result.Add(current);
                current = new List<PowerMenuConfigEntry>();
                currentH = 0f;
            }
            current.Add(entry);
            currentH += step;
        }

        static List<List<PowerMenuConfigEntry>> BuildConfigRowPages(List<PowerMenuConfigEntry> ordered, PowerMenuLayoutConfig layout, float rowScale)
        {
            var result = new List<List<PowerMenuConfigEntry>>();
            if (ordered == null || ordered.Count == 0)
            {
                result.Add(new List<PowerMenuConfigEntry>());
                return result;
            }

            float maxH = GetConfigRowsMaxHeight(layout, rowScale);
            var current = new List<PowerMenuConfigEntry>();
            float currentH = 0f;

            for (int i = 0; i < ordered.Count; i++)
            {
                float step = GetConfigRowStep(ordered[i], layout, rowScale);
                AddEntryToRowPages(result, ref current, ref currentH, ordered[i], step, maxH);
            }

            if (current.Count > 0)
                result.Add(current);

            return result;
        }

        static List<List<PowerMenuConfigEntry>> GetConfigRowPages(List<PowerMenuConfigEntry> page, PowerMenuLayoutConfig layout, float rowScale)
        {
            return BuildConfigRowPages(OrderPageEntries(page), layout, rowScale);
        }

        static int GetRowPageCount(List<PowerMenuConfigEntry> page, PowerMenuLayoutConfig layout, float rowScale)
        {
            return GetConfigRowPages(page, layout, rowScale).Count;
        }

        static List<PowerMenuConfigEntry> GetRowPageSlice(List<PowerMenuConfigEntry> page, int rowPage, PowerMenuLayoutConfig layout, float rowScale)
        {
            var rowPages = GetConfigRowPages(page, layout, rowScale);
            if (rowPage < 0 || rowPage >= rowPages.Count)
                return new List<PowerMenuConfigEntry>();
            return rowPages[rowPage];
        }

