        static GameObject PlaceSprite(Transform parent, string name, Sprite sprite, Vector2 pos, float uniform)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);
            MenuUI.ApplyImage(go, sprite, pos, uniform);
            return go;
        }

        static GameObject PlaceLocalSprite(Transform parent, string name, Sprite sprite, Vector2 localPos, float uniform)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);
            Image img = go.AddComponent<Image>();
            img.sprite = sprite;
            img.color = Color.white;
            RectTransform rt = go.GetComponent<RectTransform>();
            rt.anchoredPosition = localPos;
            rt.sizeDelta = MenuUI.SpritePixels(sprite);
            rt.localScale = new Vector3(uniform, uniform, 1f);
            return go;
        }

        static GameObject PlaceConfigBar(Transform parent, string name, Sprite sprite, Vector2 pos, float uniform)
        {
            GameObject go = PlaceSprite(parent, name, sprite, pos, uniform);
            MenuUI.DisableRaycast(go.GetComponent<Image>());
            return go;
        }

        static float GetConfigRowsLeftX(PowerMenuLayoutConfig layout)
        {
            Sprite prevSprite = DBPU.PPrevious != null ? DBPU.PPrevious : DBPU.TPrevious;
            float navScale = layout.configNavScale > 0.01f ? layout.configNavScale : 0.55f;
            float prevHalfW = MenuUI.SpritePixels(prevSprite).x * navScale * 0.5f;
            return layout.configPrevX - prevHalfW + layout.configRowsLeftOffset;
        }

        static float GetSliderRowCenterX(PowerMenuLayoutConfig layout, float rowScale)
        {
            float sliderW = MenuUI.SpritePixels(DBPU.PConfigTextSlider).x * rowScale;
            return GetConfigRowsLeftX(layout) + sliderW * 0.5f;
        }

        static float GetToggleBarCenterX(PowerMenuLayoutConfig layout, float rowScale)
        {
            float toggleW = MenuUI.SpritePixels(DBPU.PConfigTextToggle).x * rowScale;
            return GetConfigRowsLeftX(layout) + toggleW * 0.5f;
        }

        static TextMeshProUGUI PlaceRowText(Transform parent, string name, string text, Vector2 localPos, float fontSize, TextAlignmentOptions align, float boxW = 36f, bool autoFit = true)
        {
            GameObject go = new GameObject(name);
            go.transform.SetParent(parent, false);
            RectTransform rt = go.AddComponent<RectTransform>();
            rt.pivot = new Vector2(0.5f, 0.5f);
            rt.anchoredPosition = localPos;
            rt.sizeDelta = new Vector2(boxW, 10f);
            rt.localScale = Vector3.one;
            TextMeshProUGUI tmp = go.AddComponent<TextMeshProUGUI>();
            tmp.text = text;
            tmp.font = GetConfigFont();
            tmp.fontSize = fontSize;
            tmp.alignment = align;
            tmp.color = Color.black;
            tmp.enableWordWrapping = false;
            tmp.overflowMode = TextOverflowModes.Ellipsis;
            if (autoFit)
            {
                tmp.enableAutoSizing = true;
                tmp.fontSizeMin = 2f;
                tmp.fontSizeMax = fontSize;
            }
            tmp.raycastTarget = false;
            return tmp;
        }

        static float GetSliderStackHeight(PowerMenuLayoutConfig layout, float rowScale)
        {
            float gap = SliderNameBarGap(layout, rowScale);
            float nameH = MenuUI.SpritePixels(DBPU.PConfigTextSlider).y * rowScale;
            float valueH = MenuUI.SpritePixels(DBPU.PSliderValue).y * rowScale;
            return nameH + gap + valueH;
        }

        static void BuildSliderRow(GameObject rowGo, PowerMenuLayoutConfig layout, PowerMenuConfigSliderEntry slider, float rowScale, Action persist)
        {
            float gap = SliderNameBarGap(layout, rowScale);
            Vector2 namePx = MenuUI.SpritePixels(DBPU.PConfigTextSlider);
            Vector2 valuePx = MenuUI.SpritePixels(DBPU.PSliderValue);
            float nameH = namePx.y * rowScale;
            float valueH = valuePx.y * rowScale;
            float totalH = nameH + gap + valueH;
            float nameY = totalH * 0.5f - nameH * 0.5f;
            float bottomY = -totalH * 0.5f + valueH * 0.5f;

            GameObject nameBarGo = new GameObject("CfgNameBar");
            nameBarGo.transform.SetParent(rowGo.transform, false);
            Image nameImg = nameBarGo.AddComponent<Image>();
            nameImg.sprite = DBPU.PConfigTextSlider;
            nameImg.color = Color.white;
            nameImg.raycastTarget = false;
            RectTransform nameRt = nameBarGo.GetComponent<RectTransform>();
            nameRt.pivot = new Vector2(0.5f, 0.5f);
            nameRt.anchorMin = new Vector2(0.5f, 0.5f);
            nameRt.anchorMax = new Vector2(0.5f, 0.5f);
            nameRt.anchoredPosition = new Vector2(0f, nameY);
            nameRt.sizeDelta = namePx;
            nameRt.localScale = new Vector3(rowScale, rowScale, 1f);

            float nameSize = layout.configNameTextSize > 0.01f ? layout.configNameTextSize : 4f;
            float textPad = layout.configSliderNameTextInset > 0f ? layout.configSliderNameTextInset * 0.25f : 2f;
            float nameTextW = Mathf.Max(8f, namePx.x - textPad * 2f);
            PlaceRowText(nameBarGo.transform, "CfgNameText", slider.Name, Vector2.zero, nameSize, TextAlignmentOptions.Midline, nameTextW);

            float nameRenderedW = namePx.x * rowScale;
            float valueRenderedW = valuePx.x * rowScale;
            float rowLeftX = -nameRenderedW * 0.5f;
            float valueCenterX = rowLeftX + valueRenderedW * 0.5f;

            GameObject valueBarGo = new GameObject("CfgValueBar");
            valueBarGo.transform.SetParent(rowGo.transform, false);
            Image valueBarImg = valueBarGo.AddComponent<Image>();
            valueBarImg.sprite = DBPU.PSliderValue;
            valueBarImg.color = Color.white;
            valueBarImg.raycastTarget = false;
            RectTransform valueBarRt = valueBarGo.GetComponent<RectTransform>();
            valueBarRt.pivot = new Vector2(0.5f, 0.5f);
            valueBarRt.anchorMin = new Vector2(0.5f, 0.5f);
            valueBarRt.anchorMax = new Vector2(0.5f, 0.5f);
            valueBarRt.anchoredPosition = new Vector2(valueCenterX, bottomY);
            valueBarRt.sizeDelta = valuePx;
            valueBarRt.localScale = new Vector3(rowScale, rowScale, 1f);

            float valueSize = layout.configValueTextSize > 0.01f ? layout.configValueTextSize : 3.5f;
            float valueTextW = Mathf.Max(4f, valuePx.x - 2f);
            TextMeshProUGUI valueTmp = PlaceRowText(valueBarGo.transform, "CfgValueText", slider.FormatDisplay(slider.ReadDisplay()), Vector2.zero, valueSize, TextAlignmentOptions.Center, valueTextW, false);

            float handleScale = layout.configSliderLocalHandleScale;
            float slotW = layout.configSliderHitW;
            float slotH = layout.configSliderHitH;
            float halfW = slotW * 0.5f;
            float trackGap = layout.configSliderValueToTrackGap;
            float trackCenterX = rowLeftX + valueRenderedW + trackGap + halfW;

            GameObject slotGo = new GameObject("CfgSliderSlot");
            slotGo.transform.SetParent(rowGo.transform, false);
            RectTransform slotRt = slotGo.AddComponent<RectTransform>();
            slotRt.anchoredPosition = new Vector2(trackCenterX, bottomY + layout.configSliderLocalTrackY);
            slotRt.sizeDelta = new Vector2(slotW, slotH);
            slotRt.localScale = Vector3.one;

            GameObject trackGo = new GameObject("CfgTrack");
            trackGo.transform.SetParent(slotGo.transform, false);
            Image trackImg = trackGo.AddComponent<Image>();
            trackImg.sprite = DBPU.PSliderBar;
            trackImg.color = Color.white;
            trackImg.raycastTarget = false;
            RectTransform trackRt = trackGo.GetComponent<RectTransform>();
            trackRt.anchoredPosition = Vector2.zero;
            trackRt.sizeDelta = new Vector2(slotW, MenuUI.SpritePixels(DBPU.PSliderBar).y);

            float display = slider.ReadDisplay();
            float t = slider.Max > slider.Min ? Mathf.Clamp01((display - slider.Min) / (slider.Max - slider.Min)) : 0f;
            float handleX = -halfW + t * slotW;
            GameObject handleGo = PlaceLocalSprite(slotGo.transform, "CfgHandle", DBPU.PSliderHandle, new Vector2(handleX, 0f), handleScale);
            MenuUI.DisableRaycast(handleGo.GetComponent<Image>());

            GameObject hitGo = new GameObject("CfgSliderHit");
            hitGo.transform.SetParent(slotGo.transform, false);
            RectTransform hitRt = hitGo.AddComponent<RectTransform>();
            hitRt.anchorMin = Vector2.zero;
            hitRt.anchorMax = Vector2.one;
            hitRt.offsetMin = Vector2.zero;
            hitRt.offsetMax = Vector2.zero;
            hitRt.localScale = Vector3.one;
            Image hitImg = hitGo.AddComponent<Image>();
            hitImg.color = new Color(0f, 0f, 0f, 0f);
            hitImg.raycastTarget = true;

            var interactor = hitGo.AddComponent<PowerMenuConfigSliderInteractor>();
            interactor.trackRt = slotRt;
            interactor.handleRt = handleGo.GetComponent<RectTransform>();
            interactor.valueText = valueTmp;
            interactor.min = slider.Min;
            interactor.max = slider.Max;
            interactor.trackHalfW = halfW;
            interactor.readDisplay = slider.ReadDisplay;
            interactor.writeDisplay = v => slider.WriteDisplay(Mathf.Clamp(v, slider.Min, slider.Max));
            interactor.formatDisplay = () => slider.FormatDisplay(slider.ReadDisplay());
            interactor.persist = persist;
            interactor.RefreshVisual();
            hitGo.transform.SetAsLastSibling();
        }

        static void RefreshConfigPageValues(Transform rowsHolder, List<PowerMenuConfigEntry> page)
        {
            if (rowsHolder == null || page == null) return;
            int count = Mathf.Min(rowsHolder.childCount, page.Count);
            for (int row = 0; row < count; row++)
            {
                var entry = page[row];
                Transform bar = rowsHolder.GetChild(row);
                if (entry is PowerMenuConfigToggleEntry toggle)
                {
                    Transform stateTr = bar.Find("CfgState");
                    if (stateTr == null) continue;
                    Image stateImg = stateTr.GetComponent<Image>();
                    if (stateImg == null) continue;
                    bool state = toggle.GetValue != null && toggle.GetValue();
                    stateImg.sprite = state ? DBPU.PGreenButton : DBPU.PRedButton;
                }
                else if (entry is PowerMenuConfigSliderEntry)
                {
                    Transform hitTr = bar.Find("CfgSliderSlot/CfgSliderHit");
                    if (hitTr == null) continue;
                    var interactor = hitTr.GetComponent<PowerMenuConfigSliderInteractor>();
                    if (interactor != null) interactor.RefreshVisual();
                }
            }
        }

        static void PlaceBarClickAction(GameObject barGo, Action onClick)
        {
            GameObject hitGo = new GameObject("CfgActionHit");
            hitGo.transform.SetParent(barGo.transform, false);
            RectTransform hitRt = hitGo.AddComponent<RectTransform>();
            hitRt.anchorMin = Vector2.zero;
            hitRt.anchorMax = Vector2.one;
            hitRt.offsetMin = Vector2.zero;
            hitRt.offsetMax = Vector2.zero;
            hitRt.localScale = Vector3.one;
            Image hitImg = hitGo.AddComponent<Image>();
            hitImg.color = new Color(0f, 0f, 0f, 0f);
            hitImg.raycastTarget = true;
            Button btn = hitGo.AddComponent<Button>();
            btn.transition = Selectable.Transition.None;
            btn.onClick.AddListener(() => onClick?.Invoke());
            hitGo.transform.SetAsFirstSibling();
        }

        static Sprite GetSelectFrameSprite(PowerMenuConfigEntry entry)
        {
            if (entry is PowerMenuConfigSliderEntry)
                return DBPU.PConfigTextSliderSel;
            return DBPU.PConfigTextToggleSel;
        }

        static Transform GetSelectFrameParent(Transform rowBar, PowerMenuConfigEntry entry)
        {
            if (entry is PowerMenuConfigSliderEntry)
            {
                Transform nameBar = rowBar.Find("CfgNameBar");
                if (nameBar != null) return nameBar;
            }
            return rowBar;
        }

        static void SetBarSelectFrame(Transform barGo, bool selected, Sprite frameSprite)
        {
            Transform existing = barGo.Find("SelectFrame");
            if (!selected)
            {
                if (existing != null) GameObject.Destroy(existing.gameObject);
                return;
            }
            if (existing != null) return;
            GameObject selGo = new GameObject("SelectFrame");
            selGo.transform.SetParent(barGo, false);
            MenuUI.ApplyImage(selGo, frameSprite, Vector2.zero, 1f);
            MenuUI.DisableRaycast(selGo.GetComponent<Image>());
            selGo.transform.SetAsLastSibling();
        }

        static void RefreshSelectFrames(Transform rowsHolder, List<PowerMenuConfigEntry> page, string selectedId)
        {
            if (rowsHolder == null || page == null) return;
            int count = Mathf.Min(rowsHolder.childCount, page.Count);
            for (int row = 0; row < count; row++)
            {
                var entry = page[row];
                Transform bar = rowsHolder.GetChild(row);
                bool sel = !string.IsNullOrEmpty(selectedId) && entry.ID == selectedId;
                SetBarSelectFrame(GetSelectFrameParent(bar, entry), sel, GetSelectFrameSprite(entry));
            }
        }

        public static BuildResult Build(Transform canvasParent, PowerMenuLayoutConfig layout, PhysicalBehaviour phys, TextMeshProUGUI infoNameText, TextMeshProUGUI infoDescText, Func<List<List<PowerMenuConfigEntry>>> getPages)
        {
            GameObject root = new GameObject("ConfigPanel");
            root.transform.SetParent(canvasParent, false);
            RectTransform rootRt = root.AddComponent<RectTransform>();
            rootRt.anchoredPosition = new Vector2(layout.illustration.x + layout.configPanelOffsetX, layout.illustration.y);
            rootRt.sizeDelta = new Vector2(layout.illustration.targetW, layout.illustration.targetH);
            root.SetActive(false);

            GameObject rowsHolder = new GameObject("ConfigRows");
            rowsHolder.transform.SetParent(root.transform, false);
            RectTransform rowsHolderRt = rowsHolder.AddComponent<RectTransform>();
            rowsHolderRt.anchoredPosition = new Vector2(layout.configRowsOffsetX, layout.configRowsOffsetY);

            List<List<PowerMenuConfigEntry>> pages = getPages != null ? getPages() : new List<List<PowerMenuConfigEntry>>();
            int configPage = 0;
            int configRowPage = 0;
            float rowScale = layout.configRowScale > 0.01f ? layout.configRowScale : 0.9f;

            Image prevNavImg = null;
            Image nextNavImg = null;
            TextMeshProUGUI configPageLabel = null;
            string selectedEntryId = null;

            Action clearSelection = () =>
            {
                selectedEntryId = null;
                if (infoDescText != null) infoDescText.text = "";
            };

            Action<PowerMenuConfigEntry> showEntryInfo = (entry) =>
            {
                if (entry == null) return;
                if (infoDescText != null) infoDescText.text = entry.Description ?? entry.Name ?? "";
            };

            List<PowerMenuConfigEntry> currentRowPage = new List<PowerMenuConfigEntry>();

            Action<PowerMenuConfigEntry> selectEntry = (entry) =>
            {
                if (entry == null) return;
                selectedEntryId = entry.ID;
                showEntryInfo(entry);
                RefreshSelectFrames(rowsHolder.transform, currentRowPage, selectedEntryId);
            };

            Action reloadPages = () =>
            {
                pages = getPages != null ? getPages() : new List<List<PowerMenuConfigEntry>>();
                if (configPage >= pages.Count) configPage = Mathf.Max(0, pages.Count - 1);
                if (configPage < 0) configPage = 0;
                configRowPage = 0;
            };

            Action rebuildPage = null;
            rebuildPage = () =>
            {
                for (int i = rowsHolder.transform.childCount - 1; i >= 0; i--)
                    GameObject.Destroy(rowsHolder.transform.GetChild(i).gameObject);

                if (pages == null || pages.Count == 0)
                {
                    if (infoDescText != null) infoDescText.text = "This power has no configurable options.";
                    return;
                }

                if (configPage < 0 || configPage >= pages.Count) return;

                var fullPage = OrderPageEntries(pages[configPage]);
                int rowPageCount = GetRowPageCount(fullPage, layout, rowScale);
                if (configRowPage >= rowPageCount) configRowPage = rowPageCount - 1;
                if (configRowPage < 0) configRowPage = 0;
                var page = GetRowPageSlice(pages[configPage], configRowPage, layout, rowScale);
                currentRowPage = page;

                float rowTopY = layout.configTopY;

                for (int row = 0; row < page.Count; row++)
                {
                    var entry = page[row];
                    float rowH = GetRenderedRowHeight(entry, layout, rowScale);
                    float rowCenterY = rowTopY - rowH * 0.5f;

                    if (entry is PowerMenuConfigToggleEntry toggle)
                    {
                        GameObject barGo = PlaceConfigBar(rowsHolder.transform, "CfgBar" + row, DBPU.PConfigTextToggle, new Vector2(GetToggleBarCenterX(layout, rowScale), rowCenterY), rowScale);
                        float nameSize = layout.configNameTextSize > 0.01f ? layout.configNameTextSize : 4f;
                        float toggleBarHalfW = MenuUI.SpritePixels(DBPU.PConfigTextToggle).x * 0.5f;
                        float toggleNameLeftX = -toggleBarHalfW + 1f;
                        float toggleNameRightX = layout.configToggleLocalStateX - 2f;
                        float toggleTextW = Mathf.Max(8f, toggleNameRightX - toggleNameLeftX);
                        float toggleTextX = (toggleNameLeftX + toggleNameRightX) * 0.5f;
                        PlaceRowText(barGo.transform, "CfgNameText", toggle.Name, new Vector2(toggleTextX, 0f), nameSize, TextAlignmentOptions.Midline, toggleTextW);
                        var toggleEntry = toggle;
                        PlaceBarClickAction(barGo, () => selectEntry(toggleEntry));

                        bool state = toggle.GetValue != null && toggle.GetValue();
                        float stateY = layout.configToggleLocalStateY;
                        GameObject stateGo = PlaceLocalSprite(barGo.transform, "CfgState", state ? DBPU.PGreenButton : DBPU.PRedButton, new Vector2(layout.configToggleLocalStateX, stateY), 0.95f);
                        Button stateBtn = stateGo.AddComponent<Button>();
                        stateBtn.transition = Selectable.Transition.None;
                        string toggleId = toggle.ID;
                        stateBtn.onClick.AddListener(() =>
                        {
                            toggle.Toggle();
                            rebuildPage();
                        });
                    }
                    else if (entry is PowerMenuConfigSliderEntry slider)
                    {
                        Vector2 namePx = MenuUI.SpritePixels(DBPU.PConfigTextSlider);
                        float stackH = rowH;

                        GameObject rowGo = new GameObject("CfgBar" + row);
                        rowGo.transform.SetParent(rowsHolder.transform, false);
                        RectTransform rowRt = rowGo.AddComponent<RectTransform>();
                        rowRt.anchoredPosition = new Vector2(GetSliderRowCenterX(layout, rowScale), rowCenterY);
                        rowRt.sizeDelta = new Vector2(namePx.x * rowScale, stackH);
                        BuildSliderRow(rowGo, layout, slider, rowScale, null);
                        var sliderEntry = slider;
                        Transform nameBar = rowGo.transform.Find("CfgNameBar");
                        if (nameBar != null)
                            PlaceBarClickAction(nameBar.gameObject, () => selectEntry(sliderEntry));
                    }
                    else if (entry is PowerMenuConfigActionEntry action)
                    {
                        GameObject barGo = PlaceConfigBar(rowsHolder.transform, "CfgBar" + row, DBPU.PConfigTextToggle, new Vector2(GetToggleBarCenterX(layout, rowScale), rowCenterY), rowScale);
                        float actionNameSize = layout.configNameTextSize > 0.01f ? layout.configNameTextSize : 4f;
                        float actionTextW = Mathf.Max(8f, MenuUI.SpritePixels(DBPU.PConfigTextToggle).x - 2f);
                        PlaceRowText(barGo.transform, "CfgActionText", action.Name, new Vector2(0f, 0f), actionNameSize, TextAlignmentOptions.Midline, actionTextW);

                        string actionId = action.ID;
                        var actionEntry = action;
                        PlaceBarClickAction(barGo, () =>
                        {
                            selectEntry(actionEntry);
                            action.OnClick?.Invoke();
                            RefreshConfigPageValues(rowsHolder.transform, page);
                        });
                    }

                    rowTopY -= GetConfigRowStep(entry, layout, rowScale);
                }

                if (prevNavImg != null)
                {
                    bool canPrev = configPage > 0 || configRowPage > 0;
                    bool canNext = configPage < pages.Count - 1 || configRowPage < rowPageCount - 1;
                    prevNavImg.color = canPrev ? Color.white : new Color(1f, 1f, 1f, 0.35f);
                    nextNavImg.color = canNext ? Color.white : new Color(1f, 1f, 1f, 0.35f);
                }

                if (configPageLabel != null)
                {
                    if (rowPageCount > 1)
                    {
                        configPageLabel.gameObject.SetActive(true);
                        configPageLabel.text = (configRowPage + 1) + " / " + rowPageCount;
                    }
                    else
                        configPageLabel.gameObject.SetActive(false);
                }

                RefreshSelectFrames(rowsHolder.transform, page, selectedEntryId);
            };

            Sprite prevSprite = DBPU.PPrevious != null ? DBPU.PPrevious : DBPU.TPrevious;
            Sprite nextSprite = DBPU.PNext != null ? DBPU.PNext : DBPU.TNext;
            GameObject cfgPrev = PlaceSprite(root.transform, "ConfigPrev", prevSprite, new Vector2(layout.configPrevX, layout.configNavY), layout.configNavScale);
            prevNavImg = cfgPrev.GetComponent<Image>();
            cfgPrev.AddComponent<Button>().onClick.AddListener(() =>
            {
                if (configRowPage > 0)
                {
                    configRowPage--;
                }
                else if (configPage > 0)
                {
                    configPage--;
                    configRowPage = GetRowPageCount(OrderPageEntries(pages[configPage]), layout, rowScale) - 1;
                }
                else return;
                clearSelection();
                rebuildPage();
            });

            GameObject cfgNext = PlaceSprite(root.transform, "ConfigNext", nextSprite, new Vector2(layout.configNextX, layout.configNavY), layout.configNavScale);
            nextNavImg = cfgNext.GetComponent<Image>();

            GameObject cfgPageLabelGo = new GameObject("ConfigPageLabel");
            cfgPageLabelGo.transform.SetParent(root.transform, false);
            RectTransform cfgPageLabelRt = cfgPageLabelGo.AddComponent<RectTransform>();
            cfgPageLabelRt.anchoredPosition = new Vector2((layout.configPrevX + layout.configNextX) * 0.5f, layout.configNavY + 6f);
            cfgPageLabelRt.sizeDelta = new Vector2(24f, 8f);
            configPageLabel = cfgPageLabelGo.AddComponent<TextMeshProUGUI>();
            configPageLabel.font = GetConfigFont();
            configPageLabel.fontSize = 5;
            configPageLabel.alignment = TextAlignmentOptions.Center;
            configPageLabel.color = Color.black;
            configPageLabel.raycastTarget = false;
            configPageLabel.gameObject.SetActive(false);

            cfgNext.AddComponent<Button>().onClick.AddListener(() =>
            {
                var fullPage = OrderPageEntries(pages[configPage]);
                int rowPageCount = GetRowPageCount(fullPage, layout, rowScale);
                if (configRowPage < rowPageCount - 1)
                {
                    configRowPage++;
                }
                else if (configPage < pages.Count - 1)
                {
                    configPage++;
                    configRowPage = 0;
                }
                else return;
                clearSelection();
                rebuildPage();
            });

            Action selectFirstEntry = () =>
            {
                if (configPage < 0 || configPage >= pages.Count) return;
                var page = GetRowPageSlice(pages[configPage], configRowPage, layout, rowScale);
                if (page.Count > 0) selectEntry(page[0]);
            };

            Action refreshAll = () =>
            {
                reloadPages();
                rebuildPage();
            };

            refreshAll();

            return new BuildResult { Root = root, Refresh = refreshAll, ClearSelection = clearSelection, SelectFirstEntry = selectFirstEntry };
        }
    }

    public class ModMenuDragResize : MonoBehaviour, IPointerDownHandler, IDragHandler
    {
        public enum ResizeCorner { BottomRight, BottomLeft, TopRight, TopLeft }

        public bool resize;
        public ResizeCorner resizeCorner = ResizeCorner.BottomRight;
        public RectTransform moveRoot;
        public float minUniform = 5f;
        public float maxUniform = 18f;
        public Func<float> getUniform;
        public Action<float> setUniform;

        Vector2 _startScreen;
        Vector2 _startAnchoredPos;
        float _startUniform;

        public void OnPointerDown(PointerEventData eventData)
        {
            _startScreen = eventData.position;
            if (resize)
                _startUniform = getUniform != null ? getUniform() : 1f;
            else if (moveRoot != null)
                _startAnchoredPos = moveRoot.anchoredPosition;
        }

        float GetResizeDragDelta(Vector2 screenDelta)
        {
            switch (resizeCorner)
            {
                case ResizeCorner.BottomRight:
                    return screenDelta.x - screenDelta.y;

                case ResizeCorner.BottomLeft:
                    return -screenDelta.x - screenDelta.y;

                case ResizeCorner.TopRight:
                    return screenDelta.x + screenDelta.y;

                case ResizeCorner.TopLeft:
                    return -screenDelta.x + screenDelta.y;

                default:
                    return screenDelta.x + screenDelta.y;
            }
        }

        public void OnDrag(PointerEventData eventData)
        {
            if (resize)
            {
                if (setUniform == null) return;
                Vector2 screenDelta = eventData.position - _startScreen;
                float delta = GetResizeDragDelta(screenDelta) * 0.012f;
                setUniform(Mathf.Clamp(_startUniform + delta, minUniform, maxUniform));
                return;
            }

            if (moveRoot == null || moveRoot.parent == null) return;
            var parentRt = moveRoot.parent as RectTransform;
            if (parentRt == null) return;
            RectTransformUtility.ScreenPointToLocalPointInRectangle(parentRt, eventData.position, eventData.pressEventCamera, out Vector2 localNow);
            RectTransformUtility.ScreenPointToLocalPointInRectangle(parentRt, _startScreen, eventData.pressEventCamera, out Vector2 localStart);
            moveRoot.anchoredPosition = _startAnchoredPos + (localNow - localStart);
        }
    }

    public class PowerContextMenu : MonoBehaviour
    {
        public const int PowersPerPage = 9;

        public PersonBehaviour person;
        public CharacterPowers PowersData;

        public GameObject FramesHolder;
        private readonly List<Vector2> FramesPos = new List<Vector2>();

        public int PositionSelectedFrame = 0;
        public int PowerSelected = 0;
        private int LocalSelectedFrame = 0;
        private int Pages = 0;
        private int CurrentPage = 0;
        private int PreviousPage = 0;
        private bool MenuOpen = false;

        static TMP_FontAsset MenuFont;

        static TMP_FontAsset GetMenuFont()
        {
            if (MenuFont == null)
                MenuFont = ModAPI.FindSpawnable("Holographic Display").Prefab.transform.Find("Text").GetComponent<TextMeshPro>().font;
            return MenuFont;
        }

        void RecalculatePages()
        {
            int count = PowersData != null ? PowersData.PowerOrder.Count : 0;
            Pages = count <= PowersPerPage ? 0 : Mathf.CeilToInt(count / (float)PowersPerPage) - 1;
        }

        static void SetupPowerPageNavButton(GameObject go, Sprite sprite, Vector2 anchoredPos, Vector2 scale)
        {
            Image img = go.GetOrAddComponent<Image>();
            img.sprite = sprite;
            img.raycastTarget = true;
            img.color = Color.white;
            RectTransform rt = go.GetComponent<RectTransform>();
            rt.anchoredPosition = anchoredPos;
            rt.sizeDelta = MenuUI.SpritePixels(sprite);
            rt.localScale = new Vector3(scale.x, scale.y, 1f);
            if (go.GetComponent<Button>() == null)
                go.AddComponent<Button>();
        }

        public void Start()
        {
            RecalculatePages();
        }

        static void GetGridInnerSize(PowerMenuLayoutConfig layout, float panelW, float panelH, out float innerW, out float innerH)
        {
            float holderScale = layout.framesHolderScale > 0.01f ? layout.framesHolderScale : 1f;
            innerW = panelW / holderScale - layout.gridEdgePaddingX * 2f;
            innerH = panelH / holderScale - layout.gridEdgePaddingY * 2f;
        }

        void BuildGridPositions(PowerMenuLayoutConfig layout, float panelW = 0f, float panelH = 0f)
        {
            FramesPos.Clear();
            float cx = layout.gridCenterX;
            float cy = layout.gridCenterY;
            if (layout.gridAlignToCenterCanvas)
            {
                cx = 0f;
                cy = 0f;
            }

            float innerW = 0f;
            float innerH = 0f;
            if (panelW > 1f && panelH > 1f)
                GetGridInnerSize(layout, panelW, panelH, out innerW, out innerH);

            layout.GetGridSteps(out float colStep, out float rowStep, innerW, innerH);
            float[] gridY;
            if (layout.gridAlignToCenterCanvas)
            {
                if (!layout.gridAutoFitSlots)
                    rowStep = layout.gridRowSpacing;
                gridY = new float[] { cy + rowStep, cy, cy - rowStep };
            }
            else
                gridY = new float[] { layout.gridRow0Y, layout.gridRow1Y, layout.gridRow2Y };

            for (int row = 0; row < 3; row++)
            {
                for (int col = 0; col < 3; col++)
                    FramesPos.Add(new Vector2(cx - colStep + col * colStep, gridY[row]));
            }
        }

        public void Awake()
        {
            PowerMenuLayoutConfig.Load();
            BuildGridPositions(PowerMenuLayoutConfig.Active);

            var contextButtons = gameObject.GetComponent<PhysicalBehaviour>().ContextMenuOptions;
            MCP_Utils.AddContextButtonInOrder(contextButtons, new ContextMenuButton("!PowersMenu", "Powers Menu", "Powers Menu", () => OpenPowersMenu()), 0);
        }

        public static PowerContextMenu GetForSelectedLimb()
        {
            var selection = SelectionController.Main;
            if (selection != null && selection.SelectedObjects != null)
            {
                foreach (PhysicalBehaviour selected in selection.SelectedObjects)
                {
                    var menu = FindPowerMenuFromPhysical(selected);
                    if (menu != null) return menu;
                }
            }

            var tool = Global.main?.ToolControllerBehaviour?.CurrentTool;
            if (tool != null && tool.ActiveSingleSelected != null)
            {
                var menu = FindPowerMenuFromPhysical(tool.ActiveSingleSelected);
                if (menu != null) return menu;
            }

            if (selection != null && selection.CurrentlyUnderMouse != null)
                return FindPowerMenuFromPhysical(selection.CurrentlyUnderMouse);

            return null;
        }

        static PowerContextMenu FindPowerMenuFromPhysical(PhysicalBehaviour pb)
        {
            if (pb == null) return null;

            var limb = pb.GetComponent<LimbBehaviour>();
            if (limb != null && limb.Person != null && limb.Person.Limbs != null && limb.Person.Limbs.Length > 0)
                return limb.Person.Limbs[0].GetComponent<PowerContextMenu>();

            var person = pb.GetComponent<PersonBehaviour>() ?? pb.transform.root.GetComponent<PersonBehaviour>();
            if (person == null || person.Limbs == null || person.Limbs.Length == 0) return null;

            for (int i = 0; i < person.Limbs.Length; i++)
            {
                if (person.Limbs[i] != null && person.Limbs[i].gameObject == pb.gameObject)
                    return person.Limbs[0].GetComponent<PowerContextMenu>();
            }

            return null;
        }

        public void OpenPowersMenu()
        {
                if (MenuOpen || PowersData == null) return;

                PowerSetup.RegisterUniversalPhysicalPowers(PowersData, person);
                PowersData.HarvestPowerStates();
                RecalculatePages();
                MenuOpen = true;
                PreviousPage = CurrentPage;
                if (CurrentPage < 0) CurrentPage = 0;
                if (CurrentPage > Pages) CurrentPage = Pages;

                var powerList = PowersData.GetOrderedPowers();
                if (powerList.Count == 0)
                {
                    MenuOpen = false;
                    return;
                }

                int idx = Mathf.Clamp(PositionSelectedFrame + (PowersPerPage * CurrentPage), 0, powerList.Count - 1);
                PositionSelectedFrame = Mathf.Clamp(PositionSelectedFrame, 0, PowersPerPage - 1);
                var firstValue = powerList[idx];
                PowerSelected = idx;
                LocalSelectedFrame = idx - (PowersPerPage * CurrentPage);

                PowerMenuLayoutConfig layout = new PowerMenuLayoutConfig();
                PowerMenuLayoutConfig.Active = layout;

                GameObject Canvas = new GameObject("PCanvas");
                Canvas.transform.SetParent(GameObject.Find("Canvas").transform);
                Image canvasBg = Canvas.GetOrAddComponent<Image>();
                canvasBg.color = Color.clear;
                canvasBg.raycastTarget = false;
                Canvas.GetComponent<RectTransform>().anchoredPosition = Vector2.zero;
                float rootUniform = layout.menuRootUniform;
                Canvas.GetComponent<RectTransform>().localScale = new Vector3(rootUniform, rootUniform, 1f);
                Canvas.AddComponent<ExistIf>().obj = gameObject;

                GameObject centerCanvas = layout.CreateElement(Canvas.transform, "CenterCanvas", DBPU.PCanvas, layout.centerCanvas);
                MenuUI.DisableRaycast(centerCanvas.GetComponent<Image>());
                centerCanvas.transform.SetAsFirstSibling();
                Vector2 panelSize = MenuUI.GetRenderedSize(centerCanvas.GetComponent<RectTransform>());
                layout.ApplyAutoSlotSizing(panelSize.x, panelSize.y);
                BuildGridPositions(layout, panelSize.x, panelSize.y);

                GameObject PowersTitleText = new GameObject("Powers Title Text");
                PowersTitleText.transform.SetParent(centerCanvas.transform, false);
                RectTransform powersTitleRt = PowersTitleText.AddComponent<RectTransform>();
                layout.ApplyMenuTextLocalRect(
                    powersTitleRt,
                    layout.powersTitleLocalX, layout.powersTitleLocalY, layout.powersTitleLocalZ,
                    layout.powersTitleTextW, layout.powersTitleTextH);
                float titleScale = layout.powersTitleLocalScale > 0.01f ? layout.powersTitleLocalScale : 1f;
                powersTitleRt.localScale = new Vector3(titleScale, titleScale, 1f);
                TextMeshProUGUI powersTitleLabel = PowersTitleText.AddComponent<TextMeshProUGUI>();
                powersTitleLabel.text = "Powers";
                powersTitleLabel.fontSize = 10;
                powersTitleLabel.enableAutoSizing = false;
                powersTitleLabel.raycastTarget = false;
                powersTitleLabel.font = GetMenuFont();
                powersTitleLabel.alignment = TextAlignmentOptions.Center;
                powersTitleLabel.color = Color.black;
                MenuUI.ConfigureTitleDragArea(PowersTitleText, Canvas.GetComponent<RectTransform>(), new Vector2(80f, 14f));

                Transform gridParent = centerCanvas.transform;
                FramesHolder = new GameObject("FramesHolder");
                FramesHolder.transform.SetParent(gridParent, false);
                layout.ApplyFramesHolderTransform(FramesHolder.AddComponent<RectTransform>());

                GameObject illustrationGo = layout.CreateElement(Canvas.transform, "Illustration", DBPU.PIllustration, layout.illustration);

                GameObject Info = layout.CreateElement(Canvas.transform, "Info", DBPU.PInfo, layout.info);

                GameObject InfoNameText = new GameObject("Info Name Text");
                InfoNameText.transform.SetParent(Info.transform, false);
                layout.ApplyMenuTextLocalRect(
                    InfoNameText.AddComponent<RectTransform>(),
                    layout.infoNameLocalX, layout.infoNameLocalY, layout.infoNameLocalZ,
                    layout.infoNameTextW, layout.infoNameTextH);
                TextMeshProUGUI InfoNameTextStorage = InfoNameText.AddComponent<TextMeshProUGUI>();
                InfoNameTextStorage.text = firstValue.Name;
                InfoNameTextStorage.fontSize = 8;
                InfoNameTextStorage.enableAutoSizing = false;
                InfoNameTextStorage.raycastTarget = false;
                InfoNameTextStorage.font = GetMenuFont();
                InfoNameTextStorage.alignment = TextAlignmentOptions.Center;
                InfoNameTextStorage.color = Color.black;

                GameObject InfoDescriptionText = new GameObject("Info Description Text");
                InfoDescriptionText.transform.SetParent(Info.transform, false);
                RectTransform descRt = InfoDescriptionText.AddComponent<RectTransform>();
                layout.ApplyMenuTextLocalRect(
                    descRt,
                    layout.infoDescLocalX, layout.infoDescLocalY, layout.infoDescLocalZ,
                    layout.infoDescTextW, layout.infoDescTextH);
                float descScale = layout.infoDescLocalScale > 0.01f ? layout.infoDescLocalScale : 1f;
                descRt.localScale = new Vector3(descScale, descScale, 1f);
                TextMeshProUGUI InfoDescriptionTextStorage = InfoDescriptionText.AddComponent<TextMeshProUGUI>();
                InfoDescriptionTextStorage.text = firstValue.Description;
                InfoDescriptionTextStorage.fontSize = 4;
                InfoDescriptionTextStorage.font = GetMenuFont();
                InfoDescriptionTextStorage.alignment = TextAlignmentOptions.TopLeft;
                InfoDescriptionTextStorage.enableWordWrapping = true;
                InfoDescriptionTextStorage.color = Color.black;
                InfoDescriptionTextStorage.raycastTarget = false;

                float frameUniform = layout.GetFrameUniformScale();

                GameObject SelectFrame = new GameObject("SelectFrame");
                SelectFrame.transform.SetParent(FramesHolder.transform, false);
                MenuUI.ApplyImage(SelectFrame, DBPU.PSelectFrame, FramesPos[Mathf.Clamp(LocalSelectedFrame, 0, FramesPos.Count - 1)], frameUniform);
                MenuUI.DisableRaycast(SelectFrame.GetComponent<Image>());

                GameObject CloseBtn = layout.CreateElement(Canvas.transform, "Close", DBPU.PCloseButton, layout.close);
                CloseBtn.AddComponent<Button>().onClick.AddListener(() =>
                {
                    MenuOpen = false;
                    CurrentPage = PreviousPage;
                    PositionSelectedFrame = LocalSelectedFrame;
                    Destroy(Canvas);
                });

                Sprite initialOnOffSprite = firstValue.Passive ? DBPU.PButtonIdle
                    : (firstValue.Active ? DBPU.PButtonOn : DBPU.PButtonOff);
                GameObject OnOffBtn = layout.CreateElement(Canvas.transform, "OnOff", initialOnOffSprite, layout.onOff);
                Image onOffImg = OnOffBtn.GetComponent<Image>();
                Button onOffButton = OnOffBtn.AddComponent<Button>();

                layout.pageArea.y = layout.onOff.y;
                GameObject PageArea = layout.CreateElement(Canvas.transform, "PageArea", DBPU.PPageArea, layout.pageArea);

                layout.ApplyConfigTabPlacement();
                GameObject TabBtn = layout.CreateElement(Canvas.transform, "MenuTab", DBPU.PConfigsTabButton, layout.configTab);
                Image tabBtnImg = TabBtn.GetComponent<Image>();
                Button tabBtn = TabBtn.AddComponent<Button>();

                GameObject powerInstance = PowersData != null ? PowersData.gameObject : person.gameObject;
                Func<List<List<PowerMenuConfigEntry>>> getPowerConfigPages = () =>
                {
                    if (PowerSelected < 0 || PowerSelected >= powerList.Count)
                        return new List<List<PowerMenuConfigEntry>>();
                    return PowerMenuConfigData.GetPowerPages(powerList[PowerSelected], powerInstance, person);
                };

                var configUi = PowerMenuConfigUI.Build(
                    Canvas.transform,
                    layout,
                    gameObject.GetComponent<PhysicalBehaviour>(),
                    InfoNameTextStorage,
                    InfoDescriptionTextStorage,
                    getPowerConfigPages);
                GameObject configPanelRoot = configUi.Root;

                bool showingConfig = false;
                GameObject prevNavGo = null;
                GameObject nextNavGo = null;

                Action setTabSprite = () =>
                {
                    Sprite tabSprite = showingConfig ? DBPU.PPowerTabButton : DBPU.PConfigsTabButton;
                    layout.RefreshElement(TabBtn, tabSprite, layout.configTab);
                    tabBtnImg = TabBtn.GetComponent<Image>();
                };

                Action bringTabToFront = () => TabBtn.transform.SetAsLastSibling();

                Action applyPowersView = () =>
                {
                    showingConfig = false;
                    setTabSprite();
                    illustrationGo.SetActive(true);
                    configPanelRoot.SetActive(false);
                    if (PowerSelected >= 0 && PowerSelected < powerList.Count)
                    {
                        InfoNameTextStorage.text = powerList[PowerSelected].Name;
                        InfoDescriptionTextStorage.text = powerList[PowerSelected].Description;
                    }
                    bringTabToFront();
                };

                Action applyConfigView = () =>
                {
                    showingConfig = true;
                    setTabSprite();
                    illustrationGo.SetActive(false);
                    configPanelRoot.SetActive(true);
                    if (PowerSelected >= 0 && PowerSelected < powerList.Count)
                        InfoNameTextStorage.text = powerList[PowerSelected].Name;
                    configUi.Refresh?.Invoke();
                    configUi.SelectFirstEntry?.Invoke();
                    bringTabToFront();
                };

                tabBtn.onClick.AddListener(() =>
                {
                    if (showingConfig) applyPowersView();
                    else applyConfigView();
                });

                int totalPageCount = Mathf.Max(1, Mathf.CeilToInt(powerList.Count / (float)PowersPerPage));
                bool hasMultiplePages = powerList.Count > PowersPerPage;
                Pages = hasMultiplePages ? totalPageCount - 1 : 0;

                Image prevImg = null;
                Image nextImg = null;
                TextMeshProUGUI pageLabel = null;
                Button prevButton = null;
                Button nextButton = null;

                GameObject PageLabel = new GameObject("PageLabel");
                PageLabel.transform.SetParent(PageArea.transform, false);
                RectTransform pageLabelRt = PageLabel.AddComponent<RectTransform>();
                pageLabelRt.anchorMin = Vector2.zero;
                pageLabelRt.anchorMax = Vector2.one;
                pageLabelRt.offsetMin = Vector2.zero;
                pageLabelRt.offsetMax = Vector2.zero;
                pageLabelRt.anchoredPosition = new Vector2(0f, layout.pageLabelOffsetY);
                pageLabel = PageLabel.AddComponent<TextMeshProUGUI>();
                pageLabel.font = GetMenuFont();
                pageLabel.fontSize = 7;
                pageLabel.alignment = TextAlignmentOptions.Center;
                pageLabel.color = Color.black;
                pageLabel.raycastTarget = false;

                Action refreshPagination = () =>
                {
                    if (pageLabel != null)
                        pageLabel.text = (CurrentPage + 1) + " / " + totalPageCount;
                    if (!hasMultiplePages || prevImg == null || nextImg == null || prevButton == null || nextButton == null) return;
                    bool canPrev = CurrentPage > 0;
                    bool canNext = CurrentPage < Pages;
                    prevImg.color = canPrev ? Color.white : new Color(1f, 1f, 1f, 0.35f);
                    nextImg.color = canNext ? Color.white : new Color(1f, 1f, 1f, 0.35f);
                    prevButton.interactable = canPrev;
                    nextButton.interactable = canNext;
                };
                refreshPagination();

                Action refreshOnOffButton = () =>
                {
                    if (PowerSelected < 0 || PowerSelected >= powerList.Count)
                    {
                        onOffImg.sprite = DBPU.PButtonIdle;
                        onOffButton.interactable = false;
                        return;
                    }
                    var sel = powerList[PowerSelected];
                    if (sel.Passive)
                    {
                        onOffImg.sprite = DBPU.PButtonIdle;
                        onOffButton.interactable = false;
                        return;
                    }
                    onOffButton.interactable = true;
                    onOffImg.sprite = sel.Active ? DBPU.PButtonOn : DBPU.PButtonOff;
                };

                Image selectImg = SelectFrame.GetComponent<Image>();

                Action refreshSelectFrame = () =>
                {
                    int localIdx = Mathf.Clamp(LocalSelectedFrame, 0, FramesPos.Count - 1);
                    MenuUI.ApplyImage(SelectFrame, DBPU.PSelectFrame, FramesPos[localIdx], layout.GetFrameUniformScale());
                };

                Action<int> selectPower = (globalIndex) =>
                {
                    if (globalIndex < 0 || globalIndex >= powerList.Count) return;
                    var value = powerList[globalIndex];
                    int localFrame = globalIndex - (PowersPerPage * CurrentPage);
                    if (localFrame < 0 || localFrame >= FramesPos.Count) return;
                    LocalSelectedFrame = localFrame;
                    PowerSelected = globalIndex;
                    refreshSelectFrame();
                    selectImg.color = Color.white;
                    if (!showingConfig)
                    {
                        InfoNameTextStorage.text = value.Name;
                        InfoDescriptionTextStorage.text = value.Description;
                    }
                    refreshOnOffButton();
                    if (showingConfig)
                    {
                        InfoNameTextStorage.text = value.Name;
                        configUi.Refresh?.Invoke();
                        configUi.SelectFirstEntry?.Invoke();
                    }
                };

                float lastPowerClickTime = -1f;
                int lastPowerClickIndex = -1;
                const float powerDoubleClickWindow = 0.32f;

                Action rebuildFrames = null;

                Action<int> togglePowerAt = (globalIndex) =>
                {
                    if (globalIndex < 0 || globalIndex >= powerList.Count) return;
                    var value = powerList[globalIndex];
                    if (value.Passive) return;
                    PowersData.ApplyPower(value.ID);
                    rebuildFrames?.Invoke();
                    selectPower(globalIndex);
                };

                Action<int> handlePowerFrameClick = (globalIndex) =>
                {
                    float now = Time.unscaledTime;
                    if (globalIndex == lastPowerClickIndex && now - lastPowerClickTime <= powerDoubleClickWindow)
                    {
                        togglePowerAt(globalIndex);
                        lastPowerClickIndex = -1;
                        lastPowerClickTime = -1f;
                        return;
                    }

                    lastPowerClickIndex = globalIndex;
                    lastPowerClickTime = now;
                    selectPower(globalIndex);
                };

                rebuildFrames = () =>
                {
                    PowersData.HarvestPowerStates();
                    if (FramesHolder == null)
                    {
                        FramesHolder = new GameObject("FramesHolder");
                        FramesHolder.transform.SetParent(gridParent, false);
                        FramesHolder.AddComponent<RectTransform>();
                    }
                    else
                    {
                        for (int c = FramesHolder.transform.childCount - 1; c >= 0; c--)
                        {
                            Transform child = FramesHolder.transform.GetChild(c);
                            if (child.name.StartsWith("Frame"))
                                Destroy(child.gameObject);
                        }
                    }

                    layout.ApplyFramesHolderTransform(FramesHolder.GetComponent<RectTransform>());
                    if (SelectFrame.transform.parent != FramesHolder.transform)
                        SelectFrame.transform.SetParent(FramesHolder.transform, false);

                    float slotUniform = layout.GetFrameUniformScale();

                    int framesMissing = powerList.Count - (PowersPerPage * CurrentPage);
                    int currentFrames = 0;
                    while (framesMissing > 0 && currentFrames < PowersPerPage)
                    {
                        int globalIndex = currentFrames + (PowersPerPage * CurrentPage);
                        var value = powerList[globalIndex];
                        currentFrames += 1;
                        int capturedIndex = globalIndex;
                        int localId = currentFrames - 1;
                        bool active = value.Passive || value.Active;

                        Sprite frameSprite = active ? DBPU.PGreenFrame : DBPU.PRedFrame;
                        GameObject Frame = new GameObject("Frame" + currentFrames);
                        Frame.transform.SetParent(FramesHolder.transform, false);
                        MenuUI.ApplyImage(Frame, frameSprite, FramesPos[localId], slotUniform);

                        GameObject icon = new GameObject("Icon");
                        icon.transform.SetParent(Frame.transform, false);
                        Image iconImg = icon.AddComponent<Image>();
                        bool isDefaultIcon = value.Icon == null;
                        Sprite iconSprite = value.Icon ?? DBPU.PIconTemplate;
                        iconImg.sprite = iconSprite;
                        iconImg.preserveAspect = true;
                        iconImg.color = Color.white;
                        MenuUI.DisableRaycast(iconImg);
                        MenuUI.FitIconInsideFrame(icon.GetComponent<RectTransform>(), iconSprite, Frame.GetComponent<RectTransform>(), layout.iconPadding, layout.iconScaleX, layout.iconScaleY, isDefaultIcon);

                        Frame.AddComponent<PowerFrameInfo>().ID = localId;
                        Button frameBtn = Frame.GetOrAddComponent<Button>();
                        frameBtn.onClick.AddListener(() => handlePowerFrameClick(capturedIndex));
                        Image frameImg = Frame.GetComponent<Image>();
                        if (frameImg != null) frameBtn.targetGraphic = frameImg;
                        framesMissing -= 1;
                    }

                    if (Mathf.FloorToInt(PowerSelected / (float)PowersPerPage) == CurrentPage)
                        selectImg.color = Color.white;
                    else
                        selectImg.color = Color.clear;

                    SelectFrame.transform.SetAsLastSibling();
                    refreshSelectFrame();
                    refreshOnOffButton();
                };

                rebuildFrames();
                selectPower(idx);

                if (hasMultiplePages)
                {
                    float barY = layout.pageArea.y;
                    float pageX = layout.pageArea.x;
                    Vector2 navScale = new Vector2(0.75f, 0.75f);
                    Sprite prevSprite = DBPU.PPrevious != null ? DBPU.PPrevious : DBPU.TPrevious;
                    Sprite nextSprite = DBPU.PNext != null ? DBPU.PNext : DBPU.TNext;
                    float pageHalfW = layout.pageArea.targetW * layout.ScaleFor(DBPU.PPageArea, layout.pageArea) * 0.5f;
                    float btnHalfW = MenuUI.SpritePixels(prevSprite).x * navScale.x * 0.5f;
                    float navGap = 6f;
                    float prevX = pageX - pageHalfW - btnHalfW - navGap;
                    float nextX = pageX + pageHalfW + btnHalfW + navGap;

                    GameObject PreviousPageBtn = new GameObject("PreviousPage");
                    PreviousPageBtn.transform.SetParent(Canvas.transform, false);
                    SetupPowerPageNavButton(PreviousPageBtn, prevSprite, new Vector2(prevX, barY), navScale);
                    prevImg = PreviousPageBtn.GetComponent<Image>();
                    prevButton = PreviousPageBtn.GetComponent<Button>();
                    prevNavGo = PreviousPageBtn;

                    GameObject NextPageBtn = new GameObject("NextPage");
                    NextPageBtn.transform.SetParent(Canvas.transform, false);
                    SetupPowerPageNavButton(NextPageBtn, nextSprite, new Vector2(nextX, barY), navScale);
                    nextImg = NextPageBtn.GetComponent<Image>();
                    nextButton = NextPageBtn.GetComponent<Button>();
                    nextNavGo = NextPageBtn;

                    PreviousPageBtn.transform.SetAsLastSibling();
                    NextPageBtn.transform.SetAsLastSibling();
                    refreshPagination();

                    prevButton.onClick.AddListener(() =>
                    {
                        if (CurrentPage <= 0) return;
                        CurrentPage -= 1;
                        rebuildFrames();
                        refreshPagination();
                        if (PowerSelected >= PowersPerPage * CurrentPage && PowerSelected < PowersPerPage * (CurrentPage + 1))
                            selectPower(PowerSelected);
                        else
                            selectPower(Mathf.Min(powerList.Count - 1, PowersPerPage * CurrentPage));
                    });

                    nextButton.onClick.AddListener(() =>
                    {
                        if (CurrentPage >= Pages) return;
                        CurrentPage += 1;
                        rebuildFrames();
                        refreshPagination();
                        if (PowerSelected >= PowersPerPage * CurrentPage && PowerSelected < PowersPerPage * (CurrentPage + 1))
                            selectPower(PowerSelected);
                        else
                            selectPower(Mathf.Min(powerList.Count - 1, PowersPerPage * CurrentPage));
                    });
                }

                onOffButton.onClick.AddListener(() =>
                {
                    if (PowerSelected < 0 || PowerSelected >= powerList.Count) return;
                    var sel = powerList[PowerSelected];
                    if (sel.Passive) return;
                    PowersData.ApplyPower(sel.ID);
                    rebuildFrames();
                    selectPower(PowerSelected);
                });

                bringTabToFront();
                applyPowersView();

                Action rebuildGridLayout = () =>
                {
                    Vector2 panelSz = centerCanvas != null
                        ? MenuUI.GetRenderedSize(centerCanvas.GetComponent<RectTransform>())
                        : Vector2.zero;
                    if (panelSz.x > 1f && panelSz.y > 1f)
                        layout.ApplyAutoSlotSizing(panelSz.x, panelSz.y);
                    BuildGridPositions(layout, panelSz.x, panelSz.y);
                    refreshSelectFrame();
                    rebuildFrames();
                    if (PowerSelected >= 0 && PowerSelected < powerList.Count)
                        selectPower(PowerSelected);
                };

                MenuUI.AttachResizeHandle(
                    centerCanvas.transform,
                    () => layout.menuRootUniform,
                    (u) =>
                    {
                        layout.menuRootUniform = u;
                        Canvas.GetComponent<RectTransform>().localScale = new Vector3(u, u, 1f);
                        rebuildGridLayout();
                    });
        }

        public class PowerFrameInfo : MonoBehaviour
        {
            public int ID { get; set; }
        }
    }

    public class TransformationContextMenu : MonoBehaviour
    {
        public PersonBehaviour person;
        public CharacterTransformations TransformationsData;
        public SkinContextMenu skinContextMenu;
        public MultipliersAndStuffs Multipliers;
        public AuraHandler AuraHandler;

        public GameObject Aura;

        public GameObject FramesHolder;

        private int ActualSelectedFrame = 0;
        public int PositionSelectedFrame = 0;
        public int OriginalSelectedFrame = 0;
        public int LocalSelectedFrame = 0;
        private int Pages = 0;
        private int CurrentPage = 0;
        private int PreviousPage = 0;
        public int FormSelected = 0;
        public int OriginalFormSelected = 0;

        public float PreviousMultiplier = 1f;
        public string Form = "Base";
        public string CurrentAuraID = "Base";
        public string BaseForm = "Base";
        public string LastUsedForm;

        public bool AuraOn = true;
        public bool AuraCanAppear = true;

        private bool MenuOpen = false;
        private float SelectedMultiplier = 1f;
        private string SelectedFormId = "";
        private TextMeshProUGUI MultiplierText;
        private TransformationMenuMultiplierTicker multiplierTicker;

        public Dictionary<string, GameObject> AurasStorage = new Dictionary<string, GameObject>();

        private List<Vector2> FramesPos = new List<Vector2>();

        public void Start()
        {
            FormSelected = OriginalFormSelected;
            PositionSelectedFrame = OriginalSelectedFrame;

            EnsureRuntimeRefs();
            RecalculatePages();
        }

        void EnsureRuntimeRefs()
        {
            var root = transform.root != null ? transform.root.gameObject : gameObject;
            if (person == null)
            {
                person = root.GetComponent<PersonBehaviour>();
                if (person == null && transform.root != null)
                    person = transform.root.GetComponentInChildren<PersonBehaviour>();
            }

            if (TransformationsData == null)
                TransformationsData = root.GetComponent<CharacterTransformations>();

            if (!root.GetComponent<MultipliersAndStuffs>())
                root.AddComponent<MultipliersAndStuffs>();
            Multipliers = root.GetComponent<MultipliersAndStuffs>();

            var aura = root.GetComponent<AuraHandler>();
            if (aura == null) aura = root.AddComponent<AuraHandler>();
            if (aura.person == null) aura.person = person;
            if (!string.IsNullOrEmpty(CurrentAuraID)) aura.CurrentAuraID = CurrentAuraID;
            AuraHandler = aura;
        }

        void RecalculatePages()
        {
            Pages = 0;
            if (TransformationsData == null || TransformationsData.transformations == null
                || TransformationsData.transformations.TransformationData == null)
                return;

            int localPage = 0;
            int count = TransformationsData.transformations.TransformationData.Count;
            for (int i = 0; i < count; i++)
            {
                localPage += 1;
                if (localPage == 6)
                {
                    localPage = 0;
                    Pages += 1;
                }
            }
        }

        void SyncSelectionToCurrentForm(CharacterTransformations.Transformations t)
        {
            if (t == null || t.TransformationData == null || t.TransformationData.Count == 0)
            {
                FormSelected = 0;
                CurrentPage = 0;
                LocalSelectedFrame = 0;
                PositionSelectedFrame = 0;
                return;
            }

            var list = t.GetOrderedEntries();
            int index = 0;

            for (int i = 0; i < list.Count; i++)
            {
                var entry = list[i].Value;
                if (entry == null) continue;
                if (list[i].Key == Form || entry.ID == Form)
                {
                    index = i;
                    break;
                }
            }

            if (index < 0 || index >= list.Count) index = 0;
            FormSelected = index;
            CurrentPage = index / 6;
            LocalSelectedFrame = index % 6;
            PositionSelectedFrame = LocalSelectedFrame;

            var stats = list[index].Value;
            if (stats == null) return;
            SelectedFormId = stats.ID;
            SelectedMultiplier = TransformationsData != null
                ? TransformationsData.GetEffectivePower(stats)
                : stats.PowerMultiplier;
        }

        void CloseTransformMenu(GameObject canvas)
        {
            MenuOpen = false;
            MultiplierText = null;
            multiplierTicker = null;
            Destroy(canvas);
        }

        public void Awake()
        {
            if (FramesPos.Count == 0)
            {
                FramesPos.Add(new Vector2(-20f, 12f));
                FramesPos.Add(new Vector2(0f, 12f));
                FramesPos.Add(new Vector2(20f, 12f));
                FramesPos.Add(new Vector2(-20f, -22f));
                FramesPos.Add(new Vector2(0f, -22f));
                FramesPos.Add(new Vector2(20f, -22f));
            }

            var phys = gameObject.GetComponent<PhysicalBehaviour>();
            if (phys == null || phys.ContextMenuOptions == null) return;
            var contextButtons = phys.ContextMenuOptions;
            if (!MCP_Utils.CheckContextButton(contextButtons, "!CombatTransformations"))
                contextButtons.Buttons.Add(new ContextMenuButton("!CombatTransformations", "Combat Forms", "Fast combat transformation selector", () =>
                {
                    var context = UnityEngine.Object.FindObjectOfType<global::ContextMenuBehaviour>();
                    if (context) context.Hide();
                    CombatTransformationWheel.Instance.OpenFor(this, Input.mousePosition, KeyCode.None);
                }));
            if (MCP_Utils.CheckContextButton(contextButtons, "!TrasformationsMenu")) return;
            int transformInsertAt = GetTransformationsMenuInsertIndex(contextButtons);
            MCP_Utils.AddContextButtonInOrder(contextButtons, new ContextMenuButton("!TrasformationsMenu", "Trasformations Menu", "Trasformations Menu", () =>
            {
                EnsureRuntimeRefs();
                RecalculatePages();

                if (TransformationsData == null || TransformationsData.transformations == null
                    || TransformationsData.transformations.TransformationData == null
                    || TransformationsData.transformations.TransformationData.Count == 0)
                {
                    ModAPI.Notify("No transformations available.");
                    return;
                }

                MenuOpen = true;

                PreviousPage = CurrentPage;

                if (CurrentPage < 0) CurrentPage = 0;
                if (CurrentPage > Pages) CurrentPage = Pages;

                var t = TransformationsData.transformations;
                SyncSelectionToCurrentForm(t);
                var firstList = t.GetOrderedEntries();
                if (FormSelected < 0 || FormSelected >= firstList.Count) FormSelected = 0;
                var firstValue = firstList[FormSelected].Value;
                if (firstValue == null)
                {
                    ModAPI.Notify("Transformation data is missing.");
                    MenuOpen = false;
                    return;
                }

                GameObject Canvas = new GameObject("TCanvas");
                Canvas.transform.SetParent(GameObject.Find("Canvas").transform);
                Canvas.GetOrAddComponent<Image>().sprite = DBPU.TCanvas;
                Canvas.GetComponent<RectTransform>().anchoredPosition = Vector2.zero;
                Canvas.GetComponent<RectTransform>().localScale = new Vector3(12.34f, 7.056f, 1f);
                Canvas.AddComponent<ExistIf>().obj = gameObject;

                GameObject textstorageobject = new GameObject("textstorageobject");
                textstorageobject.transform.SetParent(Canvas.transform, false);

                RectTransform textRectTransform = textstorageobject.AddComponent<RectTransform>();
                textRectTransform.anchoredPosition = new Vector2(0f, 43.75f);
                textRectTransform.localScale = new Vector3(0.55f, 1f);
                //textRectTransform.anchorMin = new Vector2(0.1f, 0.1f);
                //textRectTransform.anchorMax = new Vector2(0.9f, 0.9f);

                TextMeshProUGUI textstorage = textstorageobject.AddComponent<TextMeshProUGUI>();
                textstorage.text = "TRANSFORMATION";
                textstorage.fontSize = 10;
                textstorage.font = ModAPI.FindSpawnable("Holographic Display").Prefab.transform.Find("Text").GetComponent<TextMeshPro>().font;
                textstorage.alignment = TextAlignmentOptions.Center;
                textstorage.color = new Color(0f, 0f, 0f);
                textstorage.enableWordWrapping = false;
                MenuUI.ConfigureTitleDragArea(textstorageobject, Canvas.GetComponent<RectTransform>(), new Vector2(190f, 18f));

                RectTransform canvasRt = Canvas.GetComponent<RectTransform>();
                float transformMenuScale = canvasRt.localScale.x;
                MenuUI.AttachResizeHandle(
                    Canvas.transform,
                    () => transformMenuScale,
                    (u) =>
                    {
                        transformMenuScale = u;
                        float aspect = canvasRt.localScale.y / Mathf.Max(0.01f, canvasRt.localScale.x);
                        canvasRt.localScale = new Vector3(u, u * aspect, 1f);
                    },
                    4f,
                    20f,
                    12f);

                FramesHolder = new GameObject("FramesHolder");
                FramesHolder.transform.SetParent(Canvas.transform, false);

                GameObject Info = new GameObject("Info");
                Info.transform.SetParent(Canvas.transform);
                Info.GetOrAddComponent<Image>().sprite = DBPU.TInfo;
                Info.GetComponent<RectTransform>().anchoredPosition = new Vector2(66.5f, -7f);
                Info.GetComponent<RectTransform>().localScale = new Vector3(0.3216f, 0.8215f, 1f);

                GameObject InfoNameText = new GameObject("Info Name Text");
                InfoNameText.transform.SetParent(Info.transform, false);

                RectTransform InfoNameTextRectTransform = InfoNameText.AddComponent<RectTransform>();
                InfoNameTextRectTransform.anchoredPosition = new Vector2(0f, 0f);
                InfoNameTextRectTransform.localScale = new Vector3(1.25f, 1f);
                InfoNameTextRectTransform.anchorMin = new Vector2(0, 0);
                InfoNameTextRectTransform.anchorMax = new Vector2(1, 1);
                InfoNameTextRectTransform.pivot = new Vector2(0, 1);
                InfoNameTextRectTransform.offsetMax = new Vector2(-25f, 49f);
                InfoNameTextRectTransform.offsetMin = new Vector2(8f, 35f);

                TextMeshProUGUI InfoNameTextStorage = InfoNameText.AddComponent<TextMeshProUGUI>();
                InfoNameTextStorage.text = firstValue.Name;
                InfoNameTextStorage.fontSize = 8;
                InfoNameTextStorage.enableAutoSizing = true;
                InfoNameTextStorage.fontSizeMin = 4;
                InfoNameTextStorage.fontSizeMax = 8;
                InfoNameTextStorage.font = ModAPI.FindSpawnable("Holographic Display").Prefab.transform.Find("Text").GetComponent<TextMeshPro>().font;
                InfoNameTextStorage.alignment = TextAlignmentOptions.Center;
                InfoNameTextStorage.color = new Color(0f, 0f, 0f);
                InfoNameTextStorage.enableWordWrapping = false;

                GameObject InfoDescriptionText = new GameObject("Info Description Text");
                InfoDescriptionText.transform.SetParent(Info.transform, false);

                RectTransform InfoDescriptionTextRectTransform = InfoDescriptionText.AddComponent<RectTransform>();
                InfoDescriptionTextRectTransform.anchoredPosition = new Vector2(0f, 0f);
                InfoDescriptionTextRectTransform.localScale = new Vector3(1.25f, 1f);
                InfoDescriptionTextRectTransform.anchorMin = new Vector2(0, 0);
                InfoDescriptionTextRectTransform.anchorMax = new Vector2(1, 1);
                InfoDescriptionTextRectTransform.pivot = new Vector2(0, 1);
                InfoDescriptionTextRectTransform.offsetMax = new Vector2(-23f, -20f);
                InfoDescriptionTextRectTransform.offsetMin = new Vector2(7f, -35f);

                TextMeshProUGUI InfoDescriptionTextStorage = InfoDescriptionText.AddComponent<TextMeshProUGUI>();
                InfoDescriptionTextStorage.text = firstValue.Description;
                InfoDescriptionTextStorage.fontSize = 4;
                InfoDescriptionTextStorage.font = ModAPI.FindSpawnable("Holographic Display").Prefab.transform.Find("Text").GetComponent<TextMeshPro>().font;
                InfoDescriptionTextStorage.alignment = TextAlignmentOptions.TopLeft;
                InfoDescriptionTextStorage.enableWordWrapping = true;
                InfoDescriptionTextStorage.color = new Color(0f, 0f, 0f);

                GameObject InfoMultiplierText = new GameObject("Info Multiplier Text");
                InfoMultiplierText.transform.SetParent(Info.transform, false);

                RectTransform InfoMultiplierTextRectTransform = InfoMultiplierText.AddComponent<RectTransform>();
                InfoMultiplierTextRectTransform.anchoredPosition = new Vector2(0f, -41.5f);
                InfoMultiplierTextRectTransform.localScale = new Vector3(1.25f, 1f);

                TextMeshProUGUI InfoMultiplierTextStorage = InfoMultiplierText.AddComponent<TextMeshProUGUI>();
                SelectedFormId = firstValue.ID;
                float firstEffectiveMult = GetStatsEffectivePower(firstValue);
                SelectedMultiplier = firstEffectiveMult;
                InfoMultiplierTextStorage.text = FormatInfoMultiplier(firstEffectiveMult, firstValue.ID);
                InfoMultiplierTextStorage.fontSize = 8;
                InfoMultiplierTextStorage.font = ModAPI.FindSpawnable("Holographic Display").Prefab.transform.Find("Text").GetComponent<TextMeshPro>().font;
                InfoMultiplierTextStorage.alignment = TextAlignmentOptions.Center;
                InfoMultiplierTextStorage.color = new Color(0f, 0f, 0f);
                InfoMultiplierTextStorage.enableWordWrapping = false;

                MultiplierText = InfoMultiplierTextStorage;
                multiplierTicker = Canvas.AddComponent<TransformationMenuMultiplierTicker>();
                multiplierTicker.Init(this, InfoMultiplierTextStorage, firstEffectiveMult, firstValue.ID);

                GameObject Illustration = new GameObject("Illustration");
                Illustration.transform.SetParent(Canvas.transform);
                //Illustration.GetOrAddComponent<Image>().sprite = DBPU.TIllustration;
                Illustration.GetOrAddComponent<Image>().sprite = firstValue.Illustration;
                Illustration.GetComponent<RectTransform>().anchoredPosition = new Vector2(-66.55f, -7f);
                Illustration.GetComponent<RectTransform>().localScale = new Vector3(0.3216f, 0.8215f, 1f);



                GameObject DamageToggle = new GameObject("DamageToggle");
                DamageToggle.transform.SetParent(Canvas.transform);
                DamageToggle.GetOrAddComponent<Image>().sprite = DBPU.TDamage_NULL;
                if (skinContextMenu != null)
                {
                    if (skinContextMenu.SkinDamage == true) DamageToggle.GetComponent<Image>().sprite = DBPU.TDamage_ON;
                    else if (skinContextMenu.SkinDamage == true) DamageToggle.GetComponent<Image>().sprite = DBPU.TDamage_OFF;
                    else DamageToggle.GetComponent<Image>().sprite = DBPU.TDamage_NULL;
                }
                DamageToggle.GetComponent<RectTransform>().anchoredPosition = new Vector2(-27.5f, -59.5f);
                DamageToggle.GetComponent<RectTransform>().localScale = new Vector3(0.275f, 0.348f, 1f);
                DamageToggle.GetOrAddComponent<Button>().onClick.AddListener(() =>
                {
                    if (skinContextMenu == null) return;

                    if (skinContextMenu.SkinDamage == true)
                    {
                        DamageToggle.GetComponent<Image>().sprite = DBPU.TDamage_OFF;
                        skinContextMenu.SkinDamage = false;
                    }

                    else
                    {
                        DamageToggle.GetComponent<Image>().sprite = DBPU.TDamage_ON;
                        skinContextMenu.SkinDamage = true;
                    }
                });

                GameObject DamageToggleNameText = new GameObject("Damage Name Text");
                DamageToggleNameText.transform.SetParent(DamageToggle.transform, false);

                RectTransform DamageToggleTextRectTransform = DamageToggleNameText.AddComponent<RectTransform>();
                DamageToggleTextRectTransform.anchoredPosition = new Vector2(0f, 22f);
                DamageToggleTextRectTransform.localScale = new Vector3(1f, 1.25f);

                TextMeshProUGUI DamageToggleNameTextStorage = DamageToggleNameText.AddComponent<TextMeshProUGUI>();
                DamageToggleNameTextStorage.text = "Clothing Damage";
                DamageToggleNameTextStorage.fontSize = 9;
                DamageToggleNameTextStorage.font = ModAPI.FindSpawnable("Holographic Display").Prefab.transform.Find("Text").GetComponent<TextMeshPro>().font;
                DamageToggleNameTextStorage.alignment = TextAlignmentOptions.Center;
                DamageToggleNameTextStorage.color = new Color(0f, 0f, 0f);
                DamageToggleNameTextStorage.enableWordWrapping = true;



                GameObject SelectFrame = new GameObject("SelectFrame");
                SelectFrame.transform.SetParent(Canvas.transform);
                SelectFrame.GetOrAddComponent<Image>().sprite = DBPU.TSelected;
                SelectFrame.transform.SetAsLastSibling();
                if (PositionSelectedFrame < 0 || PositionSelectedFrame >= FramesPos.Count)
                    PositionSelectedFrame = 0;
                SelectFrame.GetComponent<RectTransform>().anchoredPosition = FramesPos[PositionSelectedFrame];
                SelectFrame.GetComponent<RectTransform>().localScale = new Vector3(0.164f, 0.286f, 1f);
                SelectFrame.GetComponent<Image>().color = Color.white;
                MenuUI.DisableRaycast(SelectFrame.GetComponent<Image>());

                int FirstFramesMissing = t.TransformationData.Count - (6 * CurrentPage);
                int FirstCurrentFrames = 0;

                while (FirstFramesMissing > 0 && FirstCurrentFrames < 6)
                {
                    var list = t.GetOrderedEntries();
                    int idx = FirstCurrentFrames + (6 * CurrentPage);
                    if (idx < 0 || idx >= list.Count) break;
                    var value = list[idx].Value;
                    if (value == null)
                    {
                        FirstCurrentFrames += 1;
                        FirstFramesMissing -= 1;
                        continue;
