        private void Update()
        {
            if (currentAura != null && (DBPU.AurasEnabled == false || !IsAuraEffectivelyActive) && !_kiChargeOutwardFadeRunning)
            {
                DestroyAura();
            }

            if (currentAura == null && IsAuraEffectivelyVisible)
            {
                CreateAura(CurrentAuraID,OverdriveVisualStrength<=.001f);
            }
            if(currentAura && !_kiChargeOutwardFadeRunning && currentAura.activeSelf!=AuraVisible)currentAura.SetActive(AuraVisible);
        }

        private void LateUpdate()
        {
            if (currentAura == null || !IsAuraEffectivelyVisible) return;
            float fury=OverdriveVisualStrength;

            if(_cinematicChargeController==null)_cinematicChargeController=GetComponent<KiChargeModeController>();
            if(_cinematicChargeController!=null&&_cinematicChargeController.IsActivelyCharging)
                _chargeVisualIntensityActive=true;
            UpdateAuraPosition();
            if (_kiChargeOutwardFadeRunning) return;

            if (!_perLimbAura && _refinedAura == null)
            {
                float scaleMul = 1f;
                if (_chargeVisualIntensityActive || _sparkingVisualIntensityActive)
                    scaleMul *= DBPU.KiChargeAuraScaleMultiplier;
                if (_sparkingVisualIntensityActive)
                    scaleMul *= 1.12f;
                scaleMul*=1+fury*.24f;
                currentAura.transform.localScale = _auraVisualBaseScale * scaleMul;
            }

            float speedMul = (_chargeVisualIntensityActive || _sparkingVisualIntensityActive) ? DBPU.KiChargeAuraParticleSpeedMultiplier : 1f;
            if (_refinedAura != null)
            {
                _refinedAura.SpeedMultiplier = Mathf.Min(speedMul,1.75f);
                _refinedAura.ChargeAmount=(_chargeVisualIntensityActive||_sparkingVisualIntensityActive)?1f:0f;
                _refinedAura.OverdriveAmount=fury;
            }
            for (int i = 0; i < _auraParticleSpeedBackups.Count; i++)
            {
                var e = _auraParticleSpeedBackups[i];
                if (e.Ps == null) continue;
                var main = e.Ps.main;
                main.simulationSpeed = e.BaseSimulationSpeed * speedMul * (1+fury*1.7f);
                if((_refinedAura==null || !_refinedAura.IsCinematic) && fury>.001f && e.Ps.isPlaying && e.Ps.emission.enabled
                    && !(Global.main && Global.main.Paused))
                {
                    var emission=e.Ps.emission;
                    float sample=Mathf.Repeat(e.Ps.time/Mathf.Max(.1f,main.duration),1);
                    float rate=Mathf.Max(emission.rateOverTime.Evaluate(sample),Mathf.Min(16,main.maxParticles*.025f));
                    e.OverdriveEmissionDebt+=Mathf.Max(0,rate)*fury*1.25f*Time.deltaTime;
                    int extra=Mathf.Min(64,Mathf.FloorToInt(e.OverdriveEmissionDebt));
                    if(extra>0){e.Ps.Emit(extra);e.OverdriveEmissionDebt-=extra;}
                }
                else e.OverdriveEmissionDebt=0;
                _auraParticleSpeedBackups[i]=e;
            }

            if (_sparkingVisualIntensityActive)
                ApplySparkingAuraStylePulse();
        }

        public void CreateAura(string auraID)
        {
            CreateAura(auraID, true);
        }

        public void CreateAura(string auraID, bool playSound)
        {
            if (auraID != null && auraID.StartsWith("Naruto/", StringComparison.Ordinal)) { CurrentAuraID = auraID; if (currentAura != null) DestroyAura(); return; }
            if (person == null)
                person = GetComponent<PersonBehaviour>() ?? transform.root.GetComponent<PersonBehaviour>();
            if (person == null) return;

            if (KiFormTransition.DefersAura(person)) return;
            if (AuraVisible == true && IsAuraEffectivelyActive)
            {
                CurrentAuraID = auraID;

                if (currentAura != null)
                {
                    if (_refinedAura != null && RefinedAuras.Contains(auraID))
                    {
                        if (_retiringAura != null) Destroy(_retiringAura);
                        _retiringAura = currentAura;
                        _refinedAura.Retire(.24f, person.Limbs[2].transform);
                        currentAura = null;
                        _refinedAura = null;
                    }
                    DestroyAura();
                }

                bool isUiAura = auraID == "UI" || auraID == "MUI";
                if (isUiAura)
                    PullGlobalAuraTune();
                GameObject prefab = null;
                AurasStorage.AurasVFX.TryGetValue(auraID, out prefab);
                if (prefab == null && isUiAura)
                    prefab = DBPU.Aura_MUI;
                if (prefab == null && isUiAura)
                    AurasStorage.AurasVFX.TryGetValue("SSJBlue", out prefab);

                currentAura = RefinedAuras.Create(auraID);
                _refinedAura = currentAura != null ? currentAura.GetComponent<RefinedAuraVisual>() : null;
                if (_refinedAura != null)
                {
                    _perLimbAura = false;
                    _uiBodyAura = false;
                    currentAura.AddComponent<DestroyWithObject>().Object = person.gameObject;
                    UpdateAuraPosition();
                }
                else if (prefab != null)
                {
                    _perLimbAura = false;
                    _uiBodyAura = isUiAura;
                    ExtraPosition = 0f;
                    currentAura = Instantiate(prefab, GetAuraPosition(), Quaternion.identity);
                    float personScale = Mathf.Abs(person.transform.localScale.x);
                    float auraSize = isUiAura ? Mathf.Max(0.1f, AuraTuneScale) : 1.25f;
                    currentAura.transform.localScale = personScale > 1.15f
                        ? new Vector3(auraSize * (1f + (personScale - 1f)), auraSize * (1f + (personScale - 1f)), 1f)
                        : new Vector3(auraSize, auraSize, 1f);
                    if (!isUiAura)
                        ExtraPosition = personScale > 1.15f ? (Mathf.Abs(currentAura.transform.localScale.x) - 1.3f) : 0f;
                    currentAura.transform.localScale = CompactAuraScale(currentAura.transform.localScale);
                    currentAura.AddComponent<DestroyWithObject>().Object = person.gameObject;
                    ConfigureParticleSystems();

                    if (isUiAura)
                        ApplyUltraInstinctLimbAuraTint(auraID == "MUI");
                    else if (auraID == "PowerAwakened")
                        ApplyAuraTint(new Color(0.92f, 1f, 0.55f));
                    else if (auraID == "OrangePiccolo")
                        ApplyAuraTint(new Color(1f, 0.78f, 0.22f));
                    else if (auraID == "BeastGohan")
                        ApplyAuraTint(new Color(0.95f, 0.35f, 0.55f));
                    else if (auraID == "BlackFrieza")
                        ApplyCustomAuraColors(new Color(0.35f, 0.08f, 0.85f), new Color(0.72f, 0.32f, 1f), true, 1f);

                    CaptureAuraParticleSizeBackups();
                    ApplyAuraParticleSizeTune();
                }

                if (playSound && audioSource != null && AurasStorage.AurasSFX.TryGetValue(auraID, out AudioClip sound))
                {
                    audioSource.Stop();
                    audioSource.PlayOneShot(DBPU.Aura_Burst_Basic);
                    audioSource.clip = sound;
                    audioSource.loop = true;
                    audioSource.Play();
                }
                else if (playSound)
                {
                    Debug.LogWarning($"Aura {auraID} not found in registry");
                }

                RefreshAuraVisualCaches();
            }
        }

        static float GetLimbAuraScale(string limbName)
        {
            if (string.IsNullOrEmpty(limbName)) return 0.24f;
            if (limbName.IndexOf("Head", StringComparison.OrdinalIgnoreCase) >= 0) return 0.34f;
            if (limbName.IndexOf("UpperBody", StringComparison.OrdinalIgnoreCase) >= 0) return 0.4f;
            if (limbName.IndexOf("MiddleBody", StringComparison.OrdinalIgnoreCase) >= 0) return 0.42f;
            if (limbName.IndexOf("LowerBody", StringComparison.OrdinalIgnoreCase) >= 0) return 0.36f;
            if (limbName.IndexOf("UpperArm", StringComparison.OrdinalIgnoreCase) >= 0) return 0.26f;
            if (limbName.IndexOf("LowerArm", StringComparison.OrdinalIgnoreCase) >= 0) return 0.24f;
            if (limbName.IndexOf("UpperLeg", StringComparison.OrdinalIgnoreCase) >= 0) return 0.28f;
            if (limbName.IndexOf("LowerLeg", StringComparison.OrdinalIgnoreCase) >= 0) return 0.26f;
            if (limbName.IndexOf("Foot", StringComparison.OrdinalIgnoreCase) >= 0) return 0.2f;
            return 0.24f;
        }

        void ApplyUltraInstinctLimbAuraTint(bool mastered)
        {
            if (currentAura == null) return;
            Color deep = mastered ? new Color(0.12f, 0.38f, 0.92f) : new Color(0.1f, 0.32f, 0.88f);
            Color mid = mastered ? new Color(0.38f, 0.72f, 1f) : new Color(0.28f, 0.62f, 1f);
            foreach (var ps in currentAura.GetComponentsInChildren<ParticleSystem>(true))
            {
                if (ps == null) continue;
                var main = ps.main;
                main.startColor = new ParticleSystem.MinMaxGradient(deep, mid);
                main.simulationSpeed = mastered ? 1.12f : 1.02f;
            }
        }

        public void DestroyAura()
        {
            _refinedAura = null;
            if (audioSource != null)
                audioSource.Stop();

            if (currentAura != null)
            {
                Destroy(currentAura);
                currentAura = null;
            }

            _perLimbAura = false;
            _uiBodyAura = false;
            _chargeVisualIntensityActive = false;
            _sparkingVisualIntensityActive = false;
            RestoreSparkingAuraStyle();
            _auraParticleSpeedBackups.Clear();
            _auraParticleSizeBackups.Clear();
        }

        private Vector3 GetAuraPosition()
        {
            if (person == null || person.Limbs == null || person.Limbs.Length < 3 || person.Limbs[2] == null)
                return transform.position;
            if (_refinedAura != null)
                return person.Limbs[2].transform.position + new Vector3(0f,
                    0.4f * Mathf.Abs(person.transform.localScale.x) + AuraTuneY + 0.09f, 0f);
            if (_uiBodyAura)
                return person.Limbs[2].transform.position + new Vector3(0f, AuraTuneY, 0f);
            return person.Limbs[2].transform.position + new Vector3(0f, -1.1f - ExtraPosition + (AuraTuneY - (-0.09f)), 0f);
        }

        private void UpdateAuraPosition()
        {
            if (currentAura == null) return;
            if (_refinedAura != null)
            {
                _refinedAura.BindPerson(person);
                float s = Mathf.Max(0.01f, Mathf.Abs(person.transform.localScale.x));
                float tune = Mathf.Max(0.1f, AuraTuneScale / 3.4f);
                // Native rig smooths charge; grow from the original footprint without accumulating scale.
                _auraVisualBaseScale = new Vector3(1.25f * s * tune, 1.25f * s * tune, 1f);
                float charge=_refinedAura.SmoothedCharge;
                float grow=Mathf.Clamp(DBPU.KiChargeAuraScaleMultiplier,1f,3f)-1f;
                float fury=OverdriveVisualStrength;
                currentAura.transform.localScale = new Vector3(_auraVisualBaseScale.x*(1+grow*1.52f*charge)*(1+fury*.15f),_auraVisualBaseScale.y*(1+grow*1.12f*charge)*(1+fury*.24f),1);
                currentAura.transform.position = GetAuraPosition();
                currentAura.transform.rotation = Quaternion.identity;
                return;
            }
            if (_perLimbAura)
            {
                float personScale = person != null ? Mathf.Abs(person.transform.localScale.x) : 1f;
                float scaleMul = personScale > 1.15f ? personScale : 1f;
                for (int i = 0; i < currentAura.transform.childCount; i++)
                {
                    var child = currentAura.transform.GetChild(i);
                    if (child == null) continue;
                    var follow = child.GetComponent<LimbAuraFollow>();
                    string limbName = follow != null && follow.Target != null ? follow.Target.name : child.name;
                    float local = GetLimbAuraScale(limbName) * scaleMul;
                    if (_chargeVisualIntensityActive || _sparkingVisualIntensityActive)
                        local *= DBPU.KiChargeAuraScaleMultiplier;
                    if (_sparkingVisualIntensityActive)
                        local *= 1.12f;
                    local*=1+OverdriveVisualStrength*.24f;
                    child.localScale = new Vector3(local, local, 1f);
                }
                return;
            }

            float personScale2 = Mathf.Abs(person.transform.localScale.x);
            float auraMult = personScale2 > 1.15f ? (1f + (personScale2 - 1f)) : 1f;
            if (_uiBodyAura)
            {
                ExtraPosition = 0f;
                float auraSize = Mathf.Max(0.1f, AuraTuneScale);
                _auraVisualBaseScale = personScale2 > 1.15f
                    ? new Vector3(auraSize * (1f + (personScale2 - 1f)), auraSize * (1f + (personScale2 - 1f)), 1f)
                    : new Vector3(auraSize, auraSize, 1f);
            }
            else
            {
                float mul = Mathf.Max(0.1f, AuraTuneScale / 3.4f);
                currentAura.transform.localScale = new Vector3(baseScale.x * auraMult * mul, baseScale.y * auraMult * mul, 1f);
                _auraVisualBaseScale = currentAura.transform.localScale;
                ExtraPosition = personScale2 > 1.15f ? Mathf.Max(0f, Mathf.Abs(currentAura.transform.localScale.x) - 1.3f) : 0f;
                currentAura.transform.localScale = CompactAuraScale(currentAura.transform.localScale);
                _auraVisualBaseScale = currentAura.transform.localScale;
            }
            currentAura.transform.position = GetAuraPosition();
        }

        private void ConfigureParticleSystems()
        {
            if (currentAura == null) return;
            foreach (var lightning in currentAura.GetComponentsInChildren<ParticleSystem>().Where(x => x.name == "lightning"))
            {
                lightning.GetComponent<ParticleSystemRenderer>().sortingLayerName = "Top";
            }

            foreach (var spark in currentAura.GetComponentsInChildren<ParticleSystem>().Where(x => x.name == "spark"))
            {
                spark.GetComponent<ParticleSystemRenderer>().sortingLayerName = "Top";
            }

            float auraLift = _uiBodyAura ? 0.55f : 1.4f;
            foreach (var aura in currentAura.transform.Cast<Transform>().Where(x => x.name == "aura"))
            {
                var inner = aura.Find("aura");
                if (inner == null) continue;
                inner.localEulerAngles = new Vector3(180, 0, 0);
                inner.localPosition = new Vector3(0, auraLift, 0);

                foreach (var outer in inner.Cast<Transform>().Where(x => x.name == "outer"))
                {
                    outer.GetComponent<ParticleSystemRenderer>().sortingLayerName = "Background";
                }
            }

            if (_uiBodyAura)
            {
                foreach (var aura in currentAura.GetComponentsInChildren<Transform>(true))
                {
                    if (aura == null || aura.name != "aura") continue;
                    var inner = aura.Find("aura");
                    if (inner == null) continue;
                    inner.localEulerAngles = new Vector3(180, 0, 0);
                    inner.localPosition = new Vector3(0f, 0.55f, 0f);
                }
            }

            if (_perLimbAura)
            {
                foreach (Transform piece in currentAura.transform)
                {
                    foreach (var aura in piece.Cast<Transform>().Where(x => x.name == "aura"))
                    {
                        var inner = aura.Find("aura");
                        if (inner == null) continue;
                        inner.localEulerAngles = new Vector3(180, 0, 0);
                        inner.localPosition = new Vector3(0, 0.35f, 0);
                    }
                }
            }
        }

        private void ApplyAuraTint(Color tint)
        {
            if (currentAura == null) return;
            foreach (var ps in currentAura.GetComponentsInChildren<ParticleSystem>(true))
            {
                var main = ps.main;

                if (main.startColor.mode == ParticleSystemGradientMode.Color)
                {
                    main.startColor = new ParticleSystem.MinMaxGradient(main.startColor.color * tint);
                }

                else if (main.startColor.mode == ParticleSystemGradientMode.TwoColors)
                {
                    main.startColor = new ParticleSystem.MinMaxGradient(main.startColor.colorMin * tint, main.startColor.colorMax * tint);
                }
            }
        }

        public void ApplyCustomAuraColors(Color primary, Color secondary, bool useSecondary, float scaleMultiplier)
        {
            if (currentAura == null) return;

            Color bright = useSecondary ? secondary : Color.Lerp(primary, Color.white, 0.35f);
            if (_refinedAura != null) _refinedAura.SetTint(primary, bright);
            foreach (var ps in currentAura.GetComponentsInChildren<ParticleSystem>(true))
            {
                if (ps == null) continue;
                var main = ps.main;
                main.startColor = new ParticleSystem.MinMaxGradient(primary, bright);
            }

            foreach (var sr in currentAura.GetComponentsInChildren<SpriteRenderer>(true))
            {
                if (sr == null) continue;
                float a = sr.color.a > 0.01f ? sr.color.a : 1f;
                sr.color = new Color(primary.r, primary.g, primary.b, a);
            }

            if (scaleMultiplier > 0.01f)
                SetAuraScale(scaleMultiplier);

            RefreshAuraVisualCaches();
        }

        public void SetAuraScale(float scaleMultiplier)
        {
            if (currentAura == null) return;
            if (_refinedAura != null) { UpdateAuraPosition(); return; }
            if (_perLimbAura)
            {
                float personScale = person != null ? Mathf.Abs(person.transform.localScale.x) : 1f;
                float scaleMul = personScale > 1.15f ? personScale : 1f;
                for (int i = 0; i < currentAura.transform.childCount; i++)
                {
                    var child = currentAura.transform.GetChild(i);
                    if (child == null) continue;
                    var follow = child.GetComponent<LimbAuraFollow>();
                    string limbName = follow != null && follow.Target != null ? follow.Target.name : child.name;
                    float local = GetLimbAuraScale(limbName) * scaleMul * Mathf.Max(0.01f, scaleMultiplier);
                    child.localScale = new Vector3(local, local, 1f);
                }
                return;
            }

            currentAura.transform.localScale = CompactAuraScale(baseScale * scaleMultiplier);
        }

        public void ToggleAuraVisibility(bool visible)
        {
            AuraVisible = visible;
            if (currentAura != null)
            {
                currentAura.SetActive(visible);
            }
        }

        private void OnDisable()
        {
            if (_retiringAura != null) Destroy(_retiringAura);
            if (_refinedAura != null) DestroyAura();
        }

        private void OnDestroy()
        {
            DestroyAura();
        }

        public class LimbAuraFollow : MonoBehaviour
        {
            public Transform Target;

            void LateUpdate()
            {
                if (Target == null)
                {
                    Destroy(gameObject);
                    return;
                }
                transform.position = Target.position;
                transform.rotation = Quaternion.identity;
            }
        }
    }

    public class UltraEgoDamageBoost : MonoBehaviour
    {
        public string CharacterId = "Vegeta";
        public string FormId = "UE";
        public float MaxBonusMultiplier = 2f;
        public float UpdateInterval = 0.2f;

        float _nextUpdate;
        float _baselineHealthSum;
        PersonBehaviour _person;
        TransformationContextMenu _menu;
        bool _wasActive;

        void Start()
        {
            _person = GetComponent<PersonBehaviour>();
            if (_person == null) _person = GetComponentInChildren<PersonBehaviour>();

            if (_person != null)
            {
                var head = _person.transform.Find("Head");
                if (head != null) _menu = head.GetComponent<TransformationContextMenu>();
            }
        }

        void Update()
        {
            if (Time.time < _nextUpdate) return;
            _nextUpdate = Time.time + Mathf.Max(0.05f, UpdateInterval);

            if (_person == null || _menu == null || !_person.IsAlive())
            {
                if (_wasActive)
                {
                    CharacterPowerCatalog.ResetRuntimeFormMultiplier(CharacterId, FormId);
                    _wasActive = false;
                }
                return;
            }

            bool active = _menu.Form == FormId;
            if (!active)
            {
                if (_wasActive)
                {
                    CharacterPowerCatalog.ResetRuntimeFormMultiplier(CharacterId, FormId);
                    _baselineHealthSum = 0f;
                    _wasActive = false;
                }
                return;
            }

            if (!_wasActive)
            {
                _baselineHealthSum = SumHealth(_person, useInitial: true);
                if (_baselineHealthSum <= 0f) _baselineHealthSum = 1f;
                _wasActive = true;
            }

            float current = SumHealth(_person, useInitial: false);
            float missingFrac = Mathf.Clamp01(1f - (current / _baselineHealthSum));
            float mult = 1f + missingFrac * Mathf.Max(0f, MaxBonusMultiplier - 1f);
            CharacterPowerCatalog.SetRuntimeFormMultiplier(CharacterId, FormId, mult);
        }

        static float SumHealth(PersonBehaviour person, bool useInitial)
        {
            if (person == null || person.Limbs == null) return 0f;
            float sum = 0f;
            for (int i = 0; i < person.Limbs.Length; i++)
            {
                var limb = person.Limbs[i];
                if (limb == null) continue;
                float v = useInitial ? limb.InitialHealth : limb.Health;
                if (float.IsNaN(v) || float.IsInfinity(v) || v < 0f) continue;
                sum += v;
            }
            return sum;
        }
    }

    public class ZenkaiBoostBehaviour : MonoBehaviour
    {
        static readonly string[] SaiyanMarkers =
        {
            "Goku", "Vegeta", "Gohan", "Broly", "Trunks", "Goten", "Gogeta", "Vegito", "Gogito",
            "Pan", "Paragus", "Gotenks", "Bardock", "Raditz", "Nappa", "Oozaru", "Cabba", "Kale",
            "Caulifla", "Shallot", "Turles", "Tarble", "Cumber", "Future Trunks"
        };

        PersonBehaviour _person;
        MultipliersAndStuffs _multipliers;
        float _baselineHealthSum;
        float _pendingDamage;

        public static bool IsSaiyan(string characterId, string displayName)
        {
            string hay = ((characterId ?? "") + " " + (displayName ?? "")).ToLowerInvariant();
            if (string.IsNullOrWhiteSpace(hay)) return false;
            for (int i = 0; i < SaiyanMarkers.Length; i++)
            {
                if (hay.IndexOf(SaiyanMarkers[i].ToLowerInvariant(), StringComparison.Ordinal) >= 0)
                    return true;
            }
            return false;
        }

        public void RegisterDamage(float damage)
        {
            if (!DBPU.Special_ZenkaiBoostEnabled) return;
            if (damage <= 0f || float.IsNaN(damage) || float.IsInfinity(damage)) return;
            _pendingDamage += damage;
        }

        void Start()
        {
            EnsureRefs();
            CaptureBaseline();
        }

        void Update()
        {
            if (!DBPU.Special_ZenkaiBoostEnabled || _pendingDamage <= 0f) return;
            EnsureRefs();
            if (_multipliers == null) return;
            if (_baselineHealthSum <= 0f) CaptureBaseline();
            if (_baselineHealthSum <= 0f) _baselineHealthSum = 1f;

            float frac = _pendingDamage / _baselineHealthSum;
            _pendingDamage = 0f;
            float gain = frac * Mathf.Max(0f, DBPU.Special_ZenkaiBoostScale);
            if (gain <= 0f) return;

            float max = Mathf.Max(1f, DBPU.Special_ZenkaiBoostMax);
            _multipliers.BoostMultiplier = Mathf.Min(_multipliers.BoostMultiplier + gain, max);
        }

        void EnsureRefs()
        {
            if (_person == null)
            {
                _person = GetComponent<PersonBehaviour>();
                if (_person == null) _person = GetComponentInChildren<PersonBehaviour>();
            }
            if (_multipliers == null)
            {
                var root = transform.root.gameObject;
                _multipliers = root.GetComponent<MultipliersAndStuffs>();
                if (_multipliers == null) _multipliers = root.AddComponent<MultipliersAndStuffs>();
            }
        }

        void CaptureBaseline()
        {
            _baselineHealthSum = SumHealth(_person, true);
        }

        static float SumHealth(PersonBehaviour person, bool useInitial)
        {
            if (person == null || person.Limbs == null) return 0f;
            float sum = 0f;
            for (int i = 0; i < person.Limbs.Length; i++)
            {
                var limb = person.Limbs[i];
                if (limb == null) continue;
                float v = useInitial ? limb.InitialHealth : limb.Health;
                if (float.IsNaN(v) || float.IsInfinity(v) || v < 0f) continue;
                sum += v;
            }
            return sum;
        }
    }

    public class UltraInstinctEvasion : MonoBehaviour
    {
        public float UiChance = 0.45f;
        public float MuiChance = 0.75f;
        public float DodgeDuration = 0.25f;

        static readonly Dictionary<long, bool> FrameRollCache = new Dictionary<long, bool>();
        static readonly List<UltraInstinctEvasion> ActiveEvaders = new List<UltraInstinctEvasion>();
        static bool _globalHooksReady;

        PersonBehaviour _person;
        UltraInstinctEvasionLimb[] _limbs;
        bool _dodging;
        bool _limbsReady;
        float _nextEvasionRoll;

        public bool IsDodging => _dodging;

        void Awake()
        {
            _person = GetComponent<PersonBehaviour>();
            if (_person == null) _person = GetComponentInChildren<PersonBehaviour>();
        }

        void OnEnable()
        {
            if (!ActiveEvaders.Contains(this)) ActiveEvaders.Add(this);
            EnsureGlobalHooks();
        }

        void OnDisable()
        {
            ActiveEvaders.Remove(this);
        }

        void Start()
        {
            EnsureLimbs();
        }

        static void EnsureGlobalHooks()
        {
            if (_globalHooksReady) return;
            _globalHooksReady = true;

            ModAPI.OnGunShot += (_, gun) =>
            {
                if (gun == null) return;
                for (int i = 0; i < ActiveEvaders.Count; i++)
                {
                    var evasion = ActiveEvaders[i];
                    if (evasion != null && evasion.isActiveAndEnabled)
                        evasion.OnGunShot(gun);
                }
            };

            ModAPI.OnItemSpawned += (_, sender) =>
            {
                if (sender.Instance == null || !sender.Instance.TryGetComponent(out ExplosiveBehaviour explosive)) return;
                explosive.OnExplode.AddListener(() =>
                {
                    for (int i = 0; i < ActiveEvaders.Count; i++)
                    {
                        var evasion = ActiveEvaders[i];
                        if (evasion != null && evasion.isActiveAndEnabled)
                            evasion.OnExplosion(explosive.transform.position);
                    }
                });
            };
        }

        void OnGunShot(FirearmBehaviour gun)
        {
            if (_person == null || _person.Limbs == null || _person.Limbs.Length == 0 || !IsActiveFor(_person)) return;
            float dist = Vector3.Distance(gun.transform.position, _person.Limbs[0].transform.position);
            float delay = dist / gun.Cartridge.StartSpeed / 50f - 0.02f;
            TryDodge(Mathf.Max(0f, delay));
        }

        void OnExplosion(Vector3 position)
        {
            if (_person == null || !IsActiveFor(_person)) return;
            if (Vector3.Distance(position, MCP_Utils.GetMiddlePositionOfBody(_person)) > 8f) return;
            TryDodge(0f);
        }

        void EnsureLimbs()
        {
            if (_limbsReady || _person == null || _person.Limbs == null) return;

            _limbs = new UltraInstinctEvasionLimb[_person.Limbs.Length];
            for (int i = 0; i < _person.Limbs.Length; i++)
            {
                var limb = _person.Limbs[i];
                if (limb == null) continue;

                var limbEvasion = limb.gameObject.GetComponent<UltraInstinctEvasionLimb>();
                if (limbEvasion == null) limbEvasion = limb.gameObject.AddComponent<UltraInstinctEvasionLimb>();
                limbEvasion.Limb = limb;
                limbEvasion.Root = this;
                limbEvasion.EnsureTrigger();
                _limbs[i] = limbEvasion;
            }

            _limbsReady = true;
        }

        public static PersonBehaviour PersonFromPhys(PhysicalBehaviour phys)
        {
            if (phys == null) return null;
            return phys.transform.root.GetComponent<PersonBehaviour>();
        }

        public static PersonBehaviour FindAttackerNearPoint(PersonBehaviour victim, Vector3 point, float maxRadius = 3f)
        {
            if (victim == null) return null;

            PersonBehaviour best = null;
            float bestDist = maxRadius;

            var all = UnityEngine.Object.FindObjectsOfType<PersonBehaviour>();
            for (int i = 0; i < all.Length; i++)
            {
                var p = all[i];
                if (p == null || p == victim || !p.IsAlive()) continue;

                float d = Vector3.Distance(MCP_Utils.GetMiddlePositionOfBody(p), point);
                if (d < bestDist)
                {
                    bestDist = d;
                    best = p;
                }
            }

            return best;
        }

        public static bool TryEvade(LimbBehaviour limb, Vector3? attackPoint = null, PersonBehaviour attacker = null)
        {
            return false;
        }

        public static bool IsUltraInstinctForm(string form)
        {
            return form == "UI" || form == "MUI";
        }

        public static string GetActiveForm(PersonBehaviour person)
        {
            if (person == null) return "Base";

            var headTransform = person.transform.Find("Head");
            if (headTransform != null)
            {
                var headMenu = headTransform.GetComponent<TransformationContextMenu>();
                if (headMenu != null && !string.IsNullOrEmpty(headMenu.Form))
                    return headMenu.Form;
            }

            if (person.Limbs != null)
            {
                for (int i = 0; i < person.Limbs.Length; i++)
                {
                    var limb = person.Limbs[i];
                    if (limb == null) continue;
                    var menu = limb.GetComponent<TransformationContextMenu>();
                    if (menu != null && !string.IsNullOrEmpty(menu.Form))
                        return menu.Form;
                }
            }

            var ki = person.GetComponent<KiSystem>();
            if (ki != null && !string.IsNullOrEmpty(ki.CurrentForm))
                return ki.CurrentForm;

            return "Base";
        }

        public static bool IsActiveFor(PersonBehaviour person)
        {
            return false;
        }

        public void RequestDodge(float delay)
        {
            if (!IsActiveFor(_person)) return;
            TryDodge(delay);
        }

        bool TryDodge(float delay)
        {
            if (_person == null || !_person.IsAlive() || !IsActiveFor(_person)) return false;
            if (Time.time < _nextEvasionRoll) return false;

            string form = GetActiveForm(_person);
            float chance = form == "MUI" ? MuiChance : UiChance;
            if (!_dodging && UnityEngine.Random.value > chance) return false;

            _nextEvasionRoll = Time.time + 0.08f;
            StopAllCoroutines();
            StartCoroutine(DodgeRoutine(delay));
            return true;
        }

        IEnumerator DodgeRoutine(float delay)
        {
            if (delay > 0f) yield return new WaitForSeconds(delay);

            EnsureLimbs();
            if (_person == null || !_person.IsAlive() || _limbs == null) yield break;

            _dodging = true;

            for (int i = 0; i < _limbs.Length; i++)
            {
                var limbEvasion = _limbs[i];
                if (limbEvasion == null || limbEvasion.Limb == null) continue;
                var limb = limbEvasion.Limb;
                if (limb.Collider != null) limb.Collider.enabled = false;
                if (limb.PhysicalBehaviour != null && limb.PhysicalBehaviour.rigidbody != null)
                    limb.PhysicalBehaviour.rigidbody.constraints = RigidbodyConstraints2D.FreezeAll;
                limbEvasion.ShouldDoDodgeEffect = true;
            }

            yield return new WaitForSeconds(DodgeDuration);

            for (int i = 0; i < _limbs.Length; i++)
            {
                var limbEvasion = _limbs[i];
                if (limbEvasion == null || limbEvasion.Limb == null) continue;
                var limb = limbEvasion.Limb;
                limbEvasion.ShouldDoDodgeEffect = false;
                if (limb.Collider != null) limb.Collider.enabled = true;
                if (limb.PhysicalBehaviour != null && limb.PhysicalBehaviour.rigidbody != null)
                    limb.PhysicalBehaviour.rigidbody.constraints = RigidbodyConstraints2D.None;
            }

            _dodging = false;
        }

        public class UltraInstinctEvasionLimb : MonoBehaviour
        {
            public LimbBehaviour Limb;
            public UltraInstinctEvasion Root;
            GameObject _triggerObject;
            GameObject _childSprite;
            bool _doDodge;
            Coroutine _createGhostCo;

            public bool ShouldDoDodgeEffect
            {
                get { return _doDodge; }
                set
                {
                    if (_doDodge == value) return;
                    if (value)
                    {
                        if (Root != null && Root._person != null)
                        {
                            foreach (var sr in Root._person.GetComponentsInChildren<SpriteRenderer>(true))
                            {
                                if (sr == null) continue;
                                if (IsDodgeGhost(sr.transform)) continue;
                                sr.enabled = false;
                            }
                        }

                        if (_createGhostCo != null) StopCoroutine(_createGhostCo);
                        _createGhostCo = StartCoroutine(CreateGhostNextFrame());
                    }
                    else
                    {
                        if (_createGhostCo != null)
                        {
                            StopCoroutine(_createGhostCo);
                            _createGhostCo = null;
                        }
                        if (_childSprite != null)
                        {
                            Destroy(_childSprite);
                            _childSprite = null;
                        }
                        if (Root != null && Root._person != null)
                        {
                            foreach (var sr in Root._person.GetComponentsInChildren<SpriteRenderer>(true))
                            {
                                if (sr == null) continue;
                                if (IsDodgeGhost(sr.transform)) continue;
                                sr.enabled = true;
                            }
                        }
                    }
                    _doDodge = value;
                }
            }

            static bool IsDodgeGhost(Transform t)
            {
                while (t != null)
                {
                    if (t.name == "UIDodgeGhost") return true;
                    t = t.parent;
                }
                return false;
            }

            IEnumerator CreateGhostNextFrame()
            {
                yield return null;
                _createGhostCo = null;
                if (!_doDodge || Limb == null || Limb.SkinMaterialHandler == null || Limb.SkinMaterialHandler.renderer == null)
                    yield break;

                var src = Limb.SkinMaterialHandler.renderer;
                if (_childSprite != null) Destroy(_childSprite);

                _childSprite = new GameObject("UIDodgeGhost");
                _childSprite.transform.SetParent(transform, false);
                _childSprite.transform.localPosition = Vector3.zero;
                _childSprite.transform.localRotation = Quaternion.identity;
                _childSprite.transform.localScale = Vector3.one;

                var ghostSr = _childSprite.AddComponent<SpriteRenderer>();
                ghostSr.sprite = src.sprite;
                ghostSr.color = src.color;
                ghostSr.flipX = src.flipX;
                ghostSr.flipY = src.flipY;
                ghostSr.sortingLayerName = src.sortingLayerName;
                ghostSr.sortingOrder = src.sortingOrder;
            }

            void FixedUpdate()
            {
                if (!_doDodge || _childSprite == null) return;
                float shakeOffset = Mathf.Sin(Time.time * 100f) / 2f;
                _childSprite.transform.position = new Vector3(
                    transform.position.x + shakeOffset,
                    transform.position.y,
                    transform.position.z);
            }

            public void EnsureTrigger()
            {
                if (_triggerObject != null) return;

                _triggerObject = new GameObject("UIEvasionTrigger");
                _triggerObject.layer = 9;
                _triggerObject.transform.SetParent(transform);
                _triggerObject.transform.localPosition = Vector3.zero;

                var trigger = _triggerObject.AddComponent<CircleCollider2D>();
                trigger.radius = 5f;
                trigger.isTrigger = true;

                var trig = _triggerObject.AddComponent<UltraInstinctEvasionTrigger>();
                trig.Root = Root;
            }

            void OnDisable()
            {
                ShouldDoDodgeEffect = false;
            }
        }

        class UltraInstinctEvasionTrigger : MonoBehaviour
        {
            public UltraInstinctEvasion Root;

            void OnTriggerStay2D(Collider2D other)
            {
                if (Root == null || other.transform.root == transform.root) return;
                if (other.gameObject.layer != 9 && other.gameObject.layer != 13) return;

                var rb = other.attachedRigidbody;
                float speed = rb != null ? rb.velocity.magnitude : 0.4f;
                if (Vector3.Distance(other.transform.position, transform.position) > Mathf.Max(speed, 0.4f) / 4f) return;

                Root.RequestDodge(0f);
            }
        }
    }

    public class CharacterSkins : MonoBehaviour
    {
        public class Skins
        {
            public class SkinInfo
            {
                public Dictionary<string, Dictionary<string, Dictionary<string, List<Sprite>>>> Skins { get; set; }



                //public Dictionary<string, Dictionary<string, List<Sprite>>> Skins { get; set; }

                public Dictionary<string, Dictionary<string, List<Sprite>>> RequiredSkins { get; set; }
                public List<PhyAccessoryData> PhyAccessories { get; set; }

                ///public Sprite Illustration { get; set; }
                public Dictionary<string, Sprite> Illustrations { get; set; }
                public string DisplayName { get; set; }

                public string Name { get; set; }
                public string PackFolderName { get; set; }
                public Dictionary<string, Sprite> HairSprites { get; set; }
            }

            public class PhyAccessoryData
            {
                public Transform objForAttach { get; set; }
                public Vector2 connectedAnchor { get; set; }
                public string layerName { get; set; }
                public int order { get; set; }
                public Sprite[] sprites { get; set; }
                public float minAngleFirstPiece { get; set; }
                public float maxAngleFirstPiece { get; set; }
                public float minAngle { get; set; }
                public float maxAngle { get; set; }
                public float pieceMass { get; set; }
                public float pieceInertia { get; set; }
                public string Name { get; set; }
                public bool HasCollision { get; set; }
                public bool CollideJustWithGround { get; set; } = true;
            }

            public Dictionary<string, SkinInfo> SkinData { get; private set; } = new Dictionary<string, SkinInfo>();

            public void AddSkin(string key, SkinInfo skinInfo)
            {
                if (!SkinData.ContainsKey(key))
                {
                    SkinData[key] = skinInfo;
                }
            }

            public void UpsertSkin(string key, SkinInfo skinInfo)
            {
                if (string.IsNullOrEmpty(key) || skinInfo == null) return;
                SkinData[key] = skinInfo;
            }

            public bool RemoveSkin(string key)
            {
                return !string.IsNullOrEmpty(key) && SkinData.Remove(key);
            }
        }

        public Skins skins = new Skins();

        public string GetSkinTransformationTargetID(string skinKey, string suffixKey)
        {
            string fullSkinKey = skinKey + suffixKey;
            string transformationTargetID = "None";

            if (!skins.SkinData.ContainsKey(skinKey)) return transformationTargetID;

            var skinData = skins.SkinData[skinKey];

            if (!skinData.Skins.ContainsKey(fullSkinKey)) return transformationTargetID;

            var transformationVariants = skinData.Skins[fullSkinKey];

            var head = gameObject.GetComponent<PersonBehaviour>().Limbs[0].gameObject;
            var transformationMenu = head.GetComponent<TransformationContextMenu>();

            if (transformationMenu != null && !string.IsNullOrEmpty(transformationMenu.Form))
            {
                if (transformationVariants.ContainsKey(transformationMenu.Form))
                {
                    return transformationMenu.Form;
                }
            }

            if (transformationVariants.ContainsKey("None")) return "None";
            //if (transformationVariants.ContainsKey("Base")) return "Base";

            return transformationVariants.Keys.First();
        }

        public int GetSkinDamageVariantCount(string skinKey, string suffixKey)
        {
            string fullSkinKey = skinKey + suffixKey;

            if (!skins.SkinData.ContainsKey(skinKey)) return 0;

            var skinData = skins.SkinData[skinKey];

            if (!skinData.Skins.ContainsKey(fullSkinKey)) return 0;

            string transformationTargetID = GetSkinTransformationTargetID(skinKey, suffixKey);

            if (!skinData.Skins[fullSkinKey].ContainsKey(transformationTargetID)) return 0;

            return skinData.Skins[fullSkinKey][transformationTargetID].Count;
        }

        public void ApplySkin(PersonBehaviour person, string skinKey, string suffixKey, int Damage = 0)
        {
            if (!skins.SkinData.ContainsKey(skinKey))
            {
                Debug.LogWarning($"skin '{skinKey}' not found.");
                return;
            }

            DBPU.DbpuCustomSkinLoader.EnsureSkinSpritesLoaded(this, skinKey);

            var t = skins.SkinData[skinKey];

            string fullSkinKey = skinKey + suffixKey;
            string transformationTargetID = GetSkinTransformationTargetID(skinKey, suffixKey);
            string damageKey = "Damage" + Damage;

            if (!t.Skins.ContainsKey(fullSkinKey))
            {
                Debug.LogWarning($"skin variant '{fullSkinKey}' not found.");
                return;
            }

            if (!t.Skins[fullSkinKey].ContainsKey(transformationTargetID))
            {
                Debug.LogWarning($"skin transformation target '{transformationTargetID}' not found in skin '{fullSkinKey}'.");
                return;
            }

            if (!t.Skins[fullSkinKey][transformationTargetID].ContainsKey(damageKey))
            {
                Debug.LogWarning($"skin damage variant '{damageKey}' not found in skin '{fullSkinKey}' for transformation '{transformationTargetID}'.");
                return;
            }

            var selectedSprites = t.Skins[fullSkinKey][transformationTargetID][damageKey];
            if (selectedSprites == null || selectedSprites.Count < 14)
            {
                Debug.LogWarning($"skin sprites incomplete for '{fullSkinKey}' damage '{damageKey}'.");
                return;
            }

            Transform headTf = null;
            var personOnSelf = gameObject.GetComponent<PersonBehaviour>();
            if (personOnSelf?.Limbs != null)
            {
                for (int i = 0; i < personOnSelf.Limbs.Length; i++)
                {
                    if (personOnSelf.Limbs[i] != null
                        && personOnSelf.Limbs[i].name.IndexOf("Head", StringComparison.OrdinalIgnoreCase) >= 0)
                    {
                        headTf = personOnSelf.Limbs[i].transform;
                        break;
                    }
                }
                if (headTf == null && personOnSelf.Limbs.Length > 0 && personOnSelf.Limbs[0] != null)
                    headTf = personOnSelf.Limbs[0].transform;
            }
            Skins.SkinInfo t2 = null;
            if (headTf != null)
            {
                var skinMenu = headTf.GetComponent<SkinContextMenu>();
                if (skinMenu != null
                    && !string.IsNullOrEmpty(skinMenu.CurrentSkin)
                    && skins.SkinData.TryGetValue(skinMenu.CurrentSkin, out var currentInfo))
                    t2 = currentInfo;
            }
            if (t2 == null) t2 = t;

            Sprite headSprite = selectedSprites[0];
            List<Sprite> skin = new List<Sprite>
            {
                headSprite,
                selectedSprites[1],
                selectedSprites[2],
                selectedSprites[3],
                selectedSprites[4],
                selectedSprites[5],
                selectedSprites[6],
                selectedSprites[7],
                selectedSprites[8],
                selectedSprites[9],
                selectedSprites[10],
                selectedSprites[11],
                selectedSprites[12],
                selectedSprites[13]
            };

            person.ChangeSkin(skin);

            if (headSprite != null)
            {
                if (headTf == null && person != null)
                {
                    headTf = person.transform.root.Find("Head");
                    if (headTf == null && person.Limbs != null)
                    {
                        for (int i = 0; i < person.Limbs.Length; i++)
                        {
                            if (person.Limbs[i] != null
                                && person.Limbs[i].name.IndexOf("Head", StringComparison.OrdinalIgnoreCase) >= 0)
                            {
                                headTf = person.Limbs[i].transform;
                                break;
                            }
                        }
                    }
                }
                if (headTf != null)
                    headTf.gameObject.ChangeLimbSprite(headSprite, LimbsStorage.FHead, LimbsStorage.BHead, LimbsStorage.DHead);
            }

            ApplySkinHair(person, t, damageKey, headTf);

            if (t2 != null && t2.PhyAccessories != null)
            {
                foreach (Skins.PhyAccessoryData data in t2.PhyAccessories)
                {
                    if (data == null || data.objForAttach == null) continue;
                    foreach (Transform child in data.objForAttach)
                    {
                        if (child != null && child.name == data.Name)
                        {
                            GameObject.Destroy(child.gameObject);
                        }
                    }
                }
            }

            if (t.PhyAccessories != null)
            {
                foreach (Skins.PhyAccessoryData data in t.PhyAccessories)
                {
                    if (data == null || data.objForAttach == null || data.sprites == null) continue;
                    PHY.Cro.CreatePhysicalCloth(data.objForAttach, data.connectedAnchor, data.layerName, data.order, data.sprites, data.minAngleFirstPiece, data.maxAngleFirstPiece, data.minAngle, data.maxAngle, data.pieceMass, data.pieceInertia, data.Name, data.HasCollision, data.CollideJustWithGround);
                }
            }
        }

        static Sprite ResolveFormHairSprite(PersonBehaviour person)
        {
            if (person == null) return null;
            var root = person.transform.root;
            Transform head = root.Find("Head");
            if (head == null && person.Limbs != null)
            {
                for (int i = 0; i < person.Limbs.Length; i++)
                {
                    if (person.Limbs[i] != null
                        && person.Limbs[i].name.IndexOf("Head", StringComparison.OrdinalIgnoreCase) >= 0)
                    {
                        head = person.Limbs[i].transform;
                        break;
                    }
                }
            }
            if (head == null) return null;

            string formId = null;
            var menu = head.GetComponent<TransformationContextMenu>();
            if (menu != null) formId = menu.Form;

            var ct = root.GetComponent<CharacterTransformations>();
            if (ct?.transformations?.TransformationData != null && !string.IsNullOrEmpty(formId)
                && ct.transformations.TransformationData.TryGetValue(formId, out var stats)
                && stats != null && stats.HairSprite != null)
                return stats.HairSprite;

            var identity = root.GetComponent<DbpuCharacterIdentity>();
            if (identity != null && !string.IsNullOrEmpty(identity.CharacterId) && !string.IsNullOrEmpty(formId))
            {
                var dto = CustomTransformationCatalog.GetForm(identity.CharacterId, formId);
                if (dto != null && !string.IsNullOrEmpty(dto.HairSpritePath))
                {
                    Sprite fromDto = CustomTransformationCatalog.ResolveSpriteReference(dto.HairSpritePath, root.gameObject, true);
                    if (fromDto != null) return fromDto;
                }
            }

            if (ct?.transformations?.TransformationData != null
                && ct.transformations.TransformationData.TryGetValue("Base", out var baseStats)
                && baseStats != null && baseStats.HairSprite != null)
                return baseStats.HairSprite;

            return null;
        }

        void ApplySkinHair(PersonBehaviour person, Skins.SkinInfo info, string damageKey, Transform headTf)
        {
            if (person == null) return;
            if (headTf == null)
            {
                headTf = person.transform.root.Find("Head");
                if (headTf == null && person.Limbs != null)
                {
                    for (int i = 0; i < person.Limbs.Length; i++)
                    {
                        if (person.Limbs[i] != null
                            && person.Limbs[i].name.IndexOf("Head", StringComparison.OrdinalIgnoreCase) >= 0)
                        {
                            headTf = person.Limbs[i].transform;
                            break;
                        }
                    }
                }
            }
            if (headTf == null) return;

            Sprite packHair = null;
            if (info?.HairSprites != null)
            {
                if (!string.IsNullOrEmpty(damageKey) && info.HairSprites.TryGetValue(damageKey, out packHair) && packHair != null)
                { }
                else if (info.HairSprites.TryGetValue("Damage0", out packHair) && packHair != null)
                { }
                else
                    packHair = null;
            }

            if (packHair != null)
            {
                TmHairApply.ApplyHair(headTf, packHair, Color.white, Vector3.zero, false);
                return;
            }

            Sprite formHair = ResolveFormHairSprite(person);
            if (formHair != null)
                TmHairApply.ApplyHair(headTf, formHair, Color.white, Vector3.zero, false);
        }
    }

    public class SkinContextMenu : MonoBehaviour
    {
        public string CurrentSkin;
        public string Skin_Suffix = "";
        public string PreviousSkin;
        public int CurrentDamage = 0;
        public int PreviousDamage = 0;
        public bool SkinDamage = false;

        public int Pages = 0;
        public int Page = 0;
        public int PreviousPage = 0;

        public PersonBehaviour person;
        public CharacterSkins SkinsData;

        public List<KeyValuePair<string, CharacterSkins.Skins.SkinInfo>> RefreshSkinList()
        {
            if (SkinsData == null || SkinsData.skins == null || SkinsData.skins.SkinData == null)
            {
                Pages = 0;
                Page = 0;
                return new List<KeyValuePair<string, CharacterSkins.Skins.SkinInfo>>();
            }

            var list = SkinsData.skins.SkinData.ToList();
            Pages = Mathf.Max(0, list.Count - 1);
            if (Page < 0) Page = 0;
            else if (Page > Pages) Page = Pages;
            return list;
        }

        public void JumpToSkin(string skinKey)
        {
            var list = RefreshSkinList();
            if (string.IsNullOrEmpty(skinKey) || list.Count == 0) return;
            for (int i = 0; i < list.Count; i++)
            {
                if (string.Equals(list[i].Key, skinKey, StringComparison.OrdinalIgnoreCase))
                {
                    Page = i;
                    PreviousPage = i;
                    return;
                }
                var info = list[i].Value;
                if (info != null && string.Equals(info.Name, skinKey, StringComparison.OrdinalIgnoreCase))
                {
                    Page = i;
                    PreviousPage = i;
                    return;
                }
            }
        }

        public void Start()
        {
            person = transform.root.gameObject.GetComponent<PersonBehaviour>();
            RefreshSkinList();
        }

        public void Awake()
        {
            gameObject.GetComponent<PhysicalBehaviour>().ContextMenuOptions.Buttons.Add(new ContextMenuButton("!SkinsMenu", "Skins Menu", "Skins Menu", () =>
            {
                var firstList = RefreshSkinList();
                if (firstList.Count == 0) return;
                if (Page < 0 || Page >= firstList.Count) Page = 0;
                DBPU.DbpuCustomSkinLoader.EnsureSkinSpritesLoaded(SkinsData, firstList[Page].Key);
                firstList = RefreshSkinList();
                if (Page < 0 || Page >= firstList.Count) return;
                var firstValue = firstList[Page].Value;
                if (firstValue == null) return;
                if (firstValue.Illustrations == null)
                    firstValue.Illustrations = new Dictionary<string, Sprite>();

                int CountOfVariants = firstValue.Illustrations.Count;
                if (CountOfVariants > 0)
                {
                    if (CurrentDamage < 0) CurrentDamage = 0;
                    else if (CurrentDamage > CountOfVariants - 1) CurrentDamage = CountOfVariants - 1;
                }

                Sprite ResolveIllustration(CharacterSkins.Skins.SkinInfo info, int damage)
                {
                    if (info?.Illustrations == null) return null;
                    string key = "Damage" + damage;
                    if (info.Illustrations.TryGetValue(key, out var spr) && spr != null) return spr;
                    if (info.Illustrations.TryGetValue("Damage0", out var d0) && d0 != null) return d0;
                    foreach (var kv in info.Illustrations)
                        if (kv.Value != null) return kv.Value;
                    return null;
                }

                GameObject Canvas = new GameObject("TCanvas");
                Canvas.transform.SetParent(GameObject.Find("Canvas").transform);
                var canvasImg = Canvas.GetOrAddComponent<Image>();
                canvasImg.color = Color.clear;
                canvasImg.raycastTarget = false;
                RectTransform canvasRt = Canvas.GetComponent<RectTransform>();
                canvasRt.anchorMin = new Vector2(0.5f, 0.5f);
                canvasRt.anchorMax = new Vector2(0.5f, 0.5f);
                canvasRt.pivot = new Vector2(0.5f, 0.5f);
                canvasRt.anchoredPosition = Vector2.zero;
                canvasRt.sizeDelta = new Vector2(1400f, 650f);
                canvasRt.localScale = Vector3.one;
                Canvas.AddComponent<ExistIf>().obj = gameObject;

                float skinMenuScale = 1f;

                GameObject NameArea = new GameObject("NameArea");
                NameArea.transform.SetParent(Canvas.transform);
                Image nameAreaImg = NameArea.GetOrAddComponent<Image>();
                nameAreaImg.sprite = DBPU.SNameArea;
                nameAreaImg.raycastTarget = true;
                RectTransform nameAreaRt = NameArea.GetComponent<RectTransform>();
                nameAreaRt.anchoredPosition = Vector2.zero;
                nameAreaRt.localScale = new Vector3(5.56f, 2.78f, 1f);
                nameAreaRt.localPosition = new Vector3(430f, 240f, 0f);
                var nameAreaDrag = NameArea.AddComponent<ModMenuDragResize>();
                nameAreaDrag.moveRoot = canvasRt;

                GameObject textstorageobject = new GameObject("SkinsTitle");
                textstorageobject.transform.SetParent(NameArea.transform, false);

                RectTransform textRectTransform = textstorageobject.AddComponent<RectTransform>();
                textRectTransform.anchoredPosition = new Vector2(0f, 26f);
                textRectTransform.localScale = new Vector3(1.65f, 3f);

                TextMeshProUGUI textstorage = textstorageobject.AddComponent<TextMeshProUGUI>();
                textstorage.text = "SKINS";
                textstorage.fontSize = 10;
                textstorage.font = ModAPI.FindSpawnable("Holographic Display").Prefab.transform.Find("Text").GetComponent<TextMeshPro>().font;
                textstorage.alignment = TextAlignmentOptions.Center;
                textstorage.color = new Color(0f, 0f, 0f);
                textstorage.enableWordWrapping = false;
                textstorage.raycastTarget = false;

                GameObject NameText = new GameObject("Name Text");
                NameText.transform.SetParent(NameArea.transform, false);

                RectTransform NameTextRectTransform = NameText.AddComponent<RectTransform>();
                NameTextRectTransform.anchoredPosition = new Vector2(0f, 0f);
                NameTextRectTransform.localScale = new Vector3(1.5f, 3f);
                NameTextRectTransform.anchorMin = new Vector2(0.5f, 0.5f);
                NameTextRectTransform.anchorMax = new Vector2(0.5f, 0.5f);
                NameTextRectTransform.pivot = new Vector2(0.5f, 0.5f);
                NameTextRectTransform.offsetMax = new Vector2(25f, 20f);
                NameTextRectTransform.offsetMin = new Vector2(-25f, -70f);

                TextMeshProUGUI NameTextStorage = NameText.AddComponent<TextMeshProUGUI>();
                NameTextStorage.text = firstValue.DisplayName;
                NameTextStorage.fontSize = 8;
                NameTextStorage.enableAutoSizing = true;
                NameTextStorage.fontSizeMin = 3;
                NameTextStorage.fontSizeMax = 8;
                NameTextStorage.font = ModAPI.FindSpawnable("Holographic Display").Prefab.transform.Find("Text").GetComponent<TextMeshPro>().font;
                NameTextStorage.alignment = TextAlignmentOptions.Center;
                NameTextStorage.color = new Color(0f, 0f, 0f);
                NameTextStorage.enableWordWrapping = false;
                NameTextStorage.raycastTarget = false;

                MenuUI.AttachResizeHandle(
                    Canvas.transform,
                    () => skinMenuScale,
                    (u) =>
                    {
                        skinMenuScale = u;
                        canvasRt.localScale = new Vector3(u, u, 1f);
                    },
                    0.6f,
                    2.5f,
                    12f);

                GameObject Illustration = new GameObject("Illustration");
                Illustration.transform.SetParent(Canvas.transform);
                Illustration.GetOrAddComponent<Image>().sprite = ResolveIllustration(firstValue, CurrentDamage);
                Illustration.GetComponent<RectTransform>().anchoredPosition = new Vector2(-380f, -34f);
                Illustration.GetComponent<RectTransform>().localScale = new Vector3(5.65f, 8.251f, 1f);

                GameObject DamageVariant = new GameObject("DamageVariant");
                DamageVariant.transform.SetParent(Canvas.transform);
                DamageVariant.GetOrAddComponent<Image>().sprite = DBPU.SDamageVariantArea;
                DamageVariant.GetComponent<Image>().color = Color.clear;
                if (CountOfVariants > 1) DamageVariant.GetComponent<Image>().color = Color.white;
                DamageVariant.GetComponent<RectTransform>().anchoredPosition = new Vector2(430f, 5f);
                DamageVariant.GetComponent<RectTransform>().localScale = new Vector3(2.6f, 1.434f, 1f);

                GameObject DamageVariantText = new GameObject("Damage Text");
                DamageVariantText.transform.SetParent(DamageVariant.transform, false);

                RectTransform DamageVariantTextRectTransform = DamageVariantText.AddComponent<RectTransform>();
                DamageVariantTextRectTransform.localScale = new Vector3(3.3f, 6f, 0f);
                DamageVariantTextRectTransform.anchorMin = new Vector2(0.5f, 0.5f);
                DamageVariantTextRectTransform.anchorMax = new Vector2(0.5f, 0.5f);
                DamageVariantTextRectTransform.pivot = new Vector2(-0.075f, 1.025f);
                DamageVariantTextRectTransform.offsetMax = new Vector2(-25f, 49f);
                DamageVariantTextRectTransform.offsetMin = new Vector2(8f, 35f);

                TextMeshProUGUI DamageVariantTextStorage = DamageVariantText.AddComponent<TextMeshProUGUI>();
                DamageVariantTextStorage.text = CurrentDamage.ToString();
                DamageVariantTextStorage.fontSize = 8;
                DamageVariantTextStorage.enableAutoSizing = false;
                DamageVariantTextStorage.font = ModAPI.FindSpawnable("Holographic Display").Prefab.transform.Find("Text").GetComponent<TextMeshPro>().font;
                DamageVariantTextStorage.alignment = TextAlignmentOptions.Center;
                DamageVariantTextStorage.color = new Color(0f, 0f, 0f, 1f);
                if (CountOfVariants - 1 == 0) DamageVariantTextStorage.color = Color.clear;
                DamageVariantTextStorage.enableWordWrapping = false;

                GameObject NextDamage = new GameObject("NextDamage");
                NextDamage.transform.SetParent(Canvas.transform);
                NextDamage.GetOrAddComponent<Image>().sprite = DBPU.SNextDamage;
                NextDamage.GetComponent<Image>().color = Color.clear;
                if (CurrentDamage < CountOfVariants - 1) NextDamage.GetComponent<Image>().color = Color.white;
                NextDamage.GetComponent<RectTransform>().anchoredPosition = new Vector2(636f, 5f);
                NextDamage.GetComponent<RectTransform>().localScale = new Vector3(1.434f, 1.434f, 1f);

                GameObject PrevioursDamage = new GameObject("PreviousDamage");
                PrevioursDamage.transform.SetParent(Canvas.transform);
                PrevioursDamage.GetOrAddComponent<Image>().sprite = DBPU.SPreviousDamage;
                PrevioursDamage.GetComponent<Image>().color = Color.clear;
                if (CurrentDamage > 0) PrevioursDamage.GetComponent<Image>().color = Color.white;
                PrevioursDamage.GetComponent<RectTransform>().anchoredPosition = new Vector2(224f, 5f);
                PrevioursDamage.GetComponent<RectTransform>().localScale = new Vector3(1.434f, 1.434f, 1f);

                NextDamage.GetOrAddComponent<Button>().onClick.AddListener(() =>
                {
                    if (CurrentDamage >= CountOfVariants - 1) return;

                    CurrentDamage += 1;
                    DamageVariantTextStorage.text = CurrentDamage.ToString();
                    Illustration.GetComponent<Image>().sprite = ResolveIllustration(firstValue, CurrentDamage);

                    if (CurrentDamage >= CountOfVariants - 1)
                    {
                        NextDamage.GetComponent<Image>().color = Color.clear;
                    }

                    if (CurrentDamage > 0)
                    {
                        PrevioursDamage.GetComponent<Image>().color = Color.white;
                    }
                });

                PrevioursDamage.GetOrAddComponent<Button>().onClick.AddListener(() =>
                {
                    if (CurrentDamage <= 0) return;

                    CurrentDamage -= 1;
                    DamageVariantTextStorage.text = CurrentDamage.ToString();
                    Illustration.GetComponent<Image>().sprite = ResolveIllustration(firstValue, CurrentDamage);

                    if (CurrentDamage < CountOfVariants)
                    {
                        NextDamage.GetComponent<Image>().color = Color.white;
                    }

                    if (CurrentDamage <= 0)
                    {
                        PrevioursDamage.GetComponent<Image>().color = Color.clear;
                    }
                });

                GameObject NextPage = new GameObject("NextPage");
                NextPage.transform.SetParent(Canvas.transform);
                NextPage.GetOrAddComponent<Image>().sprite = DBPU.SNext;
                NextPage.GetComponent<Image>().color = Color.clear;
                if (Page < Pages) NextPage.GetComponent<Image>().color = Color.white;
                NextPage.GetComponent<RectTransform>().anchoredPosition = new Vector2(-26f, -34f);
                NextPage.GetComponent<RectTransform>().localScale = new Vector3(1.434f, 6.636f, 1f);

                GameObject PrevioursPage = new GameObject("PreviousPage");
                PrevioursPage.transform.SetParent(Canvas.transform);
                PrevioursPage.GetOrAddComponent<Image>().sprite = DBPU.SPrevious;
                PrevioursPage.GetComponent<Image>().color = Color.clear;
                if (Page > 0) PrevioursPage.GetComponent<Image>().color = Color.white;
                PrevioursPage.GetComponent<RectTransform>().anchoredPosition = new Vector2(-734f, -34f);
                PrevioursPage.GetComponent<RectTransform>().localScale = new Vector3(1.434f, 6.636f, 1f);

                NextPage.GetOrAddComponent<Button>().onClick.AddListener(() =>
                {
                    firstList = RefreshSkinList();
                    if (Page >= Pages || firstList.Count == 0) return;

                    Page += 1;

                    firstValue = firstList[Page].Value;
                    if (firstValue == null) return;
                    DBPU.DbpuCustomSkinLoader.EnsureSkinSpritesLoaded(SkinsData, firstList[Page].Key);
                    firstList = RefreshSkinList();
                    if (Page < 0 || Page >= firstList.Count) return;
                    firstValue = firstList[Page].Value;
                    if (firstValue == null) return;
                    if (firstValue.Illustrations == null)
                        firstValue.Illustrations = new Dictionary<string, Sprite>();
                    CountOfVariants = firstValue.Illustrations.Count;
                    if (CurrentDamage > CountOfVariants - 1) CurrentDamage = Mathf.Max(0, CountOfVariants - 1);

                    DamageVariantTextStorage.text = CurrentDamage.ToString();
                    NameTextStorage.text = firstValue.DisplayName;

                    Illustration.GetComponent<Image>().sprite = ResolveIllustration(firstValue, CurrentDamage);

                    if (CurrentDamage >= CountOfVariants - 1)
                    {
                        NextDamage.GetComponent<Image>().color = Color.clear;
                    }

                    if (CurrentDamage > 0)
                    {
                        PrevioursDamage.GetComponent<Image>().color = Color.white;
                    }

                    if (CountOfVariants - 1 == 0)
                    {
                        NextDamage.GetComponent<Image>().color = Color.clear;
                        PrevioursDamage.GetComponent<Image>().color = Color.clear;

                        DamageVariant.GetComponent<Image>().color = Color.clear;
                        DamageVariantTextStorage.color = Color.clear;
                    }

                    else
                    {
                        DamageVariant.GetComponent<Image>().color = Color.white;
                        DamageVariantTextStorage.color = new Color(0f, 0f, 0f, 1f);
                    }

                    if (Page > 0)
                    {
                        PrevioursPage.GetComponent<Image>().color = Color.white;
                    }

                    if (Page >= Pages)
                    {
                        NextPage.GetComponent<Image>().color = Color.clear;
                    }
                });

                PrevioursPage.GetOrAddComponent<Button>().onClick.AddListener(() =>
                {
                    firstList = RefreshSkinList();
                    if (Page <= 0 || firstList.Count == 0) return;

                    Page -= 1;

                    firstValue = firstList[Page].Value;
                    if (firstValue == null) return;
                    DBPU.DbpuCustomSkinLoader.EnsureSkinSpritesLoaded(SkinsData, firstList[Page].Key);
                    firstList = RefreshSkinList();
                    if (Page < 0 || Page >= firstList.Count) return;
                    firstValue = firstList[Page].Value;
                    if (firstValue == null) return;
                    if (firstValue.Illustrations == null)
                        firstValue.Illustrations = new Dictionary<string, Sprite>();
                    CountOfVariants = firstValue.Illustrations.Count;
                    if (CurrentDamage > CountOfVariants - 1) CurrentDamage = Mathf.Max(0, CountOfVariants - 1);

                    DamageVariantTextStorage.text = CurrentDamage.ToString();
                    NameTextStorage.text = firstValue.DisplayName;

                    Illustration.GetComponent<Image>().sprite = ResolveIllustration(firstValue, CurrentDamage);

                    if (CurrentDamage < CountOfVariants)
                    {
                        NextDamage.GetComponent<Image>().color = Color.white;
                    }

                    if (CurrentDamage <= 0)
                    {
                        PrevioursDamage.GetComponent<Image>().color = Color.clear;
                    }

                    if (CountOfVariants - 1 == 0)
                    {
                        NextDamage.GetComponent<Image>().color = Color.clear;
                        PrevioursDamage.GetComponent<Image>().color = Color.clear;

                        DamageVariant.GetComponent<Image>().color = Color.clear;
                        DamageVariantTextStorage.color = Color.clear;
                    }

                    else
                    {
                        DamageVariant.GetComponent<Image>().color = Color.white;
                        DamageVariantTextStorage.color = new Color(0f, 0f, 0f, 1f);
                    }

                    if (Page < Pages)
                    {
                        NextPage.GetComponent<Image>().color = Color.white;
                    }

                    if (Page <= 0)
                    {
                        PrevioursPage.GetComponent<Image>().color = Color.clear;
                    }
                });

                GameObject Cancel = new GameObject("Cancel");
                Cancel.transform.SetParent(Canvas.transform);
                Cancel.GetOrAddComponent<Image>().sprite = DBPU.SCancel;
                Cancel.GetOrAddComponent<Button>().onClick.AddListener(() =>
                {
                    CurrentDamage = PreviousDamage;
                    Page = PreviousPage;

                    Destroy(Canvas);
                });
                Cancel.GetComponent<RectTransform>().anchoredPosition = new Vector2(430f, -366f);
                Cancel.GetComponent<RectTransform>().localScale = new Vector3(4.394f, 1.614f, 1f);

                GameObject textstorageobject1 = new GameObject("cancel text");
                textstorageobject1.transform.SetParent(Cancel.transform, false);

                RectTransform textRectTransform1 = textstorageobject1.AddComponent<RectTransform>();
                textRectTransform1.anchoredPosition = new Vector2(0f, 0f);
                textRectTransform1.localScale = new Vector3(0.55f, 1f);
                textRectTransform1.localScale *= 3f;

                TextMeshProUGUI textstorage1 = textstorageobject1.AddComponent<TextMeshProUGUI>();
                textstorage1.text = "CANCEL";
                textstorage1.fontSize = 10;
                textstorage1.font = ModAPI.FindSpawnable("Holographic Display").Prefab.transform.Find("Text").GetComponent<TextMeshPro>().font;
                textstorage1.alignment = TextAlignmentOptions.Center;
                textstorage1.color = new Color(1f, 1f, 1f);
                textstorage1.enableWordWrapping = false;
                textstorage1.autoSizeTextContainer = true;

                GameObject Accept = new GameObject("Accept");
                Accept.transform.SetParent(Canvas.transform);
                Accept.GetOrAddComponent<Image>().sprite = DBPU.SAccept;
                Accept.GetComponent<RectTransform>().anchoredPosition = new Vector2(430f, -175f);
                Accept.GetComponent<RectTransform>().localScale = new Vector3(4.394f, 1.614f, 1f);
                Accept.GetOrAddComponent<Button>().onClick.AddListener(() =>
                {
                    firstList = RefreshSkinList();
                    if (firstList.Count == 0) return;
                    var value = firstList[Page].Value;

                    SkinsData.ApplySkin(person, value.Name, Skin_Suffix, CurrentDamage);

                    PreviousDamage = CurrentDamage;
                    CurrentSkin = value.Name;
                    PreviousSkin = CurrentSkin;
                    PreviousPage = Page;

                    Destroy(Canvas);
                });
                GameObject textstorageobject2 = new GameObject("accept text");
                textstorageobject2.transform.SetParent(Accept.transform, false);

                RectTransform textRectTransform2 = textstorageobject2.AddComponent<RectTransform>();
                textRectTransform2.anchoredPosition = new Vector2(0f, 0f);
                textRectTransform2.localScale = new Vector3(0.55f, 1f);
                textRectTransform2.localScale *= 3f;

                TextMeshProUGUI textstorage2 = textstorageobject2.AddComponent<TextMeshProUGUI>();
                textstorage2.text = "ACCEPT";
                textstorage2.fontSize = 10;
                textstorage2.font = ModAPI.FindSpawnable("Holographic Display").Prefab.transform.Find("Text").GetComponent<TextMeshPro>().font;
                textstorage2.alignment = TextAlignmentOptions.Center;
                textstorage2.color = new Color(1f, 1f, 1f);
                textstorage2.enableWordWrapping = false;
                textstorage2.autoSizeTextContainer = true;
            }));
        }
    }

    public static class PotaraFusionHelpers
    {
        public static Sprite CachedPotaraSprite;
        public const float PotaraWornVisualScale = 0.4f;
        public static readonly Vector3 PotaraWornLocalPosition = new Vector3(-0.05f, -0.09f, 0f);
        public const float PotaraWorldVisualScale = 0.4f;

        public static PhysicalBehaviour TryResolvePhysicalBehaviour(Transform t)
        {
            while (t != null)
            {
                if (Global.main != null && Global.main.PhysicalObjectsInWorldByTransform.TryGetValue(t, out PhysicalBehaviour pb))
                    return pb;
                t = t.parent;
            }
            return null;
        }

        public static void AttachPotaraEarring(PersonBehaviour person)
        {
            if (person == null || !person.IsAlive()) return;

            var wearer = person.GetComponent<PotaraWearerBehaviour>();
            if (wearer == null) wearer = person.gameObject.AddComponent<PotaraWearerBehaviour>();
            if (wearer.Equipped) return;

            var head = person.Limbs[0].transform;
            var existing = head.Find("PotaraEarring");
            if (existing != null) UnityEngine.Object.Destroy(existing.gameObject);

            var potaraObject = new GameObject("PotaraEarring");
            potaraObject.transform.SetParent(head);
            potaraObject.transform.localPosition = PotaraWornLocalPosition;
            potaraObject.transform.localRotation = Quaternion.identity;
            potaraObject.transform.localScale = new Vector3(PotaraWornVisualScale, PotaraWornVisualScale, 1f);
            var potaraSprite = potaraObject.AddComponent<SpriteRenderer>();
            potaraSprite.sprite = CachedPotaraSprite;
            potaraSprite.sortingLayerName = head.gameObject.GetComponent<SpriteRenderer>().sortingLayerName;
            potaraSprite.sortingOrder = head.gameObject.GetComponent<SpriteRenderer>().sortingOrder + 2;

            wearer.Equipped = true;

            foreach (var limb in person.Limbs)
            {
                if (limb == null) continue;
                var relay = limb.gameObject.GetComponent<PotaraWearerLimbRelay>();
                if (relay == null) relay = limb.gameObject.AddComponent<PotaraWearerLimbRelay>();
                relay.Owner = wearer;
            }

            head.gameObject.GetComponent<PhysicalBehaviour>().ContextMenuOptions.Buttons.Add(new ContextMenuButton("RemovePotara", "Remove Potara", "Remove Potara Earring", new UnityAction[]
            {
                () => RemovePotaraEarring(person)
            }));
        }

        public static void RemovePotaraEarring(PersonBehaviour person)
        {
            if (person == null) return;

            var wearer = person.GetComponent<PotaraWearerBehaviour>();
            if (wearer != null) wearer.Equipped = false;

            var head = person.Limbs[0].transform;
            var existing = head.Find("PotaraEarring");
            if (existing != null) UnityEngine.Object.Destroy(existing.gameObject);
        }
    }

    public class PotaraSpawnableBehaviour : MonoBehaviour
    {
        bool attached;

        public void OnCollisionEnter2D(Collision2D other) => TryAttach(other.gameObject);

        public void OnTriggerEnter2D(Collider2D other) => TryAttach(other.gameObject);

        public void FixedUpdate()
        {
            if (attached) return;
            var hits = Physics2D.OverlapCircleAll(transform.position, 0.15f);
            foreach (var hit in hits)
            {
                if (hit.gameObject != gameObject) TryAttach(hit.gameObject);
            }
        }

        void TryAttach(GameObject other)
        {
            if (attached) return;

            var pb = PotaraFusionHelpers.TryResolvePhysicalBehaviour(other.transform);
            if (pb == null) return;

            var limb = pb.GetComponent<LimbBehaviour>();
            if (limb == null || limb.name != "Head") return;

            var person = limb.Person;
            if (person == null || !person.IsAlive()) return;

            attached = true;
            PotaraFusionHelpers.AttachPotaraEarring(person);
            Destroy(gameObject);
        }
    }

    public class PotaraWearerLimbRelay : MonoBehaviour
    {
        public PotaraWearerBehaviour Owner;

        public void OnCollisionEnter2D(Collision2D collision) => Owner?.NotifyLimbContact(collision.gameObject);
    }

    public class PotaraWearerBehaviour : MonoBehaviour
    {
        public bool Equipped;
        public static bool FusionInProgress;

        public void NotifyLimbContact(GameObject otherObj) => TryFusion(otherObj);

        public void OnCollisionEnter2D(Collision2D collision) => TryFusion(collision.gameObject);

        void TryFusion(GameObject otherObj)
        {
            if (!Equipped || FusionInProgress) return;

            var otherPerson = otherObj.transform.root.GetComponent<PersonBehaviour>();
            if (otherPerson == null || otherPerson == GetComponent<PersonBehaviour>()) return;

            var otherWearer = otherPerson.GetComponent<PotaraWearerBehaviour>();
            if (otherWearer == null || !otherWearer.Equipped) return;

            var thisPerson = GetComponent<PersonBehaviour>();
            string nameA = thisPerson.gameObject.name;
            string nameB = otherPerson.gameObject.name;

            var handler = thisPerson.Limbs[11].GetComponent<FusionHandler>();
            if (handler == null) handler = thisPerson.Limbs[13].GetComponent<FusionHandler>();
            if (handler == null) handler = otherPerson.Limbs[11].GetComponent<FusionHandler>();
            if (handler == null) handler = otherPerson.Limbs[13].GetComponent<FusionHandler>();
            if (handler == null) return;

            foreach (var fusion in handler.fusions.FusionData)
            {
                if (fusion.Value.FusionType != "Potara") continue;
                if (!FusionHandler.FusionPairMatches(fusion.Value.Character1, fusion.Value.Character2, nameA, nameB)) continue;

                FusionInProgress = true;
                PotaraFusionHelpers.RemovePotaraEarring(thisPerson);
                PotaraFusionHelpers.RemovePotaraEarring(otherPerson);
                handler.StartCoroutine(FusionComplete(handler, thisPerson, otherPerson, fusion.Key));
                return;
            }
        }

        IEnumerator FusionComplete(FusionHandler handler, PersonBehaviour person, PersonBehaviour otherPerson, string fusionKey)
        {
            yield return handler.Fuse(person, otherPerson, fusionKey);
            FusionInProgress = false;
        }
    }

    public class UnFuseBehaviour : MonoBehaviour
    {
        public bool Blow = true;

        public void Awake()
        {
            gameObject.GetComponent<PhysicalBehaviour>().ContextMenuOptions.Buttons.Add(new ContextMenuButton("A1", "Unfuse", "Unfuse", new UnityAction[]
            {
                () => { Blow = false; }
            }));
        }
    }


    public class FusionHandler : MonoBehaviour
    {
        public class Fusions
        {
            public class FusionInfo
            {
                public string Character1 { get; set; }
                public string Character2 { get; set; }

                public string ResultCharacter { get; set; }

                public string FusionType { get; set; }
                public string FusionAnimationID { get; set; }

                public AudioClip VoiceLines { get; set; } = null;
            }

            public Dictionary<string, FusionInfo> FusionData { get; private set; } = new Dictionary<string, FusionInfo>();

            public void AddTransformation(string key, FusionInfo fusionInfo)
            {
                if (!FusionData.ContainsKey(key))
                {
                    FusionData[key] = fusionInfo;
                }
            }
        }

        static Fusions SharedFusions;
        static readonly object FusionInitLock = new object();

        public Fusions fusions
        {
            get
            {
                EnsureSharedFusions();
                return SharedFusions;
            }
            set { }
        }

        public static bool FusionPairMatches(string character1, string character2, string nameA, string nameB)
        {
            return (character1 == nameA && character2 == nameB) || (character1 == nameB && character2 == nameA);
        }

        static void EnsureSharedFusions()
        {
            if (SharedFusions != null) return;
            lock (FusionInitLock)
            {
                if (SharedFusions != null) return;
                var built = new Fusions();
                built.AddTransformation("Gogeta", new Fusions.FusionInfo()
                {
                    Character1 = "Goku",
                    Character2 = "Vegeta",
                    ResultCharacter = "Gogeta",
                    FusionType = "Metamoro",
                    FusionAnimationID = "1",
                });
                built.AddTransformation("Tiencha", new Fusions.FusionInfo()
                {
                    Character1 = "Tenshinhan",
                    Character2 = "Yamcha",
                    ResultCharacter = "Tiencha",
                    FusionType = "Metamoro",
                    FusionAnimationID = "1",
                });
                built.AddTransformation("Teen Gotenks", new Fusions.FusionInfo()
                {
                    Character1 = "Teen Goten",
                    Character2 = "Teen Trunks",
                    ResultCharacter = "Teen Gotenks",
                    FusionType = "Metamoro",
                    FusionAnimationID = "1",
                });
                built.AddTransformation("Teen GotenksReverse", new Fusions.FusionInfo()
                {
                    Character1 = "Teen Trunks",
                    Character2 = "Teen Goten",
                    ResultCharacter = "Teen Gotenks",
                    FusionType = "Metamoro",
                    FusionAnimationID = "1",
                });
                built.AddTransformation("Vegito", new Fusions.FusionInfo()
                {
                    Character1 = "Goku",
                    Character2 = "Vegeta",
                    ResultCharacter = "Vegito",
                    FusionType = "Potara",
                    FusionAnimationID = "1",
                });
                built.AddTransformation("VegitoReverse", new Fusions.FusionInfo()
                {
                    Character1 = "Vegeta",
                    Character2 = "Goku",
                    ResultCharacter = "Vegito",
                    FusionType = "Potara",
                    FusionAnimationID = "1",
                });
                SharedFusions = built;
            }
        }

        public void Start()
        {
            EnsureSharedFusions();
        }

        public bool canFuse = false;

        public void OnCollisionEnter2D(Collision2D collision)
        {
            if (canFuse == false) return;

            if (collision.gameObject.transform.root.GetComponent<PersonBehaviour>() != null && collision.gameObject.transform.root.GetComponent<PersonBehaviour>() != transform.root.gameObject.GetComponent<PersonBehaviour>() && collision.gameObject.GetComponentInChildren<FusionHandler>() != null)
            {
                var otherPerson = collision.gameObject.transform.root.gameObject.GetComponent<PersonBehaviour>();
                var thisPerson = transform.root.gameObject.GetComponent<PersonBehaviour>();
                string nameA = transform.root.gameObject.name;
                string nameB = collision.gameObject.transform.root.gameObject.name;

                foreach (var fusion in fusions.FusionData)
                {
                    if (fusion.Value.FusionType != "Metamoro") continue;
                    if (!FusionPairMatches(fusion.Value.Character1, fusion.Value.Character2, nameA, nameB)) continue;

                    if ((thisPerson.transform.localScale.x < 0f && otherPerson.transform.localScale.x < 0f) || (thisPerson.transform.localScale.x > 0f && otherPerson.transform.localScale.x > 0f)) return;
                    else if (MCP_Utils.GetMiddlePositionOfBody(thisPerson).x < MCP_Utils.GetMiddlePositionOfBody(otherPerson).x) if (thisPerson.transform.localScale.x < 0f && otherPerson.transform.localScale.x > 0f) return;
                    else if (MCP_Utils.GetMiddlePositionOfBody(thisPerson).x > MCP_Utils.GetMiddlePositionOfBody(otherPerson).x) if (thisPerson.transform.localScale.x > 0f && otherPerson.transform.localScale.x < 0f) return;

                    canFuse = false;
                    StartCoroutine(Fuse(thisPerson, otherPerson, fusion.Key));
                    return;
                }
            }
        }

        public IEnumerator Fuse(PersonBehaviour person, PersonBehaviour otherPerson, string fusionKey)
        {
            if (!fusions.FusionData.ContainsKey(fusionKey))
            {
                Debug.LogWarning($"Fusion '{fusionKey}' not found.");
                yield break;
            }

            string char1Transformation = "Base";
            string char2Transformation = "Base";

            if (person.gameObject.GetComponent<CharacterTransformations>() && otherPerson.gameObject.GetComponent<CharacterTransformations>())
            {
                var menu1 = person.Limbs[0].gameObject.GetComponent<TransformationContextMenu>();
                var menu2 = otherPerson.Limbs[0].gameObject.GetComponent<TransformationContextMenu>();
                if (menu1 != null && menu2 != null)
                {
                    char1Transformation = menu1.Form;
                    char2Transformation = menu2.Form;

                    if (char1Transformation != char2Transformation) { ModAPI.Notify("Unable to fuse. Characters must be on similar power levels."); yield break; }
                }
            }

            foreach (FusionHandler handler in person.gameObject.GetComponentsInChildren<FusionHandler>()) handler.canFuse = false;
            foreach (FusionHandler handler in otherPerson.gameObject.GetComponentsInChildren<FusionHandler>()) handler.canFuse = false;

            var t = fusions.FusionData[fusionKey];

            if (t.FusionType == "Metamoro")
            {
                if (DBPU.AFWEnabled == false) ModAPI.Notify("!Animation Framework isn't enabled, the Fusion Animation won't be played!");

                Vector3 Char1Pos = MCP_Utils.GetMiddlePositionOfBody(person);
                Vector3 Char2Pos = MCP_Utils.GetMiddlePositionOfBody(otherPerson);

                float XDistance = (Mathf.Abs(Char1Pos.x - Char2Pos.x) - 1.3f) / 2f;
                float direction = (Char1Pos.x < Char2Pos.x) ? 1f : -1f;

                float Scale1 = person.transform.root.localScale.x / 1.0417f;
                float Scale2 = otherPerson.transform.root.localScale.x / 1.0417f;

                if (DBPU.AFWEnabled == true)
                {
                    foreach (var limbs in person.Limbs)
                    {
                        limbs.gameObject.AddComponent<FreezeBehaviour>();
                        limbs.gameObject.GetComponent<Collider2D>().enabled = false;
                        limbs.transform.position += new Vector3((-1.65f + (XDistance * Scale1)) * direction, -0.05f, 0f);
                    }

                    foreach (var limbs in otherPerson.Limbs)
                    {
                        limbs.gameObject.AddComponent<FreezeBehaviour>();
                        limbs.gameObject.GetComponent<Collider2D>().enabled = false;
                        limbs.transform.position += new Vector3((1.65f - (XDistance * Scale2)) * direction, -0.05f, 0f);
                    }

                    Action<int, Transform> onFrameCallback = (frameIdx, root) =>
                    {
                        if (frameIdx == 1)
                        {
                            GetComponent<PhysicalBehaviour>().PlayClipOnce(DBPU.Misc_Movement1);
                        }

                        if (frameIdx == 4)
                        {
                            GetComponent<PhysicalBehaviour>().PlayClipOnce(DBPU.Voice_Fusion_GokuXVegeta);
                        }
                    };

                    Action<int, Transform> onFrameCallback2 = (frameIdx, root) =>
                    {
                    };

                    Char1Pos = MCP_Utils.GetMiddlePositionOfBody(person);
                    Char2Pos = MCP_Utils.GetMiddlePositionOfBody(otherPerson);

                    AnimationFramework.PlayAnimation(
                        target: person.transform.root,
                        animationPath: DBPU.ModFolder + "/Assets/Animations/MetamoroDance.json",
                        onFrame: onFrameCallback,
                        playbackSpeed: 1f,
                        false,
                        null,
                        null,
                        () => Char1Pos
                        );

                    AnimationFramework.PlayAnimation(
                        target: otherPerson.transform.root,
                        animationPath: DBPU.ModFolder + "/Assets/Animations/MetamoroDance.json",
                        null,
                        playbackSpeed: 1f,
                        false,
                        null,
                        null,
                        () => Char2Pos
                        );

                    yield return new WaitForSeconds(4.5f);
                }

                else
                {
                    foreach (var limbs in person.Limbs)
                    {
                        limbs.gameObject.AddComponent<FreezeBehaviour>();
                        limbs.gameObject.GetComponent<Collider2D>().enabled = false;
                    }

                    foreach (var limbs in otherPerson.Limbs)
                    {
                        limbs.gameObject.AddComponent<FreezeBehaviour>();
                        limbs.gameObject.GetComponent<Collider2D>().enabled = false;
                    }

                    GetComponent<PhysicalBehaviour>().PlayClipOnce(DBPU.Voice_Fusion_GokuXVegeta);

                    yield return new WaitForSeconds(4.1f);
                }

                yield return RunFusionVFXAndSpawn(person, otherPerson, t, char1Transformation, char2Transformation, true);
            }

            if (t.FusionType == "Potara")
            {
                foreach (var limbs in person.Limbs)
                {
                    limbs.gameObject.AddComponent<FreezeBehaviour>();
                    limbs.GetComponent<Collider2D>().enabled = false;
                }

                foreach (var limbs in otherPerson.Limbs)
                {
                    limbs.gameObject.AddComponent<FreezeBehaviour>();
                    limbs.GetComponent<Collider2D>().enabled = false;
                }

                bool supportsUnfuse = fusionKey == "Vegito" || fusionKey == "VegitoReverse";
                yield return RunFusionVFXAndSpawn(person, otherPerson, t, char1Transformation, char2Transformation, supportsUnfuse);
                yield break;
            }

            yield return null;
        }

        IEnumerator RunFusionVFXAndSpawn(PersonBehaviour person, PersonBehaviour otherPerson, Fusions.FusionInfo t, string char1Transformation, string char2Transformation, bool supportsUnfuse)
        {
            Vector3 MidlePos = (MCP_Utils.GetMiddlePositionOfBody(person) + MCP_Utils.GetMiddlePositionOfBody(otherPerson)) * 0.5f;

            var currentAura = Instantiate(DBPU.Aura_MetamoroFusion, MidlePos - new Vector3(0f, 0.5f, 0f), Quaternion.identity);
            currentAura.gameObject.layer = 9;
            currentAura.AddComponent<DestroyOverTime>().Timer = 20f;
            currentAura.AddComponent<SortingGroup>().sortingLayerName = "Bubbles";

            AudioSource audioSource = currentAura.AddComponent<AudioSource>();
            audioSource.transform.SetParent(currentAura.transform, false);
            Global global = FindObjectOfType<Global>();
            global.AddAudioSource(audioSource, false);
            audioSource.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.85f;
            audioSource.outputAudioMixerGroup = global.SoundEffects;
            audioSource.spatialBlend = 1;
            audioSource.volume = 1;
            audioSource.maxDistance = 1000;
            audioSource.PlayOneShot(DBPU.Misc_MetamoroFusion);

            float intensity = 2f;

            foreach (var transforms in currentAura.GetComponentsInChildren<Transform>())
            {
                transforms.position = new Vector3(transforms.position.x, transforms.position.y, 0f);
            }

            foreach (var ps in currentAura.GetComponentsInChildren<ParticleSystem>(true))
            {
                var main = ps.main;
                if (main.startColor.mode == ParticleSystemGradientMode.Color) main.startColor = new ParticleSystem.MinMaxGradient(main.startColor.color * intensity);
            }

            yield return new WaitForSeconds(4.6f);

            float Opac = 1f;

            while (Opac > 0f)
            {
                foreach (SpriteRenderer renderers in person.gameObject.GetComponentsInChildren<SpriteRenderer>())
                {
                    renderers.color = new Color(renderers.color.r, renderers.color.g, renderers.color.b, Opac);
                }

                foreach (SpriteRenderer renderers in otherPerson.gameObject.GetComponentsInChildren<SpriteRenderer>())
                {
                    renderers.color = new Color(renderers.color.r, renderers.color.g, renderers.color.b, Opac);
                }

                Opac -= 0.1f;

                yield return new WaitForSeconds(0.1f);
            }

            var fusionSpawnable = ModAPI.FindSpawnable(DBPU.ModTag + t.ResultCharacter);
            if (fusionSpawnable == null) fusionSpawnable = ModAPI.FindSpawnable(t.ResultCharacter);
            if (fusionSpawnable == null)
            {
                Debug.LogWarning($"Fusion result spawnable '{t.ResultCharacter}' not found.");
                yield break;
            }

            GameObject FusionCharacter = GameObject.Instantiate(fusionSpawnable.Prefab, MidlePos - new Vector3(0f, 0.2f, 0f), Quaternion.identity);
            CatalogBehaviour.PerformMod(fusionSpawnable, FusionCharacter);

            while (Opac < 1f)
            {
                Opac += 0.1f;

                foreach (SpriteRenderer renderers in FusionCharacter.gameObject.GetComponentsInChildren<SpriteRenderer>())
                {
                    renderers.color = new Color(renderers.color.r, renderers.color.g, renderers.color.b, Opac);
                }

                yield return new WaitForSeconds(0.05f);
            }

            if (char1Transformation == char2Transformation && FusionCharacter.GetComponent<CharacterTransformations>())
            {
                FusionCharacter.GetComponent<CharacterTransformations>().ApplyTransformation(FusionCharacter.GetComponent<PersonBehaviour>(), char1Transformation);
            }

            if (supportsUnfuse)
            {
                var fusionComp = FusionCharacter.AddComponent<FusionComponent>();
                fusionComp.Character1 = person.gameObject;
                fusionComp.Character2 = otherPerson.gameObject;

                var unfuseButton = new ContextMenuButton("!Unfuse", "Unfuse", "Unfuse", new UnityAction[] { () => fusionComp.DoDefuse() });

                foreach (var limbs in FusionCharacter.GetComponent<PersonBehaviour>().Limbs)
                {
                    limbs.GetComponent<PhysicalBehaviour>().ContextMenuOptions.Buttons.Add(unfuseButton);

                    MCP_Utils.MoveContextButton(limbs.GetComponent<PhysicalBehaviour>().ContextMenuOptions, "!Unfuse", 0);
                }
            }
            else
            {
                foreach (var limb in person.Limbs) Destroy(limb.gameObject);
                foreach (var limb in otherPerson.Limbs) Destroy(limb.gameObject);
            }
        }

        public class FusionComponent : MonoBehaviour
        {
            public GameObject Character1;
            public GameObject Character2;

            private bool Unfusing = false;

            public void Start()
            {
                Character1.active = false;
                Character2.active = false;

                gameObject.AddComponent<DestroyWithObject>().Object = Character1;
                gameObject.AddComponent<DestroyWithObject>().Object = Character2;

                foreach (SpriteRenderer renderers in Character1.GetComponentsInChildren<SpriteRenderer>()) renderers.color = Color.white;

                foreach (SpriteRenderer renderers in Character2.GetComponentsInChildren<SpriteRenderer>()) renderers.color = Color.white;

                StartCoroutine(CountDown());
            }

            public IEnumerator CountDown()
            {
                yield return new WaitForSeconds(60f);

                StartCoroutine(Defuse());
            }

            public void DoDefuse()
            {
                if (Unfusing == true) return;
                else Unfusing = true;

                StartCoroutine(Defuse());
            }

            public IEnumerator Defuse()
            {
                Character1.active = true;
                Character2.active = true;

                foreach (var limbs in GetComponent<PersonBehaviour>().Limbs)
                {
                    limbs.gameObject.AddComponent<FreezeBehaviour>();
                    limbs.gameObject.GetComponent<Collider2D>().enabled = false;
                }

                foreach (SpriteRenderer renderers in gameObject.GetComponentsInChildren<SpriteRenderer>()) renderers.color = Color.clear;

                float ForceDirection = (MCP_Utils.GetMiddlePositionOfBody(Character1.GetComponent<PersonBehaviour>()).x > MCP_Utils.GetMiddlePositionOfBody(Character2.GetComponent<PersonBehaviour>()).x) ? 1f : -1f;

                Vector3 Char1DistFromFuse = MCP_Utils.GetMiddlePositionOfBody(GetComponent<PersonBehaviour>()) - MCP_Utils.GetMiddlePositionOfBody(Character1.GetComponent<PersonBehaviour>());
                Vector3 Char2DistFromFuse = MCP_Utils.GetMiddlePositionOfBody(GetComponent<PersonBehaviour>()) - MCP_Utils.GetMiddlePositionOfBody(Character2.GetComponent<PersonBehaviour>());
                Vector3 UnfusePlusPos = (Char1DistFromFuse + Char2DistFromFuse) / 2f;

                foreach (var c1 in Character1.GetComponentsInChildren<Collider2D>())
                    foreach (var c2 in Character2.GetComponentsInChildren<Collider2D>())
                        Physics2D.IgnoreCollision(c1, c2, true);

                foreach (var limbs in Character1.GetComponent<PersonBehaviour>().Limbs)
                {
                    Destroy(limbs.gameObject.GetComponent<FreezeBehaviour>());
                    limbs.gameObject.GetComponent<Collider2D>().enabled = true;
                    limbs.transform.position += UnfusePlusPos + new Vector3(-0.7f * ForceDirection, 0f);
                }

                foreach (var limbs in Character2.GetComponent<PersonBehaviour>().Limbs)
                {
                    Destroy(limbs.gameObject.GetComponent<FreezeBehaviour>());
                    limbs.gameObject.GetComponent<Collider2D>().enabled = true;
                    limbs.transform.position += UnfusePlusPos + new Vector3(0.7f * ForceDirection, 0f);
                }

                IgnoreColliderWithSelves();

                yield return new WaitForFixedUpdate();

                foreach (var limbs in Character1.GetComponent<PersonBehaviour>().Limbs) { limbs.GetComponent<Rigidbody2D>().AddForce(new Vector2((4f * limbs.GetComponent<Rigidbody2D>().mass) * ForceDirection, 0f), ForceMode2D.Impulse); limbs.GetComponent<Rigidbody2D>().AddTorque((-35f * limbs.GetComponent<Rigidbody2D>().mass) * ForceDirection); }
                foreach (var limbs in Character2.GetComponent<PersonBehaviour>().Limbs) { limbs.GetComponent<Rigidbody2D>().AddForce(new Vector2((-4f * limbs.GetComponent<Rigidbody2D>().mass) * ForceDirection, 0f), ForceMode2D.Impulse); limbs.GetComponent<Rigidbody2D>().AddTorque((35f * limbs.GetComponent<Rigidbody2D>().mass) * ForceDirection); }

                yield return new WaitForSeconds(0.25f);

                foreach (var limbs in Character1.GetComponent<PersonBehaviour>().Limbs) limbs.gameObject.FixColliders();
                foreach (var limbs in Character2.GetComponent<PersonBehaviour>().Limbs) limbs.gameObject.FixColliders();

                IgnoreColliderWithSelves();

                Destroy(gameObject);

                yield return null;
            }

            void IgnoreColliderWithSelves()
            {
                foreach (var c1 in Character1.GetComponentsInChildren<Collider2D>())
                    foreach (var c2 in Character1.GetComponentsInChildren<Collider2D>())
                        Physics2D.IgnoreCollision(c1, c2, true);

                foreach (var c1 in Character2.GetComponentsInChildren<Collider2D>())
                    foreach (var c2 in Character2.GetComponentsInChildren<Collider2D>())
                        Physics2D.IgnoreCollision(c1, c2, true);
            }
        }
    }

