    [HarmonyPatch(typeof(LimbBehaviour), "Damage")]
    public static class LimbBehaviour_Damage_ZenkaiBoost
    {
        static void Postfix(LimbBehaviour __instance, float damage)
        {
            if (!DBPU.Special_ZenkaiBoostEnabled) return;
            if (__instance == null || damage <= 0f) return;
            if (float.IsNaN(damage) || float.IsInfinity(damage)) return;

            Transform root = __instance.transform.root;
            if (root == null) return;

            var zenkai = root.GetComponent<ZenkaiBoostBehaviour>();
            if (zenkai == null)
            {
                var identity = root.GetComponent<DbpuCharacterIdentity>();
                if (identity == null || !ZenkaiBoostBehaviour.IsSaiyan(identity.CharacterId, identity.DisplayName))
                    return;
                zenkai = root.gameObject.AddComponent<ZenkaiBoostBehaviour>();
            }

            zenkai.RegisterDamage(damage);
        }
    }

