        {
            EnsureKiChargeAnimationMeta();
            yield return new WaitForSeconds(Mathf.Max(0.05f, _kiChargeInDuration));

            if (!IsActivelyCharging) yield break;
            if (!_hasCapturedHoldPose)
                CaptureCurrentLimbPose();

            _holdChargePoseActive = _hasCapturedHoldPose;
            _chargeIntroPoseCo = null;
        }

        private void ReleaseHoldChargePose()
        {
            _holdChargePoseActive = false;
            _hasCapturedHoldPose = false;
            if (_chargeIntroPoseCo != null)
            {
                StopCoroutine(_chargeIntroPoseCo);
                _chargeIntroPoseCo = null;
            }
        }

        private void ApplyChargeFreeze()
        {
            if (person == null || person.Limbs == null) return;
            if (_releaseFreezeCo != null)
            {
                StopCoroutine(_releaseFreezeCo);
                _releaseFreezeCo = null;
            }

            _chargeLimbRbStates.RemoveAll(s => s.Rigidbody == null);
            foreach (var limb in person.Limbs)
            {
                if (limb == null) continue;
                var rb = limb.PhysicalBehaviour != null ? limb.PhysicalBehaviour.rigidbody : limb.GetComponent<Rigidbody2D>();
                if (rb == null) continue;

                bool alreadyLocked = false;
                for (int i = 0; i < _chargeLimbRbStates.Count; i++)
                {
                    if (_chargeLimbRbStates[i].Rigidbody == rb)
                    {
                        alreadyLocked = true;
                        break;
                    }
                }
                if (alreadyLocked) continue;

                _chargeLimbRbStates.Add(new ChargeLimbRbState
                {
                    Rigidbody = rb,
                    BodyType = rb.bodyType,
                    Constraints = rb.constraints,
                    GravityScale = rb.gravityScale,
                    Simulated = rb.simulated,
                    Velocity = rb.velocity,
                    AngularVelocity = rb.angularVelocity
                });

                rb.velocity = Vector2.zero;
                rb.angularVelocity = 0f;
                rb.gravityScale = 0f;
                rb.bodyType = RigidbodyType2D.Kinematic;
                rb.constraints = RigidbodyConstraints2D.FreezeAll;
            }
        }

        private void ClearChargeFreezeImmediate()
        {
            foreach (var state in _chargeLimbRbStates)
            {
                var rb = state.Rigidbody;
                if (rb == null) continue;
                rb.bodyType = state.BodyType;
                rb.constraints = state.Constraints;
                rb.gravityScale = state.GravityScale;
                rb.simulated = state.Simulated;
                rb.velocity = state.Velocity;
                rb.angularVelocity = state.AngularVelocity;
            }
            _chargeLimbRbStates.Clear();
        }

        private IEnumerator ReleaseChargeFreezeAfter(float delay)
        {
            yield return new WaitForSeconds(Mathf.Max(0f, delay));
            ClearChargeFreezeImmediate();
            _releaseFreezeCo = null;
        }

        void Awake()
        {
            kiSystem = GetComponent<KiSystem>();
            person = GetComponent<PersonBehaviour>();
            auraHandler = GetComponent<AuraHandler>();
        }

        void Start()
        {
            if (person != null && person.Limbs.Count() > 2)
                spawnAnchor = person.Limbs[2].transform;
            else if (person != null && person.Limbs.Count() > 0)
                spawnAnchor = person.transform;
        }

        public void SetHoldDesired(bool hold)
        {
            pendingHold = hold;
        }

        public void ForceEndCharge(bool preserveAuraForSparkingOverload = false)
        {
            if (IsActivelyCharging)
                EndCharge(preserveAuraForSparkingOverload);
        }

        void Update()
        {
            if (kiSystem == null || person == null) return;
            if (!person.IsAlive())
            {
                if (IsActivelyCharging) EndCharge();
                _sparkingPrepAccum = 0f;
                _autoTransformTierAccum = 0f;
                if (kiSystem != null) kiSystem.SparkingOvercharge01 = 0f;
                return;
            }

            var spark = GetComponent<KiSparkingController>();
            bool sparkOverload = spark != null && spark.CurrentPhase == KiSparkingController.SparkPhase.Overload;

            if (sparkOverload && IsActivelyCharging)
                EndCharge();

            bool want = pendingHold && DBPU.KiChargeFxEnabled && !sparkOverload;

            if (kiSystem.currentKi < kiSystem.maxKi * 0.995f)
            {
                _sparkingPrepAccum = 0f;
                _autoTransformTierAccum = 0f;
                kiSystem.SparkingOvercharge01 = 0f;
            }

            if (want && !IsActivelyCharging)
                BeginCharge();
            else if (!want && IsActivelyCharging)
                EndCharge();

            if (want && IsActivelyCharging && kiSystem.currentKi >= kiSystem.maxKi * 0.995f)
            {
                if (DBPU.SparkingEnabled && DBPU.KiChargeSparkingOverchargeEnabled)
                {
                    float dur = DBPU.SparkingOverchargeHoldSeconds > 0.05f ? DBPU.SparkingOverchargeHoldSeconds : 3f;
                    _sparkingPrepAccum += Time.deltaTime / dur;
                    if (_sparkingPrepAccum >= 1f)
                    {
                        _sparkingPrepAccum = 0f;
                        kiSystem.SparkingOvercharge01 = 0f;
                        spark?.TryStartOverload();
                        EndCharge();
                    }
                    else
                        kiSystem.SparkingOvercharge01 = Mathf.Clamp01(_sparkingPrepAccum);
                }
                else
                {
                    _sparkingPrepAccum = 0f;
                    kiSystem.SparkingOvercharge01 = 0f;
                }

                if (DBPU.KiChargeAutoTransformWhileChargingEnabled)
                    TryProgressAutoTransformCharge(Time.deltaTime);
                else
                    _autoTransformTierAccum = 0f;
            }
            else if (!want)
            {
                _sparkingPrepAccum = 0f;
                _autoTransformTierAccum = 0f;
                kiSystem.SparkingOvercharge01 = 0f;
            }
        }

        void LateUpdate()
        {
            if (!_holdChargePoseActive || !IsActivelyCharging || person == null || _holdChargePose == null) return;

            int count = Mathf.Min(person.Limbs.Count(), _holdChargePose.Length);
            for (int i = 0; i < count; i++)
            {
                var limb = person.Limbs[i];
                if (limb == null) continue;

                limb.transform.position = _holdChargePose[i].Position;
                limb.transform.rotation = _holdChargePose[i].Rotation;

                if (limb.PhysicalBehaviour != null && limb.PhysicalBehaviour.rigidbody != null)
                {
                    limb.PhysicalBehaviour.rigidbody.velocity = Vector2.zero;
                    limb.PhysicalBehaviour.rigidbody.angularVelocity = 0f;
                }
            }
        }

        /// <summary>Steps transformations by ascending PowerMultiplier (same idea as transformation menu list order).</summary>
        private void TryProgressAutoTransformCharge(float dt)
        {
            float need = Mathf.Max(1f, DBPU.KiChargeAutoTransformSecondsPerTier);
            _autoTransformTierAccum += dt;
            while (_autoTransformTierAccum >= need)
            {
                if (!TryStepTransformationUpOneTier())
                {
                    _autoTransformTierAccum = 0f;
                    break;
                }
                _autoTransformTierAccum -= need;
            }
        }

        private bool TryStepTransformationUpOneTier()
        {
            var ct = GetComponent<CharacterTransformations>();
            if (ct == null || person == null || person.Limbs.Count() < 1 || kiSystem == null) return false;
            var tm = person.Limbs[0].GetComponent<TransformationContextMenu>();
            if (tm == null || tm.TransformationsData == null) return false;

            var data = tm.TransformationsData.transformations.TransformationData;
            if (data == null || data.Count < 2) return false;

            var ordered = data.OrderBy(kvp => kvp.Value.PowerMultiplier).ThenBy(kvp => kvp.Key).Select(kvp => kvp.Key).ToList();

            string cur = kiSystem.CurrentForm;
            if (string.IsNullOrEmpty(cur) || !data.ContainsKey(cur))
                cur = tm.Form;
            if (string.IsNullOrEmpty(cur) || !data.ContainsKey(cur))
                cur = ordered[0];

            int idx = ordered.IndexOf(cur);
            if (idx < 0 || idx >= ordered.Count - 1) return false;

            string nextKey = ordered[idx + 1];
            var nextStats = data[nextKey];
            float prevMul = tm.PreviousMultiplier;

            Action applyTier = () =>
            {
            ct.ApplyTransformation(person, nextKey);

            tm.Form = nextStats.ID;
            tm.CurrentAuraID = nextStats.AuraID;
            foreach (var limb in person.Limbs)
            {
                if (!float.IsInfinity(limb.InitialHealth * (nextStats.PowerMultiplier / prevMul)))
                    limb.InitialHealth *= nextStats.PowerMultiplier / prevMul;
                if (!float.IsInfinity(limb.Health * (nextStats.PowerMultiplier / prevMul)))
                    limb.Health *= nextStats.PowerMultiplier / prevMul;
            }
            person.ChangeWeightBasedOnHealth();
            tm.PreviousMultiplier = nextStats.PowerMultiplier;

            if (tm.CurrentAuraID != null && !DBPU.BaseConsideredForms.Contains(tm.Form))
            {
                if (tm.AuraHandler != null)
                {
                    tm.AuraHandler.AuraActive = DBPU.AurasEnabled;
                    tm.AuraHandler.CreateAura(tm.CurrentAuraID);
                }
            }
            else if (tm.AuraHandler != null)
                tm.AuraHandler.DestroyAura();

            };
            if (!KiFormTransition.Begin(ct, person, cur, nextKey, applyTier)) applyTier();

            return true;
        }

        private void BeginCharge()
        {
            if (IsActivelyCharging) return;
            IsActivelyCharging = true;
            kiSystem.KiChargeActiveForRegen = true;

            if (DBPU.AurasEnabled && person != null && person.Limbs.Count() > 2)
            {
                auraHandler = auraHandler != null ? auraHandler : GetComponent<AuraHandler>();
                if (auraHandler == null)
                {
                    auraHandler = gameObject.AddComponent<AuraHandler>();
                    auraHandler.person = person;
                }
                if (auraHandler != null && kiSystem != null)
                {
                    auraHandler.CancelKiChargeOutwardFadeIfRunning();
                    auraHandler.CurrentAuraID = CinematicAssets.ResolveAura(person,kiSystem.CurrentForm,auraHandler.CurrentAuraID);
                    if (!auraHandler.AuraVisible)
                    {
                        auraHandler.AuraVisible = true;
                        _kiChargeForcedAuraVisible = true;
                    }
                    if (!auraHandler.AuraActive)
                    {
                        auraHandler.AuraActive = true;
                        _kiChargeForcedAura = true;
                    }
                    if (!auraHandler.HasSpawnedAuraInstance)
                        auraHandler.CreateAura(auraHandler.CurrentAuraID);
                    auraHandler.SetChargeVisualActive(true);
                }
            }
            if (debrisCoroutine == null && spawnAnchor != null)
                debrisCoroutine = StartCoroutine(SpawnDebrisLoop());
        }

        private void EndCharge(bool preserveAuraForSparkingOverload = false)
        {
            if (!IsActivelyCharging) return;
            IsActivelyCharging = false;
            kiSystem.KiChargeActiveForRegen = false;
            _sparkingPrepAccum = 0f;
            if (kiSystem != null) kiSystem.SparkingOvercharge01 = 0f;

            if (auraHandler != null)
            {
                if (preserveAuraForSparkingOverload)
                {
                    auraHandler.CancelKiChargeOutwardFadeIfRunning();
                    auraHandler.SetChargeVisualActive(true);
                    _kiChargeForcedAura = false;
                    _kiChargeForcedAuraVisible = false;
                    }
                else
                {
                    bool defAura = _kiChargeForcedAura;
                    bool defVis = _kiChargeForcedAuraVisible;
                    _kiChargeForcedAura = false;
                    _kiChargeForcedAuraVisible = false;
                    auraHandler.NotifyKiChargeReleased(defAura, defVis);
                    }
            }
            if (debrisCoroutine != null)
            {
                StopCoroutine(debrisCoroutine);
                debrisCoroutine = null;
            }
            StopDebrisFadeOut();
        }

        private IEnumerator SpawnDebrisLoop()
        {
            debrisSpawning = true;
            totalBlocksSpawned = 0;
            int maxActive = Mathf.Max(1, DBPU.KiChargeDebrisMaxActive);
            int maxSession = Mathf.Max(1, DBPU.KiChargeDebrisMaxSession);
            float interval = Mathf.Max(0.1f, DBPU.KiChargeDebrisSpawnInterval);

            EnsureKiChargeDebrisAssets();

            while (IsActivelyCharging && totalBlocksSpawned < maxSession)
            {
                chargeBlocks.RemoveAll(b => b == null);
                if (chargeBlocks.Count >= maxActive)
                {
                    yield return new WaitForSeconds(0.5f);
                    continue;
                }

                float ringMin = Mathf.Max(0.08f, DBPU.KiChargeDebrisRingMin);
                float ringMax = Mathf.Max(ringMin + 0.08f, DBPU.KiChargeDebrisRingMax);
                float yOff = DBPU.KiChargeDebrisSpawnYOffset;

                int batch = UnityEngine.Random.Range(2, 4);
                for (int i = 0; i < batch && totalBlocksSpawned < maxSession && chargeBlocks.Count < maxActive; i++)
                {
                    float angle = UnityEngine.Random.Range(0f, 360f) * Mathf.Deg2Rad;
                    float distance = UnityEngine.Random.Range(ringMin, ringMax);
                    Vector3 startPosition = spawnAnchor.position + new Vector3(Mathf.Cos(angle) * distance, yOff, Mathf.Sin(angle) * distance);
                    startPosition.z = 0f;

                    var chargeBlock = new GameObject("KiChargeDebris");
                    chargeBlock.transform.position = startPosition;
                    chargeBlock.layer = 0;
                    chargeBlock.transform.localScale = Vector3.one * UnityEngine.Random.Range(0.14f, 0.38f);
                    var sr = chargeBlock.AddComponent<SpriteRenderer>();
                    sr.sprite = _kiChargeBlackSquareSprite;
                    sr.sharedMaterial = _kiChargeDebrisMaterial;
                    sr.color = Color.black;
                    sr.sortingLayerName = "Default";
                    sr.sortingOrder = 5;
                    if (UnityEngine.Random.value < 0.7f)
                        chargeBlock.transform.eulerAngles = new Vector3(0, 0, UnityEngine.Random.Range(-35f, 35f));

                    var rising = chargeBlock.AddComponent<KiChargeRisingBlock>();
                    rising.targetHeight = UnityEngine.Random.Range(1.4f, 2.9f);
                    rising.riseDuration = UnityEngine.Random.Range(1.35f, 2.15f);
                    rising.rotationSpeed = UnityEngine.Random.Range(-20f, 20f);

                    chargeBlocks.Add(chargeBlock);
                    totalBlocksSpawned++;
                }
                yield return new WaitForSeconds(interval);
            }
            debrisCoroutine = null;
        }

        private void StopDebrisFadeOut()
        {
            foreach (var block in chargeBlocks.ToList())
            {
                if (block != null)
                    StartCoroutine(FadeOutBlock(block));
            }
            chargeBlocks.Clear();
            totalBlocksSpawned = 0;
        }

        private IEnumerator FadeOutBlock(GameObject block)
        {
            var renderer = block != null ? block.GetComponent<SpriteRenderer>() : null;
            if (renderer == null)
            {
                if (block != null) Destroy(block);
                yield break;
            }
            Color originalColor = renderer.color;
            float fadeTime = 1f;
            float elapsed = 0f;
            while (elapsed < fadeTime)
            {
                elapsed += Time.deltaTime;
                float alpha = Mathf.Lerp(originalColor.a, 0f, elapsed / fadeTime);
                renderer.color = new Color(originalColor.r, originalColor.g, originalColor.b, alpha);
                yield return null;
            }
            Destroy(block);
        }

        void OnDestroy()
        {
            if (kiSystem != null)
                kiSystem.KiChargeActiveForRegen = false;
            if (auraHandler != null)
            {
                if (_kiChargeForcedAura)
                {
                    auraHandler.AuraActive = false;
                    _kiChargeForcedAura = false;
                }
                if (_kiChargeForcedAuraVisible)
                {
                    auraHandler.AuraVisible = false;
                    _kiChargeForcedAuraVisible = false;
                }
            }
            foreach (var b in chargeBlocks)
                if (b != null) Destroy(b);
            chargeBlocks.Clear();
        }
    }

    [DefaultExecutionOrder(-150)]
    public class KiChargeHeadHoldInput : MonoBehaviour
    {
        private PhysicalBehaviour phys;
        private KiChargeModeController controller;
        private PersonBehaviour person;

        void Awake()
        {
            phys = GetComponent<PhysicalBehaviour>();
            person = transform.root.GetComponent<PersonBehaviour>();
            controller = transform.root.GetComponent<KiChargeModeController>();
        }

        void Update()
        {
            if (controller == null)
                controller = transform.root.GetComponent<KiChargeModeController>();
            if (controller == null || phys == null || person == null || !person.IsAlive())
            {
                if (controller != null) controller.SetHoldDesired(false);
                return;
            }
            if (!DBPU.KiChargeFxEnabled)
            {
                controller.SetHoldDesired(false);
                return;
            }
            if (GetComponent<CellMaxScream>() != null)
                return;
            if (!CeceUtils.IsSelected(phys))
            {
                controller.SetHoldDesired(false);
                return;
            }
            var it = transform.root.GetComponent<InstantTransmission>();
            if (it != null && it.Active && it.CanUse)
            {
                controller.SetHoldDesired(false);
                return;
            }
            bool hold = DbpuInputUtil.Held(DBPU.KiChargeHoldActionId, KeyCode.R);
            controller.SetHoldDesired(hold);
        }
    }

    public static class KiDeflectUtils
    {
        public static void DisintegratePersonIfBeamKilled(PersonBehaviour person, bool wasAliveBeforeDamage)
        {
            if (!DBPU.Beam_ToggleDelete || !DBPU.Beam_BurnAwayOnKill || person == null) return;
            if (!wasAliveBeforeDamage || person.IsAlive()) return;
            foreach (var limb in person.Limbs)
            {
                if (limb == null) continue;
                var pb = limb.PhysicalBehaviour;
                if (pb == null || pb.isDisintegrated) continue;
                pb.Disintegrate();
            }
        }

        public static bool IsBeamProtectedCorpse(PersonBehaviour person)
        {
            return person != null && !person.IsAlive() && !DBPU.Beam_ToggleDelete;
        }

        public static bool TryBeamHitCorpseOnlyKnockback(PersonBehaviour person, Rigidbody2D rb, Vector2 direction, float impulseScale)
        {
            if (!IsBeamProtectedCorpse(person) || rb == null) return false;
            float beamKnock = DBPU.EffectiveBeamKnockback;
            if (beamKnock > 0f)
                rb.AddForce(direction * (impulseScale * rb.mass * beamKnock), ForceMode2D.Impulse);
            return true;
        }

        private class BeamCatchState
        {
            public int DefenderRootId;
            public float ReleaseTime;
            public Vector2 AimedDirection;
        }

        private static readonly Dictionary<int, BeamCatchState> BeamCatchStates = new Dictionary<int, BeamCatchState>();

        private static Vector3 GetDefenderSplitAnchor(LimbBehaviour limb)
        {
            if (limb == null) return Vector3.zero;
            var person = limb.Person;
            if (person != null && person.Limbs != null)
            {
                foreach (var l in person.Limbs)
                {
                    if (l == null || string.IsNullOrEmpty(l.name)) continue;
                    if (l.name.IndexOf("UpperBody", StringComparison.OrdinalIgnoreCase) >= 0)
                        return l.transform.position;
                }
            }

            return limb.transform.position;
        }

        private static bool IsHandOrForearmLimb(LimbBehaviour limb)
        {
            if (limb == null || string.IsNullOrEmpty(limb.name)) return false;
            string n = limb.name.ToLowerInvariant();
            return n.Contains("lowerarm") || n.Contains("hand");
        }

        private static Vector2 GetPreferredDeflectDirection(LimbBehaviour contactLimb, Vector2 attackerPos, Vector2 hitPos)
        {
            if (contactLimb == null) return Vector2.right;

            Vector2 limbRight = contactLimb.transform.right;
            Vector2 limbUp = contactLimb.transform.up;
            Vector2 toAttacker = (attackerPos - hitPos).normalized;
            Vector2 chosen = limbRight.sqrMagnitude > 0.001f ? limbRight.normalized : Vector2.right;

            // If the player is actively swinging, prioritize swing direction for anime-style swats.
            var rb = contactLimb.PhysicalBehaviour != null ? contactLimb.PhysicalBehaviour.rigidbody : null;
            if (rb != null && rb.velocity.sqrMagnitude > 4f)
            {
                chosen = rb.velocity.normalized;
            }
            else
            {
                Vector2[] options = new Vector2[]
                {
                    limbRight.normalized,
                    -limbRight.normalized,
                    limbUp.normalized,
                    -limbUp.normalized
                };

                float best = float.NegativeInfinity;
                for (int i = 0; i < options.Length; i++)
                {
                    float score = Vector2.Dot(options[i], toAttacker);
                    if (score > best)
                    {
                        best = score;
                        chosen = options[i];
                    }
                }
            }

            if (chosen.sqrMagnitude < 0.001f) chosen = Vector2.right;
            return chosen.normalized;
        }

        private static float GetEffectivePowerScore(GameObject root)
        {
            if (root == null) return 1f;
            var ki = root.GetComponent<KiSystem>();
            float powerMul = DBPU.PowerMultiplier;

            var person = root.GetComponent<PersonBehaviour>();
            var tm = (person != null && person.Limbs != null && person.Limbs.Count() > 0) ? person.Limbs[0].GetComponent<TransformationContextMenu>() : null;
            if (tm != null && tm.TransformationsData != null && tm.TransformationsData.transformations != null)
            {
                var data = tm.TransformationsData.transformations.TransformationData;
                string form = ki != null && !string.IsNullOrEmpty(ki.CurrentForm) ? ki.CurrentForm : tm.Form;
                if (!string.IsNullOrEmpty(form) && data.ContainsKey(form))
                    powerMul = Mathf.Max(1f, data[form].PowerMultiplier * DBPU.PowerMultiplier);
                else if (!string.IsNullOrEmpty(tm.Form) && data.ContainsKey(tm.Form))
                    powerMul = Mathf.Max(1f, data[tm.Form].PowerMultiplier * DBPU.PowerMultiplier);
            }

            float ki01 = 1f;
            if (ki != null && ki.maxKi > 0.01f)
                ki01 = Mathf.Clamp01(ki.currentKi / ki.maxKi);
            float kiFactor = Mathf.Lerp(0.45f, 1f, ki01);
            return powerMul * kiFactor;
        }

        private static bool CanDefenderDeflect(GameObject defenderRoot, LimbBehaviour contactLimb, bool isBeam)
        {
            if (!DBPU.KiDeflectEnabled || defenderRoot == null || contactLimb == null) return false;
            if (!IsHandOrForearmLimb(contactLimb)) return false;

            var person = defenderRoot.GetComponent<PersonBehaviour>();
            if (person == null || !person.IsAlive()) return false;

            var ki = defenderRoot.GetComponent<KiSystem>();
            if (ki != null && ki.SparkingExhaustActive) return false;

            return true;
        }

        private static bool PassesHybridThreshold(GameObject defenderRoot, GameObject attackerRoot, bool isBeam)
        {
            float defenderScore = GetEffectivePowerScore(defenderRoot);
            float attackerScore = GetEffectivePowerScore(attackerRoot);
            float typeMul = isBeam ? Mathf.Max(1f, DBPU.KiDeflectBeamThresholdMultiplier) : Mathf.Max(1f, DBPU.KiDeflectBlastThresholdMultiplier);
            float need = Mathf.Max(1f, DBPU.KiDeflectHybridPowerThreshold) * typeMul;
            return defenderScore >= attackerScore * need;
        }

        public static bool TryDeflectBlast(BlastComponent blast, Collision2D collision)
        {
            if (blast == null || collision == null || blast.User == null) return false;
            var limb = collision.gameObject.GetComponent<LimbBehaviour>();
            if (limb == null) return false;
            var defenderRoot = limb.transform.root != null ? limb.transform.root.gameObject : null;
            var attackerRoot = blast.User.transform.root != null ? blast.User.transform.root.gameObject : blast.User;
            if (defenderRoot == null || attackerRoot == null || defenderRoot == attackerRoot) return false;

            if (!CanDefenderDeflect(defenderRoot, limb, false)) return false;
            if (!PassesHybridThreshold(defenderRoot, attackerRoot, false)) return false;

            Vector2 away = GetPreferredDeflectDirection(
                limb,
                attackerRoot.transform.position,
                limb.transform.position
            );

            blast.User = defenderRoot;
            blast.ID = "Deflect" + Random.Range(0, 100000);
            blast.AlreadyHit = false;
            blast.HasHit = false;
            blast.HandleSelfMovement = true;
            blast.transform.right = away.normalized;

            var rb = blast.GetComponent<Rigidbody2D>();
            if (rb != null)
                rb.velocity = away.normalized * Mathf.Max(20f, blast.realSpeed);

            var blastCol = blast.GetComponent<Collider2D>();
            var limbCol = limb.GetComponent<Collider2D>();
            if (blastCol != null && limbCol != null)
                Physics2D.IgnoreCollision(blastCol, limbCol, true);

            return true;
        }

        public static bool TryDeflectBeamHit(BeamBehaviour beam, LimbBehaviour limb)
        {
            if (beam == null || limb == null) return false;
            var defenderRoot = limb.transform.root != null ? limb.transform.root.gameObject : null;
            var attackerRoot = beam.transform.root != null ? beam.transform.root.gameObject : beam.gameObject;
            if (defenderRoot == null || attackerRoot == null || defenderRoot == attackerRoot) return false;

            if (!CanDefenderDeflect(defenderRoot, limb, true)) return false;
            if (!PassesHybridThreshold(defenderRoot, attackerRoot, true)) return false;

            Vector2 originalDir = beam.BeamDirection.sqrMagnitude > 0.001f ? new Vector2(beam.BeamDirection.x, beam.BeamDirection.y).normalized : Vector2.right;
            Vector2 deflectDir = GetPreferredDeflectDirection(
                limb,
                beam.StartBeamPosition,
                limb.transform.position
            );

            if (DBPU.KiDeflectBeamCatchThenAim)
            {
                int beamId = beam.GetInstanceID();
                int defenderId = defenderRoot.GetInstanceID();
                float catchSeconds = Mathf.Max(0.05f, DBPU.KiDeflectBeamCatchSeconds);
                BeamCatchState state;
                if (!BeamCatchStates.TryGetValue(beamId, out state) || state.DefenderRootId != defenderId)
                {
                    state = new BeamCatchState()
                    {
                        DefenderRootId = defenderId,
                        ReleaseTime = Time.time + catchSeconds,
                        AimedDirection = deflectDir
                    };
                    BeamCatchStates[beamId] = state;
                }
                else
                {
                    state.AimedDirection = deflectDir;
                }

                Vector2 activeDir = state.AimedDirection.sqrMagnitude > 0.001f ? state.AimedDirection.normalized : deflectDir;
                if (Time.time < state.ReleaseTime)
                {
                    beam.Distance = Mathf.Min(beam.Distance, Mathf.Max(0.8f, beam.realSpeed * 0.04f));
                    beam.BeamDirection = activeDir;
                    beam.EndBeamPosition = beam.StartBeamPosition + beam.BeamDirection.normalized * beam.Distance;
                    if (beam.EndBeam != null)
                        beam.EndBeam.transform.right = -beam.BeamDirection.normalized;
                    if (beam.EndBeam != null && beam.EndBeam.TryGetComponent<BeamComponent>(out var catchBeamComponent))
                        catchBeamComponent.RayDirection = beam.BeamDirection.normalized;

                    var catchRb = limb.PhysicalBehaviour != null ? limb.PhysicalBehaviour.rigidbody : null;
                    if (catchRb != null)
                        catchRb.AddForce((-originalDir) * Mathf.Max(0.05f, 0.12f * catchRb.mass), ForceMode2D.Impulse);

                    return true;
                }

                BeamCatchStates.Remove(beamId);
                deflectDir = activeDir;
            }

            float shove = Mathf.Max(3.5f, beam.realSpeed * 0.22f);
            beam.Distance = Mathf.Max(0f, beam.Distance - shove);
            beam.BeamDirection = deflectDir;
            beam.EndBeamPosition = beam.StartBeamPosition + beam.BeamDirection.normalized * beam.Distance;
            if (beam.EndBeam != null)
                beam.EndBeam.transform.right = -beam.BeamDirection.normalized;
            if (beam.EndBeam != null && beam.EndBeam.TryGetComponent<BeamComponent>(out var beamComponent))
                beamComponent.RayDirection = beam.BeamDirection.normalized;

            var rb = limb.PhysicalBehaviour != null ? limb.PhysicalBehaviour.rigidbody : null;
            if (rb != null)
                rb.AddForce((-originalDir) * Mathf.Max(0.2f, 0.8f * rb.mass), ForceMode2D.Impulse);

            return true;
        }

        private static bool PassesBeamSplitThreshold(GameObject defenderRoot, GameObject attackerRoot)
        {
            float defenderScore = GetEffectivePowerScore(defenderRoot);
            float attackerScore = GetEffectivePowerScore(attackerRoot);
            float baseNeed = Mathf.Max(1f, DBPU.KiDeflectHybridPowerThreshold) * Mathf.Max(1f, DBPU.KiDeflectBeamThresholdMultiplier);
            float splitNeed = baseNeed * Mathf.Max(0.05f, DBPU.KiDeflectBeamSplitThresholdMultiplier);
            return defenderScore >= attackerScore * splitNeed;
        }

        private static bool CanDefenderBeamSplit(GameObject defenderRoot)
        {
            if (defenderRoot == null) return false;
            var person = defenderRoot.GetComponent<PersonBehaviour>();
            if (person == null || !person.IsAlive()) return false;
            var ki = defenderRoot.GetComponent<KiSystem>();
            if (ki != null && ki.SparkingExhaustActive) return false;
            return true;
        }

        private static void ClipBeamAtHit(BeamBehaviour beam, RaycastHit2D hit)
        {
            float newD = Mathf.Max(0.06f, hit.distance + beam.MiddleMinusDistance - 0.05f);
            beam.Distance = newD;
            Vector3 dir = beam.BeamDirection.sqrMagnitude > 0.001f ? beam.BeamDirection.normalized : Vector3.right;
            beam.EndBeamPosition = beam.StartBeamPosition + dir * beam.Distance;
            beam.realSpeed = 0f;
            if (beam.EndBeam != null)
            {
                beam.EndBeam.transform.right = -dir;
                if (beam.EndBeam.TryGetComponent<BeamComponent>(out var beamComponent))
                    beamComponent.RayDirection = new Vector2(dir.x, dir.y).normalized;
            }
        }

        public static bool TryBeamSplitHit(BeamBehaviour beam, LimbBehaviour limb, RaycastHit2D hit, Vector2 castDirection)
        {
            if (beam == null || limb == null) return false;
            if (!DBPU.KiDeflectBeamSplitEnabled) return false;
            if (beam.BeamSplitConsumed) return false;

            var defenderRoot = limb.transform.root != null ? limb.transform.root.gameObject : null;
            var attackerRoot = beam.transform.root != null ? beam.transform.root.gameObject : beam.gameObject;
            if (defenderRoot == null || attackerRoot == null || defenderRoot == attackerRoot) return false;

            if (!CanDefenderBeamSplit(defenderRoot)) return false;
            if (!PassesBeamSplitThreshold(defenderRoot, attackerRoot)) return false;

            float distBeforeClip = beam.Distance;
            Vector3 defenderAnchor = GetDefenderSplitAnchor(limb);

            ClipBeamAtHit(beam, hit);
            beam.BeamSplitConsumed = true;

            Vector3 bf = new Vector3(castDirection.x, castDirection.y, 0f);
            if (bf.sqrMagnitude < 0.0001f)
                bf = beam.BeamDirection.sqrMagnitude > 0.001f ? beam.BeamDirection.normalized : Vector3.right;
            bf.Normalize();

            Color col = (beam.MiddleBeam != null && beam.MiddleBeam.material != null)
                ? beam.MiddleBeam.material.color
                : Color.cyan;
            Texture2D tex = (beam.MiddleBeam != null && beam.MiddleBeam.material != null && beam.MiddleBeam.material.mainTexture != null)
                ? beam.MiddleBeam.material.mainTexture as Texture2D
                : DBPU.StraightBeam_Texture;

            float unspentAlongBeam = Mathf.Max(0f, distBeforeClip - beam.Distance);
            float forwardLen = Mathf.Max(
                DBPU.KiDeflectBeamSplitContinuationLength,
                unspentAlongBeam + beam.Speed * DBPU.Beam_SpeedMultiplier * 5.25f);

            BeamSplitVfx.SpawnFan(hit.point, bf, col, tex, defenderAnchor, forwardLen, beam, null);
            return true;
        }

        public static bool TryBeamSplitStraightBeamHit(StraightBeamBehaviour straight, LimbBehaviour limb, Vector2 hitPoint, Vector2 incomingDirection)
        {
            if (straight == null || limb == null) return false;
            if (!DBPU.KiDeflectBeamSplitEnabled) return false;
            if (straight.DeathBeamSplitConsumed) return false;

            var defenderRoot = limb.transform.root != null ? limb.transform.root.gameObject : null;
            var attackerRoot = straight.transform.root != null ? straight.transform.root.gameObject : straight.gameObject;
            if (defenderRoot == null || attackerRoot == null || defenderRoot == attackerRoot) return false;

            if (!CanDefenderBeamSplit(defenderRoot)) return false;
            if (!PassesBeamSplitThreshold(defenderRoot, attackerRoot)) return false;

            straight.DeathBeamSplitConsumed = true;
            Vector3 bf = new Vector3(incomingDirection.x, incomingDirection.y, 0f);
            if (bf.sqrMagnitude < 0.0001f) bf = Vector3.right;
            bf.Normalize();

            Vector3 defenderAnchor = GetDefenderSplitAnchor(limb);
            float forwardLen = Mathf.Max(
                DBPU.KiDeflectBeamSplitContinuationLength,
                92f * Mathf.Max(0.4f, DBPU.Beam_SizeMultiplier));

            Color col = new Color(0.95f, 0.3f, 0.3f, 1f);
            BeamSplitVfx.SpawnFan(hitPoint, bf, col, DBPU.StraightBeam_Texture, defenderAnchor, forwardLen, null, straight);
            return true;
        }

        public static class BeamSplitVfx
        {
            public static void SpawnFan(
                Vector3 hitPoint,
                Vector3 beamForward,
                Color color,
                Texture2D texture,
                Vector3 defenderAnchor,
                float forwardLength,
                BeamBehaviour beamHost,
                StraightBeamBehaviour straightHost)
            {
                int n = Mathf.Clamp(DBPU.KiDeflectBeamSplitRayCount, 3, 24);
                float wrap = DBPU.KiDeflectBeamSplitWrapDistance * Mathf.Max(0.2f, DBPU.Beam_SizeMultiplier);
                float arcDeg = DBPU.KiDeflectBeamSplitArcDegrees;
                float lineW = 0.055f * Mathf.Max(0.2f, DBPU.Beam_SizeMultiplier);

                Vector3 bf = beamForward;
                bf.z = 0f;
                if (bf.sqrMagnitude < 0.0001f) bf = Vector3.right;
                bf.Normalize();

                Vector2 out2 = new Vector2(hitPoint.x - defenderAnchor.x, hitPoint.y - defenderAnchor.y);
                if (out2.sqrMagnitude < 0.0004f)
                    out2 = new Vector2(-bf.y, bf.x);
                out2.Normalize();
                Vector3 outward = new Vector3(out2.x, out2.y, 0f);
                Vector3 tangentBase = new Vector3(-out2.y, out2.x, 0f);
                if (tangentBase.sqrMagnitude < 0.0001f)
                    tangentBase = new Vector3(-bf.y, bf.x, 0f);
                tangentBase.Normalize();

                Texture2D tex = texture != null ? texture : DBPU.StraightBeam_Texture;
                Material matBase = ModAPI.FindMaterial("VeryBright");

                GameObject root = new GameObject("BeamSplitFan");
                root.transform.position = hitPoint;
                var track = root.AddComponent<BeamSplitVfxRoot>();
                track.BeamHost = beamHost;
                track.StraightHost = straightHost;
                track.SpawnedAt = Time.time;
                if (straightHost != null)
                    track.MinStraightSeconds = Mathf.Max(0.55f, DBPU.KiDeflectBeamSplitLifetime);

                float forwardSeg = Mathf.Max(0.5f, forwardLength);

                for (int i = 0; i < n; i++)
                {
                    float t = n <= 1 ? 0.5f : (float)i / (n - 1);
                    float halfArc = arcDeg * 0.5f * Mathf.Deg2Rad;
                    float ang = Mathf.Lerp(-halfArc, halfArc, t);
                    float cosa = Mathf.Cos(ang);
                    float sina = Mathf.Sin(ang);
                    Vector3 lateralDir = new Vector3(
                        tangentBase.x * cosa - tangentBase.y * sina,
                        tangentBase.x * sina + tangentBase.y * cosa,
                        0f);
                    if (lateralDir.sqrMagnitude < 0.0001f) lateralDir = tangentBase;
                    lateralDir.Normalize();

                    Vector3 p0 = hitPoint;
                    Vector3 p1 = p0 + lateralDir * (wrap * 0.58f) + outward * (wrap * 0.48f);
                    Vector3 p2 = p1 + bf * (wrap * 0.28f);
                    Vector3 p3 = p2 + bf * forwardSeg;

                    GameObject seg = new GameObject("BeamSplitSeg");
                    seg.transform.SetParent(root.transform, true);
                    LineRenderer lr = seg.AddComponent<LineRenderer>();
                    lr.useWorldSpace = true;
                    lr.textureMode = LineTextureMode.Tile;
                    lr.numCapVertices = 2;
                    lr.positionCount = 4;
                    lr.SetPosition(0, p0);
                    lr.SetPosition(1, p1);
                    lr.SetPosition(2, p2);
                    lr.SetPosition(3, p3);
                    lr.startWidth = lineW;
                    lr.endWidth = lineW * 0.3f;
                    lr.sortingLayerName = "Bubbles";
                    lr.sortingOrder = 6;
                    if (matBase != null)
                    {
                        lr.material = new Material(matBase);
                        lr.material.mainTexture = tex;
                        lr.material.mainTextureScale = new Vector2(0.22f, 1f);
                        lr.material.color = color;
                    }
                }
            }
        }

        public static bool TryDeflectStraightBeam(GameObject attackerRoot, LimbBehaviour limb, Vector2 incomingDirection, out Vector2 deflectDirection)
        {
            deflectDirection = incomingDirection.sqrMagnitude > 0.001f ? incomingDirection.normalized : Vector2.right;
            if (attackerRoot == null || limb == null) return false;

            var defenderRoot = limb.transform.root != null ? limb.transform.root.gameObject : null;
            if (defenderRoot == null || defenderRoot == attackerRoot) return false;

            if (!CanDefenderDeflect(defenderRoot, limb, true)) return false;
            if (!PassesHybridThreshold(defenderRoot, attackerRoot, true)) return false;

            deflectDirection = GetPreferredDeflectDirection(
                limb,
                attackerRoot.transform.position,
                limb.transform.position
            );

            var rb = limb.PhysicalBehaviour != null ? limb.PhysicalBehaviour.rigidbody : null;
            if (rb != null)
                rb.AddForce((-incomingDirection.normalized) * Mathf.Max(0.2f, 0.8f * rb.mass), ForceMode2D.Impulse);

            return true;
        }
    }


    public class BeamSplitVfxRoot : MonoBehaviour
    {
        public BeamBehaviour BeamHost;
        public StraightBeamBehaviour StraightHost;
        public float SpawnedAt;
        public float MinStraightSeconds = 0.68f;

        private void Update()
        {
            if (BeamHost != null)
            {
                if (BeamHost.EndBeam == null || !BeamHost.StillActive)
                    Destroy(gameObject);
                return;
            }

            if (StraightHost != null)
            {
                if ((Time.time - SpawnedAt >= MinStraightSeconds && !StraightHost.Firing) || Time.time - SpawnedAt > 3.5f)
                    Destroy(gameObject);
                return;
            }

            Destroy(gameObject);
        }
    }



    [DefaultExecutionOrder(-190)]
    public class KiOverdriveController : MonoBehaviour
    {
        private PersonBehaviour _person;
        private MultipliersAndStuffs _mul;
        private KiSparkingController _spark;

        private void Awake()
        {
            _person = GetComponent<PersonBehaviour>();
            _mul = GetComponent<MultipliersAndStuffs>();
            if (_mul == null) _mul = gameObject.AddComponent<MultipliersAndStuffs>();
            _spark = GetComponent<KiSparkingController>();
        }

        private void Update()
        {
            if (!DBPU.KiOverdriveOutputEnabled || _person == null || !_person.IsAlive())
                return;
            if (_mul == null) return;
            if (GetComponent<CombatPowerController>()) return;

            float maxOut = Mathf.Clamp(DBPU.KiOverdriveMaxPercent / 100f, 1.01f, 2.5f);
            _mul.KiOutput = Mathf.Clamp(_mul.KiOutput, 0.0001f, Mathf.Max(maxOut, 10f));

            TryHandOverdriveInput();
        }

        private bool TryHandOverdriveInput()
        {
            if (!DbpuInputUtil.Down(DBPU.KiOverdriveOutputActionId, DBPU.KiOverdriveOutputDefaultKey)) return false;

            var chargeCtrl = GetComponent<KiChargeModeController>();
            if (chargeCtrl != null && chargeCtrl.IsActivelyCharging)
            {
                CycleKiOutput(_mul);
                StartCoroutine(OverdriveOutputPopupRoutine(_mul.KiOutput));
                return true;
            }

            if (_spark != null && (_spark.CurrentPhase == KiSparkingController.SparkPhase.Overload
                || _spark.CurrentPhase == KiSparkingController.SparkPhase.Exhaust))
            {
                CycleKiOutput(_mul);
                StartCoroutine(OverdriveOutputPopupRoutine(_mul.KiOutput));
                return true;
            }

            foreach (var limb in _person.Limbs)
            {
                if (limb == null || limb.PhysicalBehaviour == null) continue;
                if (!limb.name.Contains("LowerArm")) continue;
                var pb = limb.PhysicalBehaviour;
                if (!pb.IsBeingUsedContinuously() && !CeceUtils.IsSelected(pb)) continue;
                CycleKiOutput(_mul);
                StartCoroutine(OverdriveOutputPopupRoutine(_mul.KiOutput));
                return true;
            }

            return false;
        }

        private static TMP_FontAsset GetHolographicUiFont()
        {
            try
            {
                var s = ModAPI.FindSpawnable("Holographic Display");
                if (s?.Prefab == null) return null;
                var tr = s.Prefab.transform.Find("Text");
                if (tr == null) return null;
                var tmp = tr.GetComponent<TextMeshPro>();
                return tmp != null ? tmp.font : null;
            }
            catch
            {
                return null;
            }
        }

        private Transform GetKiOutputPopupAnchor()
        {
            if (_person != null)
            {
                foreach (var limb in _person.Limbs)
                {
                    if (limb == null || limb.PhysicalBehaviour == null) continue;
                    if (!limb.name.Contains("LowerArm")) continue;
                    var pb = limb.PhysicalBehaviour;
                    if (pb.IsBeingUsedContinuously() || CeceUtils.IsSelected(pb))
                        return limb.transform;
                }
            }

            Transform head = transform.root.Find("Head");
            return head != null ? head : transform;
        }

        private IEnumerator OverdriveOutputPopupRoutine(float output01)
        {
            string msg = "Ki output: " + Mathf.RoundToInt(output01 * 100f) + "%";
            Transform anchor = GetKiOutputPopupAnchor();
            float anchorScaleY = anchor.localScale.y;
            Vector3 startPos = anchor.position + (-anchor.up * (0.25f * anchorScaleY)) + (Vector3.up * 0.15f);

            var textObj = new GameObject("DBPU_KiOutputText");
            textObj.transform.position = startPos;
            var textStorage = textObj.AddComponent<TextMeshPro>();
            textStorage.text = msg;
            textStorage.fontSize = 1.5f;
            TMP_FontAsset f = GetHolographicUiFont();
            if (f != null) textStorage.font = f;
            textStorage.alignment = TextAlignmentOptions.Center;
            textStorage.color = Color.white;
            textStorage.horizontalAlignment = HorizontalAlignmentOptions.Center;
            textStorage.verticalAlignment = VerticalAlignmentOptions.Middle;
            textObj.GetComponent<MeshRenderer>().sortingLayerName = "Bubbles";
            textObj.GetComponent<MeshRenderer>().sortingOrder += 1;

            float t = 0f;
            float a = 1f;
            Vector3 finalPos = textObj.transform.position + (Vector3.up * 0.75f);

            while (t < 1.2f)
            {
                t += Time.deltaTime;
                textObj.transform.position = Vector3.Lerp(textObj.transform.position, finalPos, 2.4f * Time.deltaTime);

                if (t > 0.6f)
                {
                    a = Mathf.Lerp(a, -0.1f, 4.8f * Time.deltaTime);
                    textStorage.color = new Color(1f, 1f, 1f, a);
                }

                yield return new WaitForFixedUpdate();
            }

            Destroy(textObj);
        }

        private static void CycleKiOutput(MultipliersAndStuffs m)
        {
            float max = Mathf.Clamp(DBPU.KiOverdriveMaxPercent / 100f, 1.01f, 2.5f);
            float[] steps = { 1f, 1.25f, 1.5f, 1.75f, 2f };
            float cur = m.KiOutput;
            int idx = -1;
            for (int i = 0; i < steps.Length; i++)
            {
                if (Mathf.Abs(steps[i] - cur) < 0.045f) idx = i;
            }

            if (idx < 0)
            {
                if (cur <= 1.01f)
                    m.KiOutput = Mathf.Min(1.25f, max);
                else
                    m.KiOutput = 1f;
                return;
            }

            int next = idx + 1;
            if (next >= steps.Length || steps[next] > max + 0.01f)
                m.KiOutput = 1f;
            else
                m.KiOutput = Mathf.Min(steps[next], max);
        }
    }


    [DefaultExecutionOrder(-200)]
    public class KiSparkingController : MonoBehaviour
    {
        public enum SparkPhase { Idle, Overload, Exhaust }

        public SparkPhase CurrentPhase { get; private set; } = SparkPhase.Idle;

        private KiSystem kiSystem;
        private PersonBehaviour person;
        private float phaseTimer;
        private float cooldownTimer;
        private AuraHandler auraHandler;

        private struct OverloadLimbBackup
        {
            public LimbBehaviour Limb;
            public float BaseStrength;
            public float BreakingThreshold;
            public float ImpactPainMultiplier;
        }

        private readonly List<OverloadLimbBackup> _overloadLimbBackups = new List<OverloadLimbBackup>();
        private bool _overloadBuffApplied;
        private const float OverloadStrengthMultiplier = 1.22f;
        private const float OverloadBreakThresholdMultiplier = 1.14f;
        private const float OverloadImpactPainMultiplier = 0.78f;

        void Awake()
        {
            kiSystem = GetComponent<KiSystem>();
            person = GetComponent<PersonBehaviour>();
            auraHandler = GetComponent<AuraHandler>();
        }

        void PushSparkingKiFlags()
        {
            if (kiSystem == null) return;
            kiSystem.SparkingOverloadActive = CurrentPhase == SparkPhase.Overload;
            kiSystem.SparkingExhaustActive = CurrentPhase == SparkPhase.Exhaust;
        }

        private void ApplyOverloadBuffs()
        {
            if (_overloadBuffApplied || person == null || person.Limbs == null) return;
            _overloadLimbBackups.Clear();
            foreach (var limb in person.Limbs)
            {
                if (limb == null) continue;
                _overloadLimbBackups.Add(new OverloadLimbBackup
                {
                    Limb = limb,
                    BaseStrength = limb.BaseStrength,
                    BreakingThreshold = limb.BreakingThreshold,
                    ImpactPainMultiplier = limb.ImpactPainMultiplier
                });

                limb.BaseStrength *= OverloadStrengthMultiplier;
                limb.BreakingThreshold *= OverloadBreakThresholdMultiplier;
                limb.ImpactPainMultiplier *= OverloadImpactPainMultiplier;
            }
            _overloadBuffApplied = true;
        }

        private void ClearOverloadBuffs()
        {
            if (!_overloadBuffApplied) return;
            for (int i = 0; i < _overloadLimbBackups.Count; i++)
            {
                var b = _overloadLimbBackups[i];
                if (b.Limb == null) continue;
                b.Limb.BaseStrength = b.BaseStrength;
                b.Limb.BreakingThreshold = b.BreakingThreshold;
                b.Limb.ImpactPainMultiplier = b.ImpactPainMultiplier;
            }
            _overloadLimbBackups.Clear();
            _overloadBuffApplied = false;
        }

        void Update()
        {
            if (kiSystem == null || person == null) return;

            if (!DBPU.SparkingEnabled)
            {
                if (CurrentPhase != SparkPhase.Idle)
                {
                    CurrentPhase = SparkPhase.Idle;
                    phaseTimer = 0f;
                    if (kiSystem != null) kiSystem.SparkingOvercharge01 = 0f;
                    if (auraHandler != null) auraHandler.SetSparkingPulse(false);
                    ClearOverloadBuffs();
                    PushSparkingKiFlags();
                }
                return;
            }

            if (cooldownTimer > 0f)
                cooldownTimer -= Time.deltaTime;

            if (!person.IsAlive())
            {
                CurrentPhase = SparkPhase.Idle;
                phaseTimer = 0f;
                if (kiSystem != null) kiSystem.SparkingOvercharge01 = 0f;
                if (auraHandler != null) auraHandler.SetSparkingPulse(false);
                ClearOverloadBuffs();
                PushSparkingKiFlags();
                return;
            }

            switch (CurrentPhase)
            {
                case SparkPhase.Overload:
                    phaseTimer -= Time.deltaTime;
                    if (phaseTimer <= 0f)
                    {
                        CurrentPhase = SparkPhase.Exhaust;
                        phaseTimer = Mathf.Max(0.1f, DBPU.SparkingExhaustSeconds);
                        kiSystem.currentKi = 0f;
                        GetComponent<KiChargeModeController>()?.ForceEndCharge();
                        if (auraHandler != null) auraHandler.SetSparkingPulse(true);
                        ClearOverloadBuffs();
                    }
                    break;
                case SparkPhase.Exhaust:
                    phaseTimer -= Time.deltaTime;
                    if (phaseTimer <= 0f)
                    {
                        CurrentPhase = SparkPhase.Idle;
                        cooldownTimer = Mathf.Max(0f, DBPU.SparkingCooldownSeconds);
                        if (auraHandler != null) auraHandler.SetSparkingPulse(false);
                        ClearOverloadBuffs();
                    }
                    break;
            }

            PushSparkingKiFlags();
        }

        public bool TryStartOverload()
        {
            if (!DBPU.SparkingEnabled) return false;
            if (person == null || !person.IsAlive()) return false;
            if (CurrentPhase != SparkPhase.Idle) return false;
            if (cooldownTimer > 0f) return false;
            CurrentPhase = SparkPhase.Overload;
            phaseTimer = Mathf.Max(0.1f, DBPU.SparkingOverloadSeconds);
            kiSystem.currentKi = kiSystem.maxKi;
            if (kiSystem != null) kiSystem.SparkingOvercharge01 = 0f;
            GetComponent<KiChargeModeController>()?.ForceEndCharge(true);
            if (auraHandler != null) auraHandler.SetSparkingPulse(true);
            ApplyOverloadBuffs();
            PushSparkingKiFlags();
            return true;
        }

        /// <summary>Ki overdrive held above 100% too long — same exhaust phase as post-Sparking.</summary>
        public bool ForceEnterExhaustFromOverdrive()
        {
            if (!DBPU.SparkingEnabled) return false;
            if (person == null || !person.IsAlive()) return false;
            if (CurrentPhase == SparkPhase.Overload) return false;

            if (CurrentPhase == SparkPhase.Exhaust)
                phaseTimer = Mathf.Max(phaseTimer, Mathf.Max(0.1f, DBPU.SparkingExhaustSeconds));
            else
            {
                CurrentPhase = SparkPhase.Exhaust;
                phaseTimer = Mathf.Max(0.1f, DBPU.SparkingExhaustSeconds);
            }

            kiSystem.currentKi = 0f;
            GetComponent<KiChargeModeController>()?.ForceEndCharge();
            if (auraHandler != null) auraHandler.SetSparkingPulse(true);
            ClearOverloadBuffs();
            PushSparkingKiFlags();
            return true;
        }

        void OnDestroy()
        {
            ClearOverloadBuffs();
        }
    }

    public class KiSystem : MonoBehaviour
    {
        public float currentKi = 0;
        public float maxKi = 100;
        public float baseRegen = 1;
        private Color baseColor;
        public float chargeMult = 25;
        public float exhaustionCooldownTime = 10f;
        private bool isCharging = false;
        public float exhaustionTimer = 0f;
        public bool isExhausted = false;
        public Color barColor = new Color(1, 1, 1, 1);
        public Color requiredColor = Color.clear;
        private PersonBehaviour personBehaviour;
        private TransformationContextMenu transformationContextMenu;
        private CharacterTransformations characterTransformations;
        private CharacterTransformations.Transformations transformations;
        private CharacterTransformations.Transformations.TransformationStats currentTransformation;
        private Dictionary<string, LimbInitialValues> limbInitialValues = new Dictionary<string, LimbInitialValues>();
        private SpriteRenderer barRenderer;
        private GameObject head;
        public float currentKiDrainRate = 0;
        float previousKi;
        public string CurrentForm = "Base";
        public string BaseForm = "Base";
        private PhysicalBehaviour upperBody;

