        public void ResetValues()
        {
            if (personBehaviour == null)
                personBehaviour = gameObject.GetComponent<PersonBehaviour>();
            if (personBehaviour == null) return;

            EnsureLimbBaselines();

            foreach (var limb in personBehaviour.Limbs)
            {
                if (limb == null) continue;
                if (limbInitialValues.TryGetValue(limb.name, out var values) && values != null)
                    values.RestoreInitialValues(limb);
            }
        }

        public void EnsureReadyForTransforms()
        {
            if (personBehaviour == null)
                personBehaviour = gameObject.GetComponent<PersonBehaviour>();

            if (characterTransformations == null)
                characterTransformations = gameObject.GetComponent<CharacterTransformations>();
            if (characterTransformations != null)
                transformations = characterTransformations.transformations;

            if (transformationContextMenu == null)
            {
                var head = transform.root != null ? transform.root.Find("Head") : null;
                if (head != null)
                    transformationContextMenu = head.GetComponent<TransformationContextMenu>();
                if (transformationContextMenu == null && personBehaviour != null && personBehaviour.Limbs != null && personBehaviour.Limbs.Length > 0)
                    transformationContextMenu = personBehaviour.Limbs[0].GetComponent<TransformationContextMenu>();
            }

            EnsureLimbBaselines();
        }

        void EnsureLimbBaselines()
        {
            if (personBehaviour == null || personBehaviour.Limbs == null) return;
            foreach (var limb in personBehaviour.Limbs)
            {
                if (limb == null || string.IsNullOrEmpty(limb.name)) continue;
                if (!limbInitialValues.ContainsKey(limb.name))
                    limbInitialValues[limb.name] = new LimbInitialValues(limb);
            }
        }

        public void SubtractKi(float amount)
        {
            StartCoroutine(LerpKi(currentKi, Mathf.Max(currentKi - amount, 0), 0.5f));
        }

        private IEnumerator LerpKi(float startValue, float endValue, float duration)
        {
            float time = 0;
            while (time < duration)
            {
                currentKi = Mathf.Lerp(startValue, endValue, time / duration);
                time += Time.deltaTime;
                yield return null;
            }
            currentKi = endValue;
        }

        public void ApplyTransformation(string transformationKey)
        {
            if (transformations == null || !transformations.TransformationData.ContainsKey(transformationKey))
            {
                return;
            }

            var newTransformation = transformations.TransformationData[transformationKey];
            currentTransformation = newTransformation;
            currentKiDrainRate = currentTransformation.KiDrainRate;
            CurrentForm = transformationKey;
            UpdateKiBarColor(transformationKey);
        }

        void OnDestroy()
        {
            Destroy(bar);
        }

        void Update()
        {
            Vector3 targetPosition = head.transform.position + new Vector3(0, 1f, 0);
            bar.transform.position = Vector3.Lerp(bar.transform.position, targetPosition, Time.deltaTime * 20f);
            bar.transform.rotation = Quaternion.identity;

            if (!isExhausted && DBPU.BaseConsideredForms.Contains(CurrentForm) && personBehaviour.IsAlive())
            {
                currentKi += (baseRegen * DBPU.KiRegenMultiplier) * Time.deltaTime;
                currentKi = Mathf.Min(currentKi, maxKi);
            }

            else if (isExhausted)
            {
                exhaustionTimer -= Time.deltaTime;
                if (exhaustionTimer <= 0)
                {
                    isExhausted = false;
                    currentKi = 0.1f;
                }
            }

            if (SparkingOverloadActive)
                currentKi = maxKi;
            else if (SparkingExhaustActive)
                currentKi = 0f;

            if (!SparkingExhaustActive && !isExhausted && DBPU.BaseConsideredForms.Contains(CurrentForm) && personBehaviour.IsAlive())
            {
                currentKi += (baseRegen * DBPU.KiRegenMultiplier) * Time.deltaTime;
                currentKi = Mathf.Min(currentKi, maxKi);
            }
            else if (isExhausted && !SparkingExhaustActive)
            {
                exhaustionTimer -= Time.deltaTime;
                if (exhaustionTimer <= 0)
                    isExhausted = false;
            }

            if (KiChargeActiveForRegen && !SparkingExhaustActive && !SparkingOverloadActive && personBehaviour.IsAlive())
            {
                currentKi += DBPU.KiChargeHoldRegenPerSecond * Time.deltaTime;
                currentKi = Mathf.Min(currentKi, maxKi);
            }

            if (!personBehaviour.IsAlive() && currentKi > 0)
                currentKi = 0f;

            if (currentTransformation != null)
            {
                if (!SparkingOverloadActive && !SparkingExhaustActive)
                {
                    currentKi -= (currentKiDrainRate * DBPU.KiDrainMultiplier) * Time.deltaTime;
                    currentKi = Mathf.Max(currentKi, 0);
                    if (previousKi > 0 && currentKi <= 0 && CurrentForm != BaseForm)
                        OnKiDepleted();
                    if (currentKi <= 0 && !isExhausted)
                    {
                        isExhausted = true;
                        exhaustionTimer = exhaustionCooldownTime;
                    }
                }
                else if (SparkingExhaustActive)
                    currentKi = 0f;
            }

            previousKi = currentKi;

            barRenderer.material.SetFloat("_RevealAmount", Mathf.Clamp01(currentKi / maxKi));
            ApplyKiBarSparkingPresentation();

            if (StrainRate > 0f || Strain > 0f)
            {
                StrainOn = true;

                Strain += ((StrainRate * StrainRateMultiplier) * DBPU.StrainGainMultiplier) * Time.deltaTime;
                Strain = Mathf.Min(Strain, 1f);

                strainBarRenderer.material = DBPU.barMaterial;
                strainBarRenderer.material.SetFloat("_RevealAmount", Mathf.Clamp01(Strain));

                strainBarRenderer.color = strainBarColor;
                strainBarRenderer.material.SetColor("_TintColor", new Color(strainBarColor.r, strainBarColor.g, strainBarColor.b, 1));
                strainBar.transform.Find("StrainDepletedBar").gameObject.GetComponent<SpriteRenderer>().color = Color.white;
                strainBar.transform.Find("StrainBarFrame").gameObject.GetComponent<SpriteRenderer>().color = Color.white;
            }

            else if (StrainOn == true)
            {
                StrainOn = false;
                strainBarRenderer.material = ModAPI.FindMaterial("Sprites-Default");
                strainBarRenderer.color = Color.clear;
                strainBar.transform.Find("StrainDepletedBar").gameObject.GetComponent<SpriteRenderer>().color = Color.clear;
                strainBar.transform.Find("StrainBarFrame").gameObject.GetComponent<SpriteRenderer>().color = Color.clear;
            }

            if (StrainRate == 0f)
            {
                Strain -= ((0.02f * DBPU.StrainDrainMultiplier) / Mathf.Clamp(4f * Strain, 1f, 4f)) * Time.deltaTime;
                Strain = Mathf.Max(Strain, 0f);
            }
        }

        public void SuppressLegacyHud(bool suppressed)
        {
            if (bar && bar.activeSelf == suppressed) bar.SetActive(!suppressed);
            if (strainBar && strainBar.activeSelf == suppressed) strainBar.SetActive(!suppressed);
        }

        private void ApplyKiBarSparkingPresentation()
        {
            Color normalTint = new Color(barColor.r, barColor.g, barColor.b, 1);
            bool outlineRenderersValid = sparkingOutlineOuterRenderer != null && sparkingOutlineInnerRenderer != null;

            Action disableSparkingOutline = () =>
            {
                if (!outlineRenderersValid) return;
                sparkingOutlineOuterRenderer.enabled = false;
                sparkingOutlineInnerRenderer.enabled = false;
                sparkingOutlineOuterRenderer.color = Color.clear;
                sparkingOutlineInnerRenderer.color = Color.clear;
                sparkingOutlineOuterRenderer.transform.localScale = Vector3.one;
                sparkingOutlineInnerRenderer.transform.localScale = Vector3.one;
            };

            if (sparkingPrepBarRenderer == null)
            {
                if (SparkingOverloadActive)
                {
                    float pulse = 0.5f + 0.5f * Mathf.Sin(Time.time * 7f);
                    Color brightYellow = new Color(1f, 0.93f, 0.12f, 1f) * 1.25f;
                    Color purpleAcc = new Color(0.48f, 0.1f, 0.98f, 1f);
                    barRenderer.material.SetColor("_TintColor", Color.Lerp(brightYellow, purpleAcc, 0.22f + 0.18f * pulse));
                }
                else if (SparkingExhaustActive)
                    barRenderer.material.SetColor("_TintColor", Color.Lerp(normalTint * 0.35f, new Color(0.35f, 0.12f, 0.48f, 1f), 0.65f));
                else
                    barRenderer.material.SetColor("_TintColor", normalTint);
                disableSparkingOutline();
                return;
            }

            if (SparkingOverloadActive)
            {
                sparkingPrepBarRenderer.enabled = false;
                sparkingPrepBarRenderer.material.SetFloat("_RevealAmount", 0f);
                float pulse = 0.5f + 0.5f * Mathf.Sin(Time.time * 7f);
                Color brightYellow = new Color(1f, 0.93f, 0.12f, 1f) * 1.25f;
                Color purpleAcc = new Color(0.48f, 0.1f, 0.98f, 1f);
                barRenderer.material.SetColor("_TintColor", Color.Lerp(brightYellow, purpleAcc, 0.22f + 0.18f * pulse));

                if (outlineRenderersValid)
                {
                    float ripple = 0.5f + 0.5f * Mathf.Sin(Time.time * 12f);
                    float ripple2 = 0.5f + 0.5f * Mathf.Sin(Time.time * 9.25f + 1.3f);
                    sparkingOutlineOuterRenderer.enabled = true;
                    sparkingOutlineInnerRenderer.enabled = true;
                    sparkingOutlineOuterRenderer.color = Color.Lerp(new Color(0.45f, 0.12f, 0.82f, 0.38f), new Color(0.84f, 0.56f, 1f, 0.88f), ripple);
                    sparkingOutlineInnerRenderer.color = Color.Lerp(new Color(0.3f, 0.08f, 0.62f, 0.3f), new Color(0.78f, 0.4f, 1f, 0.72f), ripple2);
                    sparkingOutlineOuterRenderer.transform.localScale = Vector3.one * (1.03f + 0.12f * ripple);
                    sparkingOutlineInnerRenderer.transform.localScale = Vector3.one * (1.01f + 0.065f * ripple2);
                }
                return;
            }

            if (SparkingExhaustActive)
            {
                sparkingPrepBarRenderer.enabled = false;
                sparkingPrepBarRenderer.material.SetFloat("_RevealAmount", 0f);
                barRenderer.material.SetColor("_TintColor", Color.Lerp(normalTint * 0.35f, new Color(0.35f, 0.12f, 0.48f, 1f), 0.65f));
                disableSparkingOutline();
                return;
            }

            if (SparkingOvercharge01 > 0.001f && currentKi >= maxKi * 0.99f)
            {
                barRenderer.material.SetColor("_TintColor", normalTint);
                sparkingPrepBarRenderer.enabled = true;
                sparkingPrepBarRenderer.material.SetFloat("_RevealAmount", Mathf.Clamp01(SparkingOvercharge01));
                disableSparkingOutline();
                return;
            }

            sparkingPrepBarRenderer.enabled = false;
            sparkingPrepBarRenderer.material.SetFloat("_RevealAmount", 0f);
            barRenderer.material.SetColor("_TintColor", normalTint);
            disableSparkingOutline();
        }

                private void OnKiDepleted()
        {
            characterTransformations.ApplyTransformation(personBehaviour, BaseForm, true);
            transformationContextMenu.PositionSelectedFrame = transformationContextMenu.OriginalSelectedFrame;
            transformationContextMenu.LocalSelectedFrame = transformationContextMenu.OriginalSelectedFrame;
            transformationContextMenu.FormSelected = transformationContextMenu.OriginalFormSelected;
            transformationContextMenu.Form = BaseForm;

            gameObject.GetComponent<AuraHandler>().CurrentAuraID = BaseForm;
            gameObject.GetComponent<AuraHandler>().AuraActive = false;

            currentKi += 1;
        }

        private void UpdateKiBarColor(string transformationKey, Sprite sprite = null)
        {
            if (requiredColor != Color.clear)
            {
                barColor = requiredColor * 1.75f;
                barRenderer.material.SetColor("_TintColor", new Color(barColor.r, barColor.g, barColor.b, 1));
                baseColor = barColor;
            }

            else
            {
                Dictionary<string, Color> ogColors = new Dictionary<string, Color>
                {
                    { "Base", Color.cyan },
                    { "SSJ1", new Color(235f / 255f, 175f / 255f, 35f / 255f) },
                    { "SSJGrade2", new Color(235f / 255f, 175f / 255f, 35f / 255f) },
                    { "PSSJ", new Color(235f / 255f, 190f / 255f, 50f / 255f) },
                    { "SSJ2", new Color(235f / 255f, 175f / 255f, 35f / 255f) },
                    { "SSJ3", new Color(255f / 255f, 165f / 255f, 0f / 255f) },
                    { "SSJGod", new Color(217f / 255f, 24f / 255f, 68f / 255f) },
                    { "SSJBlue", new Color(26f / 255f, 223f / 255f, 237f / 255f) },
                    { "PSSJBlue", new Color(46f / 255f, 243f / 255f, 255f / 255f) },
                    { "SSJBlueEvolution", new Color(21f / 255f, 92f / 255f, 245f / 255f) },
                    { "MUI", Color.white },
                    { "FirstForm", new Color(200f / 255f, 35f / 255f, 230f / 255f) },
                    { "SecondForm", new Color(200f / 255f, 35f / 255f, 230f / 255f) },
                    { "ThirdForm", new Color(200f / 255f, 35f / 255f, 230f / 255f) },
                    { "FinalForm", new Color(200f / 255f, 35f / 255f, 230f / 255f) },
                    { "FullPower", new Color(200f / 255f, 35f / 255f, 230f / 255f) },
                    { "GoldenForm", new Color(235f / 255f, 175f / 255f, 35f / 255f) },
                    { "BlackForm", new Color(140f / 255f, 60f / 255f, 220f / 255f) },
                    { "Ikari", new Color(0f / 255f, 255f / 255f, 0f / 255f) },
                    { "FPSSJ", new Color(0f / 255f, 255f / 255f, 0f / 255f) },
                    { "Android", new Color(125f / 255f, 125f / 255f, 125f / 255f) },
                    { "OrangePiccolo", new Color(255f / 255f, 210f / 255f, 50f / 255f) }
                    };

                if (ogColors.TryGetValue(transformationKey, out Color predefinedColor))
                {
                    barColor = predefinedColor * 1.75f;
                    barRenderer.material.SetColor("_TintColor", new Color(barColor.r, barColor.g, barColor.b, 1));
                    baseColor = barColor;
                }

                else
                {
                    barColor = GetAverageColor();
                    barRenderer.material.SetColor("_TintColor", new Color(barColor.r * 2.5f, barColor.g * 2.5f, barColor.b * 2.5f, 1));
                    Debug.LogError(new Color(barColor.r * 2.5f, barColor.g * 2.5f, barColor.b * 2.5f, 1));
                    baseColor = barColor;
                }
            }
        }

        private Color GenerateColor(string key, Color? influenceColor = null)
        {
            int hash = key.GetHashCode();
            float hue = Mathf.Abs(hash % 1000) / 1000f;
            float saturation = 0.8f;
            float brightness = 0.9f;
            Color generatedColor = Color.HSVToRGB(hue, saturation, brightness);

            if (influenceColor.HasValue)
            {
                float blendFactor = 0.5f;
                generatedColor = Color.Lerp(influenceColor.Value, generatedColor, blendFactor);
            }

            return generatedColor;
        }

        private Color GetAverageColor(float brightnessThreshold = 0.1f)
        {
            if (personBehaviour == null || personBehaviour.Limbs == null || personBehaviour.Limbs.Length == 0 || personBehaviour.Limbs[0] == null)
                return Color.black;

            Transform hair = personBehaviour.Limbs[0].transform.Find("Hair");
            if (hair == null)
                return Color.black;

            SpriteRenderer hairSr = hair.GetComponent<SpriteRenderer>();
            if (hairSr == null)
                return Color.black;

            Sprite sprite = hairSr.sprite;
            if (sprite == null)
            {
                return Color.black;
            }

            Texture2D texture = sprite.texture;
            if (texture == null)
            {
                return Color.black;
            }

            Rect spriteRect = sprite.textureRect;

            Color[] pixels;
            try
            {
                pixels = texture.GetPixels(
                    (int)spriteRect.x,
                    (int)spriteRect.y,
                    (int)spriteRect.width,
                    (int)spriteRect.height
                    );
            }
            catch
            {
                return Color.black;
            }

            if (pixels == null || pixels.Length == 0)
            {
                return Color.black;
            }

            Color averageColor = new Color(0, 0, 0, 0);
            int validPixelCount = 0;

            foreach (Color pixel in pixels)
            {
                if (pixel.a > 0)
                {
                    //brightness = 0.2126 * R + 0.7152 * G + 0.0722 * B

                    float brightness = 0.2126f * pixel.r + 0.7152f * pixel.g + 0.0722f * pixel.b;

                    if (brightness >= brightnessThreshold)
                    {
                        averageColor += pixel;
                        validPixelCount++;
                    }
                }
            }

            if (validPixelCount > 0)
            {
                averageColor /= validPixelCount;
            }

            else
            {
                return Color.black;
            }

            return averageColor;
        }
    }

    public class Barrage : MonoBehaviour
    {
        public GameObject projectilePrefab;
        public Sprite projectileSprite;
        public float duration = 0.2f;
        public const float baseDuration = 0.15f;
        public float damageOutput = 1f;
        public float speedOutput = 1f;
        public int projectileCount = 5;
        public float spawnInterval = 0.015f;
        public float distance = 3f;

        public float minSpawnInterval = 0.008f;
        public float maxSpawnInterval = 0.05f;

        public float randomHeightMin = 0.15f;
        public float randomHeightMax = 1f;
        public float randomPositionOffsetMagnitude = 0.4f;
        public float positiveAdditionAngle = 90f;
        public float negativeAdditionAngle = -270f;

        public float fixedOffsetValue = 1f;
        public int maxConsecutiveNegatives = 2;

        public bool useRandomHeight = true;
        private PersonBehaviour person;
        private PhysicalBehaviour phys;

        private int consecutiveNegativeCount = 0;
        private Coroutine barrageCoroutine;
        private bool isFiring = false;

        private PunchPower punchPower;
        public bool Enabled = true;

        private float time = 0;
        private List<GameObject> objects = new List<GameObject>();

        private MultipliersAndStuffs Multipliers;
        private List<SpriteRenderer> arms = new List<SpriteRenderer>();

        private void OnDestroy()
        {
            foreach (var obj in objects)
            {
                Destroy(obj);
            }
        }

        void Start()
        {
            person = transform.root.gameObject.GetComponent<PersonBehaviour>();
            phys = GetComponent<PhysicalBehaviour>();

            foreach (var limb in person.Limbs)
            {
                if (MCP_Utils.LimbCanUsePowers(limb) && limb.name.Contains("Arm"))
                {
                    var renderer = limb.gameObject.GetComponent<SpriteRenderer>();
                    if (renderer != null)
                        arms.Add(renderer);
                }
            }

            Multipliers = transform.root.gameObject.GetComponent<MultipliersAndStuffs>();
            RefreshPunchPowerReference();
        }

        void RefreshPunchPowerReference()
        {
            if (punchPower != null) return;
            var lowerArm = person.Limbs.FirstOrDefault(x => x.name == "LowerArmFront")
                ?? person.Limbs.FirstOrDefault(x => x.name.Contains("LowerArm"));
            if (lowerArm != null)
                punchPower = lowerArm.GetComponent<PunchPower>();
        }

        Sprite CreateProjectileSprite(LimbBehaviour lowerArm)
        {
            if (lowerArm == null) return null;
            var frontArm = lowerArm.GetComponent<SpriteRenderer>();
            if (frontArm == null || frontArm.sprite == null) return null;

            Sprite originalSprite = frontArm.sprite;
            Texture2D readable = DuplicateProjectileTexture(originalSprite.texture);
            if (readable == null) return originalSprite;

            Rect rect = originalSprite.rect;
            int x = Mathf.RoundToInt(rect.x);
            int y = Mathf.RoundToInt(rect.y);
            int w = Mathf.RoundToInt(rect.width);
            int h = Mathf.RoundToInt(rect.height);
            if (w <= 0 || h <= 0) return originalSprite;

            Color[] pixels;
            try
            {
                pixels = readable.GetPixels(x, y, w, h);
            }
            catch
            {
                return originalSprite;
            }

            var newTexture = new Texture2D(w, h, TextureFormat.RGBA32, false);
            newTexture.filterMode = FilterMode.Point;
            newTexture.wrapMode = TextureWrapMode.Clamp;
            newTexture.SetPixels(pixels);
            newTexture.Apply(false, false);

            return Sprite.Create(newTexture, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f), originalSprite.pixelsPerUnit);
        }

        static Texture2D DuplicateProjectileTexture(Texture2D source)
        {
            if (source == null) return null;
            try
            {
                var copy = new Texture2D(source.width, source.height, TextureFormat.RGBA32, false);
                copy.filterMode = FilterMode.Point;
                copy.wrapMode = source.wrapMode;
                copy.SetPixels32(source.GetPixels32());
                copy.Apply(false, false);
                return copy;
            }
            catch
            {
                return null;
            }
        }

        void Update()
        {
            if (Enabled == true && DbpuInputUtil.Down(DBPU.BarrageActionId, KeyCode.H) && CeceUtils.IsSelected(phys))
            {
                StartBarrage();
                foreach (var r in arms)
                {
                    r.enabled = false;
                }
                time = 0;
            }

            if (time < 0.5f && isFiring == true)
            {
                duration = baseDuration / 1.2f;
                time += Time.deltaTime;
            }

            else
            {
                duration = baseDuration;
            }

            if (DbpuInputUtil.Up(DBPU.BarrageActionId, KeyCode.H) || (Enabled == false && isFiring == true))
            {
                StopBarrage();

                if (Time.timeScale >= 0.01f)
                {
                    foreach (var r in arms)
                    {
                        r.enabled = true;
                    }
                }
            }

            if (Time.timeScale >= 0.01f && !DbpuInputUtil.Held(DBPU.BarrageActionId, KeyCode.H))
            {
                foreach (var r in arms)
                {
                    r.enabled = true;
                }
            }
        }

        void StartBarrage()
        {
            if (barrageCoroutine != null) return;

            RefreshPunchPowerReference();
            var lowerArm = person.Limbs.FirstOrDefault(x => x.name == "LowerArmFront")
                ?? person.Limbs.FirstOrDefault(x => x.name.Contains("LowerArm"));
            if (punchPower == null && lowerArm != null)
            {
                punchPower = lowerArm.GetComponent<PunchPower>();
                if (punchPower == null)
                {
                    punchPower = lowerArm.gameObject.AddComponent<PunchPower>();
                }
            }

            if (projectileSprite == null)
                projectileSprite = CreateProjectileSprite(lowerArm);
            if (projectileSprite == null)
            {
                foreach (var limb in person.Limbs)
                {
                    if (!limb.name.Contains("Arm")) continue;
                    projectileSprite = CreateProjectileSprite(limb);
                    if (projectileSprite != null) break;
                }
            }
            if (projectileSprite == null)
                projectileSprite = DBPU.KiBlast_Sprite;

            isFiring = true;
            barrageCoroutine = StartCoroutine(SpawnProjectiles());
        }

        void StopBarrage()
        {
            isFiring = false;
            if (barrageCoroutine != null)
            {
                StopCoroutine(barrageCoroutine);
                barrageCoroutine = null;
            }
        }

        IEnumerator SpawnProjectiles()
        {
            RefreshPunchPowerReference();
            if (Multipliers == null)
                Multipliers = transform.root.gameObject.GetComponent<MultipliersAndStuffs>();

            float multiplier = Multipliers != null ? Mathf.Max(0.01f, Multipliers.FinalMultiplier) : 1f;
            float baseDamage = punchPower != null && punchPower.Damage >= 0f
                ? punchPower.Damage
                : CombatPowerController.AttackHealth(person) * 0.01f / Mathf.Max(1f, multiplier);
            float punchDamageOutput = punchPower != null ? punchPower.DamageOutput : 1f;
            float Damage = (((baseDamage / 20f) * multiplier) * punchDamageOutput * damageOutput) * DBPU.DamageMultiplier * CombatPowerController.OutputFor(person);

            float speedMultiplier = MapToInvertedOutput(Damage, 5000f, 2000000000000f, minSpawnInterval, maxSpawnInterval) / Mathf.Max(speedOutput, 0.0001f);

            while (isFiring)
            {
                for (int i = 0; i < projectileCount; i++)
                {
                    SpawnProjectile(i);

                    yield return new WaitForSeconds(Mathf.Clamp(speedMultiplier, minSpawnInterval, maxSpawnInterval));

                    if (!isFiring) yield break;
                }
            }
        }

        void SpawnProjectile(int projectileIndex)
        {
            if (projectileSprite == null)
            {
                Debug.LogError("No sprite assigned to projectileSprite! Assign a sprite in the Inspector.");
                return;
            }

            GameObject projectile = new GameObject("proj");
            projectile.transform.localScale = transform.root.localScale;
            var sr = projectile.AddComponent<SpriteRenderer>();

            projectile.transform.rotation *= Quaternion.Euler(0, 0, 90);
            objects.Add(projectile);

            int WhatLayer = UnityEngine.Random.Range(0, 2);

            sr.sprite = projectileSprite;
            var colorLimb = person.Limbs.FirstOrDefault(x => x.name == "LowerArmFront")
                ?? person.Limbs.FirstOrDefault(x => x.name.Contains("LowerArm"));
            if (colorLimb != null)
                sr.color = colorLimb.gameObject.GetComponent<SpriteRenderer>().color;
            sr.sortingLayerName = (WhatLayer == 0) ? "Background" : "Foreground";
            sr.sortingOrder = 5;

            TrailRenderer trail = projectile.AddComponent<TrailRenderer>();
            trail.time = 0.35f;
            trail.numCornerVertices = 20;
            trail.numCapVertices = 20;
            AnimationCurve widthCurve = new AnimationCurve();
            widthCurve.AddKey(0, 0.15f);
            widthCurve.AddKey(1, 0.01f);
            trail.widthCurve = widthCurve;
            Gradient gradient = new Gradient();
            gradient.SetKeys(
                new GradientColorKey[] { new GradientColorKey(sr.color, 0.0f), new GradientColorKey(sr.color, 1.0f) },
                new GradientAlphaKey[] { new GradientAlphaKey(0.5f, 0.0f), new GradientAlphaKey(0f, 1.0f) }
                );

            trail.colorGradient = gradient;
            trail.material = new Material(Shader.Find("Sprites/Default"));
            trail.sortingLayerName = (WhatLayer == 0) ? "Background" : "Foreground";
            trail.sortingOrder = sr.sortingOrder - 1;

            projectile.transform.position = transform.position;

            StartCoroutine(MoveAlongBezier(projectile, projectileIndex));
        }

        IEnumerator MoveAlongBezier(GameObject projectile, int projectileIndex)
        {
            TrailRenderer trail = projectile.GetComponent<TrailRenderer>();

            Vector3 startPos = transform.position + (transform.right * (Random.Range(0.4f, -0.8f) * Mathf.Sign(transform.root.localScale.x)));
            Vector3 direction = transform.root.localScale.x > 0 ? transform.right : -transform.right;

            RaycastHit2D hit = Physics2D.Raycast(startPos, direction, distance * Mathf.Abs(transform.root.localScale.x));
            while (hit.collider != null && hit.collider.transform.root == transform.root)
            {
                hit = Physics2D.Raycast((Vector3)hit.point + direction * Mathf.Abs(transform.root.localScale.x) * 0.1f, direction, distance * Mathf.Abs(transform.root.localScale.x) - Vector3.Distance(startPos, hit.point));
            }

            Vector3 endPos;
            if (hit.collider != null)
            {
                endPos = hit.point;
            }

            else
            {
                endPos = transform.position + direction * distance * Mathf.Abs(transform.root.localScale.x);
            }

            var dist = Vector3.Distance(endPos, startPos);
            var factor = distance / dist;
            float heightOffset;
            float addition;

            if (useRandomHeight)
            {
                heightOffset = Random.Range(randomHeightMin, randomHeightMax) * Mathf.Abs(transform.root.localScale.x);
                float randVal = Random.value;
                float plus = (randVal > 0.5f) ? randomPositionOffsetMagnitude : -randomPositionOffsetMagnitude;
                startPos += transform.up * Random.Range(0f, plus) * Mathf.Abs(transform.root.localScale.x);
                endPos += transform.up * Random.Range(0f, plus) * Mathf.Abs(transform.root.localScale.x);
                projectile.transform.position = startPos;
                heightOffset *= (randVal > 0.5f) ? 1f : -1f;
                addition = (randVal > 0.5f) ? positiveAdditionAngle : negativeAdditionAngle;
            }

            else
            {
                float baseSign;
                if (consecutiveNegativeCount >= maxConsecutiveNegatives)
                {
                    baseSign = fixedOffsetValue;
                    consecutiveNegativeCount = 0;
                }

                else
                {
                    if (Random.value < 0.5f)
                    {
                        baseSign = -fixedOffsetValue;
                        consecutiveNegativeCount++;
                    }

                    else
                    {
                        baseSign = fixedOffsetValue;
                        consecutiveNegativeCount = 0;
                    }
                }

                heightOffset = baseSign + Random.Range(-0.2f, 0.2f);
                addition = (baseSign > 0) ? positiveAdditionAngle : negativeAdditionAngle;
            }

            Vector3 controlPoint1 = startPos + transform.up * heightOffset;
            Vector3 controlPoint2 = endPos + transform.up * heightOffset;

            Vector3 midPoint = CalculateCubicBezierPoint(0.5f, startPos, controlPoint1, controlPoint2, endPos);
            Vector3 initialDirection = (midPoint - startPos).normalized;
            float initialAngle = Mathf.Atan2(initialDirection.y, initialDirection.x) * Mathf.Rad2Deg;

            if (useRandomHeight)
            {
                initialAngle += (addition == positiveAdditionAngle) ? -270f : 90f;
            }

            else
            {
                initialAngle += (heightOffset < 0 ? -180f : 0f);
            }

            Quaternion initialRotation = Quaternion.Euler(0, 0, initialAngle);

            Vector3 finalDirection = (endPos - controlPoint1).normalized;
            float kiss = heightOffset < 0 ? 10f : -10f;
            kiss = transform.root.localScale.x > 0 ? kiss : -kiss;
            float finalAngle = Mathf.Atan2(finalDirection.y, finalDirection.x) * Mathf.Rad2Deg + (addition + kiss);
            Quaternion finalRotation = Quaternion.Euler(0, 0, finalAngle);

            projectile.transform.rotation = initialRotation;
            SpriteRenderer sr = projectile.GetComponent<SpriteRenderer>();

            /*float damage = (((punchPower.Damage / 20f) * Multipliers.FinalMultiplier) * punchPower.DamageOutput) * DBPU.DamageMultiplier;
            float speedMultiplier = MapToInvertedOutput(damage, 10000f, 2000000000000f, 1f, 2f);

            float travelTime = (duration / 2f) * speedMultiplier;*/

            float travelTime = duration;

            float elapsedTime = 0f;

            while (elapsedTime < Mathf.Clamp(duration * factor, 0.05f, 0.3f))
            {
                float t = elapsedTime / travelTime;
                Vector3 currentPos = Mathf.Pow(1 - t, 3) * startPos +
                                        3 * Mathf.Pow(1 - t, 2) * t * controlPoint1 +
                                        3 * (1 - t) * Mathf.Pow(t, 2) * controlPoint2 +
                                        Mathf.Pow(t, 3) * endPos;
                projectile.transform.position = currentPos;
                projectile.transform.rotation = Quaternion.Lerp(initialRotation, finalRotation, t);

                Vector2 boxSize = new Vector2(sr.sprite.bounds.size.x * projectile.transform.lossyScale.x, sr.sprite.bounds.size.y * projectile.transform.lossyScale.y);

                Collider2D[] hits = Physics2D.OverlapBoxAll(projectile.transform.position, boxSize, projectile.transform.rotation.eulerAngles.z);

                foreach (Collider2D col in hits)
                {
                    if (col.transform.root != transform.root)
                    {
                        Vector2 hitPoint = col.ClosestPoint(projectile.transform.position);
                        /*Vector2 normal = ((Vector2)projectile.transform.position - hitPoint).normalized;
                        Shot shot = new Shot(normal, hitPoint, 50, true, null);
                        col.transform.SendMessage("Shot", shot, SendMessageOptions.DontRequireReceiver);*/

                        float Damage = (punchPower.Damage / 20f) * punchPower.DamageOutput;

                        SkinMaterialHandler skin;
                        if (col.TryGetComponent<SkinMaterialHandler>(out skin))
                        {
                            float damagePercentage = ((Damage * Multipliers.FinalMultiplier) / MCP_Utils.AverageMaxHealth(skin.gameObject.GetComponent<LimbBehaviour>().Person)) * 100f;
                            float bluntVisualDamage = (100f * Mathf.Clamp(damagePercentage, 0f, 2.5f)) / skin.intensityMultiplier;
                            float bulletVisualDamage = (100f * Mathf.Clamp(damagePercentage, 0f, 2.5f)) / skin.intensityMultiplier;

                            if (damagePercentage > 0.02f)
                            {
                                skin.gameObject.GetComponent<LimbBehaviour>().Damage(Damage * Multipliers.FinalMultiplier * DBPU.DamageMultiplier);
                                skin.AddDamagePoint(DamageType.Blunt, hitPoint, bluntVisualDamage / 5f);
                                skin.AddDamagePoint(DamageType.Bullet, hitPoint, bulletVisualDamage / 5f);
                            }
                        }

                        if (UnityEngine.Random.value < 0.3f && col.GetComponent<LimbBehaviour>() != null)
                        {
                            var particle = Instantiate(DBPU.barrageImpact, hitPoint, DBPU.barrageImpact.transform.rotation);
                            particle.transform.localScale /= 2.5f;

                            var partsys = particle.GetComponent<ParticleSystem>();
                            var renderer = particle.GetComponent<ParticleSystemRenderer>();
                            renderer.sortingLayerName = col.GetComponent<Renderer>().sortingLayerName;
                            renderer.sortingOrder = col.GetComponent<Renderer>().sortingOrder + 1;

                            foreach (Transform child in particle.transform)
                            {
                                var renderers = child.gameObject.GetComponent<ParticleSystemRenderer>();
                                renderers.sortingLayerName = col.GetComponent<Renderer>().sortingLayerName;
                                renderers.sortingOrder = col.GetComponent<Renderer>().sortingOrder + 1;
                            }

                            partsys.Play();
                            Destroy(particle, 1.5f);
                        }

                        Rigidbody2D rb = col.GetComponent<Rigidbody2D>();

                        if (rb != null)
                        {
                            Vector2 forceDir = ((Vector2)col.transform.position - (Vector2)transform.position).normalized;

                            if (col.TryGetComponent<LimbBehaviour>(out LimbBehaviour limb))
                            {
                                float damagePercentage = ((Damage * Multipliers.FinalMultiplier) / MCP_Utils.AverageMaxHealth(limb.Person)) * 100f;
                                float knockbackImpulse = (damagePercentage >= 25f) ? punchPower.maxKnockbackImpulse : punchPower.maxKnockbackImpulse * (damagePercentage / 25f);

                                if (damagePercentage > 0.05f) rb.AddForce(forceDir * Mathf.Clamp(Mathf.Abs(knockbackImpulse - knockbackImpulse * 0.02f * (rb.mass / 0.14f)), (punchPower.maxKnockback / 50f) * (rb.mass / 0.5f), (punchPower.maxKnockback / 2.5f) * (rb.mass / 0.5f)), ForceMode2D.Impulse);
                            }

                            else
                            {
                                float damagePercentage = ((Damage * Multipliers.FinalMultiplier) / rb.mass) / 1000f;
                                float knockbackImpulse = (damagePercentage >= 25f) ? punchPower.maxKnockbackImpulse : punchPower.maxKnockbackImpulse * (damagePercentage / 25f);

                                if (damagePercentage > 0.05f) rb.AddForce(forceDir * Mathf.Clamp(Mathf.Abs(knockbackImpulse - knockbackImpulse * 0.01f * (rb.mass / 0.14f)), (punchPower.maxKnockback / 100f) * (rb.mass / 0.5f), (punchPower.maxKnockback / 5f) * (rb.mass / 0.5f)), ForceMode2D.Impulse);

                                if ((damagePercentage / 2f > UnityEngine.Random.Range(0, 100f)) && col.gameObject.GetComponent<DestroyableBehaviour>() && DBPU.PhysAtkCanDestroy == true) col.gameObject.GetComponent<DestroyableBehaviour>().Break();
                            }
                        }

                        Destroy(projectile);
                        yield break;
                    }
                }

                if (t >= 0.75f)
                {
                    float fadeT = (t - 0.75f) / 0.25f;
                    float newAlpha = Mathf.Lerp(1f, 0f, fadeT);
                    Color spriteColor = sr.color;
                    spriteColor.a = newAlpha;
                    sr.color = spriteColor;

                    Gradient newGradient = new Gradient();
                    newGradient.SetKeys(
                        new GradientColorKey[] { new GradientColorKey(sr.color, 0.0f), new GradientColorKey(sr.color, 1.0f) },
                        new GradientAlphaKey[] { new GradientAlphaKey(newAlpha * 0.5f, 0.0f), new GradientAlphaKey(0f, 1.0f) }
                        );
                    trail.colorGradient = newGradient;
                }

                elapsedTime += Time.deltaTime;
                yield return null;
            }

            projectile.transform.position = endPos;
            projectile.transform.rotation = finalRotation;
            Color finalColor = sr.color;
            finalColor.a = 0f;
            sr.color = finalColor;
            Destroy(projectile);
        }

        private IEnumerator ResetMovement(LimbBehaviour targetLimb)
        {
            if (targetLimb == null) yield break;

            if (targetLimb.gameObject.TryGetComponent<Rigidbody2D>(out Rigidbody2D rigidbody))
            {
                if (rigidbody.bodyType == RigidbodyType2D.Static)
                {
                    yield break;
                }
            }

            float duration = 0.2f;
            float elapsed = 0f;

            while (elapsed < duration)
            {
                foreach (var limb in targetLimb.Person.Limbs)
                {
                    Rigidbody2D rb = limb.GetComponent<Rigidbody2D>();
                    if (rb != null && rb.bodyType != RigidbodyType2D.Static) rb.velocity = Vector2.zero;
                }

                elapsed += Time.deltaTime;
                yield return null;
            }
        }

        Vector3 CalculateCubicBezierPoint(float t, Vector3 p0, Vector3 p1, Vector3 p2, Vector3 p3)
        {
            float u = 1 - t;
            float tt = t * t;
            float uu = u * u;
            float uuu = uu * u;
            float ttt = tt * t;

            Vector3 point = uuu * p0;
            point += 3 * uu * t * p1;
            point += 3 * u * tt * p2;
            point += ttt * p3;
            return point;
        }

        float MapToInvertedOutput(float input, float inputMin, float inputMax, float outputMin, float outputMax, float exponent = 0.065f)
        {
            if (input <= inputMin) return outputMax;
            if (input >= inputMax) return outputMin;

            float normalizedInput = (input - inputMin) / (inputMax - inputMin);
            float curveFactor = Mathf.Pow(normalizedInput, exponent);

            float output = (1 - curveFactor) * outputMax + curveFactor * outputMin;

            return Mathf.Max(output, outputMin);
        }
    }

    public class PunchPower : MonoBehaviour
    {
        public MultipliersAndStuffs Multipliers;

        public bool Active = false;
        public float Damage = -1f;
        public float DamageOutput = 1f;
        public float knockbackOutput = 1f;
        public float maxKnockbackImpulse = 520f;
        public bool enableNuclearExplosion = false;
        public float maxKnockback = 150f;

        public bool CanNukeRN = true;

        private PersonBehaviour person;
        private PhysicalBehaviour physicalBehaviour;
        private Rigidbody2D rbSelf;
        private LimbBehaviour selfLimb;
        private bool isResettingMovement = false;
        private bool isTailSegment;
        private float nextHitAllowed;

        const float MeleeImpactStopPercent = 0.5f;
        const float PunchDamageHealthFactor = 0.01f;
        const float HitCooldownSeconds = 0.08f;

        public Dictionary<LimbBehaviour.BodyPart, float> LimbDamageReductions = new Dictionary<LimbBehaviour.BodyPart, float>
        {
            { LimbBehaviour.BodyPart.Arms, 0.5f },
            { LimbBehaviour.BodyPart.Legs, 0.25f }
            };

        void EnsureRefs()
        {
            if (person == null) person = transform.root.GetComponent<PersonBehaviour>();
            if (physicalBehaviour == null) physicalBehaviour = GetComponent<PhysicalBehaviour>();
            if (rbSelf == null) rbSelf = GetComponent<Rigidbody2D>();
            if (selfLimb == null) selfLimb = GetComponent<LimbBehaviour>();
            if (Multipliers == null)
            {
                Multipliers = transform.root.GetComponent<MultipliersAndStuffs>();
                if (Multipliers == null) Multipliers = transform.root.gameObject.AddComponent<MultipliersAndStuffs>();
            }
        }

        void EnsureMeleeDamageCached()
        {
            EnsureRefs();
            if (Damage >= 0f) return;
            Damage = MCP_Utils.ResolveMeleeBaseDamage(person, Multipliers, -1f, PunchDamageHealthFactor);
        }

        void Awake()
        {
            physicalBehaviour = GetComponent<PhysicalBehaviour>();
            rbSelf = GetComponent<Rigidbody2D>();
            selfLimb = GetComponent<LimbBehaviour>();
            isTailSegment = GetComponent<CellMaxTailSegment>() != null;
            person = transform.root.GetComponent<PersonBehaviour>();
            if (!transform.root.gameObject.GetComponent<MultipliersAndStuffs>())
                transform.root.gameObject.AddComponent<MultipliersAndStuffs>();
            Multipliers = transform.root.gameObject.GetComponent<MultipliersAndStuffs>();
        }

        void Start()
        {
            EnsureRefs();
            EnsureMeleeDamageCached();

            if (person != null)
            {
                PowerSetup.EnsureKickPowerComponents(person);
                var powers = transform.root.GetComponent<CharacterPowers>();
                if (powers != null)
                {
                    PowerSetup.RegisterUniversalPhysicalPowers(powers, person);
                    PowerSetup.ApplyAutoEnablePunchKick(person);
                    powers.HarvestPowerStates();
                }
            }
        }

        void OnCollisionEnter2D(Collision2D collision)
        {
            if (!Active || isTailSegment) return;
            EnsureRefs();
            if (person == null || !person.IsAlive() || selfLimb == null || selfLimb.Health <= 0f) return;
            if (collision.transform.gameObject.layer == 11) return;
            if (Multipliers == null || rbSelf == null) return;
            if (Time.time < nextHitAllowed) return;

            float speed = rbSelf.velocity.magnitude;
            if (speed < 5f) return;

            EnsureMeleeDamageCached();
            float meleeDamage = Mathf.Max(0f, Damage);

            var limb = collision.gameObject.GetComponent<LimbBehaviour>();
            if (limb != null)
            {
                if (limb.Person == person) return;
                Rigidbody2D targetRb = collision.gameObject.GetComponent<Rigidbody2D>();
                if (targetRb == null) return;

                nextHitAllowed = Time.time + HitCooldownSeconds;

                float speedMultiplier = Mathf.Clamp(speed, 5f, 25f) / 5f;
                float realDamage = (meleeDamage * Mathf.Max(0.01f, Multipliers.FinalMultiplier)) * DamageOutput * CombatPowerController.OutputFor(person);
                float finalDamage = realDamage * speedMultiplier * DBPU.DamageMultiplier;
                float victimMaxHealth = MCP_Utils.AverageMaxHealth(limb.Person);
                if (victimMaxHealth <= 0f) victimMaxHealth = 1f;
                float damagePercentage = (finalDamage / victimMaxHealth) * 100f;
                float attackerPower = MCP_Utils.AverageMaxHealth(person) / CombatPowerController.KaiokenHealthScale(person) * Multipliers.FinalMultiplier;
                float victimPower = victimMaxHealth / CombatPowerController.KaiokenHealthScale(limb.Person) * MCP_Utils.GetFinalMultiplier(limb.Person);
                float stopAt = MCP_Utils.MeleeStopThreshold(attackerPower, victimPower, MeleeImpactStopPercent);

                if (speed > 15f && finalDamage >= 10000f)
                    CheckSurroundings(targetRb, collision.contacts[0].point, Mathf.Clamp(damagePercentage * 200f, 20f, 100f), finalDamage);

                if (damagePercentage <= stopAt)
                {
                    if (!isResettingMovement && DBPU.PhysAtkStopLimbs) StartCoroutine(ResetMovement(limb));
                    return;
                }

                if (LimbDamageReductions.TryGetValue(limb.RoughClassification, out float reduction))
                    finalDamage *= reduction;

                DamageLimb(limb, finalDamage, collision.contacts[0].point);

                float kbImpulse = maxKnockbackImpulse * knockbackOutput * DBPU.Universal_KnockbackMultiplier;
                float kbCap = maxKnockback * knockbackOutput * DBPU.Universal_KnockbackMultiplier;
                float knockbackImpulse = (damagePercentage >= 25f) ? kbImpulse : kbImpulse * (damagePercentage / 25f);

                if (DBPU.hitParticle != null)
                {
                    GameObject particle = Instantiate(DBPU.hitParticle, collision.contacts[0].point, DBPU.hitParticle.transform.rotation);
                    Vector2 direction = ((Vector2)targetRb.transform.position - (Vector2)transform.position).normalized;
                    particle.transform.rotation = Quaternion.Euler(0, 0, (Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg) - 90f);
                    particle.transform.localScale = new Vector3(Mathf.Clamp(damagePercentage / 500, 0, 0.833332f), Mathf.Clamp(damagePercentage / 500, 0, 0.833332f), 0.5f);

                    foreach (Transform child in particle.transform)
                    {
                        child.localScale = new Vector3(Mathf.Clamp(damagePercentage / 150, 0, 2.777f), Mathf.Clamp(damagePercentage / 150, 0, 2.777f), 0.5f);
                        var ps1renderer = child.gameObject.GetComponent<ParticleSystemRenderer>();
                        if (ps1renderer != null) ps1renderer.sortingLayerName = "Top";
                    }

                    ParticleSystem ps = particle.GetComponent<ParticleSystem>();
                    var psrenderer = particle.GetComponent<ParticleSystemRenderer>();
                    if (psrenderer != null) psrenderer.sortingLayerName = "Top";
                    if (ps != null)
                    {
                        ps.Play();
                        Destroy(particle, ps.main.duration);
                    }
                    else Destroy(particle, 1f);
                }

                if (speed > 15f && realDamage >= 50000000000f && enableNuclearExplosion == true && CanNukeRN == true) NukeShockwave(collision.contacts[0].point);

                Vector2 forceDirection = ((Vector2)targetRb.transform.position - (Vector2)transform.position).normalized;
                targetRb.AddForce(forceDirection * Mathf.Clamp(Mathf.Abs(knockbackImpulse - knockbackImpulse * 0.2f * (targetRb.mass / 0.14f)), 0, kbCap * (targetRb.mass / 0.5f)), ForceMode2D.Impulse);

                if (limb.name == "UpperBody" || limb.name == "MiddleBody")
                {
                    if (damagePercentage > 80f)
                    {
                        var head = limb.transform.root.Find("Head");
                        if (head != null)
                        {
                            var menu = head.GetComponent<TransformationContextMenu>();
                            if (menu != null && menu.Form != menu.BaseForm)
                                menu.TransformationsData.ApplyTransformation(limb.Person, menu.BaseForm, true);
                        }
                    }
                }
                else if (limb.name == "Head")
                {
                    if (damagePercentage > 80f)
                    {
                        var hc = limb.gameObject.GetComponent<HumanController>();
                        if (hc != null)
                        {
                            hc.Features.ForceKnockout = true;
                            hc.ForcedKnockout();
                        }

                        var menu = limb.gameObject.GetComponent<TransformationContextMenu>();
                        if (menu != null && menu.Form != menu.BaseForm)
                            menu.TransformationsData.ApplyTransformation(limb.Person, menu.BaseForm, true);
                    }
                }
                return;
            }

            var targetPhys = collision.gameObject.GetComponent<PhysicalBehaviour>();
            if (targetPhys == null) return;
            Rigidbody2D physRb = collision.gameObject.GetComponent<Rigidbody2D>();
            if (physRb == null) return;

            nextHitAllowed = Time.time + HitCooldownSeconds;

            float objSpeedMultiplier = Mathf.Clamp(speed, 5f, 100f) / 5f;
            float objRealDamage = (meleeDamage * Mathf.Max(0.01f, Multipliers.FinalMultiplier)) * DamageOutput * CombatPowerController.OutputFor(person);
            float objFinalDamage = objRealDamage * objSpeedMultiplier;
            float objDamagePercentage = (objFinalDamage / targetPhys.TrueInitialMass) / 100f;

            if (speed > 15f && objFinalDamage >= 10000f)
                CheckSurroundings(physRb, collision.contacts[0].point, Mathf.Clamp(objDamagePercentage * 200f, 20f, 100f), objFinalDamage);

            if (targetPhys.TrueInitialMass >= objRealDamage / 150f)
            {
                if (!isResettingMovement && DBPU.PhysAtkStopLimbs) StartCoroutine(ResetMovementForObject(targetPhys));
                if (DBPU.PhysAtkStopLimbs) return;
            }

            float objKbImpulse = maxKnockbackImpulse * knockbackOutput * DBPU.Universal_KnockbackMultiplier;
            float objKbCap = maxKnockback * knockbackOutput * DBPU.Universal_KnockbackMultiplier;
            float objKnockbackImpulse = (objDamagePercentage >= 25f) ? objKbImpulse : objKbImpulse * (objDamagePercentage / 25f);

            if (DBPU.hitParticle != null)
            {
                GameObject particle = Instantiate(DBPU.hitParticle, collision.contacts[0].point, DBPU.hitParticle.transform.rotation);
                Vector2 direction = ((Vector2)physRb.transform.position - (Vector2)transform.position).normalized;
                particle.transform.rotation = Quaternion.Euler(0, 0, (Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg) - 90f);
                particle.transform.localScale = new Vector3(Mathf.Clamp(objDamagePercentage / 500, 0, 0.833332f), Mathf.Clamp(objDamagePercentage / 500, 0, 0.833332f), 0.5f);

                foreach (Transform child in particle.transform)
                {
                    child.localScale = new Vector3(Mathf.Clamp(objDamagePercentage / 150, 0, 2.777f), Mathf.Clamp(objDamagePercentage / 150, 0, 2.777f), 0.5f);
                    var ps1renderer = child.gameObject.GetComponent<ParticleSystemRenderer>();
                    if (ps1renderer != null) ps1renderer.sortingLayerName = "Top";
                }

                ParticleSystem ps = particle.GetComponent<ParticleSystem>();
                var psrenderer = particle.GetComponent<ParticleSystemRenderer>();
                if (psrenderer != null) psrenderer.sortingLayerName = "Top";
                if (ps != null)
                {
                    ps.Play();
                    Destroy(particle, ps.main.duration);
                }
                else Destroy(particle, 1f);
            }

            if (speed > 10f && objRealDamage >= 50000000000f && enableNuclearExplosion == true && CanNukeRN == true) NukeShockwave(collision.contacts[0].point);

            Vector2 objForceDirection = ((Vector2)physRb.transform.position - (Vector2)transform.position).normalized;
            physRb.AddForce(objForceDirection * Mathf.Clamp(Mathf.Abs(objKnockbackImpulse - objKnockbackImpulse * 0.01f * (physRb.mass / 0.14f)), 0, objKbCap * (physRb.mass / 0.5f)), ForceMode2D.Impulse);

            if (objDamagePercentage > 0.5f && physRb.gameObject.GetComponent<DestroyableBehaviour>() && speed > 10f && DBPU.PhysAtkCanDestroy == true)
            {
                if (objDamagePercentage / 5f > UnityEngine.Random.Range(0, 1f)) physRb.gameObject.GetComponent<DestroyableBehaviour>().Break();
            }
        }

        public void CheckSurroundings(Rigidbody2D targetRb, Vector2 point, float range, float DamageDealt)
        {
            float cappedRange = range;
            foreach (Collider2D collider2D in Physics2D.OverlapCircleAll(point, 0.5f * cappedRange, MCP_Utils.ObjectsDebrisMask))
            {
                if ((bool)(UnityEngine.Object)collider2D.attachedRigidbody && collider2D.attachedRigidbody.transform.root.gameObject != targetRb.transform.root.gameObject)
                {
                    var targetLimb = collider2D.GetComponent<LimbBehaviour>();
                    if (targetLimb != null && targetLimb.Person != person)
                    {
                        Rigidbody2D newTargetRb = collider2D.attachedRigidbody;

                        float newDamagePercentage = (DamageDealt / targetLimb.InitialHealth) * 100f;
                        float newKnockbackImpulse = (newDamagePercentage >= 25f) ? maxKnockbackImpulse : maxKnockbackImpulse * (newDamagePercentage / 25f);
                        Vector2 newForceDirection = ((Vector2)newTargetRb.transform.position - point).normalized;

                        float rangePercentage = Mathf.Clamp(Vector3.Distance(newTargetRb.transform.position, point) / (0.4f * cappedRange), 0.2f, 1f);
                        rangePercentage /= 50f;

                        if (newDamagePercentage / 20f > 5f)
                        {
                            newTargetRb.AddForce(newForceDirection * Mathf.Clamp(Mathf.Abs(newKnockbackImpulse - newKnockbackImpulse * 0.2f * (newTargetRb.mass / 0.14f)) * rangePercentage, 0, maxKnockback * (newTargetRb.mass / 0.8f)), ForceMode2D.Impulse);
                        }
                    }

                    else if (targetLimb == null && collider2D.gameObject.GetComponent<PhysicalBehaviour>())
                    {
                        var targetPhys = collider2D.gameObject.GetComponent<PhysicalBehaviour>();
                        Rigidbody2D newTargetRb = collider2D.attachedRigidbody;

                        float newDamagePercentage = (DamageDealt / targetPhys.TrueInitialMass) / 100f;
                        float newKnockbackImpulse = (newDamagePercentage >= 25f) ? maxKnockbackImpulse : maxKnockbackImpulse * (newDamagePercentage / 25f);
                        Vector2 newForceDirection = ((Vector2)newTargetRb.transform.position - point).normalized;

                        float rangePercentage = Mathf.Clamp(Vector3.Distance(newTargetRb.transform.position, point) / (0.4f * cappedRange), 0.05f, 1f);
                        rangePercentage /= 5f;

                        if (newDamagePercentage / 20f > 5f)
                        {
                            newTargetRb.AddForce(newForceDirection * Mathf.Clamp(Mathf.Abs(newKnockbackImpulse - newKnockbackImpulse * 0.01f * (newTargetRb.mass / 0.14f)) * rangePercentage, 0, maxKnockback * (newTargetRb.mass / 0.8f)), ForceMode2D.Impulse);
                        }
                    }
                }
            }
        }

        public async void NukeShockwave(Vector2 point)
        {
            NukeCooldown();

            var nuke = Instantiate(ModAPI.FindSpawnable("Atom Bomb").Prefab, point, Quaternion.identity);
            var phys = nuke.gameObject.GetComponent<PhysicalBehaviour>();
            var atom = nuke.gameObject.GetComponent<AtomBombBehaviour>();

            phys.ForceSendUse();
            NewAtomBombExplosionBehaviour[] explosions = GameObject.FindObjectsOfType<NewAtomBombExplosionBehaviour>();

            foreach (var explosion in explosions)
            {
                explosion.VaporisationDistance = 0f;
                var child0 = explosion.transform.GetChild(0);
                var pas = child0.GetComponent<ParticleSystem>();
                pas.Stop();
            }
        }

        public async void NukeCooldown()
        {
            foreach (var limb in person.Limbs)
            {
                if (limb.gameObject.GetComponent<PunchPower>())
                {
                    limb.gameObject.GetComponent<PunchPower>().CanNukeRN = false;
                }
            }

            await Task.Delay(1000);

            foreach (var limb in person.Limbs)
            {
                if (limb.gameObject.GetComponent<PunchPower>())
                {
                    limb.gameObject.GetComponent<PunchPower>().CanNukeRN = true;
                }
            }
        }

        private void DamageLimb(LimbBehaviour limb, float damage, Vector2 hitPoint)
        {
            float damagePercentage = damage / limb.InitialHealth;
            float bluntVisualDamage = (100f * Mathf.Clamp(damagePercentage, 0f, 0.5f)) / limb.SkinMaterialHandler.intensityMultiplier;
            float bulletVisualDamage = (100f * Mathf.Clamp(damagePercentage, 0f, 0.5f)) / limb.SkinMaterialHandler.intensityMultiplier;

            if (damagePercentage > 0.001f)
            {
                limb.Damage(damage);
                limb.SkinMaterialHandler.AddDamagePoint(DamageType.Blunt, hitPoint, bluntVisualDamage);
                limb.SkinMaterialHandler.AddDamagePoint(DamageType.Bullet, hitPoint, bulletVisualDamage);
            }
        }

        static void StopRigidbodyMotion(Rigidbody2D rb)
        {
            if (rb == null || rb.bodyType == RigidbodyType2D.Static) return;
            rb.velocity = Vector2.zero;
            rb.angularVelocity = 0f;
        }

        private IEnumerator ResetMovement(LimbBehaviour targetLimb)
        {
            if (targetLimb == null) yield break;

            Rigidbody2D targetRb = targetLimb.GetComponent<Rigidbody2D>();
            if (targetRb != null && targetRb.bodyType == RigidbodyType2D.Static) yield break;

            isResettingMovement = true;
            float duration = 0.25f;
            float elapsed = 0f;
            while (elapsed < duration)
            {
                StopRigidbodyMotion(rbSelf);
                StopRigidbodyMotion(targetRb);
                elapsed += Time.deltaTime;
                yield return null;
            }
            isResettingMovement = false;
        }

        private IEnumerator ResetMovementForObject(PhysicalBehaviour phys)
        {
            if (phys == null) yield break;

            Rigidbody2D targetRb = phys.GetComponent<Rigidbody2D>();
            if (targetRb != null && targetRb.bodyType == RigidbodyType2D.Static) yield break;

            isResettingMovement = true;
            float duration = 0.25f;
            float elapsed = 0f;
            while (elapsed < duration)
            {
                StopRigidbodyMotion(rbSelf);
                StopRigidbodyMotion(targetRb);
                elapsed += Time.deltaTime;
                yield return null;
            }

            isResettingMovement = false;
        }
    }

    public class KickPower : MonoBehaviour
    {
        public MultipliersAndStuffs Multipliers;

        public bool Active = false;
        public float Damage = -1f;
        public float DamageOutput = 1f;
        public float knockbackOutput = 1f;
        public float maxKnockbackImpulse = 520f;
        public bool enableNuclearExplosion = false;
        public float maxKnockback = 150f;

        public bool CanNukeRN = true;

        const float MeleeImpactStopPercent = 0.5f;
        const float KickDamageHealthFactor = 0.02f;
        const float HitCooldownSeconds = 0.08f;

        private PersonBehaviour person;
        private PhysicalBehaviour physicalBehaviour;
        private Rigidbody2D rbSelf;
        private LimbBehaviour selfLimb;
        private bool isResettingMovement = false;
        private bool isTailSegment;
        private float nextHitAllowed;

        public Dictionary<LimbBehaviour.BodyPart, float> LimbDamageReductions = new Dictionary<LimbBehaviour.BodyPart, float>
        {
            { LimbBehaviour.BodyPart.Arms, 0.5f },
            { LimbBehaviour.BodyPart.Legs, 0.25f }
            };

        void EnsureRefs()
        {
            if (person == null) person = transform.root.GetComponent<PersonBehaviour>();
            if (physicalBehaviour == null) physicalBehaviour = GetComponent<PhysicalBehaviour>();
            if (rbSelf == null) rbSelf = GetComponent<Rigidbody2D>();
            if (selfLimb == null) selfLimb = GetComponent<LimbBehaviour>();
            if (Multipliers == null)
            {
                Multipliers = transform.root.GetComponent<MultipliersAndStuffs>();
                if (Multipliers == null) Multipliers = transform.root.gameObject.AddComponent<MultipliersAndStuffs>();
            }
        }

        void EnsureMeleeDamageCached()
        {
            EnsureRefs();
            if (Damage >= 0f) return;
            Damage = MCP_Utils.ResolveMeleeBaseDamage(person, Multipliers, -1f, KickDamageHealthFactor);
        }

        void Awake()
        {
            physicalBehaviour = GetComponent<PhysicalBehaviour>();
            rbSelf = GetComponent<Rigidbody2D>();
            selfLimb = GetComponent<LimbBehaviour>();
            isTailSegment = GetComponent<CellMaxTailSegment>() != null;
            person = transform.root.GetComponent<PersonBehaviour>();
            if (!transform.root.gameObject.GetComponent<MultipliersAndStuffs>())
                transform.root.gameObject.AddComponent<MultipliersAndStuffs>();
            Multipliers = transform.root.gameObject.GetComponent<MultipliersAndStuffs>();
        }

        void Start()
        {
            EnsureRefs();
            EnsureMeleeDamageCached();
        }

