            new Color32(0x24, 0x00, 0x04, 255)
        };

        static readonly Color32[] MarkerTailFireExact =
        {
            new Color32(0x03, 0x04, 0x05, 255),
            new Color32(0x02, 0x04, 0x05, 255),
            new Color32(0x04, 0x04, 0x05, 255),
            new Color32(0x03, 0x03, 0x05, 255),
            new Color32(0x03, 0x05, 0x05, 255),
            new Color32(0x03, 0x04, 0x04, 255),
            new Color32(0x03, 0x04, 0x06, 255)
        };

        static readonly Color32 MarkerEyeLaserExact = new Color32(0x93, 0x42, 0x44, 255);
        static readonly Color32 MarkerPiccoloEyeExact = new Color32(0, 0, 0, 255);

        public enum EyeLaserMarkerMode { CellMax, Piccolo }

        const int SpotRoleNone = -1;
        const int SpotRoleGlowOnly = 0;
        const int SpotRoleFire = 1;
        const int GreenMatchTolerance = 6;
        const int RedMatchTolerance = 8;
        const int TailFireMatchTolerance = 4;
        const int PurpleMatchTolerance = 6;
        const int EyeLaserMatchTolerance = 4;

        static readonly Color GlowPurple = new Color(0.72f, 0.28f, 1f, 1f);
        static readonly Color GlowPurpleAlt = new Color(0.85f, 0.45f, 1f, 1f);
        static readonly Color PiccoloEyeGlow = new Color(1f, 0.92f, 0.25f, 1f);
        static readonly Color PiccoloEyeGlowAlt = new Color(1f, 0.98f, 0.45f, 1f);

        public int LimbSkinIndex = 1;
        public bool IsTail;
        public bool IsLeg;
        public bool DynamicSpriteRefresh;
        public bool ScanEyeLaserMarkers;
        public EyeLaserMarkerMode EyeLaserMarker = EyeLaserMarkerMode.CellMax;
        public bool GenericFallback;
        public bool SkipEyeGlowOverlay;
        public Color EyeGlowColor = GlowPurple;
        public Color EyeGlowAltColor = GlowPurpleAlt;

        SpriteRenderer limbRenderer;
        SpriteRenderer overlayRenderer;
        SpriteRenderer eyeOverlayRenderer;
        Sprite lastScannedSprite;
        Vector2[] fireEmissionPoints;
        Vector2[] eyeLaserEmissionPoints;
        float glowTarget;
        float glow01;
        float eyeGlowTarget;
        float eyeGlow01;
        float pulseSpeed = 6f;
        bool pulseWhileActive;
        bool eyePulseWhileActive;

        public bool HasSpots => overlayRenderer != null;
        public bool HasFireSpots => fireEmissionPoints != null && fireEmissionPoints.Length > 0;
        public bool HasEyeLaserSpots => eyeLaserEmissionPoints != null && eyeLaserEmissionPoints.Length > 0;

        public Vector2[] GetEyeLaserEmissionLocals() => eyeLaserEmissionPoints ?? new Vector2[0];

        public void Initialize()
        {
            limbRenderer = GetComponent<SpriteRenderer>();
            if (limbRenderer == null || limbRenderer.sprite == null) return;

            var limb = GetComponent<LimbBehaviour>();
            IsLeg = !IsTail && limb != null && limb.RoughClassification == LimbBehaviour.BodyPart.Legs;

            RebuildSpotData(true);
        }

        public void RefreshFromCurrentSprite()
        {
            if (limbRenderer == null) limbRenderer = GetComponent<SpriteRenderer>();
            if (limbRenderer == null || limbRenderer.sprite == null) return;
            if (lastScannedSprite == limbRenderer.sprite) return;
            RebuildSpotData(false);
        }

        public void ForceRefreshFromCurrentSprite()
        {
            if (limbRenderer == null) limbRenderer = GetComponent<SpriteRenderer>();
            if (limbRenderer == null || limbRenderer.sprite == null) return;
            RebuildSpotData(false);
        }

        void RebuildSpotData(bool fullInit)
        {
            Sprite sprite = limbRenderer.sprite;
            lastScannedSprite = sprite;

            float prevGlow = glow01;
            float prevTarget = glowTarget;
            bool prevPulse = pulseWhileActive;
            float prevEyeGlow = eyeGlow01;
            float prevEyeTarget = eyeGlowTarget;
            bool prevEyePulse = eyePulseWhileActive;

            ClearOverlay();
            ClearEyeOverlay();

            var fireLocals = new List<Vector2>(32);
            var overlayPx = new Color32[0];
            int overlayW = 0;
            int overlayH = 0;
            bool foundAnySpot = false;

            if (DynamicSpriteRefresh)
            {
                TryScanTexture(sprite, GetReadableTexture(sprite), ref fireLocals, ref overlayPx, ref overlayW, ref overlayH, ref foundAnySpot);
            }
            else
            {
                if (fullInit)
                    ScanLoadedLimbTextures(sprite, ref fireLocals, ref overlayPx, ref overlayW, ref overlayH, ref foundAnySpot);

                Material mat = limbRenderer.material;
                if (mat != null)
                {
                    if (mat.HasProperty("_FleshTex"))
                        TryScanTexture(sprite, mat.GetTexture("_FleshTex") as Texture2D, ref fireLocals, ref overlayPx, ref overlayW, ref overlayH, ref foundAnySpot);
                    if (mat.HasProperty("_BoneTex"))
                        TryScanTexture(sprite, mat.GetTexture("_BoneTex") as Texture2D, ref fireLocals, ref overlayPx, ref overlayW, ref overlayH, ref foundAnySpot);
                    if (mat.HasProperty("_DamageTex"))
                        TryScanTexture(sprite, mat.GetTexture("_DamageTex") as Texture2D, ref fireLocals, ref overlayPx, ref overlayW, ref overlayH, ref foundAnySpot);
                }

                TryScanTexture(sprite, GetReadableTexture(sprite), ref fireLocals, ref overlayPx, ref overlayW, ref overlayH, ref foundAnySpot);
            }

            var eyeLaserLocals = new List<Vector2>();
            if (ScanEyeLaserMarkers)
            {
                ScanEyeLaserSources(sprite, eyeLaserLocals);
                if (!SkipEyeGlowOverlay)
                {
                    var eyeOverlayPx = new Color32[0];
                    int eyeOverlayW = 0;
                    int eyeOverlayH = 0;
                    ScanEyeLaserOverlay(sprite, ref eyeOverlayPx, ref eyeOverlayW, ref eyeOverlayH);
                    if (eyeOverlayW > 0 && eyeOverlayPx != null && eyeOverlayPx.Length > 0)
                        CreateEyeOverlay(sprite, eyeOverlayPx, eyeOverlayW, eyeOverlayH);
                }
            }

            if (ScanEyeLaserMarkers && EyeLaserMarker == EyeLaserMarkerMode.Piccolo && eyeLaserLocals.Count == 0 && sprite != null)
                eyeLaserLocals.Add(GetPiccoloEyeFallbackLocal(sprite));

            eyeLaserEmissionPoints = ScanEyeLaserMarkers && eyeLaserLocals.Count > 0
                ? BuildEyeLaserClusters(eyeLaserLocals, EyeLaserMarker == EyeLaserMarkerMode.Piccolo ? 0.05f : 0.22f)
                : new Vector2[0];

            if (ScanEyeLaserMarkers && EyeLaserMarker == EyeLaserMarkerMode.Piccolo && !SkipEyeGlowOverlay
                && eyeOverlayRenderer == null && eyeLaserEmissionPoints.Length > 0 && sprite != null)
                BuildFallbackOverlay(sprite, eyeLaserEmissionPoints, true);

            if (foundAnySpot)
            {
                fireEmissionPoints = fireLocals.ToArray();
                CreateOverlay(sprite, overlayPx, overlayW, overlayH);
            }
            else
            {
                fireEmissionPoints = new Vector2[0];
            }

            if (GenericFallback)
                ApplyGenericFallbacks(sprite, ref foundAnySpot);

            glow01 = prevGlow;
            glowTarget = prevTarget;
            pulseWhileActive = prevPulse;
            eyeGlow01 = prevEyeGlow;
            eyeGlowTarget = prevEyeTarget;
            eyePulseWhileActive = prevEyePulse;
        }

        void ClearOverlay()
        {
            if (overlayRenderer != null)
            {
                Destroy(overlayRenderer.gameObject);
                overlayRenderer = null;
            }
        }

        void ClearEyeOverlay()
        {
            if (eyeOverlayRenderer != null)
            {
                Destroy(eyeOverlayRenderer.gameObject);
                eyeOverlayRenderer = null;
            }
        }

        void CreateOverlay(Sprite sprite, Color32[] overlayPx, int overlayW, int overlayH)
        {
            ClearOverlay();

            var overlayTex = new Texture2D(overlayW, overlayH, TextureFormat.RGBA32, false);
            overlayTex.filterMode = FilterMode.Point;
            overlayTex.wrapMode = TextureWrapMode.Clamp;
            overlayTex.SetPixels32(overlayPx);
            overlayTex.Apply(false, false);

            Sprite overlaySprite = Sprite.Create(
                overlayTex,
                new Rect(0, 0, overlayW, overlayH),
                new Vector2(sprite.pivot.x / sprite.rect.width, sprite.pivot.y / sprite.rect.height),
                sprite.pixelsPerUnit,
                0,
                SpriteMeshType.FullRect,
                sprite.border);

            Material bright = ModAPI.FindMaterial("VeryBright");
            var go = new GameObject("CellMaxSpotGlow");
            go.transform.SetParent(transform, false);
            go.transform.localPosition = new Vector3(0f, 0f, -0.02f);
            go.transform.localRotation = Quaternion.identity;
            go.transform.localScale = Vector3.one;

            overlayRenderer = go.AddComponent<SpriteRenderer>();
            overlayRenderer.sprite = overlaySprite;
            overlayRenderer.material = bright != null ? bright : limbRenderer.sharedMaterial;
            overlayRenderer.sortingLayerName = limbRenderer.sortingLayerName;
            overlayRenderer.sortingOrder = limbRenderer.sortingOrder + 12;
            overlayRenderer.color = new Color(GlowPurple.r, GlowPurple.g, GlowPurple.b, glow01);
        }

        void CreateEyeOverlay(Sprite sprite, Color32[] overlayPx, int overlayW, int overlayH)
        {
            ClearEyeOverlay();

            var overlayTex = new Texture2D(overlayW, overlayH, TextureFormat.RGBA32, false);
            overlayTex.filterMode = FilterMode.Point;
            overlayTex.wrapMode = TextureWrapMode.Clamp;
            overlayTex.SetPixels32(overlayPx);
            overlayTex.Apply(false, false);

            Sprite overlaySprite = Sprite.Create(
                overlayTex,
                new Rect(0, 0, overlayW, overlayH),
                new Vector2(sprite.pivot.x / sprite.rect.width, sprite.pivot.y / sprite.rect.height),
                sprite.pixelsPerUnit,
                0,
                SpriteMeshType.FullRect,
                sprite.border);

            Material bright = ModAPI.FindMaterial("VeryBright");
            var go = new GameObject("CellMaxEyeGlow");
            go.transform.SetParent(transform, false);
            go.transform.localPosition = new Vector3(0f, 0f, -0.015f);
            go.transform.localRotation = Quaternion.identity;
            go.transform.localScale = Vector3.one;

            eyeOverlayRenderer = go.AddComponent<SpriteRenderer>();
            eyeOverlayRenderer.sprite = overlaySprite;
            eyeOverlayRenderer.material = bright != null ? bright : limbRenderer.sharedMaterial;
            eyeOverlayRenderer.sortingLayerName = limbRenderer.sortingLayerName;
            eyeOverlayRenderer.sortingOrder = limbRenderer.sortingOrder + 13;
            eyeOverlayRenderer.color = new Color(EyeGlowColor.r, EyeGlowColor.g, EyeGlowColor.b, eyeGlow01);
        }

        void ApplyGenericFallbacks(Sprite sprite, ref bool foundAnySpot)
        {
            if (sprite == null) return;

            if (ScanEyeLaserMarkers)
            {
                if (eyeLaserEmissionPoints == null || eyeLaserEmissionPoints.Length == 0)
                {
                    Bounds b = sprite.bounds;
                    float y = b.center.y + b.extents.y * 0.12f;
                    eyeLaserEmissionPoints = new Vector2[]
                    {
                        new Vector2(b.center.x - b.extents.x * 0.2f, y),
                        new Vector2(b.center.x + b.extents.x * 0.2f, y)
                    };
                    if (!SkipEyeGlowOverlay)
                        BuildFallbackOverlay(sprite, eyeLaserEmissionPoints, true);
                }
                return;
            }

            if (fireEmissionPoints == null || fireEmissionPoints.Length == 0)
            {
                if (overlayRenderer != null)
                {
                    fireEmissionPoints = new Vector2[0];
                    return;
                }

                fireEmissionPoints = new Vector2[] { sprite.bounds.center };
                BuildFallbackOverlay(sprite, fireEmissionPoints, false);
                foundAnySpot = true;
            }
        }

        void BuildFallbackOverlay(Sprite sprite, Vector2[] localPoints, bool forEyes)
        {
            if (localPoints == null || localPoints.Length == 0) return;

            Rect rect = sprite.rect;
            int w = Mathf.RoundToInt(rect.width);
            int h = Mathf.RoundToInt(rect.height);
            if (w <= 0 || h <= 0) return;

            var px = new Color32[w * h];
            Color32 glow32 = (Color32)EyeGlowAltColor;
            glow32.a = 255;
            Bounds bounds = sprite.bounds;

            for (int i = 0; i < localPoints.Length; i++)
            {
                float u = bounds.size.x > 0.0001f ? (localPoints[i].x - bounds.min.x) / bounds.size.x : 0.5f;
                float v = bounds.size.y > 0.0001f ? (localPoints[i].y - bounds.min.y) / bounds.size.y : 0.5f;
                int pxX = Mathf.Clamp(Mathf.RoundToInt(u * w), 0, w - 1);
                int pxY = Mathf.Clamp(Mathf.RoundToInt(v * h), 0, h - 1);

                for (int dy = -1; dy <= 1; dy++)
                {
                    for (int dx = -1; dx <= 1; dx++)
                    {
                        int x = pxX + dx;
                        int y = pxY + dy;
                        if (x < 0 || x >= w || y < 0 || y >= h) continue;
                        px[y * w + x] = glow32;
                    }
                }
            }

            if (forEyes)
                CreateEyeOverlay(sprite, px, w, h);
            else
                CreateOverlay(sprite, px, w, h);
        }

        void ScanLoadedLimbTextures(Sprite sprite, ref List<Vector2> fireLocals, ref Color32[] overlayPx, ref int overlayW, ref int overlayH, ref bool foundAnySpot)
        {
            if (LimbSkinIndex < 1) return;
            string folder = "Assets/Sprites/Characters/Cell Max/CellMaxCreatureSprites/";
            string idx = LimbSkinIndex.ToString();
            TryScanLoaded(sprite, folder + "LimbSpriteSkin" + idx + ".png", ref fireLocals, ref overlayPx, ref overlayW, ref overlayH, ref foundAnySpot);
            TryScanLoaded(sprite, folder + "LimbSpriteFlesh" + idx + ".png", ref fireLocals, ref overlayPx, ref overlayW, ref overlayH, ref foundAnySpot);
            TryScanLoaded(sprite, folder + "LimbSpriteBone" + idx + ".png", ref fireLocals, ref overlayPx, ref overlayW, ref overlayH, ref foundAnySpot);
            TryScanLoaded(sprite, folder + "LimbSpriteDamage" + idx + ".png", ref fireLocals, ref overlayPx, ref overlayW, ref overlayH, ref foundAnySpot);
        }

        void TryScanLoaded(Sprite sprite, string path, ref List<Vector2> fireLocals, ref Color32[] overlayPx, ref int overlayW, ref int overlayH, ref bool foundAnySpot)
        {
            try
            {
                Sprite loaded = ModAPI.LoadSprite(path);
                if (loaded != null && loaded.texture != null)
                {
                    Sprite layout = loaded;
                    if (Mathf.RoundToInt(loaded.rect.width) == Mathf.RoundToInt(sprite.rect.width)
                        && Mathf.RoundToInt(loaded.rect.height) == Mathf.RoundToInt(sprite.rect.height))
                        layout = sprite;
                    TryScanTexture(layout, loaded.texture, ref fireLocals, ref overlayPx, ref overlayW, ref overlayH, ref foundAnySpot);
                }
            }
            catch
            {
            }
        }

        void TryScanTexture(Sprite sprite, Texture2D source, ref List<Vector2> fireLocals, ref Color32[] overlayPx, ref int overlayW, ref int overlayH, ref bool foundAnySpot)
        {
            Texture2D readable = DuplicateTexture(source);
            if (readable != null)
                ScanSprite(sprite, readable, ref fireLocals, ref overlayPx, ref overlayW, ref overlayH, ref foundAnySpot);
        }

        void ScanSprite(Sprite sprite, Texture2D source, ref List<Vector2> fireLocals, ref Color32[] overlayPx, ref int overlayW, ref int overlayH, ref bool foundAnySpot)
        {
            if (sprite == null || source == null) return;

            Rect rect = sprite.rect;
            int texW = source.width;
            int texH = source.height;
            int x0 = Mathf.RoundToInt(rect.x);
            int y0 = Mathf.RoundToInt(rect.y);
            int w = Mathf.RoundToInt(rect.width);
            int h = Mathf.RoundToInt(rect.height);
            Color32[] all = source.GetPixels32();

            if (overlayW != w || overlayH != h || overlayPx == null || overlayPx.Length != w * h)
            {
                overlayW = w;
                overlayH = h;
                overlayPx = new Color32[w * h];
            }

            for (int y = 0; y < h; y++)
            {
                for (int x = 0; x < w; x++)
                {
                    int srcIdx = (y0 + y) * texW + (x0 + x);
                    if (srcIdx < 0 || srcIdx >= all.Length) continue;

                    int role = ClassifySpotRole(all[srcIdx]);
                    if (role == SpotRoleNone) continue;

                    foundAnySpot = true;
                    Color32 glow32 = (Color32)GlowPurpleAlt;
                    glow32.a = 255;
                    overlayPx[y * w + x] = glow32;

                    if (role == SpotRoleFire)
                    {
                        float px = x0 + x + 0.5f;
                        float py = y0 + y + 0.5f;
                        fireLocals.Add(PixelToSpriteLocal(sprite, px, py));
                    }
                }
            }
        }

        public void SetGlowLevel(float level, bool pulse = false)
        {
            glowTarget = Mathf.Clamp01(level);
            pulseWhileActive = pulse;
            if (glowTarget <= 0f) pulseWhileActive = false;
        }

        public void FadeOut()
        {
            glowTarget = 0f;
            pulseWhileActive = false;
        }

        public void SetEyeGlowLevel(float level, bool pulse = false)
        {
            eyeGlowTarget = Mathf.Clamp01(level);
            eyePulseWhileActive = pulse;
            if (eyeGlowTarget <= 0f) eyePulseWhileActive = false;
        }

        public void FadeOutEyeGlow()
        {
            eyeGlowTarget = 0f;
            eyePulseWhileActive = false;
        }

        public void ApplyPiccoloEyeGlowColors()
        {
            EyeGlowColor = PiccoloEyeGlow;
            EyeGlowAltColor = PiccoloEyeGlowAlt;
        }

        public Vector2 GetRandomFireEmissionLocal()
        {
            if (!HasFireSpots)
                return Vector2.zero;
            return fireEmissionPoints[UnityEngine.Random.Range(0, fireEmissionPoints.Length)];
        }

        void ScanEyeLaserSources(Sprite sprite, List<Vector2> eyeLocals)
        {
            if (DynamicSpriteRefresh)
            {
                CollectEyeLaserFromTexture(sprite, GetReadableTexture(sprite), eyeLocals);
                return;
            }

            if (LimbSkinIndex >= 1)
            {
                string folder = "Assets/Sprites/Characters/Cell Max/CellMaxCreatureSprites/";
                string idx = LimbSkinIndex.ToString();
                TryCollectEyeLaserLoaded(sprite, folder + "LimbSpriteSkin" + idx + ".png", eyeLocals);
                TryCollectEyeLaserLoaded(sprite, folder + "LimbSpriteFlesh" + idx + ".png", eyeLocals);
                TryCollectEyeLaserLoaded(sprite, folder + "LimbSpriteBone" + idx + ".png", eyeLocals);
                TryCollectEyeLaserLoaded(sprite, folder + "LimbSpriteDamage" + idx + ".png", eyeLocals);
            }

            Material mat = limbRenderer.material;
            if (mat != null)
            {
                if (mat.HasProperty("_FleshTex"))
                    CollectEyeLaserFromTexture(sprite, mat.GetTexture("_FleshTex") as Texture2D, eyeLocals);
                if (mat.HasProperty("_BoneTex"))
                    CollectEyeLaserFromTexture(sprite, mat.GetTexture("_BoneTex") as Texture2D, eyeLocals);
                if (mat.HasProperty("_DamageTex"))
                    CollectEyeLaserFromTexture(sprite, mat.GetTexture("_DamageTex") as Texture2D, eyeLocals);
            }

            CollectEyeLaserFromTexture(sprite, GetReadableTexture(sprite), eyeLocals);
        }

        void ScanEyeLaserOverlay(Sprite sprite, ref Color32[] overlayPx, ref int overlayW, ref int overlayH)
        {
            if (DynamicSpriteRefresh)
            {
                CollectEyeLaserOverlayFromTexture(sprite, GetReadableTexture(sprite), ref overlayPx, ref overlayW, ref overlayH);
                return;
            }

            if (LimbSkinIndex >= 1)
            {
                string folder = "Assets/Sprites/Characters/Cell Max/CellMaxCreatureSprites/";
                string idx = LimbSkinIndex.ToString();
                TryCollectEyeLaserOverlayLoaded(sprite, folder + "LimbSpriteSkin" + idx + ".png", ref overlayPx, ref overlayW, ref overlayH);
                TryCollectEyeLaserOverlayLoaded(sprite, folder + "LimbSpriteFlesh" + idx + ".png", ref overlayPx, ref overlayW, ref overlayH);
                TryCollectEyeLaserOverlayLoaded(sprite, folder + "LimbSpriteBone" + idx + ".png", ref overlayPx, ref overlayW, ref overlayH);
                TryCollectEyeLaserOverlayLoaded(sprite, folder + "LimbSpriteDamage" + idx + ".png", ref overlayPx, ref overlayW, ref overlayH);
            }

            Material mat = limbRenderer.material;
            if (mat != null)
            {
                if (mat.HasProperty("_FleshTex"))
                    CollectEyeLaserOverlayFromTexture(sprite, mat.GetTexture("_FleshTex") as Texture2D, ref overlayPx, ref overlayW, ref overlayH);
                if (mat.HasProperty("_BoneTex"))
                    CollectEyeLaserOverlayFromTexture(sprite, mat.GetTexture("_BoneTex") as Texture2D, ref overlayPx, ref overlayW, ref overlayH);
                if (mat.HasProperty("_DamageTex"))
                    CollectEyeLaserOverlayFromTexture(sprite, mat.GetTexture("_DamageTex") as Texture2D, ref overlayPx, ref overlayW, ref overlayH);
            }

            CollectEyeLaserOverlayFromTexture(sprite, GetReadableTexture(sprite), ref overlayPx, ref overlayW, ref overlayH);
        }

        void TryCollectEyeLaserOverlayLoaded(Sprite sprite, string path, ref Color32[] overlayPx, ref int overlayW, ref int overlayH)
        {
            try
            {
                Sprite loaded = ModAPI.LoadSprite(path);
                if (loaded != null && loaded.texture != null)
                {
                    Sprite layout = loaded;
                    if (Mathf.RoundToInt(loaded.rect.width) == Mathf.RoundToInt(sprite.rect.width)
                        && Mathf.RoundToInt(loaded.rect.height) == Mathf.RoundToInt(sprite.rect.height))
                        layout = sprite;
                    CollectEyeLaserOverlayFromTexture(layout, loaded.texture, ref overlayPx, ref overlayW, ref overlayH);
                }
            }
            catch
            {
            }
        }

        void CollectEyeLaserOverlayFromTexture(Sprite sprite, Texture2D source, ref Color32[] overlayPx, ref int overlayW, ref int overlayH)
        {
            if (sprite == null || source == null) return;

            Texture2D readable = DuplicateTexture(source);
            if (readable == null) return;

            Rect rect = sprite.rect;
            int texW = source.width;
            int texH = source.height;
            int x0 = Mathf.RoundToInt(rect.x);
            int y0 = Mathf.RoundToInt(rect.y);
            int w = Mathf.RoundToInt(rect.width);
            int h = Mathf.RoundToInt(rect.height);
            Color32[] all = readable.GetPixels32();

            if (overlayW != w || overlayH != h || overlayPx == null || overlayPx.Length != w * h)
            {
                overlayW = w;
                overlayH = h;
                overlayPx = new Color32[w * h];
            }

            Color32 glow32 = (Color32)EyeGlowAltColor;
            glow32.a = 255;

            for (int y = 0; y < h; y++)
            {
                for (int x = 0; x < w; x++)
                {
                    int srcIdx = (y0 + y) * texW + (x0 + x);
                    if (srcIdx < 0 || srcIdx >= all.Length) continue;
                    if (!MatchesEyeLaser(all[srcIdx])) continue;
                    overlayPx[y * w + x] = glow32;
                }
            }
        }

        void TryCollectEyeLaserLoaded(Sprite sprite, string path, List<Vector2> eyeLocals)
        {
            try
            {
                Sprite loaded = ModAPI.LoadSprite(path);
                if (loaded != null && loaded.texture != null)
                {
                    Sprite layout = loaded;
                    if (Mathf.RoundToInt(loaded.rect.width) == Mathf.RoundToInt(sprite.rect.width)
                        && Mathf.RoundToInt(loaded.rect.height) == Mathf.RoundToInt(sprite.rect.height))
                        layout = sprite;
                    CollectEyeLaserFromTexture(layout, loaded.texture, eyeLocals);
                }
            }
            catch
            {
            }
        }

        void CollectEyeLaserFromTexture(Sprite sprite, Texture2D source, List<Vector2> eyeLocals)
        {
            if (sprite == null || source == null) return;

            Texture2D readable = DuplicateTexture(source);
            if (readable == null) return;

            Rect rect = sprite.rect;
            int texW = source.width;
            int texH = source.height;
            int x0 = Mathf.RoundToInt(rect.x);
            int y0 = Mathf.RoundToInt(rect.y);
            int w = Mathf.RoundToInt(rect.width);
            int h = Mathf.RoundToInt(rect.height);
            Color32[] all = readable.GetPixels32();

            for (int y = 0; y < h; y++)
            {
                for (int x = 0; x < w; x++)
                {
                    int srcIdx = (y0 + y) * texW + (x0 + x);
                    if (srcIdx < 0 || srcIdx >= all.Length) continue;
                    if (!MatchesEyeLaser(all[srcIdx])) continue;
                    eyeLocals.Add(PixelToSpriteLocal(sprite, x0 + x + 0.5f, y0 + y + 0.5f));
                }
            }
        }

        bool MatchesEyeLaser(Color32 p)
        {
            if (p.a < 25) return false;
            if (EyeLaserMarker == EyeLaserMarkerMode.Piccolo)
                return p.r == MarkerPiccoloEyeExact.r && p.g == MarkerPiccoloEyeExact.g && p.b == MarkerPiccoloEyeExact.b;
            return Mathf.Abs(p.r - MarkerEyeLaserExact.r) <= EyeLaserMatchTolerance
                && Mathf.Abs(p.g - MarkerEyeLaserExact.g) <= EyeLaserMatchTolerance
                && Mathf.Abs(p.b - MarkerEyeLaserExact.b) <= EyeLaserMatchTolerance;
        }

        static Vector2 GetPiccoloEyeFallbackLocal(Sprite sprite)
        {
            Rect rect = sprite.rect;
            return PixelToSpriteLocal(sprite, rect.x + 8.5f, rect.y + 5.5f);
        }

        static Vector2[] BuildEyeLaserClusters(List<Vector2> points, float mergeRadius)
        {
            if (points == null || points.Count == 0) return new Vector2[0];

            var groups = new List<List<Vector2>>();
            float mergeRadiusSq = mergeRadius * mergeRadius;
            for (int i = 0; i < points.Count; i++)
            {
                Vector2 p = points[i];
                int best = -1;
                float bestDist = mergeRadiusSq;
                for (int g = 0; g < groups.Count; g++)
                {
                    Vector2 center = AveragePointList(groups[g]);
                    float dist = (p - center).sqrMagnitude;
                    if (dist <= bestDist)
                    {
                        best = g;
                        bestDist = dist;
                    }
                }

                if (best < 0)
                    groups.Add(new List<Vector2> { p });
                else
                    groups[best].Add(p);
            }

            var result = new Vector2[groups.Count];
            for (int i = 0; i < groups.Count; i++)
                result[i] = AveragePointList(groups[i]);
            return result;
        }

        static Vector2 AveragePointList(List<Vector2> points)
        {
            Vector2 sum = Vector2.zero;
            for (int i = 0; i < points.Count; i++)
                sum += points[i];
            return sum / points.Count;
        }

        void Update()
        {
            if (overlayRenderer != null)
            {
                float fadeSpeed = glowTarget > glow01 ? 2.5f : 5f;
                glow01 = Mathf.MoveTowards(glow01, glowTarget, Time.deltaTime * fadeSpeed);
                float pulse = pulseWhileActive && glow01 > 0.05f
                    ? 0.65f + 0.35f * Mathf.Sin(Time.time * pulseSpeed)
                    : glow01 > 0.05f ? 0.85f : 0f;
                float a = glow01 * pulse;
                overlayRenderer.color = new Color(GlowPurple.r, GlowPurple.g, GlowPurple.b, a);
            }

            if (eyeOverlayRenderer != null)
            {
                float fadeSpeed = eyeGlowTarget > eyeGlow01 ? 2.5f : 5f;
                eyeGlow01 = Mathf.MoveTowards(eyeGlow01, eyeGlowTarget, Time.deltaTime * fadeSpeed);
                float pulse = eyePulseWhileActive && eyeGlow01 > 0.05f
                    ? 0.65f + 0.35f * Mathf.Sin(Time.time * pulseSpeed)
                    : eyeGlow01 > 0.05f ? 0.85f : 0f;
                float a = eyeGlow01 * pulse;
                eyeOverlayRenderer.color = new Color(EyeGlowColor.r, EyeGlowColor.g, EyeGlowColor.b, a);
            }
        }

        void OnDestroy()
        {
            ClearOverlay();
            ClearEyeOverlay();
        }

        int ClassifySpotRole(Color32 p)
        {
            if (p.a < 25) return SpotRoleNone;

            if (MatchesTailFire(p))
                return SpotRoleFire;

            if (!MatchesAnySpot(p))
                return SpotRoleNone;

            return IsTail ? SpotRoleGlowOnly : SpotRoleFire;
        }

        static bool MatchesTailFire(Color32 p)
        {
            if (MatchesAnyExact(p, MarkerTailFireExact))
                return true;
            return MatchesAnyTolerance(p, MarkerTailFireExact, TailFireMatchTolerance);
        }

        static bool MatchesAnySpot(Color32 p)
        {
            if (MatchesAnyExact(p, MarkerGreenExact))
                return true;
            if (MatchesAnyExact(p, MarkerRedExact))
                return true;
            if (MatchesAnyTolerance(p, MarkerGreenExact, GreenMatchTolerance))
                return true;
            if (MatchesAnyTolerance(p, MarkerRedExact, RedMatchTolerance))
                return true;
            if (MatchesAnyExact(p, MarkerTailFireExact))
                return true;
            if (MatchesAnyTolerance(p, MarkerTailFireExact, TailFireMatchTolerance))
                return true;

            if (Mathf.Abs(p.r - 0x27) <= GreenMatchTolerance
                && Mathf.Abs(p.g - 0x30) <= GreenMatchTolerance
                && Mathf.Abs(p.b - 0x17) <= GreenMatchTolerance)
                return true;

            if (Mathf.Abs(p.r - 0x2e) <= RedMatchTolerance
                && p.g <= RedMatchTolerance + 2
                && p.b <= RedMatchTolerance + 4)
                return true;

            if (Mathf.Abs(p.r - 0x44) <= PurpleMatchTolerance
                && Mathf.Abs(p.g - 0x05) <= PurpleMatchTolerance
                && Mathf.Abs(p.b - 0x10) <= PurpleMatchTolerance)
                return true;

            if (MatchesRedHeuristic(p))
                return true;

            return false;
        }

        static bool MatchesAnyExact(Color32 p, Color32[] markers)
        {
            for (int i = 0; i < markers.Length; i++)
            {
                Color32 m = markers[i];
                if (p.r == m.r && p.g == m.g && p.b == m.b)
                    return true;
            }
            return false;
        }

        static bool MatchesAnyTolerance(Color32 p, Color32[] markers, int tolerance)
        {
            for (int i = 0; i < markers.Length; i++)
            {
                Color32 m = markers[i];
                if (Mathf.Abs(p.r - m.r) <= tolerance
                    && Mathf.Abs(p.g - m.g) <= tolerance
                    && Mathf.Abs(p.b - m.b) <= tolerance)
                    return true;
            }
            return false;
        }

        static bool MatchesRedHeuristic(Color32 p)
        {
            if (p.r >= 18 && p.r <= 58 && p.g <= RedMatchTolerance + 2 && p.b <= RedMatchTolerance + 4)
            {
                if (p.r > p.g + 8 && p.r > p.b + 8)
                    return true;
            }

            if (p.g >= 18 && p.g <= 48 && p.r <= RedMatchTolerance && p.b <= RedMatchTolerance)
            {
                if (p.g > p.r + 8 && p.g > p.b + 8)
                    return true;
            }

            if (p.b >= 18 && p.b <= 48 && p.r <= RedMatchTolerance && p.g <= RedMatchTolerance)
            {
                if (p.b > p.r + 8 && p.b > p.g + 8)
                    return true;
            }

            return false;
        }

        static Texture2D DuplicateTexture(Texture2D source)
        {
            if (source == null) return null;
            try
            {
                var copy = new Texture2D(source.width, source.height, TextureFormat.RGBA32, false);
                copy.filterMode = FilterMode.Point;
                copy.wrapMode = source.wrapMode;
                copy.SetPixels32(source.GetPixels32());
                copy.Apply(false, false);
                return copy;
            }
            catch
            {
                return null;
            }
        }

        static Texture2D GetReadableTexture(Sprite sprite)
        {
            if (sprite == null || sprite.texture == null) return null;
            return DuplicateTexture(sprite.texture);
        }

        static Vector2 PixelToSpriteLocal(Sprite sprite, float pixelX, float pixelY)
        {
            Rect rect = sprite.rect;
            Bounds bounds = sprite.bounds;
            float u = (pixelX - rect.x) / rect.width;
            float v = (pixelY - rect.y) / rect.height;
            return new Vector2(
                Mathf.Lerp(bounds.min.x, bounds.max.x, u),
                Mathf.Lerp(bounds.min.y, bounds.max.y, v));
        }
    }

    public class CellMaxDisasterRayBehaviour : MonoBehaviour
    {
        class DisasterBeam
        {
            public LineRenderer core;
            public LineRenderer glow;
            public CellMaxSpotGlow originSpot;
            public Vector2 localOrigin;
            public float baseAngle;
            public float sweepPhase;
            public float sweepSpeed;
            public float sweepRange;
            public float age;
            public float damageTimer;
            public float hitFxTimer;
            public Vector2 lastHitPoint;
            public bool hasLastHit;
            public bool fadingOut;
            public float fadeAlpha = 1f;
            public bool finished;
        }

        static readonly Color CoreColor = new Color(0.85f, 0.45f, 1f, 0.95f);
        static readonly Color GlowColor = new Color(0.72f, 0.28f, 1f, 0.55f);

        const float GlowRampDuration = 1.1f;
        const float BeamMaxRange = 250f;
        const int MaxConcurrentBeams = 22;
        const float BeamFadeOutDuration = 0.4f;
        const float DamageTickInterval = 0.05f;
        const float HitFxCooldown = 0.22f;
        const float HitFxMinMove = 0.5f;
        const float SweepSpeedMin = 1.2f;
        const float SweepSpeedMax = 2.4f;
        const float SweepRangeMin = 30f;
        const float SweepRangeMax = 58f;
        const float DefaultFireDuration = 7f;
        const float DisasterRayDamageScale = 3.5f;
        const float DisasterRayKnockbackScale = 5f;
        const float DisasterRayForceScale = 140f;

        public bool Active;
        public bool Firing;

        PersonBehaviour person;
        CellMaxScream scream;
        CellMaxSpotGlow[] allSpotGlows;
        CellMaxSpotGlow[] fireSpotGlows;
        CellMaxSpotGlow headSpotGlow;
        KiSystem kiSys;
        MultipliersAndStuffs multipliers;
        BeamBehaviour beamRef;
        Coroutine fireRoutine;
        Coroutine fadeRoutine;
        readonly List<DisasterBeam> beams = new List<DisasterBeam>();
        float damage;
        float realDamage;
        Material beamMaterial;
        bool lasersActive;
        float lastHitAudioTime;

        public void Setup(PersonBehaviour p)
        {
            person = p;
        }

        public void SetActive(bool active)
        {
            Active = active;
            if (!Active)
                StopFiring();
        }

        void Awake()
        {
            kiSys = GetComponent<KiSystem>();
            multipliers = GetComponent<MultipliersAndStuffs>();
            beamRef = GetComponent<BeamBehaviour>();
            beamMaterial = new Material(ModAPI.FindMaterial("VeryBright"));
        }

        void Start()
        {
            if (person == null) person = GetComponent<PersonBehaviour>();
            var head = PowerSetup.ResolveHeadLimb(person);
            scream = head != null ? head.GetComponent<CellMaxScream>() : null;

            RefreshSpotGlowsInternal();
            if (head != null)
                headSpotGlow = head.GetComponent<CellMaxSpotGlow>();

            if (multipliers == null) multipliers = gameObject.AddComponent<MultipliersAndStuffs>();
            if (kiSys == null) kiSys = gameObject.AddComponent<KiSystem>();
            if (beamRef == null) beamRef = gameObject.AddComponent<BeamBehaviour>();
            if (person != null && multipliers != null)
                damage = CombatPowerController.AttackHealth(person) / multipliers.FinalMultiplier / 1500f;

            StartCoroutine(BindHeadTrigger());
        }

        public void RefreshSpotGlows()
        {
            RefreshSpotGlowsInternal();
        }

        void RefreshSpotGlowsInternal()
        {
            var glowList = new List<CellMaxSpotGlow>();
            var fireList = new List<CellMaxSpotGlow>();
            if (person != null)
            {
                for (int i = 0; i < person.Limbs.Length; i++)
                {
                    var spot = person.Limbs[i].GetComponent<CellMaxSpotGlow>();
                    if (spot == null) continue;
                    if (spot.HasSpots) glowList.Add(spot);
                    if (spot.HasFireSpots) fireList.Add(spot);
                }
            }
            allSpotGlows = glowList.ToArray();
            fireSpotGlows = fireList.ToArray();
        }

        void RefreshDynamicSpots()
        {
            if (headSpotGlow != null)
                headSpotGlow.RefreshFromCurrentSprite();
            RefreshSpotGlowsInternal();
        }

        void SetAllSpotGlowLevel(float level, bool pulse)
        {
            if (allSpotGlows == null) return;
            for (int i = 0; i < allSpotGlows.Length; i++)
            {
                if (allSpotGlows[i] != null)
                    allSpotGlows[i].SetGlowLevel(level, pulse);
            }
        }

        void FadeAllSpotGlow()
        {
            if (allSpotGlows == null) return;
            for (int i = 0; i < allSpotGlows.Length; i++)
            {
                if (allSpotGlows[i] != null)
                    allSpotGlows[i].FadeOut();
            }
        }

        IEnumerator BindHeadTrigger()
        {
            yield return null;
            if (person == null) yield break;

            var head = PowerSetup.ResolveHeadLimb(person);
            if (head == null) yield break;

            var trigger = head.gameObject.GetOrAddComponent<UseEventTrigger>();
            Action previous = trigger.Action;
            trigger.Action = () =>
            {
                if (Active && head.Health > 0f && person.IsAlive())
                {
                    if (Firing) StopFiring();
                    else StartFiring();
                }
                previous?.Invoke();
            };
        }

        void StartFiring()
        {
            if (Firing || !Active || person == null || !person.IsAlive()) return;
            RefreshSpotGlowsInternal();
            if (fireSpotGlows == null || fireSpotGlows.Length == 0)
            {
                PowerSetup.EnsureDisasterRayRig(person);
                RefreshSpotGlowsInternal();
            }
            if (fireSpotGlows == null || fireSpotGlows.Length == 0) return;
            if (kiSys != null && kiSys.currentKi < kiSys.maxKi * 0.02f) return;

            fireRoutine = StartCoroutine(FireRoutine());
        }

        void StopFiring()
        {
            if (fireRoutine != null)
            {
                StopCoroutine(fireRoutine);
                fireRoutine = null;
            }

            Firing = false;
            lasersActive = false;
            if (scream != null) scream.FadeOutWithBeam();
            FadeAllSpotGlow();
            UnfreezePerson();
            BeginBeamFadeOut();
        }

        void BeginBeamFadeOut()
        {
            for (int i = 0; i < beams.Count; i++)
                beams[i].fadingOut = true;

            if (beams.Count > 0 && fadeRoutine == null)
                fadeRoutine = StartCoroutine(FadeBeamsRoutine());
        }

        IEnumerator FadeBeamsRoutine()
        {
            while (beams.Count > 0)
            {
                for (int i = beams.Count - 1; i >= 0; i--)
                {
                    UpdateBeam(beams[i]);
                    if (beams[i].finished)
                        RemoveBeam(i);
                }
                yield return null;
            }
            fadeRoutine = null;
        }

        void FreezePerson()
        {
            if (person == null) return;
            int coreCount = Mathf.Min(14, person.Limbs.Length);
            for (int i = 0; i < coreCount; i++)
            {
                var limb = person.Limbs[i];
                if (limb == null || limb.gameObject == null) continue;
                if (limb.gameObject.GetComponent<FreezeBehaviour>() == null)
                    limb.gameObject.AddComponent<FreezeBehaviour>();
            }
        }

        void UnfreezePerson()
        {
            if (person == null) return;
            for (int i = 0; i < person.Limbs.Length; i++)
            {
                var limb = person.Limbs[i];
                if (limb == null || limb.gameObject == null) continue;
                var freeze = limb.gameObject.GetComponent<FreezeBehaviour>();
                if (freeze != null) Destroy(freeze);
            }
        }

        Vector2 GetBodyCenter()
        {
            if (person == null) return transform.position;
            if (person.Limbs.Length > 2 && person.Limbs[2] != null)
                return person.Limbs[2].transform.position;
            return person.transform.position;
        }

        Vector2 GetOutwardDirection(Vector2 originWorld)
        {
            Vector2 center = GetBodyCenter();
            Vector2 away = originWorld - center;
            if (away.sqrMagnitude < 0.0004f)
                away = UnityEngine.Random.insideUnitCircle;
            away.Normalize();

            float baseAngle = Mathf.Atan2(away.y, away.x) * Mathf.Rad2Deg;
            float spread = UnityEngine.Random.Range(-55f, 55f);
            float finalAngle = (baseAngle + spread) * Mathf.Deg2Rad;
            return new Vector2(Mathf.Cos(finalAngle), Mathf.Sin(finalAngle));
        }

        float GetRealDamage()
        {
            float damageOutput = beamRef != null ? beamRef.DamageOutput : 1f;
            return damage * multipliers.FinalMultiplier * multipliers.KiOutput * damageOutput * DBPU.DamageMultiplier * DisasterRayDamageScale;
        }

        float GetKnockbackOutput()
        {
            float kb = beamRef != null ? beamRef.KnockbackOutput : 1f;
            return kb * DisasterRayKnockbackScale;
        }

        IEnumerator FireRoutine()
        {
            Firing = true;
            lasersActive = false;
            SetAllSpotGlowLevel(0f, false);
            FreezePerson();

            if (scream != null)
            {
                scream.ForceScreaming = true;
                scream.PlayForcedScream();
            }

            float elapsed = 0f;
            float kiTick = 0f;

            while (Firing && Active && person != null && person.IsAlive())
            {
                elapsed += Time.deltaTime;
                if (elapsed >= DefaultFireDuration)
                    break;

                realDamage = GetRealDamage();
                RefreshDynamicSpots();

                float glowLevel = Mathf.Clamp01(elapsed / GlowRampDuration);
                SetAllSpotGlowLevel(glowLevel, false);

                if (!lasersActive && elapsed >= GlowRampDuration)
                {
                    lasersActive = true;
                    SpawnPersistentBeams();
                }

                if (lasersActive)
                {
                    if (kiSys != null)
                    {
                        kiTick += Time.deltaTime;
                        if (kiTick >= 0.15f)
                        {
                            kiTick = 0f;
                            kiSys.currentKi -= kiSys.maxKi * 0.01f * DBPU.KiAttackCostMultiplier;
                            if (kiSys.currentKi < kiSys.maxKi * 0.01f)
                            {
                                StopFiring();
                                yield break;
                            }
                        }
                    }

                    for (int i = beams.Count - 1; i >= 0; i--)
                    {
                        UpdateBeam(beams[i]);
                        if (beams[i].finished)
                            RemoveBeam(i);
                    }
                }

                yield return null;
            }

            StopFiring();
        }

        void SpawnPersistentBeams()
        {
            ClearBeams();
            if (fireSpotGlows == null || fireSpotGlows.Length == 0) return;

            var eligible = new List<CellMaxSpotGlow>(fireSpotGlows.Length);
            for (int i = 0; i < fireSpotGlows.Length; i++)
            {
                var spot = fireSpotGlows[i];
                if (spot != null && spot.HasFireSpots)
                    eligible.Add(spot);
            }

            if (eligible.Count == 0) return;

            eligible.Sort((a, b) =>
            {
                int legCompare = a.IsLeg.CompareTo(b.IsLeg);
                return legCompare != 0 ? legCompare : 0;
            });

            int spawnCount = Mathf.Min(MaxConcurrentBeams, eligible.Count);
            for (int i = 0; i < spawnCount; i++)
                TrySpawnBeamFromSpot(eligible[i]);
        }

        bool TrySpawnBeamFromSpot(CellMaxSpotGlow spot)
        {
            if (spot == null || !spot.HasFireSpots) return false;

            Vector2 localOrigin = spot.GetRandomFireEmissionLocal();
            if (localOrigin == Vector2.zero) return false;

            Vector2 originWorld = spot.transform.TransformPoint(localOrigin);
            Vector2 dir = GetOutwardDirection(originWorld);
            float baseAngle = Mathf.Atan2(dir.y, dir.x);

            var beam = new DisasterBeam
            {
                originSpot = spot,
                localOrigin = localOrigin,
                baseAngle = baseAngle,
                sweepPhase = UnityEngine.Random.Range(0f, Mathf.PI * 2f),
                sweepSpeed = UnityEngine.Random.Range(SweepSpeedMin, SweepSpeedMax),
                sweepRange = UnityEngine.Random.Range(SweepRangeMin, SweepRangeMax) * Mathf.Deg2Rad,
                core = CreateBeamLine("DisasterRayCore", 0.22f, CoreColor, 146),
                glow = CreateBeamLine("DisasterRayGlow", 0.55f, GlowColor, 145)
            };

            beam.core.transform.SetParent(transform, false);
            beam.glow.transform.SetParent(transform, false);
            beams.Add(beam);
            return true;
        }

        Vector2 GetBeamDirection(DisasterBeam beam)
        {
            float angleOffset = Mathf.Sin(beam.age * beam.sweepSpeed + beam.sweepPhase) * beam.sweepRange;
            float angle = beam.baseAngle + angleOffset;
            return new Vector2(Mathf.Cos(angle), Mathf.Sin(angle));
        }

        LineRenderer CreateBeamLine(string name, float width, Color color, int sortOrder)
        {
            var go = new GameObject(name);
            var lr = go.AddComponent<LineRenderer>();
            lr.textureMode = LineTextureMode.Tile;
            lr.material = new Material(beamMaterial != null ? beamMaterial : ModAPI.FindMaterial("VeryBright"));
            lr.sortingLayerName = "Default";
            lr.sortingOrder = sortOrder;
            if (DBPU.StraightBeam_Texture != null)
                lr.material.mainTexture = DBPU.StraightBeam_Texture;
            lr.material.color = color;
            lr.numCapVertices = 2;
            lr.startWidth = width * DBPU.Beam_SizeMultiplier;
            lr.endWidth = width * 0.85f * DBPU.Beam_SizeMultiplier;
            lr.positionCount = 2;
            return lr;
        }

        void UpdateBeam(DisasterBeam beam)
        {
            if (beam == null || beam.core == null || beam.glow == null) return;

            beam.age += Time.deltaTime;

            if (beam.fadingOut)
            {
                beam.fadeAlpha -= Time.deltaTime / BeamFadeOutDuration;
                if (beam.fadeAlpha <= 0f)
                {
                    beam.fadeAlpha = 0f;
                    beam.finished = true;
                }
                ApplyBeamAlpha(beam, beam.fadeAlpha);
                return;
            }

            Vector2 origin = beam.originSpot != null
                ? (Vector2)beam.originSpot.transform.TransformPoint(beam.localOrigin)
                : (Vector2)transform.position;

            Vector2 dir = GetBeamDirection(beam);
            Vector2 castOrigin = origin + dir * 0.08f;
            float maxDist = GetBeamLength(castOrigin, dir);
            Vector2 end = castOrigin + dir * Mathf.Max(0.05f, maxDist - 0.08f);

            beam.core.SetPosition(0, origin);
            beam.core.SetPosition(1, end);
            beam.glow.SetPosition(0, origin);
            beam.glow.SetPosition(1, end);

            ApplyBeamAlpha(beam, 1f);

            beam.hitFxTimer += Time.deltaTime;
            beam.damageTimer += Time.deltaTime;
            if (beam.damageTimer >= DamageTickInterval)
            {
                beam.damageTimer = 0f;
                ApplyDamageAlongBeam(castOrigin, dir, maxDist, beam);
            }
        }

        void ApplyBeamAlpha(DisasterBeam beam, float alpha)
        {
            alpha = Mathf.Clamp01(alpha);
            if (beam.core != null && beam.core.material != null)
            {
                Color c = CoreColor;
                c.a *= alpha;
                beam.core.material.color = c;
            }
            if (beam.glow != null && beam.glow.material != null)
            {
                Color c = GlowColor;
                c.a *= alpha;
                beam.glow.material.color = c;
            }
        }

        void RemoveBeam(int index)
        {
            if (index < 0 || index >= beams.Count) return;
            var beam = beams[index];
            if (beam.core != null) Destroy(beam.core.gameObject);
            if (beam.glow != null) Destroy(beam.glow.gameObject);
            beams.RemoveAt(index);
        }

        float GetBeamLength(Vector2 origin, Vector2 direction)
        {
            RaycastHit2D[] hits = Physics2D.RaycastAll(origin, direction, BeamMaxRange);
            System.Array.Sort(hits, (a, b) => a.distance.CompareTo(b.distance));

            for (int i = 0; i < hits.Length; i++)
            {
                if (hits[i].collider == null) continue;
                if (hits[i].collider.transform.root == transform.root) continue;
                var shell = hits[i].collider.GetComponent<KiShieldSurface>();
                if (shell && shell.Owner && shell.Owner.transform.root == transform.root) continue;
                if (hits[i].collider.gameObject.layer == 11
                    || hits[i].collider.gameObject.layer == 9
                    || hits[i].collider.gameObject.layer == 13)
                    return hits[i].distance;
            }
            return BeamMaxRange;
        }

        void ApplyDamageAlongBeam(Vector2 origin, Vector2 dir, float maxLen, DisasterBeam beam)
        {
            float timeScale = Global.main.SlowMotion ? Global.main.SlowmotionTimescale : 1f;
            RaycastHit2D[] hits = Physics2D.RaycastAll(origin, dir, maxLen);
            System.Array.Sort(hits, (a, b) => a.distance.CompareTo(b.distance));

            for (int i = 0; i < hits.Length; i++)
            {
                RaycastHit2D hit = hits[i];
                if (hit.collider == null) continue;
                if (hit.collider.transform.root == transform.root) continue;

                int layer = hit.collider.gameObject.layer;

                if (layer == 11)
                {
                    var shell = hit.collider.GetComponent<KiShieldSurface>();
                    if (shell && shell.Owner)
                    {
                        if (shell.Owner.transform.root == transform.root) continue;
                        float held;
                        if (!shell.Owner.ReceivePressure(GetInstanceID() ^ beam.GetHashCode(), (double)realDamage * 30, hit.point, .05f, out held)) continue;
                    }
                    TrySpawnBeamHitFx(beam, hit.point, 1.2f);
                    break;
                }

                if (layer != 9 && layer != 13) continue;

                Rigidbody2D rb = hit.collider.attachedRigidbody;
                if (rb == null) continue;

                if (hit.collider.GetComponent<BlastComponent>() != null)
                    hit.collider.GetComponent<BlastComponent>().HasHit = true;

                var limb = hit.collider.GetComponent<LimbBehaviour>();
                if (limb != null && !hit.collider.isTrigger)
                {
                    if (limb.Person == person) continue;

                    if (KiDeflectUtils.IsBeamProtectedCorpse(limb.Person))
                    {
                        float beamKnockCorpse = DBPU.EffectiveBeamKnockback * GetKnockbackOutput();
                        if (beamKnockCorpse > 0f)
                            rb.AddForce(dir * ((4.5f * timeScale) * rb.mass * beamKnockCorpse), ForceMode2D.Impulse);
                        break;
                    }

                    float forcePercent = (realDamage * DisasterRayForceScale) / MCP_Utils.AverageMaxHealth(limb.Person);

                    if (forcePercent > 6f && DBPU.Beam_ToggleDelete)
                    {
                        Destroy(hit.collider.gameObject);
                        break;
                    }

                    if (forcePercent > 0.02f && DBPU.Beam_ToggleHeat)
                        limb.PhysicalBehaviour.BurnProgress += 0.0025f * timeScale;

                    if (forcePercent > 0.005f)
                    {
                        limb.Damage(realDamage * timeScale * 1.25f);

                        float beamKnock = DBPU.EffectiveBeamKnockback * GetKnockbackOutput();
                        if (beamKnock > 0f)
                        {
                            float knockStrength = (4.5f * timeScale) * rb.mass * Mathf.Clamp(forcePercent, 0.75f, 3f) * beamKnock;
                            rb.AddForce(dir * knockStrength, ForceMode2D.Impulse);
                        }

                        if (forcePercent > 0.05f)
                        {
                            float visualDamage = (18f * Mathf.Clamp(forcePercent, 0f, 1f)) / limb.SkinMaterialHandler.intensityMultiplier;
                            if (limb.name.Contains("Body"))
                                limb.SkinMaterialHandler.AddDamagePoint(DamageType.Bullet, hit.point, visualDamage * 5f);
                            limb.SkinMaterialHandler.AddDamagePoint(DamageType.Blunt, hit.point, visualDamage);
                        }

                        TrySpawnBeamHitFx(beam, hit.point, Mathf.Clamp(forcePercent * 2f, 0.5f, 1.5f));
                    }
                    break;
                }

                if (hit.collider.GetComponent<PhysicalBehaviour>() != null)
                {
                    if (DBPU.Beam_ToggleDelete)
                    {
                        Destroy(hit.collider.gameObject);
                        break;
                    }

                    float beamKnock = DBPU.EffectiveBeamKnockback * GetKnockbackOutput();
                    if (beamKnock > 0f)
                        rb.AddForce(dir * ((3.5f * timeScale) * rb.mass * beamKnock), ForceMode2D.Impulse);

                    if (DBPU.Beam_ToggleHeat)
                        hit.collider.GetComponent<PhysicalBehaviour>().Temperature += 1.2f * timeScale;

                    if (DBPU.Beam_ToggleDestroy)
                    {
                        if (hit.collider.GetComponent<DestroyableBehaviour>() != null)
                            hit.collider.GetComponent<DestroyableBehaviour>().Break();
                        if (hit.collider.GetComponent<DamagableMachineryBehaviour>() != null
                            && !hit.collider.GetComponent<DamagableMachineryBehaviour>().Destroyed)
                            hit.collider.GetComponent<DamagableMachineryBehaviour>().ForceBreak();
                    }

                    TrySpawnBeamHitFx(beam, hit.point, 0.9f);
                    break;
                }
            }
        }

        void TrySpawnBeamHitFx(DisasterBeam beam, Vector2 point, float scale)
        {
            if (beam.hitFxTimer < HitFxCooldown) return;
            if (beam.hasLastHit && Vector2.Distance(beam.lastHitPoint, point) < HitFxMinMove) return;

            beam.hitFxTimer = 0f;
            beam.lastHitPoint = point;
            beam.hasLastHit = true;
            SpawnBeamHitFx(point, scale);
        }

        void SpawnBeamHitFx(Vector2 point, float scale)
        {
            if (DBPU.KiBlast_Hit == null) return;

            var fx = Instantiate(DBPU.KiBlast_Hit, point, Quaternion.identity);
            fx.transform.localScale = new Vector3(scale, scale, scale);
            fx.AddComponent<DestroyOverTime>().Timer = 1f;

            foreach (Transform child in fx.transform)
            {
                var sp = child.GetComponent<Renderer>();
                if (sp != null)
                {
                    sp.sortingLayerName = "Bubbles";
                    sp.sortingOrder += 10;
                }

                var ps = child.GetComponent<ParticleSystem>();
                if (ps != null)
                {
                    var main = ps.main;
                    main.startColor = new Color(0.85f, 0.45f, 1f, 0.6f);
                }
            }

            if (Time.time - lastHitAudioTime < 0.35f || DBPU.Attack_DeathBeam_Hit == null) return;

            lastHitAudioTime = Time.time;
            var audioSource = fx.AddComponent<AudioSource>();
            Global global = FindObjectOfType<Global>();
            global.AddAudioSource(audioSource, false);
            audioSource.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.75f;
            audioSource.outputAudioMixerGroup = global.SoundEffects;
            audioSource.spatialBlend = 1f;
            audioSource.volume = DBPU.PowersVolume * 0.65f;
            audioSource.maxDistance = 1000f;
            audioSource.PlayOneShot(DBPU.Attack_DeathBeam_Hit);
        }

        void ClearBeams()
        {
            for (int i = beams.Count - 1; i >= 0; i--)
                RemoveBeam(i);
        }

        void OnDestroy()
        {
            if (fadeRoutine != null)
            {
                StopCoroutine(fadeRoutine);
                fadeRoutine = null;
            }
            ClearBeams();
        }
    }

    public class CellMaxEyeLaserBehaviour : MonoBehaviour
    {
        class EyeLaserBeam
        {
            public LineRenderer core;
            public LineRenderer glow;
            public Transform head;
            public int eyeIndex;
            public Vector2 localOrigin;
            public float damageTimer;
            public float hitFxTimer;
            public Vector2 lastHitPoint;
            public bool hasLastHit;
            public bool fadingOut;
            public float fadeAlpha = 1f;
            public bool finished;
        }

        static readonly Color DefaultCoreColor = new Color(0.85f, 0.45f, 1f, 0.95f);
        static readonly Color DefaultGlowColor = new Color(0.72f, 0.28f, 1f, 0.55f);
        static readonly Color PiccoloCoreColor = new Color(1f, 0.95f, 0.22f, 0.95f);
        static readonly Color PiccoloGlowColor = new Color(1f, 0.82f, 0.08f, 0.5f);
        const float PiccoloCoreWidth = 0.08f;

        const float BeamMaxRange = 250f;
        const float BeamFadeOutDuration = 0.4f;
        const float EyeLaserDamageTickInterval = 0.03f;
        const float HitFxCooldown = 0.22f;
        const float HitFxMinMove = 0.5f;
        const float DefaultFireDuration = 7f;
        const float EyeLaserDamageDivisor = 250f;
        const float EyeLaserDamageScale = 4f;
        const float EyeLaserTickDamageScale = 1.6f;
        const float EyeLaserKnockbackScale = 5f;
        const float EyeLaserForceScale = 140f;

        public bool Active;
        public bool Firing;
        public bool EnableEyeGlow = true;
        public bool UsePiccoloEyeMarkers;

        public Color BeamCoreColor = DefaultCoreColor;
        public Color BeamGlowColor = DefaultGlowColor;
        public float BeamCoreWidth = 0.22f;
        public float BeamGlowWidth = 0.55f;

        PersonBehaviour person;
        CellMaxSpotGlow headSpotGlow;
        Transform headTransform;
        KiSystem kiSys;
        MultipliersAndStuffs multipliers;
        BeamBehaviour beamRef;
        Coroutine fireRoutine;
        Coroutine fadeRoutine;
        readonly List<EyeLaserBeam> beams = new List<EyeLaserBeam>();
        float damage;
        float realDamage;
        Material beamMaterial;
        float lastHitAudioTime;

        public void Setup(PersonBehaviour p)
        {
            person = p;
        }

        public void SetActive(bool active)
        {
            Active = active;
            if (!Active)
            {
                StopFiring();
                if (EnableEyeGlow && headSpotGlow != null)
                    headSpotGlow.FadeOutEyeGlow();
            }
        }

        public void RefreshHeadSpots()
        {
            var head = PowerSetup.ResolveHeadLimb(person);
            if (head != null)
            {
                headTransform = head.transform;
                headSpotGlow = head.GetComponent<CellMaxSpotGlow>();
            }
        }

        public void ApplyPiccoloBeamStyle(bool piccoloEyeMarkers)
        {
            UsePiccoloEyeMarkers = piccoloEyeMarkers;
            BeamCoreColor = PiccoloCoreColor;
            BeamGlowColor = PiccoloGlowColor;
            BeamCoreWidth = PiccoloCoreWidth;
            BeamGlowWidth = 0f;
        }

        void Awake()
        {
            kiSys = GetComponent<KiSystem>();
            multipliers = GetComponent<MultipliersAndStuffs>();
            beamRef = GetComponent<BeamBehaviour>();
            beamMaterial = new Material(ModAPI.FindMaterial("VeryBright"));
        }

        void Start()
        {
            if (person == null) person = GetComponent<PersonBehaviour>();
            RefreshHeadSpots();

            if (multipliers == null) multipliers = gameObject.AddComponent<MultipliersAndStuffs>();
            if (kiSys == null) kiSys = gameObject.AddComponent<KiSystem>();
            if (beamRef == null) beamRef = gameObject.AddComponent<BeamBehaviour>();
            if (person != null && multipliers != null)
                damage = CombatPowerController.AttackHealth(person) / multipliers.FinalMultiplier / EyeLaserDamageDivisor;

            StartCoroutine(BindHeadTrigger());
        }

        IEnumerator BindHeadTrigger()
        {
            yield return null;
            if (person == null) yield break;

            var head = PowerSetup.ResolveHeadLimb(person);
            if (head == null) yield break;

            var trigger = head.gameObject.GetOrAddComponent<UseEventTrigger>();
            Action previous = trigger.Action;
            trigger.Action = () =>
            {
                if (Active && head.Health > 0f && person.IsAlive())
                {
                    if (Firing) StopFiring();
                    else StartFiring();
                }
                previous?.Invoke();
            };
        }

        void StartFiring()
        {
            if (Firing || !Active || person == null || !person.IsAlive()) return;
            RefreshHeadSpots();
            if (headSpotGlow == null)
            {
                if (UsePiccoloEyeMarkers) PowerSetup.EnsurePiccoloEyeLaserHeadRig(person);
                else PowerSetup.EnsureEyeLaserHeadRig(person, EnableEyeGlow);
                RefreshHeadSpots();
            }
            if (headSpotGlow == null || !headSpotGlow.HasEyeLaserSpots) return;
            if (kiSys != null && kiSys.currentKi < kiSys.maxKi * 0.02f) return;

            fireRoutine = StartCoroutine(FireRoutine());
        }

        void StopFiring()
        {
            if (fireRoutine != null)
            {
                StopCoroutine(fireRoutine);
                fireRoutine = null;
            }

            Firing = false;
            if (EnableEyeGlow && headSpotGlow != null)
                headSpotGlow.FadeOutEyeGlow();
            BeginBeamFadeOut();
        }

        void BeginBeamFadeOut()
        {
            for (int i = 0; i < beams.Count; i++)
                beams[i].fadingOut = true;

            if (beams.Count > 0 && fadeRoutine == null)
                fadeRoutine = StartCoroutine(FadeBeamsRoutine());
        }

        IEnumerator FadeBeamsRoutine()
        {
            while (beams.Count > 0)
            {
                for (int i = beams.Count - 1; i >= 0; i--)
                {
                    UpdateBeam(beams[i]);
                    if (beams[i].finished)
                        RemoveBeam(i);
                }
                yield return null;
            }
            fadeRoutine = null;
        }

        Vector2 GetBeamDirection()
        {
            float facing = 1f;
            if (person != null)
                facing = Mathf.Sign(person.transform.localScale.x);
            else if (transform != null)
                facing = Mathf.Sign(transform.localScale.x);
            if (Mathf.Abs(facing) < 0.01f) facing = 1f;

            if (headTransform == null)
                return facing < 0f ? Vector2.left : Vector2.right;

            // transform.right ignores negative scale flips used by PPG facing.
            Vector2 dir = headTransform.right;
            if (facing < 0f) dir = -dir;
            if (dir.sqrMagnitude < 0.0001f)
                return facing < 0f ? Vector2.left : Vector2.right;
            return dir.normalized;
        }

        float GetBaseDamage()
        {
            if (person == null || multipliers == null) return damage;
            return CombatPowerController.AttackHealth(person) / multipliers.FinalMultiplier / EyeLaserDamageDivisor;
        }

        float GetRealDamage()
        {
            return GetBaseDamage() * multipliers.FinalMultiplier * multipliers.KiOutput * DBPU.DamageMultiplier * EyeLaserDamageScale;
        }

        float GetKnockbackOutput()
        {
            float kb = beamRef != null ? beamRef.KnockbackOutput : 1f;
            return kb * EyeLaserKnockbackScale;
        }

        IEnumerator FireRoutine()
        {
            Firing = true;
            RefreshHeadSpots();
            if (headSpotGlow != null)
            {
                headSpotGlow.ForceRefreshFromCurrentSprite();
                if (EnableEyeGlow)
                    headSpotGlow.SetEyeGlowLevel(1f, true);
            }
            SpawnEyeBeams();

            float elapsed = 0f;
            float kiTick = 0f;

            while (Firing && Active && person != null && person.IsAlive())
            {
                elapsed += Time.deltaTime;
                if (elapsed >= DefaultFireDuration)
                    break;

                realDamage = GetRealDamage();

                if (headSpotGlow != null)
                    headSpotGlow.ForceRefreshFromCurrentSprite();

                if (kiSys != null)
                {
                    kiTick += Time.deltaTime;
                    if (kiTick >= 0.15f)
                    {
                        kiTick = 0f;
                        kiSys.currentKi -= kiSys.maxKi * 0.01f * DBPU.KiAttackCostMultiplier;
                        if (kiSys.currentKi < kiSys.maxKi * 0.01f)
                        {
                            StopFiring();
                            yield break;
                        }
                    }
                }

                for (int i = beams.Count - 1; i >= 0; i--)
                {
                    UpdateBeam(beams[i]);
                    if (beams[i].finished)
                        RemoveBeam(i);
                }

                yield return null;
            }

            StopFiring();
        }

        void SpawnEyeBeams()
        {
            ClearBeams();
            if (headSpotGlow == null || headTransform == null || !headSpotGlow.HasEyeLaserSpots) return;

            Vector2[] origins = headSpotGlow.GetEyeLaserEmissionLocals();
            for (int i = 0; i < origins.Length; i++)
            {
                var beam = new EyeLaserBeam
                {
                    head = headTransform,
                    eyeIndex = i,
                    localOrigin = origins[i],
                    core = CreateBeamLine("EyeLaserCore", BeamCoreWidth, BeamCoreColor, 146),
                    glow = BeamGlowWidth > 0f ? CreateBeamLine("EyeLaserGlow", BeamGlowWidth, BeamGlowColor, 145) : null
                };
                beam.core.transform.SetParent(headTransform, false);
                if (beam.glow != null)
                    beam.glow.transform.SetParent(headTransform, false);
                beams.Add(beam);
            }
        }

        LineRenderer CreateBeamLine(string name, float width, Color color, int sortOrder)
        {
            var go = new GameObject(name);
            var lr = go.AddComponent<LineRenderer>();
            lr.textureMode = LineTextureMode.Tile;
            lr.material = new Material(beamMaterial != null ? beamMaterial : ModAPI.FindMaterial("VeryBright"));
            lr.sortingLayerName = "Default";
            lr.sortingOrder = sortOrder;
            if (DBPU.StraightBeam_Texture != null)
                lr.material.mainTexture = DBPU.StraightBeam_Texture;
            lr.material.color = color;
            lr.numCapVertices = 2;
            float endScale = BeamGlowWidth > 0f ? 0.85f : 1f;
            lr.startWidth = width * DBPU.Beam_SizeMultiplier;
            lr.endWidth = width * endScale * DBPU.Beam_SizeMultiplier;
            lr.positionCount = 2;
            return lr;
        }

        void UpdateBeam(EyeLaserBeam beam)
        {
            if (beam == null || beam.core == null) return;

            if (beam.head == null && headTransform != null)
                beam.head = headTransform;

            Vector2 localOrigin = beam.localOrigin;
            if (headSpotGlow != null && headSpotGlow.HasEyeLaserSpots)
            {
                Vector2[] origins = headSpotGlow.GetEyeLaserEmissionLocals();
                if (beam.eyeIndex >= 0 && beam.eyeIndex < origins.Length)
                    localOrigin = origins[beam.eyeIndex];
            }

            Vector2 origin = beam.head != null
                ? (Vector2)beam.head.TransformPoint(localOrigin)
                : (Vector2)transform.position;

            Vector2 dir = GetBeamDirection();
            Vector2 castOrigin = origin + dir * 0.08f;
            float maxDist = GetBeamLength(castOrigin, dir);
            Vector2 end = castOrigin + dir * Mathf.Max(0.05f, maxDist - 0.08f);

            beam.core.SetPosition(0, origin);
            beam.core.SetPosition(1, end);
            if (beam.glow != null)
            {
                beam.glow.SetPosition(0, origin);
                beam.glow.SetPosition(1, end);
            }

            if (beam.fadingOut)
            {
                beam.fadeAlpha -= Time.deltaTime / BeamFadeOutDuration;
                if (beam.fadeAlpha <= 0f)
                {
                    beam.fadeAlpha = 0f;
                    beam.finished = true;
                }
                ApplyBeamAlpha(beam, beam.fadeAlpha);
                return;
            }

            ApplyBeamAlpha(beam, 1f);

            beam.hitFxTimer += Time.deltaTime;
            beam.damageTimer += Time.deltaTime;
            if (beam.damageTimer >= EyeLaserDamageTickInterval)
            {
                beam.damageTimer = 0f;
                ApplyDamageAlongBeam(castOrigin, dir, maxDist, beam);
            }
        }

        void ApplyBeamAlpha(EyeLaserBeam beam, float alpha)
        {
            alpha = Mathf.Clamp01(alpha);
            if (beam.core != null && beam.core.material != null)
            {
                Color c = BeamCoreColor;
                c.a *= alpha;
                beam.core.material.color = c;
            }
            if (beam.glow != null && beam.glow.material != null)
            {
                Color c = BeamGlowColor;
                c.a *= alpha;
                beam.glow.material.color = c;
            }
        }

        void RemoveBeam(int index)
        {
            if (index < 0 || index >= beams.Count) return;
            var beam = beams[index];
            if (beam.core != null) Destroy(beam.core.gameObject);
            if (beam.glow != null) Destroy(beam.glow.gameObject);
            beams.RemoveAt(index);
        }

        float GetBeamLength(Vector2 origin, Vector2 direction)
        {
            RaycastHit2D[] hits = Physics2D.RaycastAll(origin, direction, BeamMaxRange);
            System.Array.Sort(hits, (a, b) => a.distance.CompareTo(b.distance));

            for (int i = 0; i < hits.Length; i++)
            {
                if (hits[i].collider == null) continue;
                if (hits[i].collider.transform.root == transform.root) continue;
                var shell = hits[i].collider.GetComponent<KiShieldSurface>();
                if (shell && shell.Owner && shell.Owner.transform.root == transform.root) continue;
                if (hits[i].collider.gameObject.layer == 11
                    || hits[i].collider.gameObject.layer == 9
                    || hits[i].collider.gameObject.layer == 13)
                    return hits[i].distance;
            }
            return BeamMaxRange;
        }

        void ApplyDamageAlongBeam(Vector2 origin, Vector2 dir, float maxLen, EyeLaserBeam beam)
        {
            float timeScale = Global.main.SlowMotion ? Global.main.SlowmotionTimescale : 1f;
            RaycastHit2D[] hits = Physics2D.RaycastAll(origin, dir, maxLen);
            System.Array.Sort(hits, (a, b) => a.distance.CompareTo(b.distance));

            for (int i = 0; i < hits.Length; i++)
            {
                RaycastHit2D hit = hits[i];
                if (hit.collider == null) continue;
                if (hit.collider.transform.root == transform.root) continue;

                int layer = hit.collider.gameObject.layer;

                if (layer == 11)
                {
                    var shell = hit.collider.GetComponent<KiShieldSurface>();
                    if (shell && shell.Owner)
                    {
                        if (shell.Owner.transform.root == transform.root) continue;
                        float held;
                        if (!shell.Owner.ReceivePressure(GetInstanceID() ^ beam.GetHashCode(), (double)realDamage * 30, hit.point, .05f, out held)) continue;
                    }
                    TrySpawnBeamHitFx(beam, hit.point, 1.2f);
                    break;
                }

                if (layer != 9 && layer != 13) continue;

                Rigidbody2D rb = hit.collider.attachedRigidbody;
                if (rb == null) continue;

                if (hit.collider.GetComponent<BlastComponent>() != null)
                    hit.collider.GetComponent<BlastComponent>().HasHit = true;

                var limb = hit.collider.GetComponent<LimbBehaviour>();
                if (limb != null && !hit.collider.isTrigger)
                {
                    if (limb.Person == person) continue;

                    if (KiDeflectUtils.IsBeamProtectedCorpse(limb.Person))
                    {
                        float beamKnockCorpse = DBPU.EffectiveBeamKnockback * GetKnockbackOutput();
                        if (beamKnockCorpse > 0f)
                            rb.AddForce(dir * ((4.5f * timeScale) * rb.mass * beamKnockCorpse), ForceMode2D.Impulse);
                        break;
                    }

                    float forcePercent = (realDamage * EyeLaserForceScale) / MCP_Utils.AverageMaxHealth(limb.Person);

                    if (forcePercent > 6f && DBPU.Beam_ToggleDelete)
                    {
                        Destroy(hit.collider.gameObject);
                        break;
                    }

                    if (forcePercent > 0.02f && DBPU.Beam_ToggleHeat)
                        limb.PhysicalBehaviour.BurnProgress += 0.0025f * timeScale;

                    if (forcePercent > 0.005f)
                    {
                        limb.Damage(realDamage * timeScale * EyeLaserTickDamageScale);

                        float beamKnock = DBPU.EffectiveBeamKnockback * GetKnockbackOutput();
                        if (beamKnock > 0f)
                        {
                            float knockStrength = (4.5f * timeScale) * rb.mass * Mathf.Clamp(forcePercent, 0.75f, 3f) * beamKnock;
                            rb.AddForce(dir * knockStrength, ForceMode2D.Impulse);
                        }

                        if (forcePercent > 0.05f)
                        {
                            float visualDamage = (18f * Mathf.Clamp(forcePercent, 0f, 1f)) / limb.SkinMaterialHandler.intensityMultiplier;
                            if (limb.name.Contains("Body"))
                                limb.SkinMaterialHandler.AddDamagePoint(DamageType.Bullet, hit.point, visualDamage * 5f);
                            limb.SkinMaterialHandler.AddDamagePoint(DamageType.Blunt, hit.point, visualDamage);
                        }

                        TrySpawnBeamHitFx(beam, hit.point, Mathf.Clamp(forcePercent * 2f, 0.5f, 1.5f));
                    }
                    break;
                }

                if (hit.collider.GetComponent<PhysicalBehaviour>() != null)
                {
                    if (DBPU.Beam_ToggleDelete)
                    {
                        Destroy(hit.collider.gameObject);
                        break;
                    }

                    float beamKnock = DBPU.EffectiveBeamKnockback * GetKnockbackOutput();
                    if (beamKnock > 0f)
                        rb.AddForce(dir * ((3.5f * timeScale) * rb.mass * beamKnock), ForceMode2D.Impulse);

                    if (DBPU.Beam_ToggleHeat)
                        hit.collider.GetComponent<PhysicalBehaviour>().Temperature += 1.2f * timeScale;

                    if (DBPU.Beam_ToggleDestroy)
                    {
                        if (hit.collider.GetComponent<DestroyableBehaviour>() != null)
                            hit.collider.GetComponent<DestroyableBehaviour>().Break();
                        if (hit.collider.GetComponent<DamagableMachineryBehaviour>() != null
                            && !hit.collider.GetComponent<DamagableMachineryBehaviour>().Destroyed)
                            hit.collider.GetComponent<DamagableMachineryBehaviour>().ForceBreak();
                    }

                    TrySpawnBeamHitFx(beam, hit.point, 0.9f);
                    break;
                }
            }
        }

        void TrySpawnBeamHitFx(EyeLaserBeam beam, Vector2 point, float scale)
        {
            if (beam.hitFxTimer < HitFxCooldown) return;
            if (beam.hasLastHit && Vector2.Distance(beam.lastHitPoint, point) < HitFxMinMove) return;

            beam.hitFxTimer = 0f;
            beam.lastHitPoint = point;
            beam.hasLastHit = true;
            SpawnBeamHitFx(point, scale);
        }

        void SpawnBeamHitFx(Vector2 point, float scale)
        {
            if (DBPU.KiBlast_Hit == null) return;

            var fx = Instantiate(DBPU.KiBlast_Hit, point, Quaternion.identity);
            fx.transform.localScale = new Vector3(scale, scale, scale);
            fx.AddComponent<DestroyOverTime>().Timer = 1f;

            foreach (Transform child in fx.transform)
            {
                var sp = child.GetComponent<Renderer>();
                if (sp != null)
                {
                    sp.sortingLayerName = "Bubbles";
                    sp.sortingOrder += 10;
                }

                var ps = child.GetComponent<ParticleSystem>();
                if (ps != null)
                {
                    var main = ps.main;
                    main.startColor = new Color(0.85f, 0.45f, 1f, 0.6f);
                }
            }

            if (Time.time - lastHitAudioTime < 0.35f || DBPU.Attack_DeathBeam_Hit == null) return;

            lastHitAudioTime = Time.time;
            var audioSource = fx.AddComponent<AudioSource>();
            Global global = FindObjectOfType<Global>();
            global.AddAudioSource(audioSource, false);
            audioSource.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.75f;
            audioSource.outputAudioMixerGroup = global.SoundEffects;
            audioSource.spatialBlend = 1f;
            audioSource.volume = DBPU.PowersVolume * 0.65f;
            audioSource.maxDistance = 1000f;
            audioSource.PlayOneShot(DBPU.Attack_DeathBeam_Hit);
        }

        void ClearBeams()
        {
            for (int i = beams.Count - 1; i >= 0; i--)
                RemoveBeam(i);
        }

        void OnDestroy()
        {
            if (fadeRoutine != null)
            {
                StopCoroutine(fadeRoutine);
                fadeRoutine = null;
            }
            ClearBeams();
        }
    }

    public class CellMaxScream : MonoBehaviour
    {
        public bool isCreaming = false;
        public bool ForceScreaming = false;
        public Sprite[] Sprites = new Sprite[5];
        public AudioClip Scream;

        private PhysicalBehaviour phys;
        private PersonBehaviour person;
        private bool isShaking = false;
        Coroutine beamMouthLoop;
        Coroutine activeScreamRoutine;
        Coroutine screamFadeRoutine;

        private void Start()
        {
            phys = gameObject.GetComponent<PhysicalBehaviour>();
            person = transform.root.gameObject.GetComponent<PersonBehaviour>();
        }

        public void PlayForcedScream()
        {
            if (!isCreaming)
                activeScreamRoutine = StartCoroutine(StartScream());
        }

        public void FadeOutWithBeam()
        {
            ForceScreaming = false;

            if (beamMouthLoop != null)
            {
                StopCoroutine(beamMouthLoop);
                beamMouthLoop = null;
            }

            if (activeScreamRoutine != null)
            {
                StopCoroutine(activeScreamRoutine);
                activeScreamRoutine = null;
            }

            isShaking = false;
            isCreaming = false;
            SetFaceSprite(0);

            if (screamFadeRoutine != null)
                StopCoroutine(screamFadeRoutine);
            screamFadeRoutine = StartCoroutine(FadeScreamAudio());
        }

        IEnumerator FadeScreamAudio()
        {
            Transform screamNode = transform.Find("Scream");
            if (screamNode == null)
            {
                screamFadeRoutine = null;
                yield break;
            }

            AudioSource audioSource = screamNode.GetComponent<AudioSource>();
            if (audioSource == null)
            {
                Destroy(screamNode.gameObject);
                screamFadeRoutine = null;
                yield break;
            }

            while (audioSource.volume > 0.05f)
            {
                audioSource.volume -= 0.15f;
                yield return new WaitForSeconds(0.025f);
            }

            audioSource.Stop();
            Destroy(screamNode.gameObject);
            screamFadeRoutine = null;
        }

        public IEnumerator PrepareForBeam()
        {
            while (isCreaming) yield return null;

            isCreaming = true;
            MCP_Utils.PlayAudio(transform.position + (transform.up * -3.5f) + (transform.right * 1f), Scream, transform, spatialBlend: 0.7f, name: "Scream");

            for (int i = 1; i < 3; i++)
            {
                SetFaceSprite(i);
                yield return new WaitForSeconds(0.04f);
            }

            isShaking = true;
            ForceScreaming = true;

            if (beamMouthLoop != null) StopCoroutine(beamMouthLoop);
            beamMouthLoop = StartCoroutine(BeamMouthLoop());

            yield return new WaitForSeconds(0.08f);
        }

        IEnumerator BeamMouthLoop()
        {
            int face = 4;
            while (ForceScreaming)
            {
                SetFaceSprite(face);
                face = face == 4 ? 3 : 4;
                yield return new WaitForSeconds(0.06f);
            }
        }

        public IEnumerator FinishBeamMouth()
        {
            FadeOutWithBeam();
            yield return null;
        }

        public void CancelBeamMouth()
        {
            FadeOutWithBeam();
        }

        private void Update()
        {
            if (isCreaming || !person.IsAlive())
            {
                if (isShaking) CameraShakeBehaviour.main.Shake(2f, transform.position);

                if (transform.Find("Scream"))
                {
                    AudioSource audioSource = transform.Find("Scream").GetComponent<AudioSource>();
                    if (audioSource.volume != DBPU.VoiceLineVolume) audioSource.volume = DBPU.VoiceLineVolume;
                }

                return;
            }

            if (!person.IsAlive()) return;

            if (DbpuInputUtil.Down(DBPU.CellMaxScreamActionId, KeyCode.R) && CeceUtils.IsSelected(phys))
            {
                isCreaming = true;
                activeScreamRoutine = StartCoroutine(StartScream());
            }
        }

        void SetFaceSprite(int index)
        {
            GetComponent<SpriteRenderer>().sprite = Sprites[index];
            MCP_Utils.SafeRefreshOutline(phys);
        }

        public IEnumerator StartScream()
        {
            isCreaming = true;
            MCP_Utils.PlayAudio(transform.position + (transform.up * -3.5f) + (transform.right * 1f), Scream, transform, spatialBlend: 0.7f, name: "Scream");

            for (int i = 1; i < 3; i++)
            {
                SetFaceSprite(i);
                yield return new WaitForSeconds(0.02f);
            }

            isShaking = true;

            int face = 4;
            int ticks = 0;
            while (ForceScreaming || ticks < 67)
            {
                SetFaceSprite(face);
                face = face == 4 ? 3 : 4;
                ticks++;
                yield return new WaitForSeconds(0.06f);
            }

            isShaking = false;

            for (int i = 3; i >= 0; i--)
            {
                SetFaceSprite(i);
                yield return new WaitForSeconds(0.1f);
            }

            yield return new WaitForSeconds(0.5f);

            isCreaming = false;
            ForceScreaming = false;
            activeScreamRoutine = null;

            yield return null;
        }
    }

    public class CellMaxTailSegment : MonoBehaviour
    {
    }

    public class CellMaxIgnoresTailWeight : MonoBehaviour
    {
        const int TailStartIndex = 14;
        const int TailEndIndexExclusive = 26;
        const int CoreEndIndexExclusive = 14;
        const int TailAnchorIndex = 1;
        const float PullCompensationScale = 0.35f;
        const float FlightTailPullScale = 0.45f;
        const float FlightTailGatherScale = 0.2f;

        PersonBehaviour _person;
        Flight _flight;
        float[] _coreFakeUpright;
        float[] _tailFakeUpright;
        bool _wasFlying;
        bool _coreUprightEnabled = true;

        void Start()
        {
            _person = GetComponent<PersonBehaviour>();
            _flight = _person.GetComponentInChildren<Flight>(true);
            _coreFakeUpright = new float[CoreEndIndexExclusive];
            _tailFakeUpright = new float[TailEndIndexExclusive - TailStartIndex];

            for (int i = 0; i < _person.Limbs.Length && i < CoreEndIndexExclusive; i++)
            {
                var limb = _person.Limbs[i];
                _coreFakeUpright[i] = limb != null ? limb.FakeUprightForce : 0f;
            }

            for (int i = TailStartIndex; i < _person.Limbs.Length && i < TailEndIndexExclusive; i++)
            {
                var limb = _person.Limbs[i];
                _tailFakeUpright[i - TailStartIndex] = limb != null ? limb.FakeUprightForce : 0f;
            }
        }

        bool IsCoreTouchingSomething()
        {
            int coreCount = Mathf.Min(CoreEndIndexExclusive, _person.Limbs.Length);
            for (int i = 0; i < coreCount; i++)
            {
                var limb = _person.Limbs[i];
                if (limb == null || limb.PhysicalBehaviour == null || limb.PhysicalBehaviour.isDisintegrated) continue;
                if (limb.PhysicalBehaviour.IsTouchingSomething) return true;
            }

            return false;
        }

        void SetCoreFakeUpright(bool enabled)
        {
            if (_coreUprightEnabled == enabled) return;

            for (int i = 0; i < _person.Limbs.Length && i < CoreEndIndexExclusive; i++)
            {
                var limb = _person.Limbs[i];
                if (limb == null) continue;

                limb.FakeUprightForce = enabled ? _coreFakeUpright[i] : 0f;
            }

            _coreUprightEnabled = enabled;
        }

        void SetTailFakeUprightForFlight(bool flying)
        {
            for (int i = TailStartIndex; i < _person.Limbs.Length && i < TailEndIndexExclusive; i++)
            {
                var limb = _person.Limbs[i];
                if (limb == null) continue;

                limb.FakeUprightForce = flying ? 0f : _tailFakeUpright[i - TailStartIndex];
            }
        }

        bool TryGetTailStats(out Vector2 tailMassPosition, out float tailMass, out Vector2 tailWeightForce)
        {
            tailMassPosition = Vector2.zero;
            tailMass = 0f;
            tailWeightForce = Vector2.zero;

            for (int i = TailStartIndex; i < _person.Limbs.Length && i < TailEndIndexExclusive; i++)
            {
                var limb = _person.Limbs[i];
                if (limb == null || limb.PhysicalBehaviour.isDisintegrated) continue;

                Rigidbody2D rb = limb.PhysicalBehaviour.rigidbody;
                if (rb.bodyType == RigidbodyType2D.Static) continue;

                float limbMass = rb.mass;
                tailWeightForce += rb.gravityScale * limbMass * Physics2D.gravity;
                tailMassPosition += rb.worldCenterOfMass * limbMass;
                tailMass += limbMass;
            }

            if (tailMass <= 0f) return false;

            tailMassPosition /= tailMass;
            return true;
        }

        Vector2 GetPullCompensation(Vector2 tailMassPosition, float tailMass, Vector2 anchorPos, float scale)
        {
            Vector2 pullDir = tailMassPosition - anchorPos;
            if (pullDir.sqrMagnitude <= 0.01f) return Vector2.zero;

            pullDir.Normalize();
            return -pullDir * (tailMass * Mathf.Abs(Physics2D.gravity.y) * scale);
        }

        void ApplyCoreForce(Vector2 force)
        {
            int coreCount = Mathf.Min(CoreEndIndexExclusive, _person.Limbs.Length);
            if (coreCount <= 0 || force.sqrMagnitude <= 0.0001f) return;

            float anchorShare = 0.55f;
            float restShare = coreCount > 1 ? (1f - anchorShare) / (coreCount - 1) : 0f;

            for (int i = 0; i < coreCount; i++)
            {
                var limb = _person.Limbs[i];
                if (limb == null || limb.PhysicalBehaviour.isDisintegrated) continue;

                Rigidbody2D rb = limb.PhysicalBehaviour.rigidbody;
                if (rb.bodyType == RigidbodyType2D.Static) continue;

                float share = i == TailAnchorIndex ? anchorShare : restShare;
                rb.AddForce(force * share, ForceMode2D.Force);
            }
        }

        void StabilizeTailInFlight(Vector2 anchorPos, float tailMass)
        {
            float gatherStrength = tailMass * Mathf.Abs(Physics2D.gravity.y) * FlightTailGatherScale;

            for (int i = TailStartIndex; i < _person.Limbs.Length && i < TailEndIndexExclusive; i++)
            {
                var limb = _person.Limbs[i];
                if (limb == null || limb.PhysicalBehaviour.isDisintegrated) continue;

                Rigidbody2D rb = limb.PhysicalBehaviour.rigidbody;
                if (rb.bodyType == RigidbodyType2D.Static) continue;

                Vector2 toAnchor = anchorPos - rb.worldCenterOfMass;
                if (toAnchor.sqrMagnitude <= 0.01f) continue;

                rb.AddForce(toAnchor.normalized * gatherStrength, ForceMode2D.Force);
            }
        }

        void FixedUpdate()
        {
            if (_person == null || _person.Braindead || _person.Heartbeat == 0) return;

            bool isFlying = _flight != null && _flight.IsFlying;
            bool coreTouchingSomething = IsCoreTouchingSomething();
            SetCoreFakeUpright(!isFlying && coreTouchingSomething);

            if (isFlying != _wasFlying)
            {
                SetTailFakeUprightForFlight(isFlying);
                _wasFlying = isFlying;
            }

            if (isFlying || !coreTouchingSomething) return;

            if (!TryGetTailStats(out Vector2 tailMassPosition, out float tailMass, out Vector2 tailWeightForce)) return;

            var anchorLimb = _person.Limbs[TailAnchorIndex];
            if (anchorLimb == null || anchorLimb.PhysicalBehaviour.isDisintegrated) return;

            Vector2 anchorPos = anchorLimb.PhysicalBehaviour.rigidbody.worldCenterOfMass;

            Vector2 cancelForce = -tailWeightForce;
            cancelForce += GetPullCompensation(tailMassPosition, tailMass, anchorPos, PullCompensationScale);
            ApplyCoreForce(cancelForce);
        }
    }

    public class Flight : MonoBehaviour
    {
        private PersonBehaviour _person;
        private bool _isFlying;

        public bool IsFlying => _isFlying;

        private void Start()
        {
            _person = transform.root.GetComponent<PersonBehaviour>();
        }

        public void Use()
        {
            _isFlying = !_isFlying;
        }

        private void FixedUpdate()
        {
            if (!_isFlying || _person.Braindead || _person.Heartbeat == 0) return;

            foreach (var limb in _person.Limbs)
            {
                Rigidbody2D limbRb = limb.PhysicalBehaviour.rigidbody;
                if (limbRb.bodyType == RigidbodyType2D.Static) continue;

                limbRb.AddForce(-1f * limbRb.gravityScale * limbRb.mass * Physics2D.gravity);

                float brake = Mathf.Pow(0.95f, Mathf.Max(1f, limb.PhysicalBehaviour.Charge));
                float angularBrake = Mathf.Pow(0.9f, Mathf.Max(1f, limb.PhysicalBehaviour.Charge));

                limbRb.velocity *= brake;
                limbRb.angularVelocity *= angularBrake;
            }
        }
    }

    public class Kaioken : MonoBehaviour
    {
        public MultipliersAndStuffs Multipliers;
        public KiSystem KiSys;
        public AuraHandler AuraHandler;

        public GameObject KaiokenAura;
        public AudioSource audioSource;

        public bool AuraON = true;
        public bool Active = false;
        public float Multiplier = 2f;
        public float PreviousMultiplier = 2f;
        public float AppliedHealthMultiplier = 1f;
        public bool HealthMultiplierTracked;
        public float HealthScale { get { return Mathf.Max(1f, KiCombatMath.Finite(AppliedHealthMultiplier, 1f)); } }
        public float StrainMultiplier = 1f;
        public string LastForm = "Base";

        public List<string> CompatibleForms = new List<string>
        {
            "Base",
            "SSJ1",
            "SSJ2",
            "SSJ3",
            "SSJBlue",
            "PSSJBlue"
            };

        private void OnDestroy()
        {
            if (KaiokenAura != null) Destroy(KaiokenAura);
        }

        private void Awake()
        {
            audioSource = new GameObject("KaiokenAudioSource").AddComponent<AudioSource>();
            audioSource.transform.SetParent(transform.Find("Body/UpperBody"), false);
            Global global = FindObjectOfType<Global>();
            global.AddAudioSource(audioSource, false);
            audioSource.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.75f;
            audioSource.outputAudioMixerGroup = global.SoundEffects;
            audioSource.spatialBlend = 1;
            audioSource.volume = 1;
            audioSource.maxDistance = 1000;

            UnityAction[] ReloadSound = { () => ToggleSound() };
            UnityAction[] ReloadAura = { () => ToggleAura() };

            var contextMenuButton = new ContextMenuButton("!Kaioken", "Kaioken Multiplier", "Kaioken Multiplier", new UnityAction[] { () => ShowKaiokenDialog(ReloadSound, ReloadAura) });
            transform.Find("Body/UpperBody").GetComponent<PhysicalBehaviour>().ContextMenuOptions.Buttons.Add(contextMenuButton);
        }

        private void Start()
        {
            KiSys = GetComponent<KiSystem>();
            if (!transform.root.GetComponent<MultipliersAndStuffs>()) transform.root.gameObject.AddComponent<MultipliersAndStuffs>();
            Multipliers = transform.root.GetComponent<MultipliersAndStuffs>();

            /*transform.Find("Body/UpperBody").gameObject.AddComponent<UseEventTrigger>().Action = () =>
            {
                if (!GetComponent<PersonBehaviour>().IsAlive()) return;

                var transformationMenu = GetComponent<PersonBehaviour>().Limbs[0].GetComponent<TransformationContextMenu>();
                if (transformationMenu && !CompatibleForms.Contains(transformationMenu.Form)) return;

                StopAllCoroutines();
                if (!Active) StartCoroutine(Activate());
                else StartCoroutine(Deactivate());
                };*/

            if (transform.root.gameObject.GetComponent<AuraHandler>()) AuraHandler = transform.root.gameObject.GetComponent<AuraHandler>();
            // Scenes saved before explicit health tracking already contain the
            // active health bonus. Resume the mode without applying it twice.
            if (Active && GetComponent<PersonBehaviour>().IsAlive())
            {
                if (!HealthMultiplierTracked)
                    AppliedHealthMultiplier = Mathf.Max(1f, KiCombatMath.Finite(PreviousMultiplier, Multiplier));
                HealthMultiplierTracked = true;
                StartCoroutine(Activate());
            }
        }

        private void Update()
        {
            if (audioSource.volume != DBPU.PowersVolume) audioSource.volume = DBPU.PowersVolume;

            if (DbpuInputUtil.Down(DBPU.KaiokenActionId, KeyCode.K) && CeceUtils.IsSelected(transform.Find("Body/UpperBody").gameObject.GetComponent<PhysicalBehaviour>()))
            {
                if (!GetComponent<PersonBehaviour>().IsAlive()) return;

                var transformationMenu = GetComponent<PersonBehaviour>().Limbs[0].GetComponent<TransformationContextMenu>();
                if (transformationMenu && !CompatibleForms.Contains(transformationMenu.Form)) return;

                StopAllCoroutines();
                if (!Active) StartCoroutine(Activate());
                else StartCoroutine(Deactivate());
            }

            if (Active)
            {
                if (DBPU.AurasEnabled && AuraON)
                {
                    var native=KaiokenAura!=null?KaiokenAura.GetComponent<RefinedAuraVisual>():null;
                    if(KaiokenAura==null||(native!=null&&native.ProfileId!=CinematicAssets.KaiokenProfile(GetComponent<PersonBehaviour>())))CreateAura();
                }
                if (AuraON && KaiokenAura != null && KaiokenAura.GetComponent<RefinedAuraVisual>() == null) KaiokenAura.transform.position = GetComponent<PersonBehaviour>().Limbs[2].transform.position + new Vector3(0f, -1.1f, 0f);

                if (KiSys.Strain > 0.99f && DBPU.KaiokenStrainDamageEnabled)
                {
                    foreach (var limb in GetComponent<PersonBehaviour>().Limbs)
                    {
                        limb.Health -= (limb.InitialHealth / 2000f) * Multiplier * (StrainMultiplier * DBPU.StrainDamageMultiplier) * Time.deltaTime;
                    }
                }
            }
        }

        public void ToggleFromPowersMenu()
        {
            if (!GetComponent<PersonBehaviour>().IsAlive()) return;
            var transformationMenu = GetComponent<PersonBehaviour>().Limbs[0].GetComponent<TransformationContextMenu>();
            if (transformationMenu && !CompatibleForms.Contains(transformationMenu.Form)) return;
            StopAllCoroutines();
            if (!Active) StartCoroutine(Activate());
            else StartCoroutine(Deactivate());
        }

        private void CreateAura()
        {
            if (KaiokenAura != null) Destroy(KaiokenAura);
            KaiokenAura = RefinedAuras.Create(CinematicAssets.KaiokenProfile(GetComponent<PersonBehaviour>()));
            if (KaiokenAura != null)
            {
                KaiokenAura.GetComponent<RefinedAuraVisual>().KaiokenPerson = GetComponent<PersonBehaviour>();
                KaiokenAura.AddComponent<DestroyWithObject>().Object = gameObject;
                return;
            }

            KaiokenAura = Instantiate(DBPU.Aura_Kaioken, GetComponent<PersonBehaviour>().Limbs[2].transform.position, Quaternion.identity);
            KaiokenAura.transform.localScale = new Vector3(1.3f + Multiplier / 32f, 1.3f + Multiplier / 32f);

            foreach (var lightning in KaiokenAura.GetComponentsInChildren<ParticleSystem>().Where(x => x.name == "lightning"))
            {
                lightning.GetComponent<ParticleSystemRenderer>().sortingLayerName = "Top";
            }

            foreach (var spark in KaiokenAura.GetComponentsInChildren<ParticleSystem>().Where(x => x.name == "spark"))
            {
                spark.GetComponent<ParticleSystemRenderer>().sortingLayerName = "Top";
            }

            foreach (var aura in KaiokenAura.transform.Cast<Transform>().Where(x => x.name == "aura"))
            {
                aura.Find("aura").localEulerAngles = new Vector3(180, 0, 0);
                aura.Find("aura").localPosition = new Vector3(0, 1.4f, 0);
            }
        }

        // Keep the requested setting separate from the multiplier actually
        // applied to native health. Configuration and deactivation can happen
        // in the same frame, before the activation coroutine resumes.
        private void ApplyPowerMultiplier(float target)
        {
            var person = GetComponent<PersonBehaviour>();
            if (!person) return;
            if (!Multipliers) Multipliers = GetComponent<MultipliersAndStuffs>();
            float wanted = Mathf.Max(1f, KiCombatMath.Finite(target, 1f));
            float ratio = wanted / HealthScale;
            HealthMultiplierTracked = true;
            if (Mathf.Abs(ratio - 1f) > .000001f)
            {
                foreach (var limb in person.Limbs)
                {
                    if (!limb || limb.InitialHealth <= 0f) continue;
                    if (GogitoVitality.Scale(limb, ratio)) continue;
                    double fraction = Math.Max(0d, (double)limb.Health / limb.InitialHealth);
                    limb.InitialHealth = KiCombatMath.Cap((double)limb.InitialHealth * ratio, float.MaxValue);
                    limb.Health = KiCombatMath.Cap(limb.InitialHealth * fraction, float.MaxValue);
                }
                AppliedHealthMultiplier = wanted;
                MCP_Utils.InvalidatePersonStatCache(person);
                person.ChangeWeightBasedOnHealth();
            }
            if (Multipliers)
            {
                Multipliers.KaiokenMultiplier = wanted;
                Multipliers.Recalculate();
            }
            var power = person.GetComponent<CombatPowerController>();
            if (power) power.Refresh();
        }

        private void RefreshMultiplierAppearance()
        {
            foreach (var limb in GetComponent<PersonBehaviour>().Limbs)
            {
                if (!limb) continue;
                foreach (var renderer in limb.GetComponentsInChildren<SpriteRenderer>())
                    renderer.color = new Color(1f, 0.8f - Multiplier / 100f, 0.8f - Multiplier / 100f);
            }
            if (AuraON && KaiokenAura != null && KaiokenAura.GetComponent<RefinedAuraVisual>() == null)
                KaiokenAura.transform.localScale = new Vector3(1.3f + Multiplier / 32f, 1.3f + Multiplier / 32f);
        }

        private IEnumerator Activate()
        {
            Multiplier = Mathf.Clamp(KiCombatMath.Finite(Multiplier, 2f), 1f, Mathf.Max(1f, KiCombatMath.Finite(DBPU.KaiokenMaxMultiplier, 20f)));
            Active = true;

            audioSource.Stop();
            audioSource.PlayOneShot(DBPU.Aura_Kaioken_Start);
            audioSource.clip = DBPU.Aura_Kaioken_Loop;
            audioSource.loop = true;
            audioSource.Play();

            if (AuraON) CreateAura();

            foreach (var limb in GetComponent<PersonBehaviour>().Limbs)
            {
                limb.GetComponent<SpriteRenderer>().color = new Color(1f, 0.8f - Multiplier / 100f, 0.8f - Multiplier / 100f);
                foreach (SpriteRenderer sr in limb.GetComponentsInChildren<SpriteRenderer>())
                {
                    sr.color = new Color(1f, 0.8f - Multiplier / 100f, 0.8f - Multiplier / 100f);
                }
            }

            PreviousMultiplier = Multiplier;
            ApplyPowerMultiplier(Multiplier);

            var transformationMenu = GetComponent<PersonBehaviour>().Limbs[0].GetComponent<TransformationContextMenu>();

            if (transformationMenu)
            {
                StrainMultiplier = GetStrainMultiplier(transformationMenu.Form);
            }

            if (transformationMenu != null && !CinematicAssets.KeepsInnerAura(transformationMenu.Form) && AuraHandler != null)
                AuraHandler.DestroyAura();
            if (transformationMenu != null)
                LastForm = transformationMenu.Form;

            while (Active && GetComponent<PersonBehaviour>().IsAlive())
            {
                KiSys.StrainRate = 0.001f * Multiplier * StrainMultiplier * DBPU.KaiokenStrainMultiplier;

                if (PreviousMultiplier != Multiplier || AppliedHealthMultiplier != Multiplier)
                {
                    Multiplier = Mathf.Clamp(KiCombatMath.Finite(Multiplier, 2f), 1f, Mathf.Max(1f, KiCombatMath.Finite(DBPU.KaiokenMaxMultiplier, 20f)));
                    ApplyPowerMultiplier(Multiplier);
                    RefreshMultiplierAppearance();
                    PreviousMultiplier = Multiplier;
                }

                if (transformationMenu)
                {
                    StrainMultiplier = GetStrainMultiplier(transformationMenu.Form);

                    if (!CompatibleForms.Contains(transformationMenu.Form))
                    {
                        StartCoroutine(Deactivate());
                    }

                    if (AuraHandler != null && CinematicAssets.KeepsInnerAura(transformationMenu.Form) && (LastForm != transformationMenu.Form || !AuraHandler.AuraVisible))
                    {
                        LastForm = transformationMenu.Form;
                        AuraHandler.AuraVisible = true;
                        AuraHandler.CreateAura(transformationMenu.CurrentAuraID);
                    }

                    else if (!CinematicAssets.KeepsInnerAura(transformationMenu.Form) && AuraHandler != null && AuraHandler.AuraVisible == true)
                    {
                        LastForm = transformationMenu.Form;
                        AuraHandler.AuraVisible = false;
                        AuraHandler.DestroyAura();
                    }
                }

                yield return new WaitForEndOfFrame();
            }

            if (Active && !GetComponent<PersonBehaviour>().IsAlive()) StartCoroutine(Deactivate());
        }

        private IEnumerator Deactivate()
        {
            Active = false;
            audioSource.Stop();
            audioSource.PlayOneShot(DBPU.Aura_Kaioken_End);

            var transformationMenu = GetComponent<PersonBehaviour>().Limbs[0].GetComponent<TransformationContextMenu>();

            if (KaiokenAura != null) Destroy(KaiokenAura);

            ApplyPowerMultiplier(1f);

            if (AuraHandler != null)
                AuraHandler.AuraVisible = true;

            if (AuraHandler != null && transformationMenu != null && AuraHandler.AuraActive == true && !transformationMenu.Form.Contains("SSJBlue") && GetComponent<PersonBehaviour>().IsAlive())
            {
                AuraHandler.CreateAura(transformationMenu.CurrentAuraID);
            }

            foreach (var limb in GetComponent<PersonBehaviour>().Limbs)
            {
                limb.GetComponent<SpriteRenderer>().color = Color.white;
                foreach (SpriteRenderer sr in limb.GetComponentsInChildren<SpriteRenderer>())
                {
                    sr.color = Color.white;
                }
            }

            Multipliers.KaiokenMultiplier = 1f;
            KiSys.StrainRate = 0f;

            yield return null;
        }

        private void ToggleSound()
        {
            audioSource.volume = audioSource.volume == 1 ? 0 : 1;
            ShowKaiokenDialog(new UnityAction[] { () => ToggleSound() }, new UnityAction[] { () => ToggleAura() });
        }

        private void ToggleAura()
        {
            AuraON = !AuraON;

            if (Active)
            {
                if (AuraON) CreateAura();
                else if (KaiokenAura != null) Destroy(KaiokenAura);
            }

            ShowKaiokenDialog(new UnityAction[] { () => ToggleSound() }, new UnityAction[] { () => ToggleAura() });
        }

        private void ShowKaiokenDialog(UnityAction[] reloadSound, UnityAction[] reloadAura)
        {
            DialogBox Dialog = DialogBoxManager.Dialog("<b>Choose the Kaioken Multiplier<b>",
                new DialogButton("<b><size=75%>X2<b>", true, new UnityAction[] { () => SetMultiplier(2f) }),
                new DialogButton("<b><size=75%>X3<b>", true, new UnityAction[] { () => SetMultiplier(3f) }),
                new DialogButton("<b><size=75%>X4<b>", true, new UnityAction[] { () => SetMultiplier(4f) }),
                new DialogButton("<b><size=75%>X8<b>", true, new UnityAction[] { () => SetMultiplier(8f) }),
                new DialogButton("<b><size=75%>X12<b>", true, new UnityAction[] { () => SetMultiplier(12f) }),
                new DialogButton("<b><size=75%>X20<b>", true, new UnityAction[] { () => SetMultiplier(20f) }),

                new DialogButton("<b><size=60%>Custom<b>", true, new UnityAction[] { () => CustomMultiplier() }),

                new DialogButton(audioSource.volume == 1 ? "<b><size=50%>Sound <color=green>ON<color=white><b>" : "<b><size=50%>Sound <color=red>OFF<color=white><b>", true, reloadSound),
                new DialogButton(AuraON ? "<b><size=60%>Aura <color=green>ON<color=white><b>" : "<b><size=60%>Aura <color=red>OFF<color=white><b>", true, reloadAura),
                new DialogButton("<b><size=60%>Close<b>", true, new UnityAction[] { () => { } })
                );

            Dialog.TextMesh.gameObject.GetComponent<LayoutElement>().minWidth = 900;
        }

        private void CustomMultiplier()
        {
            Utils.OpenFloatInputDialog(Multiplier, GetComponent<PersonBehaviour>(), delegate (PersonBehaviour person, float value)
            {
                if (value < 1f) value = 1f;
                SetMultiplier(value);
            }, "Set Kaioken Multiplier", "Default: 2");
        }

        private void SetMultiplier(float multiplier)
        {
            Multiplier = Mathf.Clamp(KiCombatMath.Finite(multiplier, 2f), 1f, Mathf.Max(1f, KiCombatMath.Finite(DBPU.KaiokenMaxMultiplier, 20f)));
            if (Active)
            {
                ApplyPowerMultiplier(Multiplier);
                RefreshMultiplierAppearance();
                PreviousMultiplier = Multiplier;
                audioSource.PlayOneShot(DBPU.Aura_Kaioken_Start);
            }
        }

        public void ApplyConfiguredMultiplier(float multiplier)
        {
            SetMultiplier(multiplier);
        }

        private float GetStrainMultiplier(string form)
        {
            switch (form)
            {
                case "Base": return 1f;
                case "SSJ1": return 5f;
                case "PSSJ": return 1.2f;
                case "SSJ2": return 6f;
                case "SSJ3": return 8f;
                case "SSJBlue": return 1.5f;
                case "PSSJBlue": return 1.2f;
                default: return 1f;
            }
        }
    }

    public class InstantTransmission : MonoBehaviour
    {
        private PersonBehaviour person;
        private KiSystem KiSys;
        private AudioSource audioSource;

        public GameObject MaskObject;
        public GameObject Shadow;

        public bool Active = false;
        public bool CanUse = false;
        public bool Teleporting = false;
        public bool IsTeleporting = false;
        public float CostPercent = 0.01f;

        public List<Sprite> Effect = new List<Sprite>
        {
            DBPU.TeleportEffect_1,
            DBPU.TeleportEffect_2,
            DBPU.TeleportEffect_3,
            DBPU.TeleportEffect_4,
            DBPU.TeleportEffect_5
            };

        private void Awake()
        {
            audioSource = new GameObject("BeamAudioSource").AddComponent<AudioSource>();
            audioSource.transform.SetParent(transform.Find("Head"), false);
            Global global = FindObjectOfType<Global>();
            global.AddAudioSource(audioSource, false);
            audioSource.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.75f;
            audioSource.outputAudioMixerGroup = global.SoundEffects;
            audioSource.spatialBlend = 1;
            audioSource.volume = 1;
            audioSource.maxDistance = 1000;
        }

        private void Start()
        {
            if (!GetComponent<KiSystem>()) gameObject.AddComponent<KiSystem>();
            KiSys = GetComponent<KiSystem>();

            person = GetComponent<PersonBehaviour>();

            foreach (var limb in person.Limbs)
            {
                if (limb.gameObject == null) continue;

                if (limb.name == "Head")
                {
                    limb.gameObject.AddComponent<UseEventTrigger>().Action = () =>
                    {
                        if (Active == false) return;

                        if (CanUse == false) StartCoroutine(WaitForClick(limb.transform));
                        else CanUse = false;
                    };
                }
            }
        }

        private IEnumerator WaitForClick(Transform Head)
        {
            CanUse = true;

            while (Active == true && CanUse == true)
            {
                if (DbpuInputUtil.Down(DBPU.InstantTransmissionActionId, KeyCode.R) && Teleporting == false && KiSys.currentKi > KiSys.maxKi / 10f)
                {
                    StartCoroutine(KiCost());
                    StartCoroutine(Teleport(Head));
                    Teleporting = true;

                    yield return null;
                }

                yield return null;
            }

            yield return null;
        }

        private IEnumerator KiCost()
        {
            if (DBPU.KiAttackCostMultiplier == 0f) yield break;

            float OGKiDrain = KiSys.currentKiDrainRate;
            float KiRegen = KiSys.baseRegen;

            if (OGKiDrain != 0f) KiSys.baseRegen = 0f;

            float FinalKi = KiSys.currentKi - (KiSys.maxKi * CostPercent);
            float CurrentKi = KiSys.currentKi;

            while (CurrentKi > FinalKi)
            {
                KiSys.currentKi -= (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier)) * (Time.deltaTime);
                CurrentKi -= (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier)) * (Time.deltaTime);

                yield return new WaitForEndOfFrame();
            }

            if (OGKiDrain != 0f) KiSys.baseRegen = KiRegen;

            yield return null;
        }

        private IEnumerator Teleport(Transform Head)
        {
            if (audioSource.volume != DBPU.PowersVolume) audioSource.volume = DBPU.PowersVolume;

            //CreateShadow(Head);

            //yield return new WaitUntil(() => !Input.GetMouseButtonDown(0) || !person.IsAlive());

            //yield return new WaitUntil(() => Input.GetMouseButtonDown(0) || !person.IsAlive());

            audioSource.PlayOneShot(DBPU.Misc_IT);

            foreach (var fix in GetComponentsInChildren<FixedJoint2D>())
            {
                foreach (var sr in fix.connectedBody.transform.root.GetComponentsInChildren<SpriteRenderer>())
                {
                    sr.maskInteraction = SpriteMaskInteraction.VisibleInsideMask;
                }

                foreach (var col in fix.connectedBody.transform.root.GetComponentsInChildren<Collider2D>())
                {
                    if (!col.gameObject.GetComponent<FreezeBehaviour>()) col.gameObject.AddComponent<FreezeBehaviour>();
                    col.isTrigger = true;
                }
            }

            foreach (var limb in person.Limbs)
            {
                if (limb.gameObject == null) continue;

                if (!limb.gameObject.GetComponent<FreezeBehaviour>()) limb.gameObject.AddComponent<FreezeBehaviour>();

                if (MCP_Utils.LimbCanUsePowers(limb) && limb.name.Contains("LowerArm"))
                {
                    foreach (var hin in limb.gameObject.GetComponentsInChildren<HingeJoint2D>())
                    {
                        if (hin.connectedBody.gameObject.transform.root.gameObject != gameObject)
                        {
                            if (hin.connectedBody.gameObject.GetComponent<LimbBehaviour>())
                            {
                                foreach (var limbs2 in hin.connectedBody.gameObject.GetComponent<LimbBehaviour>().Person.Limbs)
                                {
                                    if (!limbs2.gameObject.GetComponent<FreezeBehaviour>()) limbs2.gameObject.AddComponent<FreezeBehaviour>();
                                }

                                foreach (var sr in hin.connectedBody.gameObject.transform.root.GetComponentsInChildren<SpriteRenderer>())
                                {
                                    sr.maskInteraction = SpriteMaskInteraction.VisibleInsideMask;
                                }

                                foreach (var col in hin.connectedBody.gameObject.transform.root.GetComponentsInChildren<Collider2D>())
                                {
                                    col.isTrigger = true;
                                }

                                foreach (var fix in hin.connectedBody.gameObject.transform.root.GetComponentsInChildren<FixedJoint2D>())
                                {
                                    foreach (var sr in fix.connectedBody.transform.root.GetComponentsInChildren<SpriteRenderer>())
                                    {
                                        sr.maskInteraction = SpriteMaskInteraction.VisibleInsideMask;
                                    }

                                    foreach (var col in fix.connectedBody.transform.root.GetComponentsInChildren<Collider2D>())
                                    {
                                        if (!col.gameObject.GetComponent<FreezeBehaviour>()) col.gameObject.AddComponent<FreezeBehaviour>();
                                        col.isTrigger = true;
                                    }
                                }
                            }

                            else if (hin.connectedBody.gameObject.GetComponent<Rigidbody2D>())
                            {
                                foreach (var sr in hin.connectedBody.transform.root.GetComponentsInChildren<SpriteRenderer>())
                                {
                                    sr.maskInteraction = SpriteMaskInteraction.VisibleInsideMask;
                                }

                                foreach (var col in hin.connectedBody.transform.root.GetComponentsInChildren<Collider2D>())
                                {
                                    if (!col.gameObject.GetComponent<FreezeBehaviour>()) col.gameObject.AddComponent<FreezeBehaviour>();
                                    col.isTrigger = true;
                                }
                            }
                        }
                    }
                }
            }

            foreach (var col in GetComponentsInChildren<Collider2D>())
            {
                col.isTrigger = true;
            }

            //yield return new WaitForFixedUpdate();

            Vector3 NewPosition = Global.main.MousePosition - Head.position;

            GameObject MaskObject = new GameObject();
            SpriteMask mask = MaskObject.gameObject.AddComponent<SpriteMask>();
            mask.transform.position = MCP_Utils.GetMiddlePositionOfBody(person);
            mask.transform.localScale = new Vector3(0.4f, 0.4f, 1f);
            mask.sprite = Effect[0];
            mask.isCustomRangeActive = false;

            foreach (var sr in GetComponentsInChildren<SpriteRenderer>())
            {
                sr.maskInteraction = SpriteMaskInteraction.VisibleInsideMask;
            }

            for (int i = 0; i < Effect.Count; i++)
            {
                mask.sprite = Effect[i];

                yield return new WaitForSeconds(0.005f);
            }

            foreach (var limb in person.Limbs)
            {
                if (limb.gameObject == null) continue;

                limb.transform.position += NewPosition;

                if (MCP_Utils.LimbCanUsePowers(limb) && limb.name.Contains("LowerArm"))
                {
                    foreach (var hin in limb.gameObject.GetComponentsInChildren<HingeJoint2D>())
                    {
                        if (hin.connectedBody.gameObject.transform.root.gameObject != gameObject)
                        {
                            if (hin.connectedBody.gameObject.GetComponent<LimbBehaviour>())
                            {
                                foreach (var limbs2 in hin.connectedBody.gameObject.GetComponent<LimbBehaviour>().Person.Limbs)
                                {
                                    limbs2.transform.position += NewPosition;
                                }

                                foreach (var fix in hin.connectedBody.gameObject.transform.root.GetComponentsInChildren<FixedJoint2D>())
                                {
                                    fix.connectedBody.gameObject.transform.position += NewPosition;
                                }
                            }

                            else if (hin.connectedBody.gameObject.GetComponent<Rigidbody2D>())
                            {
                                hin.connectedBody.transform.position += NewPosition;
                            }
                        }
                    }
                }
            }

            foreach (var fix in GetComponentsInChildren<FixedJoint2D>())
            {
                fix.connectedBody.gameObject.transform.position += NewPosition;
            }

            mask.transform.position = MCP_Utils.GetMiddlePositionOfBody(person);

            for (int i = Effect.Count - 1; i > 0; i--)
            {
                mask.sprite = Effect[i];

                yield return new WaitForSeconds(0.005f);
            }

            foreach (var sr in GetComponentsInChildren<SpriteRenderer>())
            {
                sr.maskInteraction = SpriteMaskInteraction.None;
            }

            if (MaskObject != null) Destroy(MaskObject);

            foreach (var limb in person.Limbs)
            {
                if (limb.gameObject == null) continue;

                Destroy(limb.gameObject.GetComponent<FreezeBehaviour>());

                if (MCP_Utils.LimbCanUsePowers(limb) && limb.name.Contains("LowerArm"))
                {
                    foreach (var hin in limb.gameObject.GetComponentsInChildren<HingeJoint2D>())
                    {
                        if (hin.connectedBody.gameObject.transform.root.gameObject != gameObject)
                        {
                            if (hin.connectedBody.gameObject.GetComponent<LimbBehaviour>())
                            {
                                foreach (var limbs2 in hin.connectedBody.gameObject.GetComponent<LimbBehaviour>().Person.Limbs)
                                {
                                    if (limbs2.gameObject.GetComponent<FreezeBehaviour>()) Destroy(limbs2.gameObject.GetComponent<FreezeBehaviour>());
                                    MCP_Utils.ForceClearViaExit(limbs2.PhysicalBehaviour);
                                }

                                foreach (var sr in hin.connectedBody.gameObject.transform.root.GetComponentsInChildren<SpriteRenderer>())
                                {
                                    sr.maskInteraction = SpriteMaskInteraction.None;
                                }

                                foreach (var col in hin.connectedBody.gameObject.transform.root.GetComponentsInChildren<Collider2D>())
                                {
                                    col.isTrigger = false;
                                }

                                foreach (var fix in hin.connectedBody.gameObject.transform.root.GetComponentsInChildren<FixedJoint2D>())
                                {
                                    foreach (var sr in fix.connectedBody.transform.root.GetComponentsInChildren<SpriteRenderer>())
                                    {
                                        sr.maskInteraction = SpriteMaskInteraction.None;
                                    }

                                    foreach (var col in fix.connectedBody.transform.root.GetComponentsInChildren<Collider2D>())
                                    {
                                        if (col.gameObject.GetComponent<FreezeBehaviour>()) Destroy(col.gameObject.GetComponent<FreezeBehaviour>());
                                        MCP_Utils.ForceClearViaExit(col.gameObject.GetComponent<PhysicalBehaviour>());
                                        col.isTrigger = false;
                                    }
                                }
                            }

                            else if (hin.connectedBody.gameObject.GetComponent<Rigidbody2D>())
                            {
                                foreach (var sr in hin.connectedBody.transform.root.GetComponentsInChildren<SpriteRenderer>())
                                {
                                    sr.maskInteraction = SpriteMaskInteraction.None;
                                }

                                foreach (var col in hin.connectedBody.transform.root.GetComponentsInChildren<Collider2D>())
                                {
                                    if (col.gameObject.GetComponent<FreezeBehaviour>()) Destroy(col.gameObject.GetComponent<FreezeBehaviour>());
                                    MCP_Utils.ForceClearViaExit(col.gameObject.GetComponent<PhysicalBehaviour>());
                                    col.isTrigger = false;
                                }
                            }
                        }
                    }
                }
            }

            foreach (var col in GetComponentsInChildren<Collider2D>())
            {
                col.isTrigger = false;
            }

            foreach (var fix in GetComponentsInChildren<FixedJoint2D>())
            {
                foreach (var sr in fix.connectedBody.transform.root.GetComponentsInChildren<SpriteRenderer>())
                {
                    sr.maskInteraction = SpriteMaskInteraction.None;
                }

                foreach (var col in fix.connectedBody.transform.root.GetComponentsInChildren<Collider2D>())
                {
                    if (col.gameObject.GetComponent<FreezeBehaviour>()) Destroy(col.gameObject.GetComponent<FreezeBehaviour>());
                    MCP_Utils.ForceClearViaExit(col.gameObject.GetComponent<PhysicalBehaviour>());
                    col.isTrigger = false;
                }
            }

            person.ForceAllLimbsClearViaExit();

            IsTeleporting = false;
            Teleporting = false;

            yield return null;
        }

        private IEnumerator CreateShadow(Transform Head)
        {
            Shadow = new GameObject();
            Shadow.transform.position = Head.position;

            foreach (var fix in GetComponentsInChildren<FixedJoint2D>())
            {
                foreach (var sr in fix.connectedBody.transform.root.GetComponentsInChildren<SpriteRenderer>())
                {
                    GameObject ShadowImage = new GameObject("Shadow Image");
                    ShadowImage.AddComponent<SpriteRenderer>().sprite = sr.sprite;
                    //ShadowImage.AddComponent<SpriteRenderer>().color = new Color(0f, 0f, 0f);
                    ShadowImage.transform.position = sr.gameObject.transform.position;
                    ShadowImage.transform.localScale = sr.gameObject.transform.localScale;
                    ShadowImage.transform.SetParent(Shadow.transform);
                }
            }

            foreach (var sr in GetComponentsInChildren<SpriteRenderer>())
            {
                GameObject ShadowImage = new GameObject("Shadow Image");
                ShadowImage.AddComponent<SpriteRenderer>().sprite = sr.sprite;
                //ShadowImage.AddComponent<SpriteRenderer>().color = new Color(0f, 0f, 0f);
                ShadowImage.transform.position = sr.gameObject.transform.position;
                ShadowImage.transform.localScale = sr.gameObject.transform.localScale;
                ShadowImage.transform.SetParent(Shadow.transform);
            }

            Shadow.transform.position = Global.main.MousePosition;

            while (IsTeleporting == true || Teleporting == true)
            {
                Shadow.transform.position = Global.main.MousePosition;
            }

            Destroy(Shadow);

            yield return null;
        }
    }

    [DefaultExecutionOrder(-50)]
    public class BlastBehaviour : MonoBehaviour
    {
        private MultipliersAndStuffs Multipliers;
        private KiSystem KiSys;

        public bool IsBarrage = false;
        public int barrageAmount = 0;

        public bool Active = false;
        public bool Firing = false;
        public float RealDamage = 100f;
        public float CostPercent = 0.005f;
        public float BarrageCostPercent = 0.0025f;
        public float KnockbackMultiplier = 1f;
        public float ExplosionSizeMultiplier = 1f;
        public float DamageOutput = 1f;

        public float Damage = 0f;
        public float Speed = 80f;
        public string ID = "Blast";

        private void Update()
        {
            if (Firing == true)
            {
                RealDamage = (Damage * Multipliers.FinalMultiplier) * Multipliers.KiOutput * DamageOutput;
            }

            if (Active == true && IsBarrage == true)
            {
                foreach (var limb in GetComponent<PersonBehaviour>().Limbs)
                {
                    if (MCP_Utils.LimbCanUsePowers(limb) && limb.name.Contains("LowerArm"))
                    {
                        if (!KiHandLoadout.LegacyAllowed(limb, IsBarrage ? "KiBlastBarrage" : "KiBlast")) continue;
                        if (limb.PhysicalBehaviour.IsBeingUsedContinuously())
                        {
                            if (!limb.Person.IsAlive() || limb.Health <= 0f || Firing == true || KiSys.currentKi < KiSys.maxKi * (CostPercent * 4f)) return;

                            StartCoroutine(Fire(limb.transform));
                        }
                        ;
                    }
                }
            }
        }

        private void Start()
        {
            if (!GetComponent<KiSystem>()) gameObject.AddComponent<KiSystem>();
            KiSys = GetComponent<KiSystem>();

            if (!GetComponent<MultipliersAndStuffs>()) gameObject.AddComponent<MultipliersAndStuffs>();
            Multipliers = GetComponent<MultipliersAndStuffs>();

            if (Damage == 0f) Damage = (CombatPowerController.AttackHealth(GetComponent<PersonBehaviour>()) / Multipliers.FinalMultiplier) / 200f;

            ID = gameObject.name + "_Blast" + UnityEngine.Random.Range(0, 999);

            foreach (var limb in GetComponent<PersonBehaviour>().Limbs)
            {
                if (MCP_Utils.LimbCanUsePowers(limb) && limb.name.Contains("LowerArm"))
                {
                    var trigger = limb.gameObject.GetOrAddComponent<UseEventTrigger>();
                    Action previous = trigger.Action;
                    LimbBehaviour capturedLimb = limb;
                    trigger.Action = () =>
                    {
                        if (!KiHandLoadout.LegacyAllowed(capturedLimb, IsBarrage ? "KiBlastBarrage" : "KiBlast"))
                        { previous?.Invoke(); return; }
                        if (IsBarrage == true || !capturedLimb.Person.IsAlive() || capturedLimb.Health <= 0f || Active == false || Firing == true || KiSys.currentKi < KiSys.maxKi * (CostPercent * 4f))
                        {
                            previous?.Invoke();
                            return;
                        }

                        StartCoroutine(Fire(capturedLimb.transform));
                    };
                }
            }
        }

        private IEnumerator Fire(Transform Arm)
        {
            Firing = true;

            if (IsBarrage == false)
            {
                CostPercent = 0.005f;
                StartCoroutine(KiCost());

                //GameObject Blast = Instantiate(DBPU.KiBlast_End, Arm.position, Arm.rotation * Quaternion.Euler(0, 0, -90));
                GameObject Blast = new GameObject("KiBlast");
                Blast.gameObject.layer = 9;
                Blast.transform.localScale = new Vector3(0.35f, 0.35f, 0.35f);
                Blast.transform.position = Arm.position + (-Arm.up * 0.3f);
                Blast.transform.rotation = Arm.rotation * Quaternion.Euler(0, 0, -90);
                Blast.gameObject.AddComponent<Rigidbody2D>().bodyType = RigidbodyType2D.Dynamic;
                Blast.gameObject.GetComponent<Rigidbody2D>().interpolation = RigidbodyInterpolation2D.Interpolate;
                if (Blast.gameObject.GetComponent<Rigidbody2D>().bodyType != RigidbodyType2D.Static) Blast.gameObject.GetComponent<Rigidbody2D>().velocity = Blast.transform.right * Speed;
                Blast.gameObject.GetComponent<Rigidbody2D>().fixedAngle = true;
                Blast.gameObject.AddComponent<CircleCollider2D>().radius = 0.6f;
                Blast.gameObject.AddComponent<BlastVFX>().KiSys = KiSys;

                foreach (var c1 in GetComponent<PersonBehaviour>().Limbs)
                    Physics2D.IgnoreCollision(c1.gameObject.GetComponent<Collider2D>(), Blast.gameObject.GetComponent<CircleCollider2D>(), true);


                /*Blast.transform.Find("Blast Color").gameObject.GetComponent<ParticleSystem>().startColor = KiColor(KiSys.CurrentForm);

                GetAllChildrenRecursive(Blast.transform);

                foreach (Transform child in Blast.transform)
                {
                    var sp = child.gameObject.GetComponent<Renderer>();
                    sp.sortingLayerName = Arm.gameObject.GetComponent<SpriteRenderer>().sortingLayerName;
                    sp.sortingOrder += 10;
                    }

                ChangePlayBackOfAllParticleSystems(Blast.transform, 2f);*/
                var blastComp = Blast.gameObject.AddComponent<BlastComponent>();
                blastComp.User = gameObject;
                blastComp.Damage = RealDamage;
                blastComp.ID = ID;
                blastComp.KnockbackMultiplier = KnockbackMultiplier;
                blastComp.ExplosionSizeMultiplier = ExplosionSizeMultiplier * Mathf.Max(0.1f, DBPU.KiBlast_ExplosionSizeMultiplier);

                GameObject FireEffect = Instantiate(DBPU.KiBlast_Start, Arm.position - (Arm.up * 0.3f), Arm.rotation * Quaternion.Euler(0, 0, -90));
                FireEffect.transform.localScale = new Vector3(0.35f, 0.35f, 0.35f);
                ChangePlayBackOfAllParticleSystems(FireEffect.transform, 2f);
                FireEffect.transform.Find("Blast Color").gameObject.GetComponent<ParticleSystem>().startColor = KiColor(KiSys.CurrentForm);

                GetAllChildrenRecursive(FireEffect.transform);

                foreach (Transform child in FireEffect.transform)
                {
                    var sp = child.gameObject.GetComponent<Renderer>();
                    sp.sortingLayerName = Arm.gameObject.GetComponent<SpriteRenderer>().sortingLayerName;
                    sp.sortingOrder += 10;
                }

                AudioSource BlastAudio = new GameObject("BlastAudioSource").AddComponent<AudioSource>();
                BlastAudio.transform.SetParent(FireEffect.transform, false);
                Global global = FindObjectOfType<Global>();
                global.AddAudioSource(BlastAudio, false);
                BlastAudio.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.75f;
                BlastAudio.outputAudioMixerGroup = global.SoundEffects;
                BlastAudio.spatialBlend = 1;
                BlastAudio.volume = DBPU.PowersVolume;
                BlastAudio.maxDistance = 1000;
                BlastAudio.PlayOneShot(DBPU.Attack_KiBlast_Fire);

                yield return new WaitForSeconds(0.1f);

                Firing = false;

                yield return new WaitForSeconds(0.9f);

                Destroy(FireEffect.gameObject);
            }

            else
            {
                CostPercent = BarrageCostPercent;
                StartCoroutine(KiCost());

                /*GameObject Blast = Instantiate(DBPU.KiBlast_End, Arm.position, Arm.rotation * Quaternion.Euler(0, 0, UnityEngine.Random.Range(-75, -105)));
                Blast.gameObject.layer = 9;
                Blast.transform.localScale = new Vector3(0.35f, 0.35f, 0.35f);
                Blast.gameObject.GetComponent<Rigidbody2D>().bodyType = RigidbodyType2D.Kinematic;
                Blast.gameObject.GetComponent<CircleCollider2D>().isTrigger = true;
                Blast.gameObject.GetComponent<CircleCollider2D>().radius = 1.4f;
                Blast.transform.Find("Blast Color").gameObject.GetComponent<ParticleSystem>().startColor = KiColor(KiSys.CurrentForm);

                GetAllChildrenRecursive(Blast.transform);

                foreach (Transform child in Blast.transform)
                {
                    var sp = child.gameObject.GetComponent<Renderer>();
                    sp.sortingLayerName = Arm.gameObject.GetComponent<SpriteRenderer>().sortingLayerName;
                    sp.sortingOrder += 10;
                    }

                ChangePlayBackOfAllParticleSystems(Blast.transform, 2f);*/

                GameObject Blast = new GameObject("KiBlast");
                Blast.gameObject.layer = 9;
                Blast.transform.localScale = new Vector3(0.35f, 0.35f, 0.35f);
                Blast.transform.position = Arm.position + (-Arm.up * 0.3f);
                Blast.transform.rotation = Arm.rotation * Quaternion.Euler(0, 0, UnityEngine.Random.Range(-75, -105));
                Blast.gameObject.AddComponent<Rigidbody2D>().bodyType = RigidbodyType2D.Dynamic;
                Blast.gameObject.GetComponent<Rigidbody2D>().interpolation = RigidbodyInterpolation2D.Interpolate;
                if (Blast.gameObject.GetComponent<Rigidbody2D>().bodyType != RigidbodyType2D.Static) Blast.gameObject.GetComponent<Rigidbody2D>().velocity = Blast.transform.right * Speed;
                Blast.gameObject.GetComponent<Rigidbody2D>().fixedAngle = true;
                Blast.gameObject.AddComponent<CircleCollider2D>().radius = 0.6f;
                Blast.gameObject.AddComponent<BlastVFX>().KiSys = KiSys;

                foreach (var c1 in GetComponent<PersonBehaviour>().Limbs)
                    Physics2D.IgnoreCollision(c1.gameObject.GetComponent<Collider2D>(), Blast.gameObject.GetComponent<CircleCollider2D>(), true);

                var barrageBlastComp = Blast.gameObject.AddComponent<BlastComponent>();
                barrageBlastComp.User = gameObject;
                barrageBlastComp.Damage = RealDamage;
                barrageBlastComp.ID = ID;
                barrageBlastComp.KnockbackMultiplier = KnockbackMultiplier;
                barrageBlastComp.ExplosionSizeMultiplier = ExplosionSizeMultiplier * Mathf.Max(0.1f, DBPU.KiBlast_ExplosionSizeMultiplier);

                GameObject FireEffect = Instantiate(DBPU.KiBlast_Start, Arm.position - (Arm.up * 0.3f), Arm.rotation * Quaternion.Euler(0, 0, -90));
                FireEffect.transform.localScale = new Vector3(0.35f, 0.35f, 0.35f);
                ChangePlayBackOfAllParticleSystems(FireEffect.transform, 2f);
                FireEffect.transform.Find("Blast Color").gameObject.GetComponent<ParticleSystem>().startColor = KiColor(KiSys.CurrentForm);

                GetAllChildrenRecursive(FireEffect.transform);

                foreach (Transform child in FireEffect.transform)
                {
                    var sp = child.gameObject.GetComponent<Renderer>();
                    sp.sortingLayerName = Arm.gameObject.GetComponent<SpriteRenderer>().sortingLayerName;
                    sp.sortingOrder += 10;
                }

                if (barrageAmount == 0)
                {
                    AudioSource BlastAudio = new GameObject("BlastAudioSource").AddComponent<AudioSource>();
                    BlastAudio.transform.SetParent(FireEffect.transform, false);
                    Global global = FindObjectOfType<Global>();
                    global.AddAudioSource(BlastAudio, false);
                    BlastAudio.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.75f;
                    BlastAudio.outputAudioMixerGroup = global.SoundEffects;
                    BlastAudio.spatialBlend = 1;
                    BlastAudio.volume = DBPU.PowersVolume;
                    BlastAudio.maxDistance = 1000;
                    BlastAudio.PlayOneShot(DBPU.Attack_KiBlast_Fire);

                    barrageAmount += 1;
                }

                else
                {
                    barrageAmount = 0;
                }

                yield return new WaitForSeconds(0.05f);

                Firing = false;

                yield return new WaitForSeconds(0.9f);

                Destroy(FireEffect.gameObject);
            }

            yield return null;
        }

        private IEnumerator KiCost()
        {
            if (DBPU.KiAttackCostMultiplier == 0f) yield break;

            float OGKiDrain = KiSys.currentKiDrainRate;
            float KiRegen = KiSys.baseRegen;

            if (OGKiDrain != 0f) KiSys.baseRegen = 0f;

            float FinalKi = KiSys.currentKi - (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier));
            float CurrentKi = KiSys.currentKi;

            while (CurrentKi > FinalKi)
            {
                KiSys.currentKi -= (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier)) * (Time.deltaTime);
                CurrentKi -= (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier)) * (Time.deltaTime);

                yield return new WaitForEndOfFrame();
            }

            if (OGKiDrain != 0f) KiSys.baseRegen = KiRegen;

            yield return null;
        }

