            if (EffectID == "Energy Wave")
            {
                if (MiddleBeam.startWidth < Width)
                {
                    MiddleBeam.startWidth += (Width * 3.5f) * Time.deltaTime;
                    MiddleBeam.endWidth += (Width * 3.5f) * Time.deltaTime;
                }

                else
                {
                    if (ExtraWidth > 0f) ExtraWidth -= Width * Time.deltaTime;
