        void DamageArms(float DamageDealt)
        {
            foreach (var limb in GetComponent<PersonBehaviour>().Limbs)
            {
                if (MCP_Utils.LimbCanUsePowers(limb) && limb.name.Contains("Arm")) limb.Damage(DamageDealt);
            }
        }

        Vector3 GetEndPosition()
        {
            if (StartBeam == null) return EndBeamPosition;
            return StartBeam.transform.position + (BeamDirection * (StartDistance + Distance)) + (StartBeam.transform.up * StartOffSet);
        }

        public void SyncEndBeamTransform()
        {
            if (EndBeam == null) return;
            EndBeam.transform.position = GetEndPosition();
        }

        void SyncToMergeHost()
        {
            if (MergeHost == null) return;

            Distance = MergeHost.Distance;
            EndBeamPosition = MergeHost.EndBeamPosition;
            BeamDirection = MergeHost.BeamDirection;

            if (EndBeam != null)
            {
                if (MergeHost.EndBeam != null)
                    EndBeam.transform.position = MergeHost.EndBeam.transform.position;
                else if (MergeHost.StartBeam != null)
                    EndBeam.transform.position = MergeHost.GetEndPosition();
            }

            if (MiddleBeam != null && MergeHost.MiddleBeam != null && MiddleBeam.positionCount >= 2 && MergeHost.MiddleBeam.positionCount >= 2)
            {
                MiddleBeam.SetPosition(0, MergeHost.MiddleBeam.GetPosition(0));
                MiddleBeam.SetPosition(1, MergeHost.MiddleBeam.GetPosition(1));
            }
        }

        Vector3 GetSoundPosition()
        {
            float minX = Mathf.Min(StartBeam.transform.position.x, EndBeam.transform.position.x);
            float maxX = Mathf.Max(StartBeam.transform.position.x, EndBeam.transform.position.x);

            float minY = Mathf.Min(StartBeam.transform.position.y, EndBeam.transform.position.y);
            float maxY = Mathf.Max(StartBeam.transform.position.y, EndBeam.transform.position.y);

            float clampedX = Mathf.Clamp(Global.CameraPosition.x, minX, maxX);
            float clampedY = Mathf.Clamp(Global.CameraPosition.y, minY, maxY);

            return new Vector3(clampedX, clampedY);
        }
    }

    public class BeamClashShockwaveMarker : MonoBehaviour
    {
        public float BaseScale = 3f;
        public float OrbVisualRadius = 0.35f;
        public float MinRingRadius = 0.4f;
        public float MaxRingRadius = 12f;
        public float RingExpandSpeed = 9f;
        public LineRenderer[] Rings;
        public float[] RingRadii;
        public SpriteRenderer CoreOrb;
    }

    public class BeamComponent : MonoBehaviour
    {
        public BeamBehaviour beamBehaviour;

        static readonly List<(BeamBehaviour a, BeamBehaviour b)> ActiveBeamClashes = new List<(BeamBehaviour, BeamBehaviour)>();

        static void RegisterBeamClash(BeamBehaviour a, BeamBehaviour b)
        {
            if (a == null || b == null) return;
            for (int i = 0; i < ActiveBeamClashes.Count; i++)
            {
                var pair = ActiveBeamClashes[i];
                if ((pair.a == a && pair.b == b) || (pair.a == b && pair.b == a))
                    return;
            }
            ActiveBeamClashes.Add((a, b));
        }

        static void UnregisterBeamClash(BeamBehaviour a, BeamBehaviour b)
        {
            for (int i = ActiveBeamClashes.Count - 1; i >= 0; i--)
            {
                var pair = ActiveBeamClashes[i];
                if ((pair.a == a && pair.b == b) || (pair.a == b && pair.b == a))
                    ActiveBeamClashes.RemoveAt(i);
            }
        }

        static void PruneActiveBeamClashes()
        {
            for (int i = ActiveBeamClashes.Count - 1; i >= 0; i--)
            {
                var pair = ActiveBeamClashes[i];
                if (pair.a == null || pair.b == null || !pair.a.Firing || !pair.b.Firing || !pair.a.Clashing || !pair.b.Clashing)
                    ActiveBeamClashes.RemoveAt(i);
            }
        }

        public float DistanceOfWallContact = 0f;
        public float MinDistanceToLose = 3f;
        public float SafeMargin = 1f;
        public bool HitAWall = false;
        public Vector3 RayDirection;

        bool IsSpecialBeamCannon => beamBehaviour != null && beamBehaviour.EffectID == "Special Beam Cannon";

        float GetPersonCombatPower(PersonBehaviour person)
        {
            if (person == null) return 0f;
            var mult = person.GetComponent<MultipliersAndStuffs>();
            float formMult = mult != null ? mult.FinalMultiplier : 1f;
            float kiOut = mult != null ? mult.KiOutput : 1f;
            return MCP_Utils.AverageMaxHealth(person) / CombatPowerController.HealthScale(person) / CombatPowerController.KaiokenHealthScale(person) * formMult * kiOut;
        }

        bool IsPersonStrongerThanAttacker(PersonBehaviour target)
        {
            if (target == null || !IsSpecialBeamCannon) return false;
            var attacker = beamBehaviour.GetComponent<PersonBehaviour>();
            if (attacker == null || target == attacker) return false;
            return GetPersonCombatPower(target) > GetPersonCombatPower(attacker) * 1.08f;
        }

        float GetDistAlongBeam(Vector3 worldPoint)
        {
            if (beamBehaviour.MiddleBeam == null || beamBehaviour.MiddleBeam.positionCount < 2)
                return beamBehaviour.Distance;
            Vector3 a = beamBehaviour.MiddleBeam.GetPosition(0);
            Vector3 b = beamBehaviour.MiddleBeam.GetPosition(1);
            Vector3 dir = (b - a).normalized;
            return Mathf.Clamp(Vector3.Dot(worldPoint - a, dir), 0f, beamBehaviour.Distance);
        }

        Vector3 GetBeamTipWorld(BeamBehaviour beam)
        {
            if (beam == null) return Vector3.zero;
            if (beam.EndBeam != null)
                return beam.EndBeam.transform.position;
            return beam.StartBeamPosition + beam.BeamDirection.normalized * beam.Distance;
        }

        Vector3 GetBeamClashPoint(BeamBehaviour a, BeamBehaviour b)
        {
            return (GetBeamTipWorld(a) + GetBeamTipWorld(b)) * 0.5f;
        }

        void SyncBeamTipTransform(BeamBehaviour beam)
        {
            if (beam == null) return;
            beam.SyncEndBeamTransform();
        }

        LineRenderer CreateExpandingRing(Transform parent, Material mat, float radius, float zRot)
        {
            GameObject go = new GameObject("ClashRing");
            go.transform.SetParent(parent, false);
            go.transform.localRotation = Quaternion.Euler(0f, 0f, zRot);

            LineRenderer lr = go.AddComponent<LineRenderer>();
            lr.useWorldSpace = false;
            lr.loop = true;
            lr.material = new Material(mat != null ? mat : ModAPI.FindMaterial("VeryBright"));
            lr.sortingLayerName = "Bubbles";
            lr.sortingOrder = 525;
            lr.textureMode = LineTextureMode.Tile;
            if (DBPU.StraightBeam_Texture != null)
                lr.material.mainTexture = DBPU.StraightBeam_Texture;

            int segments = 40;
            lr.positionCount = segments;
            SetRingPositions(lr, radius, segments);

            Color ringColor = new Color(1f, 1f, 1f, 0.9f);
            lr.startColor = ringColor;
            lr.endColor = ringColor;
            float thin = 0.1f * DBPU.Beam_SizeMultiplier;
            lr.startWidth = thin;
            lr.endWidth = thin;
            lr.numCapVertices = 2;
            return lr;
        }

        void SetRingPositions(LineRenderer lr, float radius, int segments)
        {
            if (lr == null) return;
            if (segments <= 0) segments = lr.positionCount;
            for (int i = 0; i < segments; i++)
            {
                float ang = (i / (float)segments) * Mathf.PI * 2f;
                lr.SetPosition(i, new Vector3(Mathf.Cos(ang) * radius, Mathf.Sin(ang) * radius, -0.01f));
            }
        }

        SpriteRenderer CreateClashOrb(Transform parent, float scale)
        {
            GameObject orb = new GameObject("ClashOrb");
            orb.transform.SetParent(parent, false);
            orb.transform.localPosition = Vector3.zero;

            SpriteRenderer sr = orb.AddComponent<SpriteRenderer>();
            sr.sprite = DBPU.KiShield_Sprite;
            sr.material = ModAPI.FindMaterial("VeryBright");
            sr.color = new Color(0.88f, 0.92f, 0.98f, 0.09f);
            sr.sortingLayerName = "Bubbles";
            sr.sortingOrder = 515;
            float orbSize = scale * 0.065f;
            orb.transform.localScale = new Vector3(orbSize, orbSize, 1f);
            return sr;
        }

        void BoostParticleVisibility(GameObject root)
        {
            if (root == null) return;
            foreach (Renderer r in root.GetComponentsInChildren<Renderer>(true))
            {
                if (r == null) continue;
                r.sortingLayerName = "Bubbles";
                r.sortingOrder += 520;
            }
        }

        void SpawnClashImpactBurst(Vector3 position, float scale)
        {
            if (DBPU.KiBlast_Hit == null) return;

            GameObject core = Instantiate(DBPU.KiBlast_Hit, position, Quaternion.identity);
            core.transform.localScale = Vector3.one * scale * 1.9f;
            BoostParticleVisibility(core);
            foreach (Transform child in core.transform)
            {
                ParticleSystem ps = child.GetComponent<ParticleSystem>();
                if (ps != null) ps.Play(true);
            }
            core.AddComponent<DestroyOverTime>().Timer = 0.5f;
        }

        float GetClashOrbVisualRadius(SpriteRenderer sr)
        {
            if (sr == null || sr.sprite == null) return 0.5f;
            return sr.sprite.bounds.extents.x * sr.transform.localScale.x;
        }

        GameObject SpawnClashShockwave(Vector3 position, BeamBehaviour a, BeamBehaviour b)
        {
            GameObject root = new GameObject("BeamClashShockwave");
            root.transform.position = position;

            float scale = Mathf.Clamp(2f + (a.Width + b.Width) * 0.35f, 2.5f, 10f) * DBPU.Beam_SizeMultiplier;
            Material mat = ModAPI.FindMaterial("VeryBright");

            BeamClashShockwaveMarker marker = root.AddComponent<BeamClashShockwaveMarker>();
            marker.BaseScale = scale;
            marker.CoreOrb = CreateClashOrb(root.transform, scale);

            float orbVisualRadius = GetClashOrbVisualRadius(marker.CoreOrb);
            float startRadius = orbVisualRadius * 1.5f;
            float maxRingRadius = orbVisualRadius * 6.5f;

            LineRenderer ringA = CreateExpandingRing(root.transform, mat, startRadius, 0f);
            LineRenderer ringB = CreateExpandingRing(root.transform, mat, startRadius * 0.92f, 0f);

            marker.OrbVisualRadius = orbVisualRadius;
            marker.MinRingRadius = startRadius;
            marker.MaxRingRadius = maxRingRadius;
            marker.RingExpandSpeed = 13f * DBPU.Beam_SizeMultiplier;
            marker.Rings = new[] { ringA, ringB };
            marker.RingRadii = new[] { startRadius, startRadius * 0.92f };

            SpawnClashImpactBurst(position, scale);

            if (CameraShakeBehaviour.main != null)
                CameraShakeBehaviour.main.Shake(0.55f, position);

            AudioSource shockAudio = root.AddComponent<AudioSource>();
            Global global = FindObjectOfType<Global>();
            if (global != null)
            {
                global.AddAudioSource(shockAudio, false);
                shockAudio.outputAudioMixerGroup = global.SoundEffects;
            }
            shockAudio.spatialBlend = 1f;
            shockAudio.volume = DBPU.PowersVolume * 0.5f;
            shockAudio.maxDistance = 1200f;
            shockAudio.PlayOneShot(DBPU.Attack_KiBlast_Impact);

            return root;
        }

        IEnumerator PlayClashShockwaveOneShot(Vector3 position, BeamBehaviour a, BeamBehaviour b)
        {
            GameObject root = SpawnClashShockwave(position, a, b);
            ApplyClashShockwaveDestruction(position, a, b, GetClashSideRoll(a) + GetClashSideRoll(b));

            float duration = 0.82f;
            float elapsed = 0f;
            while (elapsed < duration && root != null)
            {
                UpdateClashShockwaveOneShot(root, Time.deltaTime, elapsed / duration);
                elapsed += Time.deltaTime;
                yield return null;
            }

            if (root != null)
                Destroy(root);
        }

        void UpdateClashShockwaveOneShot(GameObject root, float delta, float normalizedTime)
        {
            if (root == null) return;

            BeamClashShockwaveMarker marker = root.GetComponent<BeamClashShockwaveMarker>();
            if (marker == null) return;

            if (marker.CoreOrb != null)
            {
                float swell = Mathf.Clamp01(normalizedTime / 0.18f);
                float fade = 1f - Mathf.Clamp01((normalizedTime - 0.22f) / 0.48f);
                float orbSize = marker.BaseScale * 0.065f;
                float scalePulse = Mathf.Lerp(0.78f, 1.2f, swell);
                marker.CoreOrb.transform.localScale = new Vector3(orbSize * scalePulse, orbSize * scalePulse, 1f);
                float alphaPulse = Mathf.Lerp(0.14f, 0.1f, swell) * fade;
                marker.CoreOrb.color = new Color(0.88f, 0.92f, 0.98f, alphaPulse);
                marker.OrbVisualRadius = GetClashOrbVisualRadius(marker.CoreOrb);
            }

            if (marker.Rings == null || marker.RingRadii == null) return;

            float thin = 0.11f * DBPU.Beam_SizeMultiplier;

            for (int i = 0; i < marker.Rings.Length; i++)
            {
                LineRenderer lr = marker.Rings[i];
                if (lr == null) continue;

                marker.RingRadii[i] += marker.RingExpandSpeed * delta;
                marker.RingRadii[i] = Mathf.Min(marker.RingRadii[i], marker.MaxRingRadius);

                float travel = Mathf.InverseLerp(marker.MinRingRadius, marker.MaxRingRadius, marker.RingRadii[i]);
                float fade = travel < 0.2f ? 1f : 1f - ((travel - 0.2f) / 0.8f);
                Color c = new Color(0.9f, 0.94f, 1f, fade * 0.75f);
                lr.startColor = c;
                lr.endColor = c;
                lr.startWidth = thin;
                lr.endWidth = thin;
                SetRingPositions(lr, marker.RingRadii[i], lr.positionCount);
            }
        }

        void ApplyClashShockwaveDestruction(Vector3 origin, BeamBehaviour a, BeamBehaviour b, float intensity)
        {
            if (!DBPU.Beam_ToggleDestroy) return;

            float radius = (3.5f + (a.Width + b.Width) * 0.58f) * DBPU.Beam_SizeMultiplier * Mathf.Clamp(intensity / 250000f, 0.85f, 2.1f);
            Collider2D[] hits = Physics2D.OverlapCircleAll(origin, radius, LayerMask.GetMask("Objects", "CollidingDebris"));
            Transform rootA = a.transform.root;
            Transform rootB = b.transform.root;

            foreach (Collider2D hit in hits)
            {
                if (hit == null) continue;
                if (hit.transform.root == rootA || hit.transform.root == rootB) continue;

                Rigidbody2D rb = hit.GetComponent<Rigidbody2D>();
                Vector3 direction = (hit.transform.position - origin).normalized;

                if (hit.GetComponent<DestroyableBehaviour>() != null)
                    hit.GetComponent<DestroyableBehaviour>().Break();
                else if (hit.GetComponent<DamagableMachineryBehaviour>() != null && hit.GetComponent<DamagableMachineryBehaviour>().Destroyed == false)
                    hit.GetComponent<DamagableMachineryBehaviour>().ForceBreak();

                if (rb != null && rb.bodyType != RigidbodyType2D.Static)
                {
                    float dist = Mathf.Max(Vector2.Distance(origin, hit.transform.position), 0.5f);
                    rb.AddForce(direction * (Mathf.Clamp(38f / dist, 6f, 55f) * rb.mass), ForceMode2D.Impulse);
                }
            }
        }

        void TriggerSpecialBeamBlock(Vector3 worldPos, float clampDistance)
        {
            if (!IsSpecialBeamCannon || beamBehaviour.SbcBlockedThisFire) return;

            beamBehaviour.SbcBlockedThisFire = true;
            beamBehaviour.realSpeed = 0f;
            beamBehaviour.Distance = Mathf.Min(beamBehaviour.Distance, Mathf.Max(clampDistance, 0.5f));
            beamBehaviour.Firing = false;
            beamBehaviour.Clashing = false;

            StartCoroutine(SpawnSpecialBeamBlockExplosion(worldPos));
        }

        public IEnumerator SpawnSpecialBeamBlockExplosion(Vector3 position)
        {
            float scale = 1.35f * DBPU.Beam_SizeMultiplier;
            GameObject explosion = Instantiate(DBPU.KiBlast_Hit, position, Quaternion.identity);
            explosion.transform.localScale = new Vector3(scale, scale, scale);
            explosion.AddComponent<DestroyOverTime>().Timer = 2.5f;

            foreach (Transform child in explosion.transform)
            {
                var sp = child.GetComponent<Renderer>();
                if (sp != null)
                {
                    sp.sortingLayerName = "Bubbles";
                    sp.sortingOrder += 10;
                }

                var ps = child.GetComponent<ParticleSystem>();
                if (ps != null)
                {
                    ps.playbackSpeed *= 0.65f;
                    ps.startColor = new Color(1f, 0.55f, 0.85f, 0.12f);
                }
            }

            AudioSource boomAudio = explosion.AddComponent<AudioSource>();
            Global global = FindObjectOfType<Global>();
            global.AddAudioSource(boomAudio, false);
            boomAudio.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.75f;
            boomAudio.outputAudioMixerGroup = global.SoundEffects;
            boomAudio.spatialBlend = 1;
            boomAudio.volume = DBPU.PowersVolume;
            boomAudio.maxDistance = 1000;
            boomAudio.PlayOneShot(DBPU.Attack_KiBlast_Impact);

            yield return StartCoroutine(SpecialBeamExplosionDamage(position));

            yield return null;
        }

        public IEnumerator SpecialBeamExplosionDamage(Vector3 origin)
        {
            float blastDamage = GetCombinedBeamDamage(beamBehaviour) * 14f;
            float radius = 2.4f * DBPU.Beam_SizeMultiplier;

            Collider2D[] hits = Physics2D.OverlapCircleAll(
                origin,
                radius,
                LayerMask.GetMask("Objects", "CollidingDebris"));

            foreach (Collider2D hit in hits)
            {
                if (hit.transform.root == beamBehaviour.transform.root) continue;
                if (hit.GetComponent<Rigidbody2D>() == null) continue;

                float dist = Mathf.Clamp(Vector2.Distance(origin, hit.transform.position), 0.75f, radius);
                float scaledDamage = blastDamage / Mathf.Clamp(dist * dist, 1f, 30f);
                Vector3 direction = (hit.transform.position - (Vector3)origin).normalized;
                Rigidbody2D rb = hit.GetComponent<Rigidbody2D>();

                if (hit.GetComponent<LimbBehaviour>() != null && hit.isTrigger == false)
                {
                    hit.GetComponent<LimbBehaviour>().Damage(scaledDamage);
                    if (rb.velocity.magnitude < 10f)
                        rb.AddForce(direction * (Mathf.Clamp(80f / dist, 4f, 40f) * rb.mass), ForceMode2D.Impulse);
                }
                else if (hit.GetComponent<PhysicalBehaviour>() != null)
                {
                    if (rb.velocity.magnitude < 12f)
                        rb.AddForce(direction * (Mathf.Clamp(60f / dist, 5f, 35f) * rb.mass), ForceMode2D.Impulse);

                    if (hit.GetComponent<DestroyableBehaviour>() != null)
                        hit.GetComponent<DestroyableBehaviour>().Break();

                    if (hit.GetComponent<DamagableMachineryBehaviour>() != null && hit.GetComponent<DamagableMachineryBehaviour>().Destroyed == false)
                        hit.GetComponent<DamagableMachineryBehaviour>().ForceBreak();
                }
            }

            yield return null;
        }

        public void Start()
        {
        }

        public void Update()
        {
            if (Global.main.Paused || beamBehaviour == null || !beamBehaviour.StillActive || beamBehaviour.MiddleBeam == null)
                return;

            if (beamBehaviour.MergeHost != null)
                return;

            Physics2D.queriesHitTriggers = true;

            RaycastHit2D[] hits = Physics2D.BoxCastAll(
                origin: beamBehaviour.StartBeamPosition,
                size: new Vector2(0.1f, beamBehaviour.MiddleBeam.startWidth * 0.96f),
                angle: beamBehaviour.BeamDirection.z,
                direction: RayDirection,
                distance: beamBehaviour.Distance - beamBehaviour.MiddleMinusDistance,
                layerMask: LayerMask.GetMask("Objects", "CollidingDebris", "Bounds")
                );

            Physics2D.queriesHitTriggers = false;

            foreach (RaycastHit2D hit in hits)
            {
                if (hit.collider.gameObject.transform.root.transform != beamBehaviour.transform)
                {
                    StartCoroutine(OnHit(hit, (beamBehaviour.MiddleBeam.GetPosition(1) - beamBehaviour.MiddleBeam.GetPosition(0)).normalized));
                }
            }

            if (HitAWall == false)
            {
                RaycastHit2D[] rayHits = Physics2D.RaycastAll(
                    origin: beamBehaviour.StartBeamPosition,
                    direction: (beamBehaviour.MiddleBeam.GetPosition(1) - beamBehaviour.MiddleBeam.GetPosition(0)).normalized,
                    distance: beamBehaviour.Distance - beamBehaviour.MiddleMinusDistance
                    );

                foreach (RaycastHit2D hit in rayHits)
                {
                    if (hit.collider.gameObject.transform.root.transform != beamBehaviour.transform && hit.collider.gameObject.layer == 11 && !hit.collider.GetComponent<KiShieldSurface>())
                    {
                        StartCoroutine(HitWall());
                    }
                }
            }

            TryAutoJoinNearbyClash();
        }

        void TryAutoJoinNearbyClash()
        {
            if (!DBPU.BeamAssistEnabled || beamBehaviour == null) return;
            if (!beamBehaviour.Firing || !beamBehaviour.StillActive || beamBehaviour.Clashing || beamBehaviour.MergeHost != null) return;

            PruneActiveBeamClashes();

            for (int i = 0; i < ActiveBeamClashes.Count; i++)
            {
                var pair = ActiveBeamClashes[i];
                BeamBehaviour sideA = pair.a;
                BeamBehaviour sideB = pair.b;
                if (sideA == null || sideB == null || !sideA.Clashing || !sideB.Clashing || !sideA.Firing || !sideB.Firing) continue;

                Vector3 clashPoint = (sideA.EndBeamPosition + sideB.EndBeamPosition) * 0.5f;
                float joinRadius = Mathf.Max(14f, (sideA.Width + sideB.Width + 6f) * DBPU.Beam_SizeMultiplier * 3f);

                if (!IsBeamAimedAtClash(beamBehaviour, clashPoint)) continue;
                if (DistancePointToBeam(beamBehaviour, clashPoint) > joinRadius) continue;

                if (beamBehaviour.transform.root != sideA.transform.root && CheckSameDirection(beamBehaviour, sideA))
                    TryMergeIntoSide(beamBehaviour, sideA);
                else if (beamBehaviour.transform.root != sideB.transform.root && CheckSameDirection(beamBehaviour, sideB))
                    TryMergeIntoSide(beamBehaviour, sideB);
            }
        }

        float DistancePointToBeam(BeamBehaviour b, Vector3 point)
        {
            Vector3 a = b.StartBeamPosition;
            Vector3 dir = b.BeamDirection.normalized;
            float along = Vector3.Dot(point - a, dir);
            if (along < 0f) return float.MaxValue;
            Vector3 closest = a + dir * Mathf.Clamp(along, 0f, b.Distance + 10f);
            return Vector3.Distance(closest, point);
        }

        public void OnTriggerEnter2D(Collider2D other)
        {
            BeamComponent otherComp = other.gameObject.GetComponent<BeamComponent>();
            if (otherComp != null)
            {
                if (TryMergeBeams(otherComp.beamBehaviour))
                    return;

                BeamBehaviour otherBeam = otherComp.beamBehaviour;
                if (beamBehaviour.Clashing == false && otherBeam.Clashing == false && CheckAngles(otherBeam))
                {
                    beamBehaviour.Clashing = true;
                    otherBeam.Clashing = true;
                    beamBehaviour.ClashOpponent = otherBeam;
                    otherBeam.ClashOpponent = beamBehaviour;
                    StartCoroutine(BeamClash(otherBeam));
                }
            }

            else if (other.gameObject.GetComponent<BallBehaviour.BallComponent>())
            {
                BallBehaviour.BallComponent ballComp = other.gameObject.GetComponent<BallBehaviour.BallComponent>();
                BallBehaviour ball = ballComp.ballBehaviour;
                if (ball == null || beamBehaviour.Clashing) return;

                if (!ball.Clashing)
                {
                    beamBehaviour.Clashing = true;
                    ball.Clashing = true;
                    if (DBPU.BeamAssistEnabled)
                        ball.PushingBeams.Clear();
                    ball.PushingBeams.Add(beamBehaviour);
                    StartCoroutine(BeamBallClash(ball));
                }
                else if (DBPU.BeamAssistEnabled && TryJoinBallPush(ball))
                {
                    beamBehaviour.Clashing = true;
                    beamBehaviour.realSpeed = 0f;
                    ball.PushingBeams.Add(beamBehaviour);
                }
            }
        }

        bool TryMergeBeams(BeamBehaviour otherBeam)
        {
            if (!DBPU.BeamAssistEnabled) return false;
            if (otherBeam == null || beamBehaviour == null || otherBeam == beamBehaviour) return false;
            if (otherBeam.transform.root == beamBehaviour.transform.root) return false;
            if (beamBehaviour.MergeHost != null || otherBeam.MergeHost != null) return false;

            if (otherBeam.Clashing && otherBeam.ClashOpponent != null && !beamBehaviour.Clashing)
            {
                if (TryMergeIntoSide(beamBehaviour, otherBeam)) return true;
                if (TryMergeIntoSide(beamBehaviour, otherBeam.ClashOpponent)) return true;
            }

            if (beamBehaviour.Clashing && beamBehaviour.ClashOpponent != null && !otherBeam.Clashing)
            {
                if (TryMergeIntoSide(otherBeam, beamBehaviour)) return true;
                if (TryMergeIntoSide(otherBeam, beamBehaviour.ClashOpponent)) return true;
            }

            if (!beamBehaviour.Clashing && !otherBeam.Clashing)
                return TryFuseParallelBeams(beamBehaviour, otherBeam);

            return false;
        }

        bool TryFuseParallelBeams(BeamBehaviour a, BeamBehaviour b)
        {
            if (a.GetInstanceID() > b.GetInstanceID())
                return TryFuseParallelBeams(b, a);
            if (!a.Firing || !b.Firing || !a.StillActive || !b.StillActive) return false;
            if (a.Clashing || b.Clashing) return false;
            if (!CheckSameDirection(a, b)) return false;
            if (!CheckParallelProximity(a, b)) return false;
            BeamBehaviour host = a.Distance >= b.Distance ? a : b;
            BeamBehaviour incoming = host == a ? b : a;
            return ApplyBeamMerge(incoming, host, false);
        }

        bool IsBeamAimedAtClash(BeamBehaviour b, Vector3 clashPoint)
        {
            Vector3 toClash = clashPoint - b.StartBeamPosition;
            if (toClash.sqrMagnitude < 0.01f) return true;
            if (Vector3.Angle(b.BeamDirection.normalized, toClash.normalized) > 25f) return false;
            return Vector3.Dot(toClash, b.BeamDirection.normalized) > 0f;
        }

        void ScanForClashAssist(BeamBehaviour sideHost)
        {
            if (!DBPU.BeamAssistEnabled || sideHost == null) return;
            if (!sideHost.Clashing || !sideHost.Firing || sideHost.ClashOpponent == null || !sideHost.ClashOpponent.Firing) return;

            PruneActiveBeamClashes();

            Vector3 clashPoint = (sideHost.EndBeamPosition + sideHost.ClashOpponent.EndBeamPosition) * 0.5f;
            float radius = Mathf.Max(8f, (sideHost.Width + sideHost.ClashOpponent.Width + 4f) * DBPU.Beam_SizeMultiplier * 2.5f);

            Collider2D[] hits = Physics2D.OverlapCircleAll(clashPoint, radius);
            foreach (Collider2D hit in hits)
            {
                BeamComponent comp = hit.GetComponent<BeamComponent>();
                if (comp == null || comp.beamBehaviour == null) continue;

                BeamBehaviour candidate = comp.beamBehaviour;
                if (candidate == sideHost || candidate == sideHost.ClashOpponent) continue;
                if (candidate.MergeHost != null || candidate.Clashing) continue;
                if (!candidate.Firing || !candidate.StillActive) continue;
                if (candidate.transform.root == sideHost.transform.root) continue;
                if (!CheckSameDirection(candidate, sideHost)) continue;
                if (!IsBeamAimedAtClash(candidate, clashPoint)) continue;

                TryMergeIntoSide(candidate, sideHost);
            }
        }

        bool CheckParallelProximity(BeamBehaviour a, BeamBehaviour b)
        {
            Vector3 dir = a.BeamDirection.normalized;
            Vector3 delta = b.StartBeamPosition - a.StartBeamPosition;
            float lateral = Mathf.Abs(dir.x * delta.y - dir.y * delta.x);
            float maxSep = (a.Width + b.Width + a.ExtraWidth + b.ExtraWidth) * DBPU.Beam_SizeMultiplier * 4f + 5f;
            return lateral <= maxSep;
        }

        bool TryMergeIntoSide(BeamBehaviour incoming, BeamBehaviour host)
        {
            if (incoming == null || host == null || host.ClashOpponent == null) return false;
            if (!incoming.Firing || !incoming.StillActive || !host.Firing || !host.ClashOpponent.Firing) return false;
            if (!host.Clashing) return false;
            if (host.MergedBeams.Contains(incoming)) return false;
            if (!CheckSameDirection(incoming, host)) return false;
            return ApplyBeamMerge(incoming, host);
        }

        bool CheckSameDirection(BeamBehaviour a, BeamBehaviour b)
        {
            return Vector3.Angle(a.BeamDirection.normalized, b.BeamDirection.normalized) <= 18f;
        }

        bool ApplyBeamMerge(BeamBehaviour incoming, BeamBehaviour host, bool inClash = true)
        {
            incoming.MergeHost = host;
            if (inClash) incoming.Clashing = true;
            incoming.realSpeed = 0f;
            host.MergedBeams.Add(incoming);

            float preWidth = host.Width;
            host.Width = Mathf.Min(preWidth + incoming.Width * 0.75f, preWidth * 4.5f);
            host.MergeWidthBonus += host.Width - preWidth;
            host.ExtraWidth = Mathf.Max(host.ExtraWidth, incoming.Width * 0.35f);

            incoming.Distance = host.Distance;
            incoming.EndBeamPosition = host.EndBeamPosition;
            if (incoming.EndBeam != null && host.EndBeam != null)
                incoming.EndBeam.transform.position = host.EndBeam.transform.position;

            if (incoming.EndBeam != null)
            {
                Collider2D col = incoming.EndBeam.GetComponent<Collider2D>();
                if (col != null) col.enabled = false;
            }

            BeamComponent hostComp = host.EndBeam != null ? host.EndBeam.GetComponent<BeamComponent>() : null;
            if (hostComp == null) hostComp = this;
            hostComp.StartCoroutine(hostComp.AnimateBeamMerge(incoming, host));

            return true;
        }

        public IEnumerator AnimateBeamMerge(BeamBehaviour incoming, BeamBehaviour host)
        {
            float duration = 0.4f;
            float elapsed = 0f;
            float startIncomingW = incoming.MiddleBeam != null ? incoming.MiddleBeam.startWidth : incoming.Width;
            float startHostW = host.MiddleBeam != null ? host.MiddleBeam.startWidth : host.Width;
            float targetHostW = (host.Width + host.ExtraWidth) * DBPU.Beam_SizeMultiplier;
            Color hostColor = host.MiddleBeam != null ? host.MiddleBeam.material.color : Color.white;
            Color incomingColor = incoming.MiddleBeam != null ? incoming.MiddleBeam.material.color : hostColor;
            Color blendTarget = Color.Lerp(hostColor, incomingColor, 0.4f);

            host.MergeVisualActive = true;

            while (elapsed < duration && incoming.MergeHost == host && host.Firing)
            {
                elapsed += Time.deltaTime;
                float t = elapsed / duration;
                float swell = 1f + 0.3f * Mathf.Sin(t * Mathf.PI);

                if (host.MiddleBeam != null && host.MiddleBeam.material != null)
                {
                    float w = Mathf.Lerp(startHostW, targetHostW * swell, t);
                    host.MiddleBeam.startWidth = w;
                    host.MiddleBeam.endWidth = w;
                    host.MiddleBeam.material.color = Color.Lerp(hostColor, blendTarget, t);
                }

                if (incoming.MiddleBeam != null && incoming.MiddleBeam.material != null)
                {
                    float w = Mathf.Lerp(startIncomingW, 0f, t);
                    incoming.MiddleBeam.startWidth = w;
                    incoming.MiddleBeam.endWidth = w;
                    Color c = incoming.MiddleBeam.material.color;
                    incoming.MiddleBeam.material.color = new Color(c.r, c.g, c.b, Mathf.Lerp(c.a, 0f, t));
                }

                yield return null;
            }

            host.MergeVisualActive = false;
            FinalizeMergedBeamVisual(incoming, host);
        }

        void FinalizeMergedBeamVisual(BeamBehaviour incoming, BeamBehaviour host)
        {
            bool clashAssist = incoming.Clashing && host != null && host.Clashing;
            if (!clashAssist)
                incoming.Firing = false;

            if (incoming.MiddleBeam != null)
            {
                incoming.MiddleBeam.startWidth = 0f;
                incoming.MiddleBeam.endWidth = 0f;
                if (incoming.MiddleBeam.material != null)
                {
                    Color c = incoming.MiddleBeam.material.color;
                    incoming.MiddleBeam.material.color = new Color(c.r, c.g, c.b, 0f);
                }
            }

            if (host.MiddleBeam != null)
            {
                float w = (host.Width + host.ExtraWidth) * DBPU.Beam_SizeMultiplier;
                host.MiddleBeam.startWidth = w;
                host.MiddleBeam.endWidth = w;
            }

            if (host.Firing && !host.Clashing && host.MergedBeams != null && host.MergedBeams.Count > 0)
                host.MergeVisualActive = false;
        }

        float GetSingleBeamPower(BeamBehaviour b)
        {
            if (b == null || b.KiSys == null) return 0f;
            return b.RealDamage * PowerLostByKi(b);
        }

        float GetCombinedSidePower(BeamBehaviour host)
        {
            if (host == null) return 0f;
            PruneMergedBeams(host);
            float total = GetSingleBeamPower(host);
            for (int i = 0; i < host.MergedBeams.Count; i++)
            {
                BeamBehaviour m = host.MergedBeams[i];
                if (m != null && m.StillActive)
                    total += GetSingleBeamPower(m);
            }
            return total;
        }

        float GetCombinedBeamDamage(BeamBehaviour host)
        {
            if (host == null) return 0f;
            PruneMergedBeams(host);
            float total = host.RealDamage;
            for (int i = 0; i < host.MergedBeams.Count; i++)
            {
                BeamBehaviour m = host.MergedBeams[i];
                if (m != null && m.StillActive)
                    total += m.RealDamage;
            }
            return total;
        }

        float GetClashSideRoll(BeamBehaviour host)
        {
            return Random.Range(1f, 100f) * GetCombinedSidePower(host);
        }

        void PruneMergedBeams(BeamBehaviour host)
        {
            for (int i = host.MergedBeams.Count - 1; i >= 0; i--)
            {
                BeamBehaviour m = host.MergedBeams[i];
                if (m == null)
                {
                    host.MergedBeams.RemoveAt(i);
                    continue;
                }
                if (m.MergeHost == host) continue;
                if (!m.Firing)
                {
                    m.MergeHost = null;
                    m.Clashing = false;
                    host.MergedBeams.RemoveAt(i);
                }
            }
        }

        public void ReleaseMergedBeams(BeamBehaviour host)
        {
            if (host == null || host.MergedBeams == null) return;
            foreach (BeamBehaviour m in host.MergedBeams)
            {
                if (m == null) continue;
                m.MergeHost = null;
                m.Clashing = false;
                m.Firing = false;
                m.Distance = 0f;
                m.realSpeed = 0f;
            }
            host.MergedBeams.Clear();
            host.Width = Mathf.Max(0.1f, host.Width - host.MergeWidthBonus);
            host.MergeWidthBonus = 0f;
            host.MergeVisualActive = false;
        }

        void EndClashState(BeamBehaviour beam, bool preserveMerges)
        {
            if (beam == null) return;
            beam.ClashOpponent = null;
            beam.Clashing = false;
            if (preserveMerges && beam.MergedBeams != null)
            {
                foreach (BeamBehaviour m in beam.MergedBeams)
                {
                    if (m != null) m.Clashing = false;
                }
                return;
            }
            ReleaseMergedBeams(beam);
        }

        void ClearBeamClashPair(BeamBehaviour a, BeamBehaviour b, BeamBehaviour winner)
        {
            bool preserveA = winner == a && a != null && a.MergedBeams != null && a.MergedBeams.Count > 0;
            bool preserveB = winner == b && b != null && b.MergedBeams != null && b.MergedBeams.Count > 0;
            EndClashState(a, preserveA);
            EndClashState(b, preserveB);
        }

        bool TryJoinBallPush(BallBehaviour ball)
        {
            if (!DBPU.BeamAssistEnabled) return false;
            if (ball == null || beamBehaviour == null) return false;
            if (ball.transform.root == beamBehaviour.transform.root) return false;
            if (ball.PushingBeams.Contains(beamBehaviour)) return false;
            return CheckFacingBall(ball);
        }

        bool CheckFacingBall(BallBehaviour ball)
        {
            Vector3 ballPoint = ball.BallPosition + ball.BallDirection * ball.Distance;
            Vector3 toBall = ballPoint - beamBehaviour.StartBeamPosition;
            if (toBall.sqrMagnitude < 0.01f) return true;
            return Vector3.Angle(beamBehaviour.BeamDirection.normalized, toBall.normalized) <= 35f;
        }

        float GetCombinedBeamPushRoll(BallBehaviour ball)
        {
            float total = 0f;
            for (int i = ball.PushingBeams.Count - 1; i >= 0; i--)
            {
                BeamBehaviour b = ball.PushingBeams[i];
                if (b == null || !b.Firing)
                {
                    if (b != null) b.Clashing = false;
                    ball.PushingBeams.RemoveAt(i);
                    continue;
                }
                total += Random.Range(1f, 100f) * GetCombinedSidePower(b);
            }
            return total;
        }

        void FinishBeamBallWin(BallBehaviour otherBall)
        {
            foreach (BeamBehaviour b in otherBall.PushingBeams)
            {
                if (b == null) continue;
                b.TimeHolding = 0f;
                b.FinalHoldingTime = b.HoldingTime;
                b.realSpeed = b.OriginalSpeed;
                b.Clashing = false;
            }
            otherBall.PushingBeams.Clear();
            otherBall.Distance = 0f;
            otherBall.Firing = false;
            otherBall.Clashing = false;
            otherBall.DelayTime = 0f;
            otherBall.FinalUseDelay = otherBall.UseDelay;
            otherBall.Speed = otherBall.OriginalSpeed;
        }

        void FinishBallBeamsWin(BallBehaviour otherBall)
        {
            foreach (BeamBehaviour b in otherBall.PushingBeams)
            {
                if (b == null) continue;
                if (b == beamBehaviour && IsSpecialBeamCannon && !b.SbcBlockedThisFire)
                {
                    Vector3 clashPos = beamBehaviour.EndBeam != null
                        ? beamBehaviour.EndBeam.transform.position
                        : beamBehaviour.EndBeamPosition;
                    TriggerSpecialBeamBlock(clashPos, beamBehaviour.Distance);
                }
                else
                {
                    b.Distance = 0f;
                    b.Firing = false;
                }
                b.Clashing = false;
                b.TimeHolding = 0f;
                b.FinalHoldingTime = b.HoldingTime;
                if (b != beamBehaviour || !b.SbcBlockedThisFire)
                    b.realSpeed = b.OriginalSpeed;
            }
            otherBall.PushingBeams.Clear();
            otherBall.Distance += beamBehaviour.Distance;
            otherBall.DelayTime = 0f;
            otherBall.FinalUseDelay = otherBall.UseDelay;
            otherBall.Speed = otherBall.OriginalSpeed;
            otherBall.Clashing = false;
        }

        public void OnTriggerStay2D(Collider2D other)
        {
            BeamComponent otherComp = other.GetComponent<BeamComponent>();
            if (otherComp != null && TryMergeBeams(otherComp.beamBehaviour))
                return;

            if (!other.gameObject.GetComponent<BallBehaviour.BallComponent>()) return;
            BallBehaviour ball = other.gameObject.GetComponent<BallBehaviour.BallComponent>().ballBehaviour;
            if (ball == null || !ball.Clashing || beamBehaviour.Clashing || !DBPU.BeamAssistEnabled) return;
            if (!TryJoinBallPush(ball)) return;
            beamBehaviour.Clashing = true;
            beamBehaviour.realSpeed = 0f;
            ball.PushingBeams.Add(beamBehaviour);
        }

        public IEnumerator BeamClash(BeamBehaviour otherBeam)
        {
            beamBehaviour.realSpeed = 0f;
            otherBeam.realSpeed = 0f;

            Vector3 thisDir = beamBehaviour.BeamDirection.normalized;
            Vector3 otherDir = otherBeam.BeamDirection.normalized;

            Vector3 thisEnd = beamBehaviour.StartBeamPosition + thisDir * beamBehaviour.Distance;
            Vector3 otherEnd = otherBeam.StartBeamPosition + otherDir * otherBeam.Distance;

            Vector3 collisionPoint = (thisEnd + otherEnd) / 2f;

            float thisNewDistance = Vector3.Distance(beamBehaviour.StartBeamPosition, collisionPoint);
            float otherNewDistance = Vector3.Distance(otherBeam.StartBeamPosition, collisionPoint);

            float safeMargin = SafeMargin;
            thisNewDistance = Mathf.Max(0, thisNewDistance + safeMargin);
            otherNewDistance = Mathf.Max(0, otherNewDistance + safeMargin);

            beamBehaviour.Distance = thisNewDistance;
            beamBehaviour.EndBeamPosition = beamBehaviour.StartBeamPosition + thisDir * thisNewDistance;

            otherBeam.Distance = otherNewDistance;
            otherBeam.EndBeamPosition = otherBeam.StartBeamPosition + otherDir * otherNewDistance;

            RealityRift.TryBeamClash(beamBehaviour, otherBeam, collisionPoint);

            if (DBPU.BeamClashShockwaveEnabled)
                StartCoroutine(PlayClashShockwaveOneShot(GetBeamClashPoint(beamBehaviour, otherBeam), beamBehaviour, otherBeam));

            float waitElapsed = 0f;
            while (waitElapsed < 0.1f)
            {
                SyncBeamTipTransform(beamBehaviour);
                SyncBeamTipTransform(otherBeam);
                waitElapsed += Time.deltaTime;
                yield return null;
            }

            StartCoroutine(BeamStruggle(otherBeam));

            yield return null;
        }

        public IEnumerator BeamStruggle(BeamBehaviour otherBeam)
        {
            beamBehaviour.realSpeed = 0f;
            otherBeam.realSpeed = 0f;

            Vector3 thisDir = beamBehaviour.BeamDirection.normalized;
            Vector3 otherDir = otherBeam.BeamDirection.normalized;

            float updateInterval = 0.01f;
            float elapsed = 0f;
            float timeBeforeAllowingWin = 1.0f;

            RegisterBeamClash(beamBehaviour, otherBeam);

            while (beamBehaviour.Firing == true && otherBeam.Firing == true)
            {
                ScanForClashAssist(beamBehaviour);
                ScanForClashAssist(otherBeam);

                float thisRoll = GetClashSideRoll(beamBehaviour);
                float otherRoll = GetClashSideRoll(otherBeam);

                float shiftAmount = (0.05f * DBPU.Beam_SpeedMultiplier) * Mathf.Clamp(thisRoll / Mathf.Max(otherRoll, 0.01f), 1f, 5f);

                if (thisRoll > otherRoll)
                {
                    beamBehaviour.Distance += shiftAmount;
                    otherBeam.Distance = Mathf.Max(0f, otherBeam.Distance - shiftAmount);
                }

                else
                {
                    otherBeam.Distance += shiftAmount;
                    beamBehaviour.Distance = Mathf.Max(0f, beamBehaviour.Distance - shiftAmount);
                }

                beamBehaviour.EndBeamPosition = beamBehaviour.StartBeamPosition + thisDir * beamBehaviour.Distance;
                otherBeam.EndBeamPosition = otherBeam.StartBeamPosition + otherDir * otherBeam.Distance;

                SyncBeamTipTransform(beamBehaviour);
                SyncBeamTipTransform(otherBeam);

                elapsed += updateInterval;

                if (elapsed >= timeBeforeAllowingWin)
                {
                    Vector3 thisEnd = beamBehaviour.EndBeamPosition;
                    Vector3 otherStart = otherBeam.StartBeamPosition;

                    Vector3 otherEnd = otherBeam.EndBeamPosition;
                    Vector3 thisStart = beamBehaviour.StartBeamPosition;

                    float dist1 = Vector3.Distance(thisEnd, otherStart);
                    float dist2 = Vector3.Distance(otherEnd, thisStart);

                    if (dist1 <= otherBeam.EndBeam.GetComponent<BeamComponent>().MinDistanceToLose)
                    {
                        beamBehaviour.Distance += otherBeam.Distance;
                        beamBehaviour.TimeHolding = 0f;
                        beamBehaviour.FinalHoldingTime = beamBehaviour.HoldingTime;
                        beamBehaviour.realSpeed = beamBehaviour.OriginalSpeed;

                        otherBeam.Distance = 0f;
                        otherBeam.Firing = false;

                        ClearBeamClashPair(beamBehaviour, otherBeam, beamBehaviour);
                        break;
                    }

                    if (dist2 <= MinDistanceToLose)
                    {
                        if (IsSpecialBeamCannon && !beamBehaviour.SbcBlockedThisFire)
                        {
                            Vector3 clashPos = (beamBehaviour.EndBeam != null)
                                ? beamBehaviour.EndBeam.transform.position
                                : beamBehaviour.EndBeamPosition;
                            TriggerSpecialBeamBlock(clashPos, beamBehaviour.Distance);
                        }

                        otherBeam.Distance += beamBehaviour.Distance;
                        otherBeam.TimeHolding = 0f;
                        otherBeam.FinalHoldingTime = otherBeam.HoldingTime;
                        otherBeam.realSpeed = otherBeam.OriginalSpeed;

                        if (!beamBehaviour.SbcBlockedThisFire)
                        {
                            beamBehaviour.Distance = 0f;
                            beamBehaviour.Firing = false;
                        }

                        ClearBeamClashPair(beamBehaviour, otherBeam, otherBeam);
                        break;
                    }
                }

                yield return new WaitForSeconds(updateInterval);
            }

            UnregisterBeamClash(beamBehaviour, otherBeam);

            bool preserveThis = beamBehaviour.Firing && beamBehaviour.MergedBeams != null && beamBehaviour.MergedBeams.Count > 0;
            bool preserveOther = otherBeam.Firing && otherBeam.MergedBeams != null && otherBeam.MergedBeams.Count > 0;
            EndClashState(beamBehaviour, preserveThis);
            EndClashState(otherBeam, preserveOther);
            beamBehaviour.ClashOpponent = null;
            otherBeam.ClashOpponent = null;
            beamBehaviour.Clashing = false;
            beamBehaviour.TimeHolding = 0f;
            beamBehaviour.FinalHoldingTime = beamBehaviour.HoldingTime;
            if (!beamBehaviour.SbcBlockedThisFire)
                beamBehaviour.realSpeed = beamBehaviour.OriginalSpeed;

            otherBeam.Clashing = false;
            otherBeam.TimeHolding = 0f;
            otherBeam.FinalHoldingTime = beamBehaviour.HoldingTime;
            otherBeam.realSpeed = beamBehaviour.OriginalSpeed;
        }

        public IEnumerator BeamBallClash(BallBehaviour otherBall)
        {
            beamBehaviour.realSpeed = 0f;
            otherBall.Speed = 0f;

            yield return new WaitForSeconds(0.1f);

            StartCoroutine(BeamBallStruggle(otherBall));

            yield return null;
        }

        public IEnumerator BeamBallStruggle(BallBehaviour otherBall)
        {
            beamBehaviour.realSpeed = 0f;
            otherBall.Speed = 0f;

            Vector3 thisDir = beamBehaviour.BeamDirection.normalized;

            float updateInterval = 0.01f;
            float elapsed = 0f;
            float timeBeforeAllowingWin = 1.0f;

            while (otherBall.Firing == true && otherBall.PushingBeams.Count > 0)
            {
                foreach (BeamBehaviour b in otherBall.PushingBeams)
                {
                    if (b != null) b.realSpeed = 0f;
                }
                otherBall.Speed = 0f;

                float thisRoll = GetCombinedBeamPushRoll(otherBall);
                if (otherBall.PushingBeams.Count == 0) break;

                float otherRoll = Random.Range(1f, 100f) * otherBall.RealDamage * PowerLostByKiBall(otherBall);

                float shiftAmount = (0.05f * DBPU.Beam_SpeedMultiplier) * Mathf.Clamp(thisRoll / Mathf.Max(otherRoll, 0.01f), 1f, 5f);

                if (thisRoll > otherRoll)
                {
                    beamBehaviour.Distance += shiftAmount;
                    otherBall.Distance = Mathf.Max(0f, otherBall.Distance - shiftAmount);
                }
                else
                {
                    otherBall.Distance += shiftAmount * 2f;
                    beamBehaviour.Distance = Mathf.Max(0f, beamBehaviour.Distance - (shiftAmount * 2f));
                }

                beamBehaviour.EndBeamPosition = beamBehaviour.StartBeamPosition + thisDir * beamBehaviour.Distance;

                elapsed += updateInterval;

                if (elapsed >= timeBeforeAllowingWin)
                {
                    if (otherBall.Distance <= MinDistanceToLose)
                    {
                        beamBehaviour.Distance += otherBall.Distance;
                        beamBehaviour.TimeHolding = 0f;
                        beamBehaviour.FinalHoldingTime = beamBehaviour.HoldingTime;
                        beamBehaviour.realSpeed = beamBehaviour.OriginalSpeed;
                        FinishBeamBallWin(otherBall);
                        break;
                    }

                    if (beamBehaviour.Distance <= MinDistanceToLose)
                    {
                        FinishBallBeamsWin(otherBall);
                        break;
                    }
                }

                yield return new WaitForSeconds(updateInterval);
            }

            if (otherBall.PushingBeams.Count > 0)
            {
                foreach (BeamBehaviour b in otherBall.PushingBeams)
                {
                    if (b == null) continue;
                    b.Clashing = false;
                    b.TimeHolding = 0f;
                    b.FinalHoldingTime = b.HoldingTime;
                    if (!b.SbcBlockedThisFire)
                        b.realSpeed = b.OriginalSpeed;
                }
                otherBall.PushingBeams.Clear();
            }

            beamBehaviour.Clashing = false;
            otherBall.Clashing = false;
            otherBall.DelayTime = 0f;
            otherBall.FinalUseDelay = otherBall.UseDelay;
            otherBall.Speed = otherBall.OriginalSpeed;
        }

        bool CheckAngles(BeamBehaviour BB)
        {
            Vector3 thisDir = beamBehaviour.BeamDirection.normalized;
            Vector3 otherDir = BB.BeamDirection.normalized;

            float angleBetween = Vector3.Angle(thisDir, -otherDir);

            return angleBetween <= 10f;
        }

        float PowerLostByKi(BeamBehaviour BB)
        {
            float Percent = Mathf.Clamp((BB.KiSys.currentKi / BB.KiSys.maxKi) * 2f, 0.20f, 1f);

            return Percent;
        }

        float PowerLostByKiBall(BallBehaviour BB)
        {
            float Percent = Mathf.Clamp((BB.KiSys.currentKi / BB.KiSys.maxKi) * 2f, 0.20f, 1f);

            return Percent;
        }

        public IEnumerator HitWall()
        {
            if (beamBehaviour.realSpeed != 0f)
            {
                if (DistanceOfWallContact == 0f) DistanceOfWallContact = beamBehaviour.Distance;

                if (beamBehaviour.Distance > DistanceOfWallContact + (12f * DBPU.Beam_SizeMultiplier))
                {
                    HitAWall = true;
                    beamBehaviour.realSpeed = 0f;

                    if (IsSpecialBeamCannon && !beamBehaviour.SbcBlockedThisFire)
                    {
                        Vector3 tip = beamBehaviour.EndBeam != null
                            ? beamBehaviour.EndBeam.transform.position
                            : beamBehaviour.StartBeamPosition + beamBehaviour.BeamDirection * beamBehaviour.Distance;
                        TriggerSpecialBeamBlock(tip, beamBehaviour.Distance);
                    }
                }
            }

            yield return null;
        }

        public IEnumerator OnHit(RaycastHit2D hit, Vector2 direction)
        {
            if (hit.collider.gameObject.layer == 9 || hit.collider.gameObject.layer == 13)
            {
                if (hit.collider.gameObject.GetComponent<Rigidbody2D>())
                {
                    if (hit.collider.gameObject.GetComponent<BlastComponent>())
                    {
                        hit.collider.gameObject.GetComponent<BlastComponent>().HasHit = true;
                    }

                    float TimeScale = Global.main.SlowmotionTimescale;
                    if (!Global.main.SlowMotion) TimeScale = 1f;

                    Rigidbody2D rb = hit.collider.gameObject.GetComponent<Rigidbody2D>();

                    if (hit.collider.gameObject.GetComponent<LimbBehaviour>() && hit.collider.isTrigger != true)
                    {
                        LimbBehaviour limb = hit.collider.gameObject.GetComponent<LimbBehaviour>();
                        if (KiShield.Protects(limb.Person, beamBehaviour.gameObject, beamBehaviour.StartBeamPosition, (double)beamBehaviour.RealDamage * 60, beamBehaviour.GetInstanceID())) yield break;

                        if (KiDeflectUtils.TryDeflectBeamHit(beamBehaviour, limb))
                        {
                            yield break;
                        }

                        if (KiDeflectUtils.TryBeamSplitHit(beamBehaviour, limb, hit, direction))
                        {
                            yield break;
                        }

                        if (IsSpecialBeamCannon && !beamBehaviour.SbcBlockedThisFire && IsPersonStrongerThanAttacker(limb.Person))
                        {
                            TriggerSpecialBeamBlock(hit.point, GetDistAlongBeam(hit.point));
                            yield break;
                        }

                        if (KiDeflectUtils.IsBeamProtectedCorpse(limb.Person))
                        {
                            float beamKnock = DBPU.EffectiveBeamKnockback * (beamBehaviour != null ? beamBehaviour.KnockbackOutput : 1f);
                            if (beamKnock > 0f)
                                rb.AddForce(direction * (((1.2f * TimeScale) * rb.mass * beamKnock)), ForceMode2D.Impulse);
                            yield return null;
                            yield break;
                        }

                        float beamDamage = GetCombinedBeamDamage(beamBehaviour);
                        float ForcePercent = (beamDamage * 60f) / MCP_Utils.AverageMaxHealth(limb.Person);
                        bool wasAliveForAsh = limb.Person != null && limb.Person.IsAlive();

                        if (ForcePercent > 10f && DBPU.Beam_ToggleDelete == true) Destroy(hit.collider.gameObject);

                        else
                        {
                            if (ForcePercent > 0.02f && DBPU.Beam_ToggleHeat == true && !KiDeflectUtils.IsBeamProtectedCorpse(limb.Person))
                            {
                                limb.PhysicalBehaviour.BurnProgress += (0.0008f * TimeScale);
                            }

                            if (ForcePercent > 0.005f)
                            {
                                limb.Damage(beamDamage * TimeScale);
                                KiDeflectUtils.DisintegratePersonIfBeamKilled(limb.Person, wasAliveForAsh);

                                float beamKnock = DBPU.EffectiveBeamKnockback * (beamBehaviour != null ? beamBehaviour.KnockbackOutput : 1f);
                                if (beamKnock > 0f)
                                {
                                    float knockMult = IsSpecialBeamCannon ? 0.35f : 1f;
                                    rb.AddForce(direction * ((((1.2f * TimeScale) * rb.mass * Mathf.Clamp(ForcePercent, 0.25f, 1f)) * beamKnock) * knockMult), ForceMode2D.Impulse);
                                }
                            }
                        }
                    }

                    else if (!hit.collider.gameObject.GetComponent<LimbBehaviour>() && hit.collider.gameObject.GetComponent<PhysicalBehaviour>())
                    {
                        if (DBPU.Beam_ToggleDelete == true) Destroy(hit.collider.gameObject);

                        else
                        {
                            float beamKnockObj = DBPU.EffectiveBeamKnockback * (beamBehaviour != null ? beamBehaviour.KnockbackOutput : 1f);
                            if (beamKnockObj > 0f)
                            {
                                rb.AddForce(direction * (((1f * TimeScale) * rb.mass * beamKnockObj)), ForceMode2D.Impulse);
                            }

                            if (DBPU.Beam_ToggleHeat == true)
                            {
                                hit.collider.gameObject.GetComponent<PhysicalBehaviour>().Temperature += (0.4f * TimeScale);
                            }

                            if (DBPU.Beam_ToggleDestroy == true)
                            {
                                if (hit.collider.gameObject.GetComponent<DestroyableBehaviour>())
                                {
                                    hit.collider.gameObject.GetComponent<DestroyableBehaviour>().Break();
                                }

                                if (hit.collider.gameObject.GetComponent<DamagableMachineryBehaviour>() && hit.collider.gameObject.GetComponent<DamagableMachineryBehaviour>().Destroyed == false)
                                {
                                    hit.collider.gameObject.GetComponent<DamagableMachineryBehaviour>().ForceBreak();
                                }
                            }
                        }
                    }
                }
            }

            yield return null;
        }

        public class ColliderVisualizer : MonoBehaviour
        {
            private BoxCollider2D box;
            private LineRenderer line;

            void Start()
            {
                box = GetComponent<BoxCollider2D>();

                line = gameObject.AddComponent<LineRenderer>();
                line.sortingLayerName = "Decals";
                line.sortingOrder = 1000;
                line.positionCount = 5;
                line.loop = false;
                line.widthMultiplier = 0.05f;
                line.material = new Material(Shader.Find("Sprites/Default"));
                line.startColor = line.endColor = Color.red;
            }

            void Update()
            {
                if (box == null) return;

                Vector2 size = box.size;
                Vector2 offset = box.offset;
                Vector2 center = (Vector2)transform.position + (Vector2)(transform.rotation * offset);

                Vector2 halfSize = size * 0.5f;
                Vector2[] localCorners = new Vector2[4]
                {
                new Vector2(-halfSize.x, -halfSize.y),
                new Vector2(-halfSize.x,  halfSize.y),
                new Vector2( halfSize.x,  halfSize.y),
                new Vector2( halfSize.x, -halfSize.y)
                    };

                for (int i = 0; i < 4; i++)
                {
                    Vector2 worldPoint = center + (Vector2)(transform.rotation * Vector3.Scale(localCorners[i], transform.localScale));
                    line.SetPosition(i, worldPoint);
                }

                Vector2 firstWorldPoint = center + (Vector2)(transform.rotation * Vector3.Scale(localCorners[0], transform.localScale));
                line.SetPosition(4, firstWorldPoint);
            }
        }
    }

    public class StraightBeamBehaviour : MonoBehaviour
    {
        private MultipliersAndStuffs Multipliers;
        private KiSystem KiSys;
        private AudioSource audioSource;

        private Transform UsedArm;

        public bool IsBarrage = false;
        public int barrageAmount = 0;

        private Vector3 StopPos;
        private bool DeathBeamWasDeflected = false;
        private Vector3 DeathBeamDeflectPoint;
        private Vector3 DeathBeamDeflectStopPos;

        public bool Active = false;
        public bool Firing = false;
        public float CostPercent = 0.05f;
        public bool DeathBeamSplitConsumed = false;

        public string Character = "Human";

        public float Damage = 0f;
        public float RealDamage = 15000f;
        public float Width = 0.08f;

        public string EffectID;

        private void Awake()
        {
            audioSource = new GameObject("straightBeamAudioSource").AddComponent<AudioSource>();
            audioSource.transform.SetParent(transform.Find("Body/UpperBody"), false);
            Global global = FindObjectOfType<Global>();
            global.AddAudioSource(audioSource, false);
            audioSource.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.75f;
            audioSource.outputAudioMixerGroup = global.SoundEffects;
            audioSource.spatialBlend = 1;
            audioSource.volume = 1;
            audioSource.maxDistance = 1000;
        }

        private void Start()
        {
            if (!GetComponent<KiSystem>()) gameObject.AddComponent<KiSystem>();
            KiSys = GetComponent<KiSystem>();

            if (!GetComponent<MultipliersAndStuffs>()) gameObject.AddComponent<MultipliersAndStuffs>();
            Multipliers = GetComponent<MultipliersAndStuffs>();

            if (Damage == 0f) Damage = (CombatPowerController.AttackHealth(GetComponent<PersonBehaviour>()) / Multipliers.FinalMultiplier) / 40f;

            foreach (var limb in GetComponent<PersonBehaviour>().Limbs)
            {
                if (MCP_Utils.LimbCanUsePowers(limb) && limb.name.Contains("LowerArm"))
                {
                    limb.gameObject.AddComponent<UseEventTrigger>().Action = () =>
                    {
                        if (!KiHandLoadout.LegacyAllowed(limb, EffectID)) return;
                        if (Active == false || Firing == true || KiSys.currentKi < KiSys.maxKi * CostPercent || limb.Health <= 0f) return;

                        if (limb.Health > 0f && Active == true && Firing == false)
                        {
                            RealDamage = Damage * Multipliers.FinalMultiplier * Multipliers.KiOutput;

                            UsedArm = limb.transform;
                            StartCoroutine(Fire(limb.transform));
                        }
                    };
                }
            }
        }

        public void Update()
        {
            if (audioSource.volume != DBPU.PowersVolume) audioSource.volume = DBPU.PowersVolume;

            if (Active == true && IsBarrage == true)
            {
                foreach (var limb in GetComponent<PersonBehaviour>().Limbs)
                {
                    if (MCP_Utils.LimbCanUsePowers(limb) && limb.name.Contains("LowerArm"))
                    {
                        if (!KiHandLoadout.LegacyAllowed(limb, EffectID)) continue;
                        if (limb.PhysicalBehaviour.IsBeingUsedContinuously())
                        {
                            if (!limb.Person.IsAlive() || limb.Health <= 0f || Firing == true || KiSys.currentKi < KiSys.maxKi * (CostPercent * 4f)) return;

                            StartCoroutine(Fire(limb.transform));
                        }
                        ;
                    }
                }
            }
        }

        private IEnumerator KiCost()
        {
            if (DBPU.KiAttackCostMultiplier == 0f) yield break;

            float OGKiDrain = KiSys.currentKiDrainRate;
            float KiRegen = KiSys.baseRegen;

            if (OGKiDrain != 0f) KiSys.baseRegen = 0f;

            float FinalKi = KiSys.currentKi - (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier));
            float CurrentKi = KiSys.currentKi;

            while (CurrentKi > FinalKi)
            {
                KiSys.currentKi -= (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier)) * Time.deltaTime;
                CurrentKi -= (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier)) * Time.deltaTime;

                yield return new WaitForEndOfFrame();
            }

            if (OGKiDrain != 0f) KiSys.baseRegen = KiRegen;

            yield return null;
        }

        private IEnumerator Fire(Transform Arm)
        {
            Firing = true;

            RealDamage = (Damage * Multipliers.FinalMultiplier) * Multipliers.KiOutput;

            if (EffectID == "Death Beam")
            {
                if (IsBarrage == false)
                {
                    CostPercent = 0.01f;
                }

                else
                {

                    CostPercent = 0.005f;
                }

                StartCoroutine(KiCost());

                float RandomPos = (IsBarrage == true) ? UnityEngine.Random.Range(-0.12f, 0.12f) : 0f;

                GameObject FireEffect;

                yield return new WaitForFixedUpdate();

                if (DBPU.ExtraCharge == true && IsBarrage == false)
                {
                    FireEffect = Instantiate(DBPU.DeathBeamCharge1, Arm.position - (Arm.up * 0.3f) + (Arm.right * RandomPos), Arm.rotation * Quaternion.Euler(0, 0, -90));
                    FireEffect.transform.SetParent(Arm, false);
                    FireEffect.transform.localScale = new Vector3(0.8f, 0.8f, 0.8f);
                    FireEffect.transform.position = Arm.position - (Arm.up * 0.3f) + (Arm.right * RandomPos);
                    //GetAllChildrenRecursive(FireEffect.transform);
                    FireEffect.AddComponent<DestroyOverTime>().Timer = 2f;
                    //ChangePlayBackOfAllParticleSystems(FireEffect.transform, 2.5f);
                    //FireEffect.transform.Find("Blast Color").gameObject.GetComponent<ParticleSystem>().startColor = new Color(0.95f, 0.3f, 0.3f, 0.3f);

                    yield return new WaitForSeconds(0.5f);

                    GameObject FireEffect2 = Instantiate(DBPU.DeathBeamCharge2, Arm.position - (Arm.up * 0.3f) + (Arm.right * RandomPos), Arm.rotation * Quaternion.Euler(0, 0, -90));
                    FireEffect2.transform.SetParent(Arm, false);
                    FireEffect2.transform.localScale = new Vector3(0.5f, 0.5f, 0.5f);
                    FireEffect2.transform.position = Arm.position - (Arm.up * 0.3f) + (Arm.right * RandomPos);
                    //GetAllChildrenRecursive(FireEffect.transform);
                    FireEffect2.AddComponent<DestroyOverTime>().Timer = 2f;

                    yield return new WaitForSeconds(1.3f);
                }

                else
                {
                    FireEffect = Instantiate(DBPU.KiBlast_Start, Arm.position - (Arm.up * 0.3f) + (Arm.right * RandomPos), Arm.rotation * Quaternion.Euler(0, 0, -90));
                    FireEffect.transform.SetParent(Arm.transform, true);
                    FireEffect.transform.localScale = new Vector3(0.3f, 0.3f, 0.3f);
                    ChangePlayBackOfAllParticleSystems(FireEffect.transform, 2.5f);
                    FireEffect.transform.Find("Blast Color").gameObject.GetComponent<ParticleSystem>().startColor = new Color(0.95f, 0.3f, 0.3f, 0.3f);
                    FireEffect.AddComponent<DestroyOverTime>().Timer = 2f;

                    GetAllChildrenRecursive(FireEffect.transform);

                    foreach (Transform child in FireEffect.transform)
                    {
                        var sp = child.gameObject.GetComponent<Renderer>();
                        sp.sortingLayerName = Arm.gameObject.GetComponent<SpriteRenderer>().sortingLayerName;
                        sp.sortingOrder += 10;
                    }
                }

                DeathBeamWasDeflected = false;
                DeathBeamSplitConsumed = false;
                yield return StartCoroutine(RayCast(Arm, RandomPos));

                audioSource.PlayOneShot(DBPU.Attack_DeathBeam_Fire);

                GameObject BeamLineObj = new GameObject("BeamLine");
                BeamLineObj.transform.SetParent(Arm);
                LineRenderer BeamLine = BeamLineObj.AddComponent<LineRenderer>();
                BeamLine.textureMode = LineTextureMode.Tile;
                BeamLine.material = new Material(ModAPI.FindMaterial("VeryBright"));
                BeamLine.sortingLayerName = "Default";
                BeamLine.sortingOrder = 0;
                BeamLine.material.mainTexture = DBPU.StraightBeam_Texture;
                BeamLine.material.color = new Color(0.95f, 0.3f, 0.3f, 8f);
                BeamLine.material.mainTextureScale = new Vector2(1f, 1f);
                BeamLine.numCapVertices = 2;
                BeamLine.startWidth = 0f;
                BeamLine.endWidth = 0f;
                BeamLine.positionCount = 2;
                BeamLine.SetPosition(0, Arm.position + (-Arm.up * 0.4f) + (Arm.right * RandomPos));
                BeamLine.SetPosition(1, DeathBeamWasDeflected ? DeathBeamDeflectPoint : StopPos);

                StartCoroutine(MiddlePartAnimation(EffectID, BeamLine));

                GameObject DeflectBeamLineObj = null;
                if (DeathBeamWasDeflected)
                {
                    DeflectBeamLineObj = new GameObject("BeamLineDeflect");
                    DeflectBeamLineObj.transform.SetParent(Arm);
                    LineRenderer DeflectBeamLine = DeflectBeamLineObj.AddComponent<LineRenderer>();
                    DeflectBeamLine.textureMode = LineTextureMode.Tile;
                    DeflectBeamLine.material = new Material(ModAPI.FindMaterial("VeryBright"));
                    DeflectBeamLine.sortingLayerName = "Default";
                    DeflectBeamLine.sortingOrder = 0;
                    DeflectBeamLine.material.mainTexture = DBPU.StraightBeam_Texture;
                    DeflectBeamLine.material.color = new Color(0.95f, 0.3f, 0.3f, 8f);
                    DeflectBeamLine.material.mainTextureScale = new Vector2(1f, 1f);
                    DeflectBeamLine.numCapVertices = 2;
                    DeflectBeamLine.startWidth = 0f;
                    DeflectBeamLine.endWidth = 0f;
                    DeflectBeamLine.positionCount = 2;
                    DeflectBeamLine.SetPosition(0, DeathBeamDeflectPoint);
                    DeflectBeamLine.SetPosition(1, DeathBeamDeflectStopPos);
                    StartCoroutine(MiddlePartAnimation(EffectID, DeflectBeamLine));
                }

                if (IsBarrage == false)
                {
                    yield return new WaitForSeconds(0.5f);

                    Destroy(BeamLineObj);
                    if (DeflectBeamLineObj != null) Destroy(DeflectBeamLineObj);
                    Destroy(FireEffect);

                    Firing = false;

                    yield return null;
                }

                else
                {
                    yield return new WaitForSeconds(0.1f);

                    Firing = false;

                    yield return new WaitForSeconds(0.4f);

                    Destroy(BeamLineObj);
                    if (DeflectBeamLineObj != null) Destroy(DeflectBeamLineObj);
                    Destroy(FireEffect);

                    yield return null;
                }
            }

            yield return null;
        }

        public IEnumerator RayCast(Transform Arm, float RandomPos)
        {
            RaycastHit2D[] rayHits = Physics2D.RaycastAll(Arm.position + (-Arm.up * 0.3f) + (Arm.right * RandomPos), -Arm.up, 10000f);

            StopPos = Arm.position + (-Arm.up * 10000f) + (Arm.right * RandomPos);

            foreach (RaycastHit2D hit in rayHits)
            {
                if (hit.collider.gameObject.transform.root.transform != transform && (hit.collider.gameObject.layer == 11 || hit.collider.gameObject.layer == 9 || hit.collider.gameObject.layer == 13))
                {
                    Rigidbody2D rb = hit.collider.gameObject.GetComponent<Rigidbody2D>();

                    var shell = hit.collider.GetComponent<KiShieldSurface>();
                    if (shell && shell.Owner)
                    {
                        if (shell.Owner.transform.root == transform.root) continue;
                        if (shell.Owner.ReceiveDamage(RealDamage, hit.point, GetInstanceID())) { StopPos = hit.point; break; }
                        continue;
                    }
                    if (hit.collider.gameObject.layer == 11)
                    {
                        StopPos = hit.point;

                        var Explosion = Instantiate(DBPU.KiBlast_Hit, StopPos, Quaternion.identity);
                        Explosion.transform.localScale = new Vector3(1.5f, 1.5f, 1.5f);
                        Explosion.gameObject.AddComponent<DestroyOverTime>().Timer = 2f;

                        foreach (Transform child in Explosion.transform)
                        {
                            var sp = child.gameObject.GetComponent<Renderer>();
                            sp.sortingLayerName = "Bubbles";
                            sp.sortingOrder += 10;

                            var ps = child.gameObject.GetComponent<ParticleSystem>();
                            ps.playbackSpeed *= 0.8f;
                        }

                        AudioSource audioSource2 = Explosion.AddComponent<AudioSource>();
                        Global global = FindObjectOfType<Global>();
                        global.AddAudioSource(audioSource2, false);
                        audioSource2.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.75f;
                        audioSource2.outputAudioMixerGroup = global.SoundEffects;
                        audioSource2.spatialBlend = 1;
                        audioSource2.volume = 1;
                        audioSource2.maxDistance = 1000;
                        audioSource2.PlayOneShot(DBPU.Attack_DeathBeam_Hit);

                        break;
                    }

                    else if (hit.collider.gameObject.GetComponent<LimbBehaviour>())
                    {
                        var limb = hit.collider.gameObject.GetComponent<LimbBehaviour>();

                        Vector2 incomingDir = (-Arm.up).normalized;
                        if (KiDeflectUtils.TryDeflectStraightBeam(transform.root.gameObject, limb, incomingDir, out var deflectDir))
                        {
                            DeathBeamWasDeflected = true;
                            DeathBeamDeflectPoint = hit.point;
                            DeathBeamDeflectStopPos = (Vector3)hit.point + ((Vector3)deflectDir.normalized * 10000f);
                            StopPos = DeathBeamDeflectPoint;
                            break;
                        }

                        if (KiDeflectUtils.TryBeamSplitStraightBeamHit(this, limb, hit.point, incomingDir))
                        {
                            StopPos = hit.point;
                            break;
                        }

                        float DamagePercent = RealDamage / MCP_Utils.AverageMaxHealth(limb.Person);
                        bool wasAliveForAsh = limb.Person != null && limb.Person.IsAlive();
                        if (KiDeflectUtils.IsBeamProtectedCorpse(limb.Person))
                        {
                            if (rb != null && DBPU.EffectiveBeamKnockback > 0f)
                                rb.AddForce(-Arm.up * ((15f * (rb.mass * 0.9f) * DBPU.EffectiveBeamKnockback)), ForceMode2D.Impulse);
                            StopPos = hit.point;
                            break;
                        }
                        limb.Damage(RealDamage);
                        KiDeflectUtils.DisintegratePersonIfBeamKilled(limb.Person, wasAliveForAsh);

                        if (DamagePercent > 0.05f)
                        {
                            rb.AddForce(-Arm.up * ((15f * (rb.mass * 0.9f) * Mathf.Clamp(DamagePercent, 0.4f, 1f))), ForceMode2D.Impulse);
                        }

                        if (DamagePercent < 0.2f)
                        {
                            StopPos = hit.point;

                            var Explosion = Instantiate(DBPU.KiBlast_Hit, StopPos, Quaternion.identity);
                            Explosion.transform.localScale = new Vector3(0.9f, 0.9f, 0.9f);
                            Explosion.gameObject.AddComponent<DestroyOverTime>().Timer = 2f;

                            foreach (Transform child in Explosion.transform)
                            {
                                var sp = child.gameObject.GetComponent<Renderer>();
                                sp.sortingLayerName = "Bubbles";
                                sp.sortingOrder += 10;

                                var ps = child.gameObject.GetComponent<ParticleSystem>();
                                ps.playbackSpeed *= 1f;
                            }

                            AudioSource audioSource2 = Explosion.AddComponent<AudioSource>();
                            Global global = FindObjectOfType<Global>();
                            global.AddAudioSource(audioSource2, false);
                            audioSource2.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.75f;
                            audioSource2.outputAudioMixerGroup = global.SoundEffects;
                            audioSource2.spatialBlend = 1;
                            audioSource2.volume = 1;
                            audioSource2.maxDistance = 1000;
                            audioSource2.PlayOneShot(DBPU.Attack_DeathBeam_Hit);

                            break;
                        }

                        else if (DamagePercent >= 0.6f)
                        {
                            if (hit.collider.gameObject.GetComponent<LimbBehaviour>().name == "UpperBody")
                            {
                                ModAPI.CreateParticleEffect("BloodExplosion", hit.point);

                                hit.collider.gameObject.GetComponent<LimbBehaviour>().BreakBone();

                                yield return new WaitForFixedUpdate();

                                hit.collider.gameObject.GetComponent<LimbBehaviour>().HealBone();
                            }

                            float VisualDamage = (10f * Mathf.Clamp(DamagePercent, 0f, 0.5f)) / limb.SkinMaterialHandler.intensityMultiplier;

                            if (hit.collider.gameObject.GetComponent<LimbBehaviour>().name.Contains("Body")) limb.SkinMaterialHandler.AddDamagePoint(DamageType.Bullet, hit.point, VisualDamage * 5f);
                            limb.SkinMaterialHandler.AddDamagePoint(DamageType.Blunt, hit.point, VisualDamage);
                        }

                        else if (DamagePercent >= 0.8f)
                        {
                            if (hit.collider.gameObject.GetComponent<LimbBehaviour>().name == "UpperBody")
                            {
                                ModAPI.CreateParticleEffect("BloodExplosion", hit.point);

                                hit.collider.gameObject.GetComponent<LimbBehaviour>().BreakBone();

                                yield return new WaitForFixedUpdate();

                                hit.collider.gameObject.GetComponent<LimbBehaviour>().HealBone();
                            }

                            else if (hit.collider.gameObject.GetComponent<LimbBehaviour>().name == "Head")
                            {
                                var headLimb = hit.collider.gameObject.GetComponent<LimbBehaviour>();
                                if (!UltraInstinctEvasion.TryEvade(headLimb, hit.point))
                                    headLimb.Health = 0f;

                                ModAPI.CreateParticleEffect("BloodExplosion", hit.point);
                            }

                            float VisualDamage = (25f * Mathf.Clamp(DamagePercent, 0f, 0.5f)) / limb.SkinMaterialHandler.intensityMultiplier;

                            if (hit.collider.gameObject.GetComponent<LimbBehaviour>().name.Contains("Body")) limb.SkinMaterialHandler.AddDamagePoint(DamageType.Bullet, hit.point, VisualDamage * 5f);
                            limb.SkinMaterialHandler.AddDamagePoint(DamageType.Blunt, hit.point, VisualDamage);
                        }
                    }

                    else if (hit.collider.gameObject.GetComponent<PhysicalBehaviour>())
                    {
                        var Explosion = Instantiate(DBPU.KiBlast_Hit, StopPos, Quaternion.identity);
                        Explosion.transform.localScale = new Vector3(0.9f, 0.9f, 0.9f);
                        Explosion.gameObject.AddComponent<DestroyOverTime>().Timer = 2.5f;

                        foreach (Transform child in Explosion.transform)
                        {
                            var sp = child.gameObject.GetComponent<Renderer>();
                            sp.sortingLayerName = "Bubbles";
                            sp.sortingOrder += 10;

                            var ps = child.gameObject.GetComponent<ParticleSystem>();
                            ps.playbackSpeed *= 0.8f;
                        }

                        AudioSource audioSource2 = Explosion.AddComponent<AudioSource>();
                        Global global = FindObjectOfType<Global>();
                        global.AddAudioSource(audioSource2, false);
                        audioSource2.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.75f;
                        audioSource2.outputAudioMixerGroup = global.SoundEffects;
                        audioSource2.spatialBlend = 1;
                        audioSource2.volume = 1;
                        audioSource2.maxDistance = 1000;
                        audioSource2.PlayOneShot(DBPU.Attack_DeathBeam_Hit);

                        Vector3 direction = (hit.transform.position - (Vector3)hit.point).normalized;

                        StartCoroutine(Hit(hit.collider.gameObject));

                        if (rb.velocity.magnitude < 12f) rb.AddForce(direction * (50f * rb.mass), ForceMode2D.Impulse);

                        if (hit.collider.gameObject.GetComponent<DestroyableBehaviour>()) hit.collider.gameObject.GetComponent<DestroyableBehaviour>().Break();

                        if (hit.collider.gameObject.GetComponent<DamagableMachineryBehaviour>() && hit.collider.gameObject.GetComponent<DamagableMachineryBehaviour>().Destroyed == false) hit.collider.gameObject.GetComponent<DamagableMachineryBehaviour>().ForceBreak();
                    }
                }
            }

            yield return null;
        }

        public IEnumerator Hit(GameObject other)
        {
            Collider2D[] hits = Physics2D.OverlapCircleAll(
                point: other.transform.position,
                radius: 15f,
                layerMask: LayerMask.GetMask("Objects", "CollidingDebris")
                );

            foreach (var hit in hits)
            {
                if (hit.gameObject != other.gameObject && hit.transform.root.gameObject != transform.root.gameObject && hit.gameObject.GetComponent<Rigidbody2D>())
                {
                    Vector3 direction = (hit.transform.position - other.transform.position).normalized;
                    float Distance = Mathf.Clamp(Vector2.Distance(other.transform.position, hit.transform.position), 1f, 20f);

                    Rigidbody2D rb = hit.gameObject.GetComponent<Rigidbody2D>();

                    if (hit.gameObject.GetComponent<LimbBehaviour>() && hit.isTrigger == false)
                    {
                        var hitLimb = hit.gameObject.GetComponent<LimbBehaviour>();
                        if (MCP_Utils.MeetsMinLimbDamage(hitLimb, Damage))
                        {
                            if (Distance < 5f) hitLimb.Damage(Damage / Mathf.Clamp(Distance * Distance, 1f, 25f));

                            float ForcePercent = (Damage * 5f) / MCP_Utils.AverageMaxHealth(hitLimb.Person);
                            if (rb.velocity.magnitude < 8f) rb.AddForce(direction * ((Mathf.Clamp(150f / Distance, 2f, 50f) * rb.mass * Mathf.Clamp(ForcePercent, 0.25f, 1f))), ForceMode2D.Impulse);
                        }
                    }

                    else if (hit.gameObject.GetComponent<PhysicalBehaviour>())
                    {
                        if (rb.velocity.magnitude < 12f) rb.AddForce(direction * (Mathf.Clamp(150f / Distance, 5f, 50f) * rb.mass), ForceMode2D.Impulse);

                        if (hit.gameObject.GetComponent<DestroyableBehaviour>())
                        {
                            if (UnityEngine.Random.Range(5, 20) > Distance) hit.gameObject.GetComponent<DestroyableBehaviour>().Break();
                        }

                        if (hit.gameObject.GetComponent<DamagableMachineryBehaviour>() && hit.gameObject.GetComponent<DamagableMachineryBehaviour>().Destroyed == false)
                        {
                            if (UnityEngine.Random.Range(10, 20) > Distance) hit.gameObject.GetComponent<DamagableMachineryBehaviour>().ForceBreak();
                        }
                    }
                }
            }

            yield return null;
        }

        public IEnumerator MiddlePartAnimation(string EffectID, LineRenderer BeamLine)
        {
            if (EffectID == "Death Beam")
            {
                while (BeamLine.startWidth < Width)
                {
                    BeamLine.startWidth += (Width * 20f) * Time.deltaTime;
                    BeamLine.endWidth += (Width * 20f) * Time.deltaTime;

                    yield return new WaitForFixedUpdate();
                }

                BeamLine.startWidth = Width;
                BeamLine.endWidth = Width;

                while (BeamLine.startWidth > 0f)
                {
                    BeamLine.startWidth -= (Width * 12f) * Time.deltaTime;
                    BeamLine.endWidth -= (Width * 12f) * Time.deltaTime;

                    yield return new WaitForFixedUpdate();
                }

                BeamLine.startWidth = 0f;
                BeamLine.endWidth = 0f;
            }

            else
            {
                yield return null;
            }

            yield return null;
        }

        void ChangePlayBackOfAllParticleSystems(Transform parent, float speed)
        {
            foreach (Transform child in parent)
            {
                var ps = child.gameObject.GetComponent<ParticleSystem>();
                ps.playbackSpeed *= speed;
            }
        }

        void GetAllChildrenRecursive(Transform parent)
        {
            foreach (Transform child in parent)
            {
                child.position = new Vector3(child.position.x, child.position.y, 0f);
                var sp = child.gameObject.GetComponent<Renderer>();
                sp.sortingLayerName = "Bubbles";
                sp.sortingOrder = 100;

                GetAllChildrenRecursive(child);
            }
        }
    }

    public class BallBehaviour : MonoBehaviour
    {
        private MultipliersAndStuffs Multipliers;
        public KiSystem KiSys;
        private AudioSource audioSource;

        private GameObject Ball;
        public GameObject ProjectileObject { get { return Ball; } }
        public KiShield ShieldBarrier;
        public bool ShieldDissolved;
        public float ShieldStopDistance;
        private GameObject ballChargeWind;
        private Transform UsedArm;
        private AudioSource activeChargeAudio;
        private float chargeSavedRegen;
        private bool chargeSuppressesRegen;

        public bool Active = false;
        public bool Charging = false;
        public bool FullCharged = false;
        public bool Firing = false;
        public bool StillActive = false;
        public bool Clashing = false;
        public float RealDamage = 7500f;
        public List<BeamBehaviour> PushingBeams = new List<BeamBehaviour>();
        public float CostPercent = 0.15f;

        public string Character = "Human";

        public float Damage = 0f;
        public float Speed = 40f;
        public float DamageOutput = 1f;
        public float KnockbackOutput = 1f;
        public float UseDelay = 6f;
        public float FinalUseDelay = 6f;
        public float DelayTime = 0f;

        public float OriginalSpeed = 100f;

        public float Distance = 0f;
        private float Brightness = 0.14f;
        private float Opacity = 0f;

        public Vector3 BallPosition;
        public Vector3 BallDirection;

        public string EffectID;

        public static float DeathBallChargeAnimSeconds = 1.7f;

        private static readonly float[] s_deathBallAnimPresets = { 0.5f, 0.75f, 1f, 1.25f, 1.5f, 1.75f, 2f, 2.25f, 2.5f, 2.75f, 3f, 3.25f, 3.5f, 4f, 5f, 6f, 8f };

        // A fired sphere is still moved and damaged by this controller. Keep its
        // release coroutine alive when changing technique; cancel only a held charge.
        public void CancelBallState()
        {
            Active = false;
            var spirit = GetComponent<SpiritBombChannel>();
            if (spirit) spirit.CancelCharge();
            if (UsedArm != null)
            {
                var freeze = UsedArm.GetComponent<FreezeBehaviour>();
                if (freeze != null) Destroy(freeze);
            }
            UsedArm = null;
            if (StillActive) return;

            StopAllCoroutines();
            Charging = false;
            FullCharged = false;
            Firing = false;
            Clashing = false;
            Distance = 0f;
            DelayTime = 0f;
            PushingBeams.Clear();
            if (ballChargeWind != null) { Destroy(ballChargeWind); ballChargeWind = null; }
            if (Ball != null) { Destroy(Ball); Ball = null; }
            if (activeChargeAudio != null)
            {
                activeChargeAudio.Stop();
                Destroy(activeChargeAudio.gameObject);
                activeChargeAudio = null;
            }
            if (audioSource != null) { audioSource.Stop(); audioSource.loop = false; }
            if (chargeSuppressesRegen && KiSys != null && KiSys.baseRegen == 0f)
                KiSys.baseRegen = chargeSavedRegen;
            chargeSuppressesRegen = false;
        }

        public static void CycleDeathBallChargeAnimPreset()
        {
            float c = DeathBallChargeAnimSeconds;
            int best = 0;
            float bestDiff = float.MaxValue;
            for (int i = 0; i < s_deathBallAnimPresets.Length; i++)
            {
                float d = Mathf.Abs(s_deathBallAnimPresets[i] - c);
                if (d < bestDiff)
                {
                    bestDiff = d;
                    best = i;
                }
            }

            best = (best + 1) % s_deathBallAnimPresets.Length;
            DeathBallChargeAnimSeconds = s_deathBallAnimPresets[best];
        }

        private void OnDestroy()
        {
            if (ballChargeWind != null) Destroy(ballChargeWind);
            if (Ball != null) Destroy(Ball);
        }

        private void Awake()
        {
            audioSource = new GameObject("BeamAudioSource").AddComponent<AudioSource>();
            audioSource.transform.SetParent(transform.Find("Head"), false);
            Global global = FindObjectOfType<Global>();
            global.AddAudioSource(audioSource, false);
            audioSource.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.75f;
            audioSource.outputAudioMixerGroup = global.SoundEffects;
            audioSource.spatialBlend = 1;
            audioSource.volume = 1;
            audioSource.maxDistance = 1000;
        }

        private void Start()
        {
            if (!GetComponent<KiSystem>()) gameObject.AddComponent<KiSystem>();
            KiSys = GetComponent<KiSystem>();

            if (!GetComponent<MultipliersAndStuffs>()) gameObject.AddComponent<MultipliersAndStuffs>();
            Multipliers = GetComponent<MultipliersAndStuffs>();

            if (Damage == 0f) Damage = (CombatPowerController.AttackHealth(GetComponent<PersonBehaviour>()) / Multipliers.FinalMultiplier) / 350f;

            foreach (var limb in GetComponent<PersonBehaviour>().Limbs)
            {
                if (MCP_Utils.LimbCanUsePowers(limb) && limb.name.Contains("LowerArm"))
                {
                    limb.gameObject.AddComponent<UseEventTrigger>().Action = () =>
                    {
                        if (StillActive || !KiHandLoadout.LegacyAllowed(limb, EffectID)) return;
                        if (IsSpiritBombEffect)
                        {
                            if (Active && limb.Health > 0) SpiritBombChannel.GetOrCreate(limb.Person).Activate(limb);
                            return;
                        }
                        if (Charging == false && KiSys.currentKi < KiSys.maxKi * CostPercent) return;

                        if (limb.Health > 0f && Active == true && Charging == false && Firing == false)
                        {
                            UsedArm = limb.transform;
                            StartCoroutine(StartCharge(limb.transform));
                        }

                        else if (Active == true && Charging == true && Firing == false && FullCharged == true && UsedArm == limb.transform)
                        {
                            Firing = true;
                        }
                    };
                }
            }
        }

        private bool IsSpiritBombEffect =>
            EffectID == "Spirit Bomb" || EffectID == "Super Spirit Bomb";

        private void Update()
        {
            if (StillActive == true)
            {
                RealDamage = (Damage * Multipliers.FinalMultiplier) * Multipliers.KiOutput * DamageOutput;

                if (Clashing == false) DelayTime += 1f * Time.deltaTime;

                if (Ball != null)
                {
                    Distance += (Speed * DBPU.Beam_SpeedMultiplier) * Time.deltaTime;

                    KiShield.ConstrainBall(this);
                    Vector3 pos = GetEndPosition();
                    if (IsSpiritBombEffect) pos.z = 27f;
                    Ball.transform.position = pos;
                }
            }
        }

        private IEnumerator StartCharge(Transform Arm)
        {
            if (StillActive) yield break;
            Charging = true;
            ShieldDissolved = false; ShieldBarrier = null;
            Firing = false;
            Clashing = false;

            AudioSource BallAudio = new GameObject("BallAudioSource").AddComponent<AudioSource>();
            activeChargeAudio = BallAudio;
            BallAudio.transform.SetParent(transform.Find("Body/UpperBody"), false);
            Global global = FindObjectOfType<Global>();
            global.AddAudioSource(BallAudio, false);
            BallAudio.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.75f;
            BallAudio.outputAudioMixerGroup = global.SoundEffects;
            BallAudio.spatialBlend = 1;
            BallAudio.volume = 1;
            BallAudio.maxDistance = 1000;

            if (EffectID == "Gigantic Crusher")
            {
                BallAudio.clip = DBPU.Attack_GalickGun_Charging;
                BallAudio.loop = true;
                //BallAudio.Play();
                BallAudio.volume = 0.25f;

                CostPercent = 0.4f;

                StartCoroutine(KiCost());

                Ball = Instantiate(GetEffect(EffectID, "Ball"), Arm.position + (Vector3.up * 36f), Quaternion.identity);
                Ball.layer = 9;

                ballChargeWind = Instantiate(DBPU.GiganticCrusherWind, Ball.transform.position, Quaternion.identity);
                ballChargeWind.transform.SetParent(Ball.transform, false);

                ApplyChargeBallSortingForCharge(Ball.transform, Arm);

                SetGiganticCrusherStage(Ball, 1);

                while (BallAudio.volume < 1f)
                {
                    BallAudio.volume += 0.01f;

                    yield return new WaitForSeconds(0.0125f);
                }

                yield return new WaitForSeconds(8f);

                FullCharged = true;

                if (Ball != null) SetGiganticCrusherStage(Ball, 2);

                while (Firing == false && Arm.GetComponent<LimbBehaviour>().Health > 0f)
                {
                    yield return null;
                }

                if (Arm.GetComponent<LimbBehaviour>().Health > 0f)
                {
                    StartCoroutine(Release(Arm, BallAudio));
                }
                else
                {
                    FullCharged = false;
                    Charging = false;
                    Destroy(Ball);
                }

                yield return null;
            }

            else if (EffectID == "Death Ball")
            {
                BallAudio.clip = DBPU.Attack_GalickGun_Charging;
                BallAudio.loop = true;
                //BallAudio.Play();
                BallAudio.volume = 0.25f;

                CostPercent = 0.4f;

                StartCoroutine(KiCost());

                Ball = Instantiate(GetEffect(EffectID, "Ball"), Arm.position + (Vector3.up * 20f), Quaternion.identity);
                Ball.layer = 9;

                Ball.transform.localScale = Ball.transform.localScale * 1.18f;

                ApplyChargeBallSortingForCharge(Ball.transform, Arm);

                while (BallAudio.volume < 1f)
                {
                    BallAudio.volume += 0.01f;

                    yield return new WaitForSeconds(0.0125f);
                }

                yield return new WaitForSeconds(Mathf.Clamp(DeathBallChargeAnimSeconds, 0.05f, 30f));

                DisableDeathBallAnimators(Ball);

                FullCharged = true;

                while (Firing == false && Arm.GetComponent<LimbBehaviour>().Health > 0f)
                {
                    yield return null;
                }

                if (Arm.GetComponent<LimbBehaviour>().Health > 0f)
                {
                    StartCoroutine(Release(Arm, BallAudio));
                }
                else
                {
                    FullCharged = false;
                    Charging = false;
                    Destroy(Ball);
                }

                yield return null;
            }

            else if (EffectID == "Supernova" || EffectID == "Beerus Ball")
            {
                BallAudio.clip = DBPU.Attack_GalickGun_Charging;
                BallAudio.loop = true;
                BallAudio.volume = 0.25f;

                CostPercent = EffectID == "Beerus Ball" ? 0.45f : 0.4f;

                StartCoroutine(KiCost());

                float scaleMult = EffectID == "Beerus Ball" ? 1.35f : 1f;
                Vector3 supernovaEndScale = new Vector3(10f * scaleMult, 10f * scaleMult, 10f * scaleMult);
                Vector3 supernovaStartScale = Vector3.zero;
                Vector3 supernovaArmBottom = Arm.position + (-Arm.up * 0.4f);
                Vector3 supernovaHoverStart = new Vector3(supernovaArmBottom.x, supernovaArmBottom.y, 27f);
                Vector3 supernovaHoverDelta = (-Arm.up) * 34f + Vector3.up * 22f;
                Vector3 supernovaHoverEnd = new Vector3(supernovaHoverStart.x + supernovaHoverDelta.x, supernovaHoverStart.y + supernovaHoverDelta.y, 27f);

                Ball = Instantiate(GetEffect(EffectID, "Ball"), supernovaHoverStart, Quaternion.identity);
                Ball.transform.localScale = supernovaStartScale;
                Ball.layer = 9;

                foreach (Transform child in Ball.transform)
                {
                    var sp = child.gameObject.GetComponent<Renderer>();
                    sp.sortingLayerName = Arm.gameObject.GetComponent<SpriteRenderer>().sortingLayerName;
                    sp.sortingOrder += 10;
                }
                float supernovaGrowDuration = EffectID == "Beerus Ball" ? 3.5f : 3.15f;
                float supernovaGrowElapsed = 0f;
                float supernovaVolStepTimer = 0f;

                while (BallAudio.volume < 1f || supernovaGrowElapsed < supernovaGrowDuration)
                {
                    supernovaVolStepTimer += Time.deltaTime;
                    while (supernovaVolStepTimer >= 0.0125f && BallAudio.volume < 1f)
                    {
                        supernovaVolStepTimer -= 0.0125f;
                        BallAudio.volume += 0.01f;
                    }

                    supernovaGrowElapsed += Time.deltaTime;
                    float supernovaT = Mathf.Clamp01(supernovaGrowElapsed / supernovaGrowDuration);
                    float supernovaSmooth = supernovaT * supernovaT * supernovaT * (supernovaT * (supernovaT * 6f - 15f) + 10f);
                    Ball.transform.localScale = Vector3.Lerp(supernovaStartScale, supernovaEndScale, supernovaSmooth);
                    Vector3 supernovaBasePos = Vector3.Lerp(supernovaHoverStart, supernovaHoverEnd, supernovaSmooth);
                    Vector3 supernovaFromHand = (-Arm.up).normalized * (supernovaSmooth * 3.5f);
                    Ball.transform.position = new Vector3(supernovaBasePos.x + supernovaFromHand.x, supernovaBasePos.y + supernovaFromHand.y, 27f);

                    yield return null;
                }

                BallAudio.volume = 1f;
                Ball.transform.localScale = supernovaEndScale;
                Ball.transform.position = new Vector3(supernovaHoverEnd.x + ((-Arm.up).normalized * 3.5f).x, supernovaHoverEnd.y + ((-Arm.up).normalized * 3.5f).y, 27f);

                FullCharged = true;

                while (Firing == false && Arm.GetComponent<LimbBehaviour>().Health > 0f)
                {
                    yield return null;
                }

                if (Arm.GetComponent<LimbBehaviour>().Health > 0f)
                {
                    StartCoroutine(Release(Arm, BallAudio));
                }
                else
                {
                    FullCharged = false;
                    Charging = false;
                    Destroy(Ball);
                }

                yield return null;
            }


            yield return null;
        }

        private IEnumerator KiCost()
        {
            float OGKiDrain = KiSys.currentKiDrainRate;
            float KiRegen = KiSys.baseRegen;

            chargeSavedRegen = KiRegen;
            chargeSuppressesRegen = OGKiDrain != 0f;
            if (chargeSuppressesRegen) KiSys.baseRegen = 0f;

            float FinalKi = KiSys.currentKi - (KiSys.maxKi * CostPercent);
            float CurrentKi = KiSys.currentKi;

            while (CurrentKi > FinalKi)
            {
                KiSys.currentKi -= (KiSys.maxKi * CostPercent) * (Time.deltaTime / 5f);
                CurrentKi -= (KiSys.maxKi * CostPercent) * (Time.deltaTime / 5f);

                yield return new WaitForEndOfFrame();
            }

            if (OGKiDrain != 0f) KiSys.baseRegen = KiRegen;
            chargeSuppressesRegen = false;

            yield return null;
        }

        private IEnumerator Release(Transform Arm, AudioSource BallAudio)
        {
            FullCharged = false;
            Firing = true;
            Charging = false;

            BallPosition = Ball.transform.position;

            if (EffectID == "Gigantic Crusher")
            {
                BallAudio.PlayOneShot(DBPU.Attack_Kamehameha_Fire);

                if (ballChargeWind != null)
                {
                    Destroy(ballChargeWind);
                    ballChargeWind = null;
                }

                OriginalSpeed = 40f;
                Speed = 40f;

                Distance = 0f;

                Damage = (CombatPowerController.AttackHealth(GetComponent<PersonBehaviour>()) / Multipliers.FinalMultiplier) / 300f;

                Ball.transform.parent = null;
                GetAllChildrenRecursive(Ball.transform);

                BallDirection = -Arm.transform.up;

                Ball.gameObject.layer = 9;

                Rigidbody2D rb = Ball.AddComponent<Rigidbody2D>();
                rb.bodyType = RigidbodyType2D.Kinematic;

                Ball.AddComponent<BallComponent>().ballBehaviour = gameObject.GetComponent<BallBehaviour>();
                Ball.GetComponent<BallComponent>().RayDirection = -Arm.transform.up;
                Ball.GetComponent<BallComponent>().User = this.gameObject;

                CircleCollider2D ballTrigger = Ball.AddComponent<CircleCollider2D>();
                ballTrigger.radius = 1.4f/* * DBPU.Beam_SizeMultiplier*/;
                ballTrigger.isTrigger = true;

                StillActive = true;

                SetGiganticCrusherStage(Ball, 3);

                yield return new WaitUntil(() => Distance > 600f || KiSys.currentKi < (KiSys.maxKi * 0.01f) || !Firing);

                Firing = false;
                StillActive = false;

                if (Ball != null) Destroy(Ball);

                yield return null;
            }

            else if (EffectID == "Death Ball")
            {
                //BallAudio.PlayOneShot(DBPU.Attack_Kamehameha_Fire);

                OriginalSpeed = 60f;
                Speed = 60f;

                Arm.gameObject.AddComponent<FreezeBehaviour>();

                Distance = 0f;

                Damage = (CombatPowerController.AttackHealth(GetComponent<PersonBehaviour>()) / Multipliers.FinalMultiplier) / 1000f;

                RestoreDeathBallFiredVisualPlayback(Ball);

                Ball.transform.parent = null;
                GetAllChildrenRecursive(Ball.transform);

                BallDirection = -Arm.transform.up;

                Ball.gameObject.layer = 9;

                Rigidbody2D rb = Ball.AddComponent<Rigidbody2D>();
                rb.bodyType = RigidbodyType2D.Kinematic;

                Ball.AddComponent<BallComponent>().ballBehaviour = gameObject.GetComponent<BallBehaviour>();
                Ball.GetComponent<BallComponent>().RayDirection = -Arm.transform.up;
                Ball.GetComponent<BallComponent>().User = this.gameObject;

                CircleCollider2D ballTrigger = Ball.AddComponent<CircleCollider2D>();
                ballTrigger.radius = 3.1f/* * DBPU.Beam_SizeMultiplier*/;
                ballTrigger.isTrigger = true;

                StillActive = true;

                audioSource.clip = DBPU.Attack_Kamehameha_Loop;
                audioSource.loop = true;
                //audioSource.Play();

                StartCoroutine(HoldingBall());

                yield return new WaitUntil(() => Firing == false || (KiSys.currentKi < (KiSys.maxKi * 0.01f) && Clashing == false));

                Firing = false;
                Clashing = false;

                StopAllParticleSystems(Ball.transform);

                Destroy(Arm.gameObject.GetComponent<FreezeBehaviour>());

                while (audioSource.volume > 0f)
                {
                    audioSource.volume -= 0.1f;

                    yield return new WaitForSeconds(0.025f);
                }

                audioSource.Stop();
                audioSource.volume = 1f;

                yield return new WaitForSeconds(0.6f);

                StillActive = false;

                Destroy(Ball);

                yield return null;
            }

            else if (EffectID == "Supernova" || EffectID == "Beerus Ball")
            {
                OriginalSpeed = EffectID == "Beerus Ball" ? 58f : 50f;
                Speed = OriginalSpeed;

                Arm.gameObject.AddComponent<FreezeBehaviour>();

                Distance = 0f;

                Damage = (CombatPowerController.AttackHealth(GetComponent<PersonBehaviour>()) / Multipliers.FinalMultiplier) / (EffectID == "Beerus Ball" ? 120f : 250f);

                Ball.transform.parent = null;
                GetAllChildrenRecursiveNoZ(Ball.transform);

                BallDirection = -Arm.transform.up;

                Ball.gameObject.layer = 9;

                Rigidbody2D rb = Ball.AddComponent<Rigidbody2D>();
                rb.bodyType = RigidbodyType2D.Kinematic;

                Ball.AddComponent<BallComponent>().ballBehaviour = gameObject.GetComponent<BallBehaviour>();
                Ball.GetComponent<BallComponent>().RayDirection = -Arm.transform.up;
                Ball.GetComponent<BallComponent>().User = this.gameObject;

                CircleCollider2D ballTrigger = Ball.AddComponent<CircleCollider2D>();
                ballTrigger.radius = EffectID == "Beerus Ball" ? 7.2f : 5.4f;
                ballTrigger.isTrigger = true;

                StillActive = true;

                audioSource.clip = DBPU.Attack_Kamehameha_Loop;
                audioSource.loop = true;
                //audioSource.Play();

                StartCoroutine(HoldingBall());

                yield return new WaitUntil(() => Firing == false || (KiSys.currentKi < (KiSys.maxKi * 0.01f) && Clashing == false));

                Firing = false;
                Clashing = false;

                //StopAllParticleSystems(Ball.transform);

                Destroy(Arm.gameObject.GetComponent<FreezeBehaviour>());
                Destroy(Ball.GetComponent<BallComponent>());

                /*while (audioSource.volume > 0f)
                {
                    audioSource.volume -= 0.1f;

                    yield return new WaitForSeconds(0.025f);
                }*/

                audioSource.Stop();
                audioSource.volume = 1f;

                yield return new WaitForSeconds(0.1f);

                StillActive = false;

                Destroy(Ball);

                yield return null;
            }


            else
            {
                yield return null;
            }

            yield return null;
        }

        private IEnumerator HoldingBall()
        {
            FinalUseDelay = UseDelay;

            DelayTime = 0f;

            yield return new WaitUntil(() => (DelayTime > FinalUseDelay || Firing == false));

            DelayTime = 0f;
            Firing = false;

            yield return null;
        }

        void StopAllParticleSystems(Transform parent)
        {
            foreach (Transform child in parent)
            {
                GetAllChildrenRecursive(child);

                var ps = child.gameObject.GetComponent<ParticleSystem>();
                ps.Stop();
            }
        }

        void ChangePlayBackOfAllParticleSystems(Transform parent, float speed)
        {
            foreach (Transform child in parent)
            {
                var ps = child.gameObject.GetComponent<ParticleSystem>();
                ps.playbackSpeed *= speed;

                GetAllChildrenRecursive(child);
            }
        }

        void GetAllChildrenRecursive(Transform parent)
        {
            foreach (Transform child in parent)
            {
                child.position = new Vector3(child.position.x, child.position.y, 0f);
                var sp = child.gameObject.GetComponent<Renderer>();
                if (sp != null)
                {
                    sp.sortingLayerName = "Bubbles";
                    sp.sortingOrder = 100;
                }

                GetAllChildrenRecursive(child);
            }
        }

        void GetAllChildrenRecursiveNoZ(Transform parent)
        {
            foreach (Transform child in parent)
            {
                var sp = child.gameObject.GetComponent<Renderer>();
                if (sp != null)
                {
                    sp.sortingLayerName = "Bubbles";
                    sp.sortingOrder = 100;
                }

                GetAllChildrenRecursiveNoZ(child);
            }
        }

        void GetAllChildrenRecursiveToBack(Transform parent)
        {
            foreach (Transform child in parent)
            {
                var sp = child.gameObject.GetComponent<Renderer>();
                if (sp != null)
                {
                    sp.sortingLayerName = "Bottom";
                    sp.sortingOrder += 100;
                }

                GetAllChildrenRecursiveToBack(child);
            }
        }

        void ApplyChargeBallSortingForCharge(Transform root, Transform Arm)
        {
            var armSr = Arm.gameObject.GetComponent<SpriteRenderer>();
            if (armSr == null) return;

            root.position = new Vector3(root.position.x, root.position.y, 0f);
            var rootR = root.gameObject.GetComponent<Renderer>();
            if (rootR != null)
            {
                rootR.sortingLayerName = armSr.sortingLayerName;
                rootR.sortingOrder += 10;
            }

            foreach (Transform child in root)
                ApplyChargeBallSortingRecursive(child, armSr.sortingLayerName, 10);
        }

        void ApplyChargeBallSortingRecursive(Transform t, string sortingLayer, int orderBoost)
        {
            t.position = new Vector3(t.position.x, t.position.y, 0f);
            var sp = t.gameObject.GetComponent<Renderer>();
            if (sp != null)
            {
                sp.sortingLayerName = sortingLayer;
                sp.sortingOrder += orderBoost;
            }

            foreach (Transform child in t)
                ApplyChargeBallSortingRecursive(child, sortingLayer, orderBoost);
        }

        void DisableDeathBallAnimators(GameObject ball)
        {
            if (ball == null) return;

            foreach (Animator an in ball.GetComponentsInChildren<Animator>(true))
                an.enabled = false;

            foreach (Animation legacy in ball.GetComponentsInChildren<Animation>(true))
                legacy.enabled = false;
        }

        void RestoreDeathBallFiredVisualPlayback(GameObject ball)
        {
            if (ball == null) return;

            foreach (ParticleSystem ps in ball.GetComponentsInChildren<ParticleSystem>(true))
                ps.Play(true);
        }

        private void SetGiganticCrusherStage(GameObject ball, int stage)
        {
            if (ball == null) return;

            Transform energyCollect = ball.transform.Find("EnergyCollect");
            Transform one = ball.transform.Find("1");
            Transform startSparks = ball.transform.Find("StartSparks");
            Transform physDebris = ball.transform.Find("PhysDebris");
            Transform fog = ball.transform.Find("FogLivelyWhite");

            bool enableEnergyCollect = (stage == 1);

            if (energyCollect != null) energyCollect.gameObject.SetActive(enableEnergyCollect);
            if (one != null) one.gameObject.SetActive(true);
            if (startSparks != null) startSparks.gameObject.SetActive(true);
            if (physDebris != null) physDebris.gameObject.SetActive(true);
            if (fog != null) fog.gameObject.SetActive(true);

            var coreR = one != null ? one.GetComponent<Renderer>() : null;
            var fogR = fog != null ? fog.GetComponent<Renderer>() : null;

            if (fogR != null)
            {
                fogR.sortingLayerName = "Bottom";
                fogR.sortingOrder = 0;
            }

            if (coreR != null)
            {
                coreR.sortingLayerName = "Bubbles";
                coreR.sortingOrder = 200;
            }
        }

        private GameObject GetEffect(string EffectID, string EffectPart)
        {
            if (EffectID == "Gigantic Crusher")
            {
                if (EffectPart == "Ball")
                {
                    return DBPU.GiganticCrusher;
                }
            }

            else if (EffectID == "Supernova" || EffectID == "Beerus Ball")
            {
                if (EffectPart == "Ball")
                {
                    return DBPU.Supernova;
                }
            }

            else if (EffectID == "Spirit Bomb")
            {
                if (EffectPart == "Ball")
                {
                    return DBPU.GenkiDama;
                }
            }

            else if (EffectID == "Super Spirit Bomb")
            {
                if (EffectPart == "Ball")
                {
                    return DBPU.SuperGenkiDama;
                }
            }

            else if (EffectID == "Death Ball")
            {
                if (EffectPart == "Ball")
                {
                    return DBPU.DeathBall_Ball;
                }
            }

            else
            {
                return null;
            }

            return null;
        }

        Vector3 GetEndPosition()
        {
            return BallPosition + (BallDirection * (Distance));
        }

        public class BallComponent : MonoBehaviour
        {
            public BallBehaviour ballBehaviour;
            public GameObject User;

            public float DistanceOfWallContact = 0f;
            public float MinDistanceToLose = 3f;
            public float SafeMargin = 1f;
            public bool HitAWall = false;
            public Vector3 RayDirection;

            public void Update()
            {
                if (ballBehaviour.ShieldDissolved || (ballBehaviour.ShieldBarrier && ballBehaviour.ShieldBarrier.Using)) return;
                if (!Global.main.Paused && HitAWall == false)
                {
                    RaycastHit2D[] rayHits = Physics2D.RaycastAll(
                        origin: transform.position,
                        direction: RayDirection,
                        distance: GetComponent<CircleCollider2D>().radius
                        );

                    foreach (RaycastHit2D hit in rayHits)
                    {
                        if (hit.collider.gameObject.transform.root.transform != ballBehaviour.transform && hit.collider.gameObject.layer == 11 && !hit.collider.GetComponent<KiShieldSurface>())
                        {
                            StartCoroutine(HitWall());
                        }
                    }
                }

                if (ballBehaviour.Clashing == false && ballBehaviour.Speed != ballBehaviour.OriginalSpeed) ballBehaviour.Speed = ballBehaviour.OriginalSpeed;
            }

            public void OnTriggerEnter2D(Collider2D other)
            {
                if (ballBehaviour.ShieldDissolved || (ballBehaviour.ShieldBarrier && ballBehaviour.ShieldBarrier.Using)) return;
                if (other.gameObject.GetComponent<BallComponent>() && ballBehaviour.Clashing == false)
                {
                    BallComponent otherBallComp = other.gameObject.GetComponent<BallComponent>();
                    if (otherBallComp.ballBehaviour.Clashing == false)
                    {
                        ballBehaviour.Clashing = true;
                        otherBallComp.ballBehaviour.Clashing = true;
                        StartCoroutine(BallClash(otherBallComp.ballBehaviour));
                    }
                }
            }

            public void OnTriggerStay2D(Collider2D other)
            {
                if (other.gameObject.transform.root.gameObject != User && !other.gameObject.GetComponent<BallComponent>() && !other.gameObject.GetComponent<BeamComponent>() && !other.gameObject.GetComponent<BlastComponent>() && (other.gameObject.layer == 9 || other.gameObject.layer == 13))
                {
                    StartCoroutine(OnHit(other, RayDirection));
                }
            }

            public IEnumerator BallClash(BallBehaviour otherBall)
            {
                ballBehaviour.Speed = 0f;
                otherBall.Speed = 0f;

                yield return new WaitForSeconds(0.1f);

                StartCoroutine(BallStruggle(otherBall));

                yield return null;
            }

            public IEnumerator BallStruggle(BallBehaviour otherBall)
            {
                ballBehaviour.Speed = 0f;
                otherBall.Speed = 0f;

                float updateInterval = 0.01f;
                float elapsed = 0f;
                float timeBeforeAllowingWin = 1.0f;

                while (ballBehaviour.Firing == true && otherBall.Firing == true)
                {
                    float thisDamage = ballBehaviour.RealDamage;
                    float otherDamage = otherBall.RealDamage;

                    float thisRoll = Random.Range(1f, 100f) * thisDamage * PowerLostByKi(ballBehaviour);
                    float otherRoll = Random.Range(1f, 100f) * otherDamage * PowerLostByKi(otherBall);

                    float shiftAmount = (0.05f * DBPU.Beam_SpeedMultiplier) * Mathf.Clamp(thisRoll / otherRoll, 1f, 5f);

                    if (thisRoll > otherRoll)
                    {
                        ballBehaviour.Distance += shiftAmount;
                        otherBall.Distance = Mathf.Max(0f, otherBall.Distance - shiftAmount);
                    }
                    else
                    {
                        otherBall.Distance += shiftAmount;
                        ballBehaviour.Distance = Mathf.Max(0f, ballBehaviour.Distance - shiftAmount);
                    }

                    elapsed += updateInterval;

                    if (elapsed >= timeBeforeAllowingWin)
                    {
                        if (otherBall.Distance <= MinDistanceToLose)
                        {
                            ballBehaviour.Distance += otherBall.Distance;
                            ballBehaviour.DelayTime = 0f;
                            ballBehaviour.FinalUseDelay = ballBehaviour.UseDelay;
                            ballBehaviour.Speed = ballBehaviour.OriginalSpeed;
                            ballBehaviour.Clashing = false;

                            otherBall.Distance = 0f;
                            otherBall.Firing = false;
                            otherBall.Clashing = false;

                            break;
                        }

                        if (ballBehaviour.Distance <= MinDistanceToLose)
                        {
                            otherBall.Distance += ballBehaviour.Distance;
                            otherBall.DelayTime = 0f;
                            otherBall.FinalUseDelay = otherBall.UseDelay;
                            otherBall.Speed = otherBall.OriginalSpeed;
                            otherBall.Clashing = false;

                            ballBehaviour.Distance = 0f;
                            ballBehaviour.Firing = false;
                            ballBehaviour.Clashing = false;

                            break;
                        }
                    }

                    yield return new WaitForSeconds(updateInterval);
                }

                ballBehaviour.Clashing = false;
                ballBehaviour.DelayTime = 0f;
                ballBehaviour.FinalUseDelay = ballBehaviour.UseDelay;
                ballBehaviour.Speed = ballBehaviour.OriginalSpeed;

                otherBall.Clashing = false;
                otherBall.DelayTime = 0f;
                otherBall.FinalUseDelay = otherBall.UseDelay;
                otherBall.Speed = otherBall.OriginalSpeed;
            }

            float PowerLostByKi(BallBehaviour BB)
            {
                float Percent = Mathf.Clamp((BB.KiSys.currentKi / BB.KiSys.maxKi) * 2f, 0.20f, 1f);
                return Percent;
            }

            public IEnumerator HitWall()
            {
                if (ballBehaviour.Speed != 0f)
                {
                    if (DistanceOfWallContact == 0f) DistanceOfWallContact = ballBehaviour.Distance;

                    if (ballBehaviour.Distance > DistanceOfWallContact + (12f * DBPU.Beam_SizeMultiplier))
                    {
                        HitAWall = true;
                        ballBehaviour.Speed = 0f;
                    }
                }

                yield return null;
            }

            public IEnumerator OnHit(Collider2D col, Vector2 direction)
            {
                if (ballBehaviour.ShieldDissolved || (ballBehaviour.ShieldBarrier && ballBehaviour.ShieldBarrier.Using)) yield break;
                if (col.gameObject.layer == 9 || col.gameObject.layer == 13)
                {
                    if (col.gameObject.GetComponent<Rigidbody2D>())
                    {
                        float TimeScale = Global.main.SlowmotionTimescale;
                        if (!Global.main.SlowMotion) TimeScale = 1f;

                        Rigidbody2D rb = col.gameObject.GetComponent<Rigidbody2D>();

                        if (col.gameObject.GetComponent<LimbBehaviour>() && col.isTrigger != true)
                        {
                            LimbBehaviour limb = col.gameObject.GetComponent<LimbBehaviour>();
                            if (KiShield.Protects(limb.Person, User, ballBehaviour.BallPosition, (double)ballBehaviour.RealDamage * 60, ballBehaviour.GetInstanceID())) yield break;

                            float ForcePercent = (ballBehaviour.RealDamage * 60f) / MCP_Utils.AverageMaxHealth(limb.Person);

                            if (KiDeflectUtils.IsBeamProtectedCorpse(limb.Person))
                            {
                                if (DBPU.EffectiveBeamKnockback > 0f)
                                    rb.AddForce((Vector2)direction * ((((1.2f * TimeScale) * rb.mass) * DBPU.EffectiveBeamKnockback)), ForceMode2D.Impulse);
                            }
                            else if (ForcePercent > 10f && DBPU.Beam_ToggleDelete == true) Destroy(col.gameObject);

                            else
                            {
                                if (ForcePercent > 0.02f && DBPU.Beam_ToggleHeat == true)
                                {
                                    limb.PhysicalBehaviour.BurnProgress += (0.0008f * TimeScale);
                                }

                                if (ForcePercent > 0.005f)
                                {
                                    limb.Damage(ballBehaviour.RealDamage * TimeScale);

                                    if (DBPU.EffectiveBeamKnockback > 0f) rb.AddForce((Vector2)direction * ((((1.2f * TimeScale) * rb.mass * Mathf.Clamp(ForcePercent, 0.25f, 1f)) * DBPU.EffectiveBeamKnockback)), ForceMode2D.Impulse);
                                }
                            }
                        }

                        else if (!col.gameObject.GetComponent<LimbBehaviour>() && col.gameObject.GetComponent<PhysicalBehaviour>())
                        {
                            if (DBPU.Beam_ToggleDelete == true) Destroy(col.gameObject);

                            else
                            {
                                if (DBPU.EffectiveBeamKnockback > 0f)
                                {
                                    rb.AddForce((Vector2)direction * (((2f * TimeScale) * rb.mass * DBPU.EffectiveBeamKnockback)), ForceMode2D.Impulse);
                                }

                                if (DBPU.Beam_ToggleHeat == true)
                                {
                                    col.gameObject.GetComponent<PhysicalBehaviour>().Temperature += (0.4f * TimeScale);
                                }

                                if (DBPU.Beam_ToggleDestroy == true)
                                {
                                    if (col.gameObject.GetComponent<DestroyableBehaviour>())
                                    {
                                        col.gameObject.GetComponent<DestroyableBehaviour>().Break();
                                    }

                                    if (col.gameObject.GetComponent<DamagableMachineryBehaviour>() && col.gameObject.GetComponent<DamagableMachineryBehaviour>().Destroyed == false)
                                    {
                                        col.gameObject.GetComponent<DamagableMachineryBehaviour>().ForceBreak();
                                    }
                                }
                            }
                        }
                    }
                }

                yield return null;
            }
        }
    }

    public class FinalExplosion : MonoBehaviour
    {
        private MultipliersAndStuffs Multipliers;
        private KiSystem KiSys;

        private AudioSource audioSource;

        private GameObject sphere;
        private GameObject outerSphere;
        private GameObject glowAnchor;
        private LightSprite glow;

        public float maxScale = 580f;
        public float growSpeed = 80f;
        public float Damage = 0f;
        public float DamageOutput = 1f;
        public float KnockbackOutput = 1f;

        public bool Active = false;
        public bool stillActive = false;
        public bool Firing = false;
        public float RealDamage = 100f;
        public float CostPercent = 0.6f;

        private void OnDestroy()
        {
            if (Firing == true)
            {
                Destroy(sphere);
                Destroy(outerSphere);
                Destroy(glowAnchor);
                Destroy(glow);
            }
        }

        private void Awake()
        {
            audioSource = new GameObject("ExplosionAudioSource").AddComponent<AudioSource>();
            audioSource.transform.SetParent(transform.Find("Head"), false);
            Global global = FindObjectOfType<Global>();
            global.AddAudioSource(audioSource, false);
            audioSource.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.85f;
            audioSource.outputAudioMixerGroup = global.SoundEffects;
            audioSource.spatialBlend = 1;
            audioSource.volume = 1;
            audioSource.maxDistance = 1000;
        }

        private void FixedUpdate()
        {
            if (stillActive == true)
            {
                foreach (var limb in GetComponent<PersonBehaviour>().Limbs)
                {
                    limb.Health -= RealDamage / 2f;
                }
            }
        }

        private void Update()
        {
            if (audioSource.volume != DBPU.PowersVolume) audioSource.volume = DBPU.PowersVolume;

            if (stillActive == true)
            {
                RealDamage = Damage * Multipliers.FinalMultiplier * Multipliers.KiOutput * DamageOutput;

                float scaleIncrease = growSpeed * Time.deltaTime;

                if (Firing == true)
                {
                    sphere.transform.localScale += Vector3.one * scaleIncrease;
                    sphere.transform.position -= new Vector3(0f, 0f, 33f * Time.deltaTime);
                    sphere.transform.Rotate(-60f * Time.deltaTime, 200f * Time.deltaTime, 0f);

                    outerSphere.transform.localScale = sphere.transform.localScale * 1.025f;
                    outerSphere.transform.position = sphere.transform.position;
                    outerSphere.transform.Rotate(-80f * Time.deltaTime, 250f * Time.deltaTime, 0f);

                    float currentScale = sphere.transform.localScale.x;

                    if (glow != null)
                    {
                        glow.transform.localScale = Vector3.one * currentScale * 1.5f;
                        glow.Brightness = currentScale / 5f;
                    }

                    if (currentScale >= maxScale)
                    {
                        Firing = false;
                    }
                }

                else if (stillActive == true)
                {
                    sphere.transform.localScale += Vector3.one * scaleIncrease;
                    sphere.transform.position -= new Vector3(0f, 0f, 35f * Time.deltaTime);
                    sphere.transform.Rotate(60f * Time.deltaTime, 200f * Time.deltaTime, 0f);

                    outerSphere.transform.localScale = sphere.transform.localScale * 1.025f;
                    outerSphere.transform.position = sphere.transform.position;
                    outerSphere.transform.Rotate(80f * Time.deltaTime, 250f * Time.deltaTime, 0f);

                    float currentScale = sphere.transform.localScale.x;

                    sphere.GetComponent<Renderer>().material.color -= new Color(0f, 0f, 0f, 0.5f * Time.deltaTime);
                    outerSphere.GetComponent<Renderer>().material.color -= new Color(0f, 0f, 0f, 1f * Time.deltaTime);

                    if (glow != null)
                    {
                        glow.transform.localScale = Vector3.one * currentScale * 1.5f;
                        glow.Brightness = ((currentScale / 5f) * 2f) * sphere.GetComponent<Renderer>().material.color.a;
                    }

                    if (sphere.GetComponent<Renderer>().material.color.a <= 0f)
                    {
                        stillActive = false;
                    }
                }
            }
        }

        private void Start()
        {
            if (!GetComponent<KiSystem>()) gameObject.AddComponent<KiSystem>();
            KiSys = GetComponent<KiSystem>();

            if (!GetComponent<MultipliersAndStuffs>()) gameObject.AddComponent<MultipliersAndStuffs>();
            Multipliers = GetComponent<MultipliersAndStuffs>();

            if (Damage == 0f) Damage = (CombatPowerController.AttackHealth(GetComponent<PersonBehaviour>()) / Multipliers.FinalMultiplier) / 100f;

            GetComponent<PersonBehaviour>().Limbs[2].gameObject.AddComponent<UseEventTrigger>().Action = () =>
            {
                if (!GetComponent<PersonBehaviour>().IsAlive() || GetComponent<PersonBehaviour>().Limbs[2].Health <= 0f || Active == false || Firing == true || KiSys.currentKi < KiSys.maxKi * CostPercent) return;

                StartCoroutine(Fire(GetComponent<PersonBehaviour>().Limbs[2].gameObject.transform));
            };
        }

        private IEnumerator Fire(Transform Middle)
        {
            Firing = true;
            stillActive = true;

            StartCoroutine(KiCost());

            audioSource.PlayOneShot(DBPU.Attack_FinalExplosion);

            if (DBPU.VoiceLines == true) audioSource.PlayOneShot(DBPU.Voice_Vegeta_FinalExplosion);

            Material newMaterial = new Material(Shader.Find("Sprites/Default"));

            newMaterial.color = Color.white;

            if (DBPU.FinalExplosion_Texture != null)
            {
                newMaterial.mainTexture = DBPU.FinalExplosion_Texture.texture;
            }

            sphere = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            sphere.transform.position = Middle.position + new Vector3(0f, -1f);
            sphere.transform.localScale = Vector3.zero;

            Renderer renderer = sphere.GetComponent<Renderer>();
            renderer.material = newMaterial;
            renderer.material.color = new Color(1f, 1f, 1f, 0.5f);
            renderer.sortingLayerName = "Bubbles";

            Material newMaterial2 = new Material(Shader.Find("Sprites/Default"));

            newMaterial2.color = Color.white;

            if (DBPU.FinalExplosion_OuterTexture != null)
            {
                newMaterial2.mainTexture = DBPU.FinalExplosion_OuterTexture.texture;
            }

            outerSphere = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            outerSphere.transform.position = sphere.transform.position;
            outerSphere.transform.localScale = Vector3.zero;

            Renderer renderer2 = outerSphere.GetComponent<Renderer>();
            renderer2.material = newMaterial2;
            renderer2.material.color = new Color(1f, 1f, 1f, 1f);
            renderer2.sortingLayerName = "Bubbles";
            renderer2.sortingOrder = renderer.sortingOrder + 1;

            sphere.AddComponent<BallCollision>().User = transform;
            sphere.GetComponent<BallCollision>().finalExplosion = gameObject.GetComponent<FinalExplosion>();

            glowAnchor = new GameObject("GlowAnchor");
            glowAnchor.transform.position = sphere.transform.position;
            glowAnchor.transform.SetParent(null);

            glow = ModAPI.CreateLight(glowAnchor.transform, new Color(252f / 255f, 255f / 255f, 94f / 255f, 0.15f), 3f, 3f);

            yield return new WaitUntil(() => Firing == false && stillActive == false);

            Destroy(sphere);
            Destroy(outerSphere);
            Destroy(glowAnchor);
            Destroy(glow);
        }

        private IEnumerator KiCost()
        {
            if (DBPU.KiAttackCostMultiplier == 0f) yield break;

            float OGKiDrain = KiSys.currentKiDrainRate;
            float KiRegen = KiSys.baseRegen;

            if (OGKiDrain != 0f) KiSys.baseRegen = 0f;

            float FinalKi = KiSys.currentKi - (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier));
            float CurrentKi = KiSys.currentKi;

            while (CurrentKi > FinalKi)
            {
                KiSys.currentKi -= (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier)) * (Time.deltaTime);
                CurrentKi -= (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier)) * (Time.deltaTime);

                yield return new WaitForEndOfFrame();
            }

            if (OGKiDrain != 0f) KiSys.baseRegen = KiRegen;

            yield return null;
        }

        private class BallCollision : MonoBehaviour
        {
            public FinalExplosion finalExplosion;
            public Transform User;

            public void FixedUpdate()
            {
                foreach (Collider2D collider2D in Physics2D.OverlapCircleAll(transform.position, finalExplosion.sphere.transform.localScale.x / 3f, LayerMask.GetMask("Objects", "CollidingDebris")))
                {
                    if (collider2D.gameObject.transform.root.transform == User || !collider2D.gameObject.GetComponent<Rigidbody2D>()) continue;

                    if (collider2D.gameObject.GetComponent<BlastComponent>())
                    {
                        collider2D.gameObject.GetComponent<BlastComponent>().HasHit = true;
                        continue;
                    }

                    StartCoroutine(OnHit(collider2D.gameObject, (collider2D.gameObject.transform.position - transform.position).normalized));
                }
            }

            public IEnumerator OnHit(GameObject other, Vector2 direction)
            {
                float TimeScale = Global.main.SlowmotionTimescale;
                if (!Global.main.SlowMotion) TimeScale = 1f;

                Rigidbody2D rb = other.GetComponent<Rigidbody2D>();

                if (other.GetComponent<LimbBehaviour>()/* && other.GetComponent<Collider2D>().isTrigger != true*/)
                {
                    LimbBehaviour limb = other.GetComponent<LimbBehaviour>();

                    float ForcePercent = (finalExplosion.RealDamage * 10f) / MCP_Utils.AverageMaxHealth(limb.Person);

                    if (ForcePercent > 0.005f)
                    {
                        limb.Damage(finalExplosion.RealDamage * TimeScale);

                        float DistanceMultiplier = Mathf.Clamp((Vector3.Distance(other.transform.position, transform.position) / (finalExplosion.sphere.transform.localScale.x / 3f)), 0.02f, 1f);

                        rb.AddForce(direction * (((40f / DistanceMultiplier) * TimeScale) * rb.mass * Mathf.Clamp(ForcePercent, 0.25f, 1f)), ForceMode2D.Impulse);
                    }
                }

                else if (!other.GetComponent<LimbBehaviour>() && other.GetComponent<PhysicalBehaviour>())
                {
                    float DistanceMultiplier = Mathf.Clamp((Vector3.Distance(other.transform.position, transform.position) / (finalExplosion.sphere.transform.localScale.x / 3f)), 0.02f, 1f);

                    rb.AddForce(direction * (((5f / DistanceMultiplier) * TimeScale) * rb.mass), ForceMode2D.Impulse);

                    if (DBPU.Beam_ToggleDestroy == true)
                    {
                        if (other.GetComponent<DestroyableBehaviour>())
                        {
                            other.GetComponent<DestroyableBehaviour>().Break();
                        }

                        if (other.GetComponent<DamagableMachineryBehaviour>() && other.GetComponent<DamagableMachineryBehaviour>().Destroyed == false)
                        {
                            other.GetComponent<DamagableMachineryBehaviour>().ForceBreak();
                        }
                    }
                }

                yield return null;
            }
        }
    }

    public class HellzoneGranade : MonoBehaviour
    {
        private MultipliersAndStuffs Multipliers;
        private KiSystem KiSys;

        public int barrageAmount = 0;

        public bool Active = false;
        public bool Firing = false;
        public bool Chase = false;
        public GameObject Target;
        public Vector3 TargetPosition;
        public float RealDamage = 100f;
        public float CostPercent = 0.1f;

        public List<GameObject> Blasts = new List<GameObject>();

        public float Damage = 0f;
        public float Speed = 40f;
        public float DamageOutput = 1f;
        public float KnockbackMultiplier = 1f;
        public int blastsAmount = 80;
        public string ID = "Blast";

        private void OnDestroy()
        {
            if (Blasts.Any())
            {
                foreach (var Blast in Blasts)
                {
                    if (Blast != null) Destroy(Blast);
                }
            }
        }

        private void Start()
        {
            if (!GetComponent<KiSystem>()) gameObject.AddComponent<KiSystem>();
            KiSys = GetComponent<KiSystem>();

            if (!GetComponent<MultipliersAndStuffs>()) gameObject.AddComponent<MultipliersAndStuffs>();
            Multipliers = GetComponent<MultipliersAndStuffs>();

            if (Damage == 0f) Damage = (CombatPowerController.AttackHealth(GetComponent<PersonBehaviour>()) / Multipliers.FinalMultiplier) / 50f;

            ID = gameObject.name + "_Blast" + UnityEngine.Random.Range(0, 999);

            foreach (var limb in GetComponent<PersonBehaviour>().Limbs)
            {
                if (MCP_Utils.LimbCanUsePowers(limb) && limb.name.Contains("LowerArm"))
                {
                    limb.gameObject.AddComponent<UseEventTrigger>().Action = () =>
                    {
                        if (!KiHandLoadout.LegacyAllowed(limb, "HellzoneGranade")) return;
                        if (!limb.Person.IsAlive() || limb.Health <= 0f || Active == false || Firing == true || KiSys.currentKi < KiSys.maxKi * (CostPercent * 4f)) return;

                        var hit = Physics2D.Raycast(limb.transform.position, -limb.transform.up, 50f);

                        if (hit.transform == null || hit.transform.root.gameObject == gameObject || hit.transform.gameObject.layer == 11 || hit.transform.gameObject.layer == 13) return;

                        Target = hit.transform.gameObject;

                        StartCoroutine(Fire(limb.transform));
                    };
                }
            }
        }

        private IEnumerator Fire(Transform Arm)
        {
            Firing = true;
            Chase = false;

            CostPercent = 0.1f;
            StartCoroutine(KiCost());

            RealDamage = (Damage * Multipliers.FinalMultiplier) * Multipliers.KiOutput * DamageOutput;

            for (int i = 0; i < blastsAmount; i++)
            {
                Vector2 randomPoint = Random.insideUnitCircle * 20f;
                Vector3 finalPos = Target.transform.position + new Vector3(randomPoint.x, randomPoint.y);

                /*GameObject Blast = Instantiate(DBPU.KiBlast_End, Arm.position, Arm.rotation * Quaternion.Euler(0, 0, -90));
                Blast.gameObject.layer = 9;
                Blast.transform.localScale = new Vector3(0.35f, 0.35f, 0.35f);
                Blast.gameObject.GetComponent<Rigidbody2D>().bodyType = RigidbodyType2D.Kinematic;
                Blast.gameObject.GetComponent<CircleCollider2D>().isTrigger = true;
                Blast.gameObject.GetComponent<CircleCollider2D>().radius = 2.2f;
                Blast.transform.Find("Blast Color").gameObject.GetComponent<ParticleSystem>().startColor = KiColor(KiSys.CurrentForm);*/

                GameObject Blast = new GameObject("KiBlast");
                Blast.gameObject.layer = 10;
                Blast.transform.localScale = new Vector3(0.35f, 0.35f, 0.35f);
                Blast.transform.position = Arm.position + (-Arm.up * 0.3f);
                Blast.transform.rotation = Arm.rotation * Quaternion.Euler(0, 0, -90);
                Blast.gameObject.AddComponent<Rigidbody2D>().bodyType = RigidbodyType2D.Kinematic;
                Blast.gameObject.GetComponent<Rigidbody2D>().interpolation = RigidbodyInterpolation2D.Interpolate;
                Blast.gameObject.GetComponent<Rigidbody2D>().fixedAngle = true;
                Blast.gameObject.AddComponent<CircleCollider2D>().radius = 0.6f;
                Blast.gameObject.AddComponent<BlastVFX>().KiSys = KiSys;

                foreach (var c1 in GetComponent<PersonBehaviour>().Limbs)
                    Physics2D.IgnoreCollision(c1.gameObject.GetComponent<Collider2D>(), Blast.gameObject.GetComponent<CircleCollider2D>(), true);

                Vector3 direction = finalPos - Blast.transform.position;
                float angle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg;
                Blast.transform.rotation = Quaternion.Euler(0f, 0f, angle);

                Blasts.Add(Blast);

                /*GetAllChildrenRecursive(Blast.transform);

                foreach (Transform child in Blast.transform)
                {
                    var sp = child.gameObject.GetComponent<Renderer>();
                    sp.sortingLayerName = Arm.gameObject.GetComponent<SpriteRenderer>().sortingLayerName;
                    sp.sortingOrder += 10;
                    }

                ChangePlayBackOfAllParticleSystems(Blast.transform, 2f);*/

                GameObject FireEffect = Instantiate(DBPU.KiBlast_Start, Arm.position - (Arm.up * 0.3f), Arm.rotation * Quaternion.Euler(0, 0, -90));
                FireEffect.transform.localScale = new Vector3(0.35f, 0.35f, 0.35f);
                ChangePlayBackOfAllParticleSystems(FireEffect.transform, 2f);
                FireEffect.transform.Find("Blast Color").gameObject.GetComponent<ParticleSystem>().startColor = KiColor(KiSys.CurrentForm);

                GetAllChildrenRecursive(FireEffect.transform);

                foreach (Transform child in FireEffect.transform)
                {
                    var sp = child.gameObject.GetComponent<Renderer>();
                    sp.sortingLayerName = Arm.gameObject.GetComponent<SpriteRenderer>().sortingLayerName;
                    sp.sortingOrder += 10;
                }

                if (barrageAmount < 10)
                {
                    AudioSource BlastAudio = new GameObject("BlastAudioSource").AddComponent<AudioSource>();
                    BlastAudio.transform.SetParent(FireEffect.transform, false);
                    Global global = FindObjectOfType<Global>();
                    global.AddAudioSource(BlastAudio, false);
                    BlastAudio.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.75f;
                    BlastAudio.outputAudioMixerGroup = global.SoundEffects;
                    BlastAudio.spatialBlend = 1;
                    BlastAudio.volume = DBPU.PowersVolume;
                    BlastAudio.maxDistance = 1000;
                    BlastAudio.PlayOneShot(DBPU.Attack_KiBlast_Fire);

                    barrageAmount += 1;
                }

                else
                {
                    barrageAmount = 0;
                }

                StartCoroutine(FollowTarget(Blast, FireEffect, finalPos));

                yield return new WaitForSeconds(0.025f);
            }

            yield return new WaitForSeconds(1.5f);

            TargetPosition = Target.transform.position;

            Chase = true;

            yield return new WaitForSeconds(5f);

            Blasts.Clear();
            Firing = false;

            yield return null;
        }

        private IEnumerator FollowTarget(GameObject Blast, GameObject FireEffect, Vector3 StopPosition)
        {
            while (Vector3.Distance(Blast.transform.position, StopPosition) > 0.2f)
            {
                Blast.transform.position = Vector3.Lerp(Blast.transform.position, StopPosition, Time.deltaTime * 2f);

                yield return new WaitForEndOfFrame();
            }

            Destroy(FireEffect);

            yield return new WaitUntil(() => Chase == true);

            yield return new WaitForSeconds(UnityEngine.Random.Range(0f, 1f));

            Vector3 direction = TargetPosition - Blast.transform.position;
            float angle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg;
            Blast.transform.rotation = Quaternion.Euler(0f, 0f, angle);


            Blast.gameObject.GetComponent<Rigidbody2D>().bodyType = RigidbodyType2D.Dynamic;
            Blast.gameObject.layer = 13;

            Blast.gameObject.AddComponent<BlastComponent>().User = gameObject;
            Blast.gameObject.GetComponent<BlastComponent>().Damage = RealDamage;
            Blast.gameObject.GetComponent<BlastComponent>().ID = ID;
            Blast.gameObject.GetComponent<BlastComponent>().KnockbackMultiplier = 0.1f;

            yield return new WaitUntil(() => Vector3.Distance(Blast.transform.position, TargetPosition) < 1f);

            yield return new WaitUntil(() => Vector3.Distance(Blast.transform.position, TargetPosition) > 1f);

            Blast.gameObject.GetComponent<BlastComponent>().HasHit = true;

            yield return null;
        }

        private IEnumerator KiCost()
        {
            if (DBPU.KiAttackCostMultiplier == 0f) yield break;

            float OGKiDrain = KiSys.currentKiDrainRate;
            float KiRegen = KiSys.baseRegen;

            if (OGKiDrain != 0f) KiSys.baseRegen = 0f;

            float FinalKi = KiSys.currentKi - (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier));
            float CurrentKi = KiSys.currentKi;

            while (CurrentKi > FinalKi)
            {
                KiSys.currentKi -= (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier)) * (Time.deltaTime);
                CurrentKi -= (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier)) * (Time.deltaTime);

                yield return new WaitForEndOfFrame();
            }

            if (OGKiDrain != 0f) KiSys.baseRegen = KiRegen;

            yield return null;
        }

        Color KiColor(string Form)
        {
            if (DBPU.KiBlast_CustomColorEnabled)
                return DBPU.GetKiBlastCustomColor(0.1f);

            if (KiSys.requiredColor != Color.clear)
            {
                return new Color(KiSys.requiredColor.r, KiSys.requiredColor.g, KiSys.requiredColor.b, 0.1f);
            }

            else
            {
                Dictionary<string, Color> ogColors = new Dictionary<string, Color>
                {
                    { "Base", new Color(1f, 0.85f, 0.3f, 0.1f) },
                    { "SSJ1", new Color(1f, 0.85f, 0.3f, 0.1f) },
                    { "PSSJ", new Color(1f, 0.85f, 0.3f, 0.1f) },
                    { "SSJ2", new Color(1f, 0.85f, 0.3f, 0.1f) },
                    { "SSJ3", new Color(1f, 0.75f, 0f, 0.1f) },
                    { "SSJGod", new Color(0f, 0.75f, 1f, 0.1f) },
                    { "SSJBlue", new Color(0f, 0.75f, 1f, 0.1f) },
                    { "PSSJBlue", new Color(0f, 0.75f, 1f, 0.1f) },
                    { "SSJBlueEvolution", new Color(0f, 0.3f, 0.6f, 0.1f) },
                    { "MUI", new Color(0f, 0.75f, 1f, 0.1f) },
                    { "FirstForm", new Color(1f, 0.4f, 1f, 0.1f) },
                    { "SecondForm", new Color(1f, 0.4f, 1f, 0.1f) },
                    { "ThirdForm", new Color(1f, 0.4f, 1f, 0.1f) },
                    { "FinalForm", new Color(1f, 0.4f, 1f, 0.1f) },
                    { "FullPower", new Color(1f, 0.4f, 1f, 0.1f) },
                    { "GoldenForm", new Color(1f, 0f, 0.2f, 0.1f) },
                    { "Android", new Color(0f, 0.75f, 1f, 0.1f) },
                    { "Ikari", new Color(0f, 1f, 0f, 0.1f) },
                    { "FPSSJ", new Color(0f, 1f, 0f, 0.1f) }
                    };

                if (ogColors.TryGetValue(Form, out Color predefinedColor))
                {
                    return predefinedColor;
                }

                else
                {
                    return new Color(1f, 0.85f, 0.3f, 0.1f);
                }
            }
        }

        void StopAllParticleSystems(Transform parent)
        {
            foreach (Transform child in parent)
            {
                GetAllChildrenRecursive(child);

                var ps = child.gameObject.GetComponent<ParticleSystem>();
                ps.Stop();
            }
        }

        void ChangePlayBackOfAllParticleSystems(Transform parent, float speed)
        {
            foreach (Transform child in parent)
            {
                var ps = child.gameObject.GetComponent<ParticleSystem>();
                ps.playbackSpeed *= speed;
            }
        }

        void GetAllChildrenRecursive(Transform parent)
        {
            foreach (Transform child in parent)
            {
                child.position = new Vector3(child.position.x, child.position.y, 0f);
                var sp = child.gameObject.GetComponent<Renderer>();
                sp.sortingLayerName = "Bubbles";
                sp.sortingOrder = 100;

                GetAllChildrenRecursive(child);
            }
        }

