    public class SolarFlare : MonoBehaviour
    {
        private KiSystem KiSys;
        private AudioSource audioSource;
        private AudioSource audioSource2;

        public bool Active = false;
        public bool Using = false;
        public bool Firing = false;
        public float CostPercent = 0.25f;
        public float flareDuration = 4.25f;
        public float brightnessOutput = 1f;

        public string Character = "Human";

        public List<PersonBehaviour> Persons = new List<PersonBehaviour>();

        public LightSprite Light;

        private void OnDestroy()
        {
            if (Light != null) Destroy(Light);
        }

        private void Awake()
        {
            audioSource = new GameObject("AudioSource").AddComponent<AudioSource>();
            audioSource.transform.SetParent(transform.Find("Head"), false);
            Global global = FindObjectOfType<Global>();
            global.AddAudioSource(audioSource, false);
            audioSource.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.85f;
            audioSource.outputAudioMixerGroup = global.SoundEffects;
            audioSource.spatialBlend = 1;
            audioSource.volume = DBPU.PowersVolume;
            audioSource.maxDistance = 1000;

            audioSource2 = new GameObject("AudioSource").AddComponent<AudioSource>();
            audioSource2.transform.SetParent(transform.Find("Head"), false);
            Global global2 = FindObjectOfType<Global>();
            global2.AddAudioSource(audioSource2, false);
            audioSource2.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.85f;
            audioSource2.outputAudioMixerGroup = global2.SoundEffects;
            audioSource2.spatialBlend = 1;
            audioSource2.volume = DBPU.VoiceLineVolume;
            audioSource2.maxDistance = 1000;
        }

        private void Start()
        {
            if (!GetComponent<KiSystem>()) gameObject.AddComponent<KiSystem>();
            KiSys = GetComponent<KiSystem>();

            foreach (var limb in GetComponent<PersonBehaviour>().Limbs)
            {
                if (MCP_Utils.LimbCanUsePowers(limb) && limb.name.Contains("LowerArm"))
                {
                    limb.gameObject.AddComponent<UseEventTrigger>().Action = () =>
                    {
                        if (!KiHandLoadout.LegacyAllowed(limb, "SolarFlare")) return;
                        if (!limb.Person.IsAlive() || Active == false || Firing == true || KiSys.currentKi < KiSys.maxKi * (CostPercent * 1.5f)) return;

                        StartCoroutine(Fire());
                    };
                }
            }
        }

        private void FixedUpdate()
        {
            if (audioSource.volume != DBPU.PowersVolume) audioSource.volume = DBPU.PowersVolume;
            if (audioSource2.volume != DBPU.VoiceLineVolume) audioSource2.volume = DBPU.VoiceLineVolume;

            if (Using == true)
            {
                foreach (Collider2D collider2D in Physics2D.OverlapCircleAll(transform.Find("Head").transform.position, 20f, LayerMask.GetMask("Objects", "CollidingDebris")))
                {
                    if (collider2D.gameObject.GetComponent<LimbBehaviour>() && collider2D.transform.root.gameObject != gameObject && !Persons.Contains(collider2D.gameObject.GetComponent<LimbBehaviour>().Person))
                    {
                        Persons.Add(collider2D.gameObject.GetComponent<LimbBehaviour>().Person);
                        StartCoroutine(Stunned(collider2D.gameObject.GetComponent<LimbBehaviour>().Person));
                    }
                }
            }
        }

        private IEnumerator Stunned(PersonBehaviour Person)
        {
            while (Using == true)
            {
                if (Person.ActivePose.State != PoseState.Protective)
                {
                    /*Vector3 direction = (transform.Find("Head").transform.position - Person.transform.Find("Head").transform.position).normalized;
                    float angle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg;

                    float angle2 = Person.transform.Find("Head").transform.localEulerAngles.z + (Person.transform.localScale.x > 0f ? 90f : -90f);

                    ModAPI.Notify(Mathf.Abs(((angle2 % 360 + 360) % 360) - angle));

                    if (Mathf.Abs(angle - angle2) < 50)
                    {*/
                    Person.OverridePoseIndex = 1;
                    //}
                }

                yield return new WaitForFixedUpdate();
            }

            yield return new WaitForSeconds(5f);

            if (Person.ActivePose.State != PoseState.Rest)
            {
                Person.OverridePoseIndex = 0;
            }

            yield return null;
        }

        private IEnumerator Fire()
        {
            Firing = true;
            Using = true;

            CostPercent = 0.25f;
            StartCoroutine(KiCost());

            if (DBPU.VoiceLines)
            {
                if (Character == "Goku") audioSource2.PlayOneShot(DBPU.Voice_Goku_SolarFlare);
                if (Character == "Krillin") audioSource2.PlayOneShot(DBPU.Voice_Krillin_SolarFlare);
                if (Character == "Tien") audioSource2.PlayOneShot(DBPU.Voice_Tien_SolarFlare);
            }

            audioSource.PlayOneShot(DBPU.Attack_SolarFlare_Fire);

            Light = ModAPI.CreateLight(transform.Find("Head").transform, new Color(1f, 1f, 1f, 1f), 1f, 0.1f);

            AudioSource audioSourceLoop = new GameObject("LoopAudioSource").AddComponent<AudioSource>();
            audioSourceLoop.transform.SetParent(Light.transform, false);
            Global global = FindObjectOfType<Global>();
            global.AddAudioSource(audioSourceLoop, false);
            audioSourceLoop.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.85f;
            audioSourceLoop.outputAudioMixerGroup = global.SoundEffects;
            audioSourceLoop.spatialBlend = 1;
            audioSourceLoop.volume = 0;
            audioSourceLoop.maxDistance = 1000;

            audioSourceLoop.clip = DBPU.Attack_SolarFlare_Loop;
            audioSourceLoop.loop = true;
            audioSourceLoop.Play();

            StartCoroutine(SoundManagement(audioSourceLoop));

            if (GetComponent<PersonBehaviour>().ActivePose.State == PoseState.Protective)
            {
                GetComponent<PersonBehaviour>().OverridePoseIndex = 0;
            }

            float angle = 0f;

            float targetBrightness = 35f * brightnessOutput;

            while (Light.Brightness < targetBrightness * 0.85f)
            {
                Light.transform.localRotation = Quaternion.Euler(0f, 0f, angle + (25f * Time.deltaTime));

                Light.Brightness = Mathf.Lerp(Light.Brightness, targetBrightness, 2 * Time.deltaTime);
                Light.Radius = Mathf.Lerp(Light.Radius, 100f, 2f * Time.deltaTime);

                yield return null;
            }

            float time = 0f;

            while (time < flareDuration)
            {
                Light.transform.localRotation = Quaternion.Euler(0f, 0f, angle + (25f * Time.deltaTime));

                time += Time.deltaTime;

                yield return null;
            }

            Using = false;

            while (Light.Brightness > 0f)
            {
                Light.transform.localRotation = Quaternion.Euler(0f, 0f, angle + (25f * Time.deltaTime));

                Light.Brightness = Mathf.Lerp(Light.Brightness, -5f, 2f * Time.deltaTime);
                Light.Radius = Mathf.Lerp(Light.Radius, -6f, 2f * Time.deltaTime);

                yield return null;
            }

            Firing = false;
            Destroy(Light);

            yield return new WaitForSeconds(2f);

            Persons.Clear();

            yield return null;
        }

        private IEnumerator SoundManagement(AudioSource Loop)
        {
            while (Loop.volume < 1f)
            {
                Loop.volume += 0.8f * Time.deltaTime;

                yield return null;
            }

            yield return new WaitUntil(() => Using == false);

            while (Loop.volume > 0f)
            {
                Loop.volume -= 0.8f * Time.deltaTime;

                yield return null;
            }

            yield return null;
        }

        private IEnumerator KiCost()
        {
            if (DBPU.KiAttackCostMultiplier == 0f) yield break;

            float OGKiDrain = KiSys.currentKiDrainRate;
            float KiRegen = KiSys.baseRegen;

            if (OGKiDrain != 0f) KiSys.baseRegen = 0f;

            float FinalKi = KiSys.currentKi - (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier));
            float CurrentKi = KiSys.currentKi;

            while (CurrentKi > FinalKi)
            {
                KiSys.currentKi -= (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier)) * (Time.deltaTime * 0.25f);
                CurrentKi -= (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier)) * (Time.deltaTime * 0.25f);

                yield return new WaitForEndOfFrame();
            }

            if (OGKiDrain != 0f) KiSys.baseRegen = KiRegen;

            yield return null;
        }
    }

    public class GodsWrathBehaviour : MonoBehaviour
    {
        private KiSystem KiSys;
        private MultipliersAndStuffs Multipliers;
        private PersonBehaviour person;
        private Transform middleBody;
        private PhysicalBehaviour middlePhys;
        private BlastBehaviour blastRef;
        private string blastId;

        public bool Active = false;
        public bool Firing = false;
        public float CostPercent = 0.004f;
        public float ShotInterval = 0.04f;
        public float Damage = 0f;
        public float DamageOutput = 1.35f;
        public float KnockbackMultiplier = 1.35f;
        public float ExplosionSizeMultiplier = 1.2f;
        public float Speed = 95f;

        float nextShotTime;

        private void Start()
        {
            person = GetComponent<PersonBehaviour>();
            if (!GetComponent<KiSystem>()) gameObject.AddComponent<KiSystem>();
            KiSys = GetComponent<KiSystem>();
            if (!GetComponent<MultipliersAndStuffs>()) gameObject.AddComponent<MultipliersAndStuffs>();
            Multipliers = GetComponent<MultipliersAndStuffs>();
            blastRef = GetComponent<BlastBehaviour>();
            if (Damage == 0f) Damage = (CombatPowerController.AttackHealth(person) / Multipliers.FinalMultiplier) / 120f;
            blastId = gameObject.name + "_GodsWrath";

            middleBody = person.transform.Find("Body/MiddleBody");
            if (middleBody == null)
            {
                foreach (var limb in person.Limbs)
                {
                    if (limb.name.Contains("MiddleBody"))
                    {
                        middleBody = limb.transform;
                        break;
                    }
                }
            }

            if (middleBody != null) middlePhys = middleBody.GetComponent<PhysicalBehaviour>();
        }

        private void Update()
        {
            if (!Active || person == null || !person.IsAlive() || middlePhys == null) return;
            if (!middlePhys.IsBeingUsedContinuously()) return;
            if (Firing || KiSys.currentKi < KiSys.maxKi * (CostPercent * 3f)) return;
            if (Time.time < nextShotTime) return;

            nextShotTime = Time.time + ShotInterval;
            StartCoroutine(FireShot());
        }

        Color GetKiColor()
        {
            if (blastRef != null) return blastRef.KiColor(KiSys.CurrentForm);
            return new Color(0.75f, 0.35f, 1f, 0.12f);
        }

        static void SpeedUpParticles(Transform parent, float speed)
        {
            foreach (Transform child in parent)
            {
                var ps = child.gameObject.GetComponent<ParticleSystem>();
                if (ps != null) ps.playbackSpeed *= speed;
            }
        }

        IEnumerator FireShot()
        {
            Firing = true;
            KiSys.currentKi -= KiSys.maxKi * CostPercent * DBPU.KiAttackCostMultiplier;

            float realDamage = (Damage * Multipliers.FinalMultiplier) * Multipliers.KiOutput * DamageOutput;
            float angle = Random.Range(0f, 360f);
            Vector3 origin = middleBody.position;
            Quaternion rotation = Quaternion.Euler(0f, 0f, angle);

            GameObject blast = new GameObject("GodsWrathBlast");
            blast.layer = 9;
            blast.transform.localScale = new Vector3(0.32f, 0.32f, 0.32f);
            blast.transform.position = origin;
            blast.transform.rotation = rotation * Quaternion.Euler(0f, 0f, -90f);
            blast.AddComponent<Rigidbody2D>().bodyType = RigidbodyType2D.Dynamic;
            blast.GetComponent<Rigidbody2D>().interpolation = RigidbodyInterpolation2D.Interpolate;
            blast.GetComponent<Rigidbody2D>().velocity = blast.transform.right * Speed;
            blast.GetComponent<Rigidbody2D>().fixedAngle = true;
            blast.AddComponent<CircleCollider2D>().radius = 0.55f;

            foreach (var limb in person.Limbs)
                Physics2D.IgnoreCollision(limb.gameObject.GetComponent<Collider2D>(), blast.GetComponent<CircleCollider2D>(), true);

            var blastComp = blast.AddComponent<BlastComponent>();
            blastComp.User = gameObject;
            blastComp.Damage = realDamage;
            blastComp.ID = blastId;
            blastComp.KnockbackMultiplier = KnockbackMultiplier;
            blastComp.ExplosionSizeMultiplier = ExplosionSizeMultiplier * Mathf.Max(0.1f, DBPU.KiBlast_ExplosionSizeMultiplier);

            GameObject fireEffect = Instantiate(DBPU.KiBlast_Start, origin, rotation * Quaternion.Euler(0f, 0f, -90f));
            fireEffect.transform.localScale = new Vector3(0.28f, 0.28f, 0.28f);
            SpeedUpParticles(fireEffect.transform, 2.2f);
            var blastColor = fireEffect.transform.Find("Blast Color");
            if (blastColor != null)
            {
                var ps = blastColor.GetComponent<ParticleSystem>();
                if (ps != null) ps.startColor = GetKiColor();
            }

            yield return new WaitForSeconds(0.05f);
            if (fireEffect != null) Destroy(fireEffect);
            Firing = false;
        }
    }

    public class CataclysmicOrbBehaviour : MonoBehaviour
    {
        private KiSystem KiSys;
        private MultipliersAndStuffs Multipliers;
        private PersonBehaviour person;
        private BlastBehaviour blastRef;
        private string blastId;

        public bool Active = false;
        public bool Firing = false;
        public float CostPercent = 0.08f;
        public float Damage = 0f;
        public float DamageOutput = 2.5f;
        public float Speed = 110f;

        private void Start()
        {
            person = GetComponent<PersonBehaviour>();
            if (!GetComponent<KiSystem>()) gameObject.AddComponent<KiSystem>();
            KiSys = GetComponent<KiSystem>();
            if (!GetComponent<MultipliersAndStuffs>()) gameObject.AddComponent<MultipliersAndStuffs>();
            Multipliers = GetComponent<MultipliersAndStuffs>();
            blastRef = GetComponent<BlastBehaviour>();
            if (Damage == 0f) Damage = (CombatPowerController.AttackHealth(person) / Multipliers.FinalMultiplier) / 30f;
            blastId = gameObject.name + "_CataclysmicOrb";

            CeceUtils.DelayedInvoke(0.25f, RegisterArmTriggers);
        }

        void RegisterArmTriggers()
        {
            if (person == null) return;

            foreach (var limb in person.Limbs)
            {
                if (!MCP_Utils.LimbCanUsePowers(limb) || !limb.name.Contains("LowerArm")) continue;

                var trigger = limb.gameObject.GetOrAddComponent<UseEventTrigger>();
                Action previous = trigger.Action;
                LimbBehaviour capturedLimb = limb;
                trigger.Action = () =>
                {
                    if (!Active || !KiHandLoadout.LegacyAllowed(capturedLimb, "CataclysmicOrb"))
                    {
                        previous?.Invoke();
                        return;
                    }

                    if (!person.IsAlive() || Firing || capturedLimb.Health <= 0f) return;
                    if (KiSys.currentKi < KiSys.maxKi * (CostPercent * 1.5f)) return;
                    StartCoroutine(Fire(capturedLimb.transform));
                };
            }
        }

        Color GetKiColor()
        {
            if (blastRef != null) return blastRef.KiColor(KiSys.CurrentForm);
            return new Color(0.85f, 0.45f, 1f, 0.2f);
        }

        static void SpeedUpParticles(Transform parent, float speed)
        {
            foreach (Transform child in parent)
            {
                var ps = child.gameObject.GetComponent<ParticleSystem>();
                if (ps != null) ps.playbackSpeed *= speed;
            }
        }

        IEnumerator Fire(Transform arm)
        {
            Firing = true;
            KiSys.currentKi -= KiSys.maxKi * CostPercent * DBPU.KiAttackCostMultiplier;

            float realDamage = (Damage * Multipliers.FinalMultiplier) * Multipliers.KiOutput * DamageOutput;
            Vector3 spawnPos = arm.position + (-arm.up * 0.25f);
            Quaternion rotation = arm.rotation * Quaternion.Euler(0f, 0f, -90f);

            GameObject orb = new GameObject("CataclysmicOrb");
            orb.layer = 9;
            orb.transform.localScale = new Vector3(0.18f, 0.18f, 0.18f);
            orb.transform.position = spawnPos;
            orb.transform.rotation = rotation;
            orb.AddComponent<Rigidbody2D>().bodyType = RigidbodyType2D.Dynamic;
            orb.GetComponent<Rigidbody2D>().interpolation = RigidbodyInterpolation2D.Interpolate;
            orb.GetComponent<Rigidbody2D>().velocity = orb.transform.right * Speed;
            orb.GetComponent<Rigidbody2D>().fixedAngle = true;
            orb.AddComponent<CircleCollider2D>().radius = 0.45f;

            foreach (var limb in person.Limbs)
                Physics2D.IgnoreCollision(limb.gameObject.GetComponent<Collider2D>(), orb.GetComponent<CircleCollider2D>(), true);

            var blastComp = orb.AddComponent<BlastComponent>();
            blastComp.User = gameObject;
            blastComp.Damage = realDamage;
            blastComp.ID = blastId;
            blastComp.KnockbackMultiplier = 2.5f;
            blastComp.ExplosionSizeMultiplier = 14f;

            GameObject fireEffect = Instantiate(DBPU.KiBlast_Start, spawnPos, rotation);
            fireEffect.transform.localScale = new Vector3(0.2f, 0.2f, 0.2f);
            SpeedUpParticles(fireEffect.transform, 2.5f);
            var blastColor = fireEffect.transform.Find("Blast Color");
            if (blastColor != null)
            {
                var ps = blastColor.GetComponent<ParticleSystem>();
                if (ps != null) ps.startColor = GetKiColor();
            }

            audioSourcePlay(arm);

            yield return new WaitForSeconds(0.08f);
            if (fireEffect != null) Destroy(fireEffect);
            Firing = false;
        }

        void audioSourcePlay(Transform arm)
        {
            var audio = new GameObject("CataclysmicOrbAudio").AddComponent<AudioSource>();
            audio.transform.SetParent(arm, false);
            Global global = FindObjectOfType<Global>();
            global.AddAudioSource(audio, false);
            audio.outputAudioMixerGroup = global.SoundEffects;
            audio.spatialBlend = 1;
            audio.volume = DBPU.PowersVolume;
            audio.maxDistance = 1000;
            audio.PlayOneShot(DBPU.Attack_KiBlast_Fire);
        }
    }

    public class PiccoloGiantForm : MonoBehaviour
    {
        public bool Active = false;
        public bool Growing = false;
        public float GrowthSpeed = 3f;
        public float ShrinkSpeed = 5f;
        public float HeightSmoothTime = 0.4f;
        public float targetSizeMeters = 15f;

        private PersonBehaviour person;
        private GameObject middleBody;
        private KiSystem kiSys;
        private HumanController humanController;
        private AuraHandler auraHandler;
        private string lastForm = "";
        private bool lastActive;
        private bool lastGrowing;
        private float lastAppliedHeight = -1f;
        private float animHeight;
        private float heightVelocity;
        private bool animating;
        private Coroutine heightAnim;

        private float GetFormBaseHeight(string form)
        {
            if (form == "OrangePiccolo") return 2.74f;
            return 2.26f;
        }

        private float GetMaxHeight(string form)
        {
            if (targetSizeMeters > 0f) return targetSizeMeters;
            if (form == "OrangePiccolo") return 20f;
            return 15f;
        }

        private string GetCurrentForm()
        {
            if (kiSys != null && !string.IsNullOrEmpty(kiSys.CurrentForm)) return kiSys.CurrentForm;
            return "Base";
        }

        private float GetTargetHeight()
        {
            string form = GetCurrentForm();
            return (Active && Growing) ? GetMaxHeight(form) : GetFormBaseHeight(form);
        }

        private float GetActualHeightMeters()
        {
            return Mathf.Abs(person.transform.localScale.y) * 1.68f;
        }

        private void Start()
        {
            person = GetComponent<PersonBehaviour>();
            kiSys = GetComponent<KiSystem>();
            middleBody = person.Limbs[2].gameObject;
            humanController = person.Limbs[0].GetComponent<HumanController>();
            auraHandler = GetComponent<AuraHandler>();

            lastForm = GetCurrentForm();
            lastActive = Active;
            lastGrowing = Growing;
            lastAppliedHeight = GetActualHeightMeters();

            StartCoroutine(SetupHeadActivation());
        }

        private IEnumerator SetupHeadActivation()
        {
            yield return null;

            var head = person.transform.Find("Head");
            System.Action growthAction = () =>
            {
                if (!person.IsAlive() || head.GetComponent<LimbBehaviour>().Health <= 0f || !Active) return;
                Growing = !Growing;
                NotifyStateChanged();
            };

            var trigger = head.GetComponent<UseEventTrigger>();
            if (trigger == null)
            {
                head.gameObject.AddComponent<UseEventTrigger>().Action = growthAction;
            }
            else
            {
                var previous = trigger.Action;
                trigger.Action = () =>
                {
                    growthAction();
                    previous?.Invoke();
                };
            }
        }

        private void FixedUpdate()
        {
            if (person == null || !person.IsAlive() || animating) return;

            string form = GetCurrentForm();
            bool formChanged = form != lastForm;
            bool stateChanged = Active != lastActive || Growing != lastGrowing;

            if (formChanged || stateChanged)
            {
                lastForm = form;
                lastActive = Active;
                lastGrowing = Growing;
                StartHeightAnimation();
            }
        }

        public void NotifyStateChanged()
        {
            lastActive = Active;
            lastGrowing = Growing;
            lastForm = GetCurrentForm();
            StartHeightAnimation();
        }

        private void StartHeightAnimation()
        {
            if (heightAnim != null)
                StopCoroutine(heightAnim);

            heightAnim = StartCoroutine(AnimateHeightCoroutine());
        }

        private void FreezeForResize()
        {
            foreach (var limb in person.Limbs)
            {
                if (limb?.gameObject == null) continue;
                if (!limb.gameObject.GetComponent<FreezeBehaviour>())
                    limb.gameObject.AddComponent<FreezeBehaviour>();
            }
        }

        private void UnfreezeAfterResize()
        {
            foreach (var limb in person.Limbs)
            {
                if (limb?.gameObject == null) continue;
                var freeze = limb.gameObject.GetComponent<FreezeBehaviour>();
                if (freeze != null) Destroy(freeze);
                if (limb.PhysicalBehaviour != null)
                    MCP_Utils.ForceClearViaExit(limb.PhysicalBehaviour);
            }
        }

        private IEnumerator AnimateHeightCoroutine()
        {
            animating = true;
            float target = GetTargetHeight();

            if (Mathf.Abs(GetActualHeightMeters() - target) < 0.02f)
            {
                ApplyHeightAt(target, true);
                animating = false;
                heightAnim = null;
                yield break;
            }

            FreezeForResize();
            animHeight = GetActualHeightMeters();
            heightVelocity = 0f;

            yield return new WaitForFixedUpdate();

            while (person != null && person.IsAlive())
            {
                target = GetTargetHeight();
                float formBase = GetFormBaseHeight(GetCurrentForm());
                float formMax = GetMaxHeight(GetCurrentForm());

                if (Active && Growing)
                {
                    animHeight = Mathf.SmoothDamp(animHeight, target, ref heightVelocity, HeightSmoothTime, GrowthSpeed * 1.5f, Time.fixedDeltaTime);
                }
                else
                {
                    heightVelocity = 0f;
                    animHeight = Mathf.MoveTowards(animHeight, target, ShrinkSpeed * Time.fixedDeltaTime);
                }

                animHeight = Mathf.Clamp(animHeight, formBase, formMax);

                if (Mathf.Abs(animHeight - lastAppliedHeight) > 0.02f)
                    ApplyHeightAt(animHeight, false);

                if (Mathf.Abs(animHeight - target) < 0.03f)
                    break;

                yield return new WaitForFixedUpdate();
            }

            if (person != null && person.IsAlive())
                ApplyHeightAt(GetTargetHeight(), true);

            UnfreezeAfterResize();
            animating = false;
            heightAnim = null;
        }

        private void ApplyHeightAt(float meters, bool updateWeight)
        {
            person.transform.root.transform.SetHeight(person, middleBody, meters);
            person.ForceAllLimbsClearViaExit();
            lastAppliedHeight = meters;

            if (auraHandler != null && auraHandler.AuraActive)
            {
                float personScale = Mathf.Abs(person.transform.localScale.x);
                float auraMult = personScale > 1.15f ? (1f + (personScale - 1f)) : 1f;
                auraHandler.SetAuraScale(auraMult);
            }

            if (updateWeight && humanController != null)
                humanController.StartChangeWeight();
        }

        public void SyncAfterTransformation(float formSizeMeters)
        {
            if (heightAnim != null)
            {
                StopCoroutine(heightAnim);
                heightAnim = null;
                animating = false;
                UnfreezeAfterResize();
            }

            lastForm = GetCurrentForm();
            float targetHeight = (!Active || !Growing) ? formSizeMeters : Mathf.Max(formSizeMeters, GetTargetHeight());
            ApplyHeightAt(targetHeight, true);
        }
    }

    public partial class KiShield : MonoBehaviour { }

    public class StardustFall : MonoBehaviour
    {
        private MultipliersAndStuffs Multipliers;
        private KiSystem KiSys;

        public bool Active = false;
        public bool Firing = false;
        public float RealDamage = 100f;
        public float CostPercent = 0.01f;

        private Quaternion TargetRotation;

        public float Damage = 0f;
        public float Speed = 120f;
        public float DamageOutput = 1f;
        public float KnockbackOutput = 1f;
        public int blastsAmount = 160;
        public float durationSeconds = 2f;
        public string ID = "Blast";

        private void Start()
        {
            if (!GetComponent<KiSystem>()) gameObject.AddComponent<KiSystem>();
            KiSys = GetComponent<KiSystem>();

            if (!GetComponent<MultipliersAndStuffs>()) gameObject.AddComponent<MultipliersAndStuffs>();
            Multipliers = GetComponent<MultipliersAndStuffs>();

            if (Damage == 0f) Damage = (CombatPowerController.AttackHealth(GetComponent<PersonBehaviour>()) / Multipliers.FinalMultiplier) / 60f;

            ID = gameObject.name + "_Blast" + Random.Range(0, 999);

            foreach (var limb in GetComponent<PersonBehaviour>().Limbs)
            {
                if (MCP_Utils.LimbCanUsePowers(limb) && limb.name.Contains("LowerArm"))
                {
                    limb.gameObject.AddComponent<UseEventTrigger>().Action = () =>
                    {
                        if (!KiHandLoadout.LegacyAllowed(limb, "StardustFall")) return;
                        if (!limb.Person.IsAlive() || limb.Health <= 0f || Active == false || Firing == true || KiSys.currentKi < KiSys.maxKi * (CostPercent * 4f)) return;

                        StartCoroutine(Fire(limb.transform));
                    };
                }
            }
        }

        private IEnumerator Fire(Transform Arm)
        {
            Firing = true;

            StartCoroutine(KiCost());

            RealDamage = (Damage * Multipliers.FinalMultiplier) * Multipliers.KiOutput * DamageOutput;

            TargetRotation = Arm.rotation;

            Arm.gameObject.AddComponent<FreezeBehaviour>();

            for (int i = 0; i < blastsAmount; i++)
            {
                GameObject Blast = new GameObject("KiBlast");
                Blast.gameObject.layer = 13;
                Blast.transform.localScale = new Vector3(0.35f, 0.35f, 0.35f);
                Blast.transform.position = Arm.position + (-Arm.up * 0.3f);
                float Angle = Random.Range(-78f, 78f);
                Blast.transform.rotation = TargetRotation * Quaternion.Euler(0, 0, Angle);
                Blast.gameObject.AddComponent<Rigidbody2D>().bodyType = RigidbodyType2D.Dynamic;
                Blast.gameObject.GetComponent<Rigidbody2D>().interpolation = RigidbodyInterpolation2D.Interpolate;
                //Blast.gameObject.GetComponent<Rigidbody2D>().fixedAngle = true;
                if (Blast.gameObject.GetComponent<Rigidbody2D>().bodyType != RigidbodyType2D.Static) Blast.gameObject.GetComponent<Rigidbody2D>().velocity = -Blast.transform.up * Speed;
                Blast.gameObject.GetComponent<Rigidbody2D>().gravityScale = 0f;
                Blast.gameObject.AddComponent<CircleCollider2D>().radius = 0.6f;
                var tr = Blast.gameObject.AddComponent<TrailRenderer>();
                Color starttrailColor = new Color(0f, Random.Range(0.6f, 0.85f), Random.Range(0.85f, 1f), Random.Range(0.005f, 0.02f));
                Color endtrailColor = new Color(0f, Random.Range(0.6f, 0.85f), Random.Range(0.85f, 1f), Random.Range(0.02f, 0.04f));
                tr.startColor = starttrailColor;
                tr.endColor = endtrailColor;
                //tr.widthMultiplier = 0.4f;
                tr.startWidth = 0.25f;
                tr.endWidth = 0.25f;
                tr.time = 1.5f;
                tr.numCapVertices = 8;
                tr.numCornerVertices = 8;
                tr.textureMode = LineTextureMode.Stretch;
                tr.material = ModAPI.FindMaterial("VeryBright");

                Blast.gameObject.AddComponent<BlastComponent>().User = gameObject;
                Blast.gameObject.GetComponent<BlastComponent>().Damage = RealDamage;
                Blast.gameObject.GetComponent<BlastComponent>().ID = ID;
                Blast.gameObject.GetComponent<BlastComponent>().KnockbackMultiplier = 0.1f * KnockbackOutput;
                Blast.gameObject.GetComponent<BlastComponent>().HandleSelfMovement = false;

                StartCoroutine(Animation(tr));
                StartCoroutine(DirectionChange(Blast.transform, Angle));

                foreach (var c1 in GetComponent<PersonBehaviour>().Limbs)
                    Physics2D.IgnoreCollision(c1.gameObject.GetComponent<Collider2D>(), Blast.gameObject.GetComponent<CircleCollider2D>(), true);

                yield return new WaitForSeconds(0.02f);
            }

            if (Arm.gameObject.GetComponent<FreezeBehaviour>()) Destroy(Arm.gameObject.GetComponent<FreezeBehaviour>());

            yield return new WaitForSeconds(durationSeconds);

            Firing = false;

            yield return null;
        }

        private IEnumerator DirectionChange(Transform Blast, float Angle)
        {
            Rigidbody2D rb = Blast.GetComponent<Rigidbody2D>();

            float maxSpeed = 55f;
            float minSpeed = 2f;

            float slowStartAngle = 35f;

            while (Mathf.Abs(Mathf.DeltaAngle(Blast.eulerAngles.z, TargetRotation.eulerAngles.z)) > 0.1f)
            {
                float angleDiff = Mathf.Abs(Mathf.DeltaAngle(Blast.eulerAngles.z, TargetRotation.eulerAngles.z));

                float t = Mathf.Clamp01(angleDiff / slowStartAngle);
                float changeSpeed = Mathf.Lerp(minSpeed, maxSpeed, t);

                Blast.rotation = Quaternion.RotateTowards(
                    Blast.rotation,
                    TargetRotation,
                    changeSpeed * Time.fixedDeltaTime
                );

                if (rb.bodyType != RigidbodyType2D.Static) rb.velocity = -Blast.up * Speed;

                yield return new WaitForFixedUpdate();
            }
        }

        private IEnumerator Animation(TrailRenderer tr)
        {
            for (int i = 0; i < 80; i++)
            {
                tr.startWidth += Random.Range(0.005f, 0.02f);
                tr.gameObject.GetComponent<CircleCollider2D>().radius += 0.02f;

                yield return new WaitForFixedUpdate();
            }

            yield return null;
        }

        private IEnumerator KiCost()
        {
            if (DBPU.KiAttackCostMultiplier == 0f) yield break;

            float OGKiDrain = KiSys.currentKiDrainRate;
            float KiRegen = KiSys.baseRegen;

            if (OGKiDrain != 0f) KiSys.baseRegen = 0f;

            float FinalKi = KiSys.currentKi - (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier));
            float CurrentKi = KiSys.currentKi;

            while (CurrentKi > FinalKi)
            {
                KiSys.currentKi -= (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier)) * (Time.deltaTime);
                CurrentKi -= (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier)) * (Time.deltaTime);

                yield return new WaitForEndOfFrame();
            }

            if (OGKiDrain != 0f) KiSys.baseRegen = KiRegen;

            yield return null;
        }
    }

    public class GodPunisher : MonoBehaviour
    {
        private MultipliersAndStuffs Multipliers;
        private KiSystem KiSys;

        public bool Active = false;
        public bool Firing = false;
        public float RealDamage = 100f;
        public float CostPercent = 0.05f;

        private Quaternion TargetRotation;

        public float Damage = 0f;
        public float Speed = 80f;
        public float DamageOutput = 1f;
        public float KnockbackOutput = 1f;
        public int blastsAmount = 100;
        public string ID = "Blast";

        private void Start()
        {
            if (!GetComponent<KiSystem>()) gameObject.AddComponent<KiSystem>();
            KiSys = GetComponent<KiSystem>();

            if (!GetComponent<MultipliersAndStuffs>()) gameObject.AddComponent<MultipliersAndStuffs>();
            Multipliers = GetComponent<MultipliersAndStuffs>();

            if (Damage == 0f) Damage = (CombatPowerController.AttackHealth(GetComponent<PersonBehaviour>()) / Multipliers.FinalMultiplier) / 60f;

            ID = gameObject.name + "_Blast" + Random.Range(0, 999);

            foreach (var limb in GetComponent<PersonBehaviour>().Limbs)
            {
                if (MCP_Utils.LimbCanUsePowers(limb) && limb.name.Contains("LowerArm"))
                {
                    limb.gameObject.AddComponent<UseEventTrigger>().Action = () =>
                    {
                        if (!KiHandLoadout.LegacyAllowed(limb, "GodPunisher")) return;
                        if (!limb.Person.IsAlive() || limb.Health <= 0f || Active == false || Firing == true || KiSys.currentKi < KiSys.maxKi * (CostPercent * 4f)) return;

                        StartCoroutine(Fire(limb.transform));
                    };
                }
            }
        }

        private IEnumerator Fire(Transform Arm)
        {
            Firing = true;

            StartCoroutine(KiCost());

            RealDamage = (Damage * Multipliers.FinalMultiplier) * Multipliers.KiOutput * DamageOutput;

            TargetRotation = Arm.rotation;

            Arm.gameObject.AddComponent<FreezeBehaviour>();

            for (int i = 0; i < blastsAmount; i++)
            {
                GameObject Blast = new GameObject("KiBlast");
                Blast.gameObject.layer = 9;
                Blast.transform.localScale = new Vector3(0.35f, 0.35f, 0.35f);
                Blast.transform.position = Arm.position + (-Arm.up * 0.3f);
                float Angle = Random.Range(-10f, 10f);
                Blast.transform.rotation = TargetRotation * Quaternion.Euler(0, 0, Angle);
                Blast.gameObject.AddComponent<Rigidbody2D>().bodyType = RigidbodyType2D.Dynamic;
                Blast.gameObject.GetComponent<Rigidbody2D>().interpolation = RigidbodyInterpolation2D.Interpolate;
                //Blast.gameObject.GetComponent<Rigidbody2D>().fixedAngle = true;
                if (Blast.gameObject.GetComponent<Rigidbody2D>().bodyType != RigidbodyType2D.Static) Blast.gameObject.GetComponent<Rigidbody2D>().velocity = -Blast.transform.up * Speed;
                Blast.gameObject.GetComponent<Rigidbody2D>().gravityScale = 0f;
                Blast.gameObject.AddComponent<CircleCollider2D>().radius = 0.6f;
                Blast.gameObject.AddComponent<BlastVFX>();

                Blast.gameObject.AddComponent<BlastComponent>().User = gameObject;
                Blast.gameObject.GetComponent<BlastComponent>().Damage = RealDamage;
                Blast.gameObject.GetComponent<BlastComponent>().ID = ID;
                Blast.gameObject.GetComponent<BlastComponent>().KnockbackMultiplier = 0.08f * KnockbackOutput;
                Blast.gameObject.GetComponent<BlastComponent>().ExplosionSizeMultiplier = 3f;
                Blast.gameObject.GetComponent<BlastComponent>().HandleSelfMovement = false;

                StartCoroutine(DirectionChange(Blast.transform, Angle));

                foreach (var c1 in GetComponent<PersonBehaviour>().Limbs)
                    Physics2D.IgnoreCollision(c1.gameObject.GetComponent<Collider2D>(), Blast.gameObject.GetComponent<CircleCollider2D>(), true);

                yield return new WaitForSeconds(0.02f);
            }

            if (Arm.gameObject.GetComponent<FreezeBehaviour>()) Destroy(Arm.gameObject.GetComponent<FreezeBehaviour>());

            yield return new WaitForSeconds(2f);

            Firing = false;

            yield return null;
        }

        private IEnumerator DirectionChange(Transform Blast, float Angle)
        {
            Rigidbody2D rb = Blast.GetComponent<Rigidbody2D>();

            float maxSpeed = 25f;
            float minSpeed = 5f;

            float slowStartAngle = 10f;

            float angleDiff = Mathf.Abs(Mathf.DeltaAngle(Blast.eulerAngles.z, TargetRotation.eulerAngles.z));
            float DesiredAngleDiff = angleDiff / 6f;

            while (Mathf.Abs(Mathf.DeltaAngle(Blast.eulerAngles.z, TargetRotation.eulerAngles.z)) > 0.1f)
            {
                angleDiff = Mathf.Abs(Mathf.DeltaAngle(Blast.eulerAngles.z, TargetRotation.eulerAngles.z));

                float t = Mathf.Clamp01(angleDiff / slowStartAngle);
                float changeSpeed = Mathf.Lerp(minSpeed, maxSpeed, t);

                Blast.rotation = Quaternion.RotateTowards(
                    Blast.rotation,
                    TargetRotation,
                    changeSpeed * Time.fixedDeltaTime
                );

                if (rb.bodyType != RigidbodyType2D.Static) rb.velocity = -Blast.up * Speed;

                yield return new WaitForFixedUpdate();
            }
        }

        private IEnumerator KiCost()
        {
            if (DBPU.KiAttackCostMultiplier == 0f) yield break;

            float OGKiDrain = KiSys.currentKiDrainRate;
            float KiRegen = KiSys.baseRegen;

            if (OGKiDrain != 0f) KiSys.baseRegen = 0f;

            float FinalKi = KiSys.currentKi - (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier));
            float CurrentKi = KiSys.currentKi;

            while (CurrentKi > FinalKi)
            {
                KiSys.currentKi -= (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier)) * (Time.deltaTime);
                CurrentKi -= (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier)) * (Time.deltaTime);

                yield return new WaitForEndOfFrame();
            }

            if (OGKiDrain != 0f) KiSys.baseRegen = KiRegen;

            yield return null;
        }

        public class BlastVFX : MonoBehaviour
        {
            private GameObject VFX;

            public void Start()
            {
                VFX = new GameObject("KiBlastVFX");
                VFX.transform.SetParent(transform, true);
                VFX.transform.position = transform.position;
                VFX.transform.localScale = new Vector3(0.044f, 0.05f, 1f);
                VFX.AddComponent<SpriteRenderer>().sprite = DBPU.DenseKiBlast_Sprite;
                VFX.GetComponent<SpriteRenderer>().material = ModAPI.FindMaterial("VeryBright");
                VFX.GetComponent<SpriteRenderer>().color = new Color(0.25f, 0.65f, 1f, 0.05f) /*new Color(1f, 1f, 1f, 0.05f)*/;
            }

            public void Update()
            {
                VFX.transform.position = transform.position;
                VFX.transform.eulerAngles += new Vector3(0f, 0f, 1200f * Time.deltaTime);
            }
        }
    }

    public class StardustBreaker : MonoBehaviour
    {
        private MultipliersAndStuffs Multipliers;
        private KiSystem KiSys;
        private AudioSource audioSource;

        private GameObject Ball;
        private Transform UsedArm;
        private float chargeSavedRegen;
        private bool chargeSuppressesRegen;

        public bool Active = false;
        public bool Charging = false;
        public bool FullCharged = false;
        public bool StillActive = false;
        public float RealDamage = 7500f;
        public float CostPercent = 0.1f;

        public float Damage = 0f;
        public float Speed = 80f;
        public float DamageOutput = 1f;
        public float KnockbackOutput = 1f;

        // The launched projectile has its own Rigidbody2D and BlastComponent.
        // Cancel only the orb still held by the hand; fired attacks remain in flight.
        public void CancelHeldCharge()
        {
            Active = false;
            if (!Charging) return;
            StopAllCoroutines();
            Charging = false;
            FullCharged = false;
            StillActive = false;
            UsedArm = null;
            if (Ball != null) { Destroy(Ball); Ball = null; }
            if (chargeSuppressesRegen && KiSys != null && KiSys.baseRegen == 0f)
                KiSys.baseRegen = chargeSavedRegen;
            chargeSuppressesRegen = false;
        }
        private void OnDestroy()
        {
            CancelHeldCharge();
            if (Ball != null) Destroy(Ball);
        }

        private void Awake()
        {
            audioSource = new GameObject("BeamAudioSource").AddComponent<AudioSource>();
            audioSource.transform.SetParent(transform.Find("Head"), false);
            Global global = FindObjectOfType<Global>();
            global.AddAudioSource(audioSource, false);
            audioSource.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.75f;
            audioSource.outputAudioMixerGroup = global.SoundEffects;
            audioSource.spatialBlend = 1;
            audioSource.volume = 1;
            audioSource.maxDistance = 1000;
        }

        private void Start()
        {
            if (!GetComponent<KiSystem>()) gameObject.AddComponent<KiSystem>();
            KiSys = GetComponent<KiSystem>();

            if (!GetComponent<MultipliersAndStuffs>()) gameObject.AddComponent<MultipliersAndStuffs>();
            Multipliers = GetComponent<MultipliersAndStuffs>();

            if (Damage == 0f) Damage = (CombatPowerController.AttackHealth(GetComponent<PersonBehaviour>()) / Multipliers.FinalMultiplier) / 40f;

            foreach (var limb in GetComponent<PersonBehaviour>().Limbs)
            {
                if (MCP_Utils.LimbCanUsePowers(limb) && limb.name.Contains("LowerArm"))
                {
                    limb.gameObject.AddComponent<UseEventTrigger>().Action = () =>
                    {
                        if (!KiHandLoadout.LegacyAllowed(limb, "StardustBreaker")) return;
                        if ((Charging == false && KiSys.currentKi < KiSys.maxKi * CostPercent) || (StillActive == true && Charging == false)) return;

                        if (limb.Health > 0f && Active == true && Charging == false)
                        {
                            UsedArm = limb.transform;
                            StartCoroutine(StartCharge(limb.transform));
                        }

                        else if (Active == true && Charging == true && FullCharged == true && UsedArm == limb.transform)
                        {
                            StillActive = true;
                        }
                    };
                }
            }
        }

        private void FixedUpdate()
        {
            if (Charging && (!Active || UsedArm == null || Ball == null || UsedArm.GetComponent<LimbBehaviour>().Health <= 0f))
            { CancelHeldCharge(); return; }
            if (Charging == true)
            {
                RealDamage = (Damage * Multipliers.FinalMultiplier) * Multipliers.KiOutput * DamageOutput;

                if (Ball != null)
                {
                    Ball.GetComponent<Rigidbody2D>().MovePosition(Vector3.Lerp(Ball.transform.position, (UsedArm.position + (-UsedArm.up * 0.175f) + (Vector3.up * 0.4f)), 20f * Time.deltaTime));

                    if (Active == false) Destroy(Ball);
                }
            }
        }

        private IEnumerator StartCharge(Transform Arm)
        {
            Charging = true;

            StartCoroutine(KiCost());

            Ball = Instantiate(DBPU.StardustBreaker, Arm.position + (-UsedArm.up * 0.175f) + (Vector3.up * 0.4f), Quaternion.identity);
            Ball.transform.localScale = new Vector3(0f, 0f, 0f);
            Ball.layer = 9;
            //Ball.transform.SetParent(Arm, false);

            Ball.gameObject.AddComponent<Rigidbody2D>().bodyType = RigidbodyType2D.Kinematic;
            Ball.gameObject.GetComponent<Rigidbody2D>().interpolation = RigidbodyInterpolation2D.Interpolate;

            //ChangePlayBackOfAllParticleSystems(Ball.transform, 0.42f);

            AudioSource BallAudio = new GameObject("BallAudioSource").AddComponent<AudioSource>();
            BallAudio.transform.SetParent(Ball.transform, false);
            Global global = FindObjectOfType<Global>();
            global.AddAudioSource(BallAudio, false);
            BallAudio.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.75f;
            BallAudio.outputAudioMixerGroup = global.SoundEffects;
            BallAudio.spatialBlend = 1;
            BallAudio.volume = 1;
            BallAudio.maxDistance = 1000;

            BallAudio.PlayOneShot(DBPU.Attack_StardustBreaker_Charging);

            float size = 0f;

            while (size < 0.2f)
            {
                size = Mathf.Lerp(size, 0.205f, 1.5f * Time.deltaTime);
                Ball.transform.localScale = new Vector3(size, size, size);

                yield return new WaitForFixedUpdate();
            }

            yield return new WaitForSeconds(0.6f);

            AudioSource AudioLoop = new GameObject("BallAudioSource").AddComponent<AudioSource>();
            AudioLoop.transform.SetParent(Ball.transform, false);
            global = FindObjectOfType<Global>();
            global.AddAudioSource(AudioLoop, false);
            AudioLoop.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.75f;
            AudioLoop.outputAudioMixerGroup = global.SoundEffects;
            AudioLoop.spatialBlend = 1;
            AudioLoop.volume = 0.2f;
            AudioLoop.maxDistance = 1000;
            AudioLoop.clip = DBPU.Attack_StardustBreaker_Loop;
            AudioLoop.loop = true;
            AudioLoop.Play();

            FullCharged = true;

            while (StillActive == false && Arm.GetComponent<LimbBehaviour>().Health > 0f)
            {
                yield return null;
            }

            if (Arm.GetComponent<LimbBehaviour>().Health > 0f) StartCoroutine(Release(Arm, BallAudio));

            else
            {
                FullCharged = false;
                Charging = false;

                Destroy(Ball);
            }

            yield return null;
        }

        private IEnumerator KiCost()
        {
            float OGKiDrain = KiSys.currentKiDrainRate;
            float KiRegen = KiSys.baseRegen;

            chargeSavedRegen = KiRegen;
            chargeSuppressesRegen = OGKiDrain != 0f;
            if (chargeSuppressesRegen) KiSys.baseRegen = 0f;

            float FinalKi = KiSys.currentKi - (KiSys.maxKi * CostPercent);
            float CurrentKi = KiSys.currentKi;

            while (CurrentKi > FinalKi)
            {
                KiSys.currentKi -= (KiSys.maxKi * CostPercent) * (Time.deltaTime / 5f);
                CurrentKi -= (KiSys.maxKi * CostPercent) * (Time.deltaTime / 5f);

                yield return new WaitForEndOfFrame();
            }

            if (OGKiDrain != 0f) KiSys.baseRegen = KiRegen;
            chargeSuppressesRegen = false;

            yield return null;
        }

        private IEnumerator Release(Transform Arm, AudioSource BallAudio)
        {
            FullCharged = false;
            Charging = false;

            BallAudio.PlayOneShot(DBPU.Attack_KiBlast_Fire);

            /*if (DBPU.VoiceLines)
            {
                if (Character == "Frieza") BeamAudio.PlayOneShot(DBPU.Voice_Goku_HA);
                }*/

            Rigidbody2D rb = Ball.GetComponent<Rigidbody2D>();
            rb.bodyType = RigidbodyType2D.Dynamic;
            rb.interpolation = RigidbodyInterpolation2D.Interpolate;
            if (rb.bodyType != RigidbodyType2D.Static) rb.velocity = -Arm.up * Speed;
            Ball.gameObject.AddComponent<CircleCollider2D>().radius = 0.6f;

            foreach (var c1 in GetComponent<PersonBehaviour>().Limbs)
                Physics2D.IgnoreCollision(c1.gameObject.GetComponent<Collider2D>(), Ball.gameObject.GetComponent<CircleCollider2D>(), true);

            Ball.gameObject.AddComponent<BlastComponent>().User = gameObject;
            Ball.gameObject.GetComponent<BlastComponent>().Damage = RealDamage;
            Ball.gameObject.GetComponent<BlastComponent>().ID = "Gogeta" + Random.Range(0, 100);
            Ball.gameObject.GetComponent<BlastComponent>().HandleSelfMovement = false;
            Ball.gameObject.GetComponent<BlastComponent>().ExplosionSizeMultiplier = 5f;
            Ball.gameObject.GetComponent<BlastComponent>().KnockbackMultiplier = 0.5f * KnockbackOutput;

            StillActive = true;

            yield return new WaitWhile(() => Ball != null);

            StillActive = false;

            yield return null;
        }
    }

    public class MeteorExplosion : MonoBehaviour
    {
        private MultipliersAndStuffs Multipliers;
        private KiSystem KiSys;
        private AudioSource audioSource;

        public int barrageAmount = 0;

        public bool Active = false;
        public bool Firing = false;
        public GameObject Target;
        public float RealDamage = 100f;
        public float CostPercent = 0.2f;

        public float Damage = 100f;
        public float DamageOutput = 1f;
        public float KnockbackOutput = 1f;

        private void Awake()
        {
            audioSource = new GameObject("VoiceLinesSource").AddComponent<AudioSource>();
            audioSource.transform.SetParent(transform.Find("Head"), false);
            Global global = FindObjectOfType<Global>();
            global.AddAudioSource(audioSource, false);
            audioSource.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.75f;
            audioSource.outputAudioMixerGroup = global.SoundEffects;
            audioSource.spatialBlend = 0.98f;
            audioSource.volume = 1;
            audioSource.maxDistance = 1000;
        }

        private void Start()
        {
            if (!GetComponent<KiSystem>()) gameObject.AddComponent<KiSystem>();
            KiSys = GetComponent<KiSystem>();

            if (!GetComponent<MultipliersAndStuffs>()) gameObject.AddComponent<MultipliersAndStuffs>();
            Multipliers = GetComponent<MultipliersAndStuffs>();

            if (Damage == 0f) Damage = (CombatPowerController.AttackHealth(GetComponent<PersonBehaviour>()) / Multipliers.FinalMultiplier) / 8f;

            foreach (var limb in GetComponent<PersonBehaviour>().Limbs)
            {
                if (MCP_Utils.LimbCanUsePowers(limb) && limb.name.Contains("LowerArm"))
                {
                    limb.gameObject.AddComponent<UseEventTrigger>().Action = () =>
                    {
                        if (!KiHandLoadout.LegacyAllowed(limb, "MeteorExplosion")) return;
                        if (!limb.Person.IsAlive() || limb.Health <= 0f || Active == false || Firing == true || KiSys.currentKi < KiSys.maxKi * (CostPercent * 4f)) return;

                        var hit = Physics2D.Raycast(limb.transform.position, -limb.transform.up, 50f);

                        if (hit.transform == null || hit.transform.root.gameObject == gameObject || !hit.transform.root.gameObject.GetComponent<PersonBehaviour>() || hit.transform.gameObject.layer == 11 || hit.transform.gameObject.layer == 13) return;

                        Target = hit.transform.gameObject;

                        StartCoroutine(Fire(limb.transform));
                    };
                }
            }
        }

        private IEnumerator Fire(Transform Arm)
        {
            Firing = true;

            Vector3 TargetPosition = (Target.gameObject.GetComponent<LimbBehaviour>().Person.Limbs.Length >= 3) ? Target.gameObject.GetComponent<LimbBehaviour>().Person.Limbs[2].transform.position : MCP_Utils.GetMiddlePositionOfBody(Target.GetComponent<LimbBehaviour>().Person);

            Vector2 contactPoint = Physics2D.Raycast(TargetPosition, -Vector2.up, 1000f, LayerMask.GetMask("Bounds")).point;

            foreach (var limb in Target.GetComponent<LimbBehaviour>().Person.Limbs) limb.gameObject.AddComponent<FreezeBehaviour>();

            foreach (var limb in GetComponent<PersonBehaviour>().Limbs) limb.gameObject.AddComponent<FreezeBehaviour>();

            CostPercent = 0.2f;
            StartCoroutine(KiCost());

            RealDamage = (Damage * Multipliers.FinalMultiplier) * Multipliers.KiOutput * DamageOutput;

            AudioSource audioSource2 = new GameObject("AttackSource").AddComponent<AudioSource>();
            audioSource2.transform.SetParent(transform.Find("Head"), true);
            audioSource2.transform.position = TargetPosition;
            Global global = FindObjectOfType<Global>();
            global.AddAudioSource(audioSource2, false);
            audioSource2.gameObject.AddComponent<AudioDistortionFilter>().distortionLevel = 0.8f;
            audioSource2.outputAudioMixerGroup = global.SoundEffects;
            audioSource2.spatialBlend = 0.95f;
            audioSource2.volume = 1;
            audioSource2.maxDistance = 1000;

            if (DBPU.VoiceLines == true)
            {
                audioSource.PlayOneShot(DBPU.Voice_Gogeta_MeteorExplosion);
                audioSource2.PlayOneShot(DBPU.Attack_MeteorExplosion_Fire_Extended);

                yield return new WaitForSeconds(3.2f);

                GameObject Effect1 = GameObject.Instantiate(DBPU.MeteorExplosion_WindArea, contactPoint, Quaternion.identity);
                Effect1.layer = 9;
                Effect1.AddComponent<DestroyOverTime>().Timer = 5.7f;
            }

            else
            {
                GameObject Effect1 = GameObject.Instantiate(DBPU.MeteorExplosion_WindArea, contactPoint, Quaternion.identity);
                Effect1.layer = 9;
                Effect1.AddComponent<DestroyOverTime>().Timer = 5.7f;

                yield return new WaitForSeconds(0.15f);

                audioSource2.PlayOneShot(DBPU.Attack_MeteorExplosion_Fire);
            }

            GameObject Effect2 = GameObject.Instantiate(DBPU.MeteorExplosion_AuraDrag, TargetPosition, Quaternion.identity);
            Effect2.transform.localScale = new Vector3(1f, 1f, 1f);
            Effect2.layer = 9;
            //GetAllChildrenRecursive(Effect2.transform);
            Effect2.AddComponent<DestroyOverTime>().Timer = 3.8f;

            yield return new WaitForSeconds(1.1f);

            GameObject Effect3 = GameObject.Instantiate(DBPU.MeteorExplosion_LightBeams, TargetPosition, Quaternion.identity);
            Effect3.layer = 9;
            GetAllChildrenRecursive(Effect3.transform);
            Effect3.AddComponent<DestroyOverTime>().Timer = 3.2f;

            yield return new WaitForSeconds(2f);

            StopAllParticleSystems(Effect2.transform);

            yield return new WaitForSeconds(0.8f);

            GameObject Effect4 = GameObject.Instantiate(DBPU.MeteorExplosion_EnergyPillar, contactPoint, Quaternion.identity);
            Effect4.layer = 9;
            GetAllChildrenRecursive(Effect4.transform);
            Effect4.AddComponent<DestroyOverTime>().Timer = 1.9f;

            yield return new WaitForSeconds(1.7f);

            GameObject Effect5 = GameObject.Instantiate(DBPU.MeteorExplosion_GiganticExplosion, contactPoint, Quaternion.identity);
            Effect5.transform.localScale = new Vector3(20f, 20f, 20f);
            Effect5.layer = 9;
            GetAllChildrenRecursive(Effect5.transform);
            Effect5.AddComponent<DestroyOverTime>().Timer = 8f;

            foreach (Transform child in Effect5.transform)
            {
                var ps = child.gameObject.GetComponent<ParticleSystem>();
                ps.playbackSpeed *= 10f;
            }

            yield return new WaitForSeconds(0.2f);

            foreach (Transform child in Effect5.transform)
            {
                var ps = child.gameObject.GetComponent<ParticleSystem>();
                ps.playbackSpeed /= 10f;
            }

            foreach (var limb in Target.GetComponent<LimbBehaviour>().Person.Limbs)
            {
                limb.Health -= Mathf.Clamp(RealDamage, 0, limb.Health);
                Destroy(limb.gameObject.GetComponent<FreezeBehaviour>());
            }

            foreach (var limb in GetComponent<PersonBehaviour>().Limbs) Destroy(limb.gameObject.GetComponent<FreezeBehaviour>());

            yield return new WaitForSeconds(5f);

            Destroy(audioSource2.gameObject);

            Firing = false;

            yield return null;
        }

        private IEnumerator KiCost()
        {
            if (DBPU.KiAttackCostMultiplier == 0f) yield break;

            float OGKiDrain = KiSys.currentKiDrainRate;
            float KiRegen = KiSys.baseRegen;

            if (OGKiDrain != 0f) KiSys.baseRegen = 0f;

            float FinalKi = KiSys.currentKi - (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier));
            float CurrentKi = KiSys.currentKi;

            while (CurrentKi > FinalKi)
            {
                KiSys.currentKi -= (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier)) * (Time.deltaTime);
                CurrentKi -= (KiSys.maxKi * (CostPercent * DBPU.KiAttackCostMultiplier)) * (Time.deltaTime);

                yield return new WaitForEndOfFrame();
            }

            if (OGKiDrain != 0f) KiSys.baseRegen = KiRegen;

            yield return null;
        }

        void StopAllParticleSystems(Transform parent)
        {
            foreach (Transform child in parent)
            {
                GetAllChildrenRecursive(child);

                var ps = child.gameObject.GetComponent<ParticleSystem>();
                ps.Stop();
            }
        }

        void ChangePlayBackOfAllParticleSystems(Transform parent, float speed)
        {
            foreach (Transform child in parent)
            {
                var ps = child.gameObject.GetComponent<ParticleSystem>();
                ps.playbackSpeed *= speed;
            }
        }

        void GetAllChildrenRecursive(Transform parent)
        {
            foreach (Transform child in parent)
            {
                child.position = new Vector3(child.position.x, child.position.y, 0f);
                var sp = child.gameObject.GetComponent<Renderer>();
                sp.sortingLayerName = "Bubbles";
                sp.sortingOrder += 100;

                GetAllChildrenRecursive(child);
            }
        }
    }

