    public class SenzuBeanBagBehaviour : MonoBehaviour
    {
        public bool Open = false;

        public void Use()
        {
            if (Open)
            {
                GameObject Senzu = GameObject.Instantiate(ModAPI.FindSpawnable("[DBPU] Senzu Bean").Prefab, transform.position + (transform.up * 0.2f), Quaternion.identity);
                CatalogBehaviour.PerformMod(ModAPI.FindSpawnable("[DBPU] Senzu Bean"), Senzu);
                Senzu.gameObject.GetComponent<PhysicalBehaviour>().SpawnSpawnParticles = false;
            }
        }
    }

    public class SenzuBeanBehaviour : MonoBehaviour
    {
        public void OnCollisionEnter2D(Collision2D other)
        {
            ContactPoint2D[] contacts = other.contacts;
            var averageImpact = Utils.GetAverageImpulse(contacts, contacts.Length);

            if (averageImpact > 0.01f)
            {
                if (other.gameObject.GetComponent<LimbBehaviour>())
                {
                    if (other.gameObject.GetComponent<LimbBehaviour>().name == "Head" && other.transform.root.GetComponent<PersonBehaviour>().IsAlive() && other.gameObject.GetComponent<LimbBehaviour>().Health > 0)
                    {
                        foreach (var limb in other.transform.root.GetComponent<PersonBehaviour>().Limbs)
                        {
                            limb.gameObject.AddComponent<SenzuBeanRegen>();
                        }

                        if (other.transform.root.GetComponent<KiSystem>())
                        {
                            other.transform.root.GetComponent<KiSystem>().currentKi = other.transform.root.GetComponent<KiSystem>().maxKi;
                            other.transform.root.GetComponent<KiSystem>().Strain = 0f;
                        }

                        other.gameObject.GetComponent<PhysicalBehaviour>().PlayClipOnce(DBPU.SenzuBeanEatingSounds[UnityEngine.Random.Range(0, 3)]);

                        Destroy(gameObject);
                    }
                }
            }
        }

        public class SenzuBeanRegen : MonoBehaviour
        {
            public LimbBehaviour limb;

            public void Start()
            {
                limb = GetComponent<LimbBehaviour>();
                StartCoroutine(waitheal());

                if (limb.IsDismembered == false)
                {
                    limb.Health = limb.InitialHealth;
                    limb.CirculationBehaviour.HealBleeding();
                    limb.HealBone();
                    limb.LungsPunctured = false;
                    limb.Numbness = 0f;
                    limb.CirculationBehaviour.StabWoundCount = 0;
                    limb.CirculationBehaviour.GunshotWoundCount = 0;
                    limb.BruiseCount = 0;
                    limb.CirculationBehaviour.BloodAmount = 1f;
                    limb.Person.PainLevel = 0f;
                    limb.Person.ShockLevel = 0f;
                    limb.Person.Consciousness = 1f;
                    limb.Person.OxygenLevel = 1f;
                    limb.Person.AdrenalineLevel = 0f;
                    limb.Person.BrainDamaged = false;
                    limb.PhysicalBehaviour.Temperature = 29f;
                    limb.InternalTemperature = 37f;
                    if (limb.CirculationBehaviour.WasInitiallyPumping == true) limb.CirculationBehaviour.IsPump = true;

                    limb.SkinMaterialHandler.Sync();
                }
            }

            private IEnumerator waitheal()
            {
                yield return new WaitForSeconds(2.5f);

                Destroy(gameObject.GetComponent<SenzuBeanRegen>());
            }

            public void FixedUpdate()
            {
                if (limb.IsDismembered == false)
                {
                    if (limb.PhysicalBehaviour.BurnProgress > 0f)
                    {
                        limb.PhysicalBehaviour.BurnProgress -= Time.deltaTime * 1f;
                    }

                    else
                    {
                        limb.PhysicalBehaviour.BurnProgress = 0f;
                    }

                    if (limb.SkinMaterialHandler.AcidProgress > 0f)
                    {
                        limb.SkinMaterialHandler.AcidProgress -= Time.deltaTime * 1f;
                    }

                    else
                    {
                        limb.SkinMaterialHandler.AcidProgress = 0f;
                    }

                    if (limb.SkinMaterialHandler.RottenProgress > 0f)
                    {
                        limb.SkinMaterialHandler.RottenProgress -= Time.deltaTime * 1f;
                    }

                    else
                    {
                        limb.SkinMaterialHandler.RottenProgress = 0f;
                    }

                    if (limb.SkinMaterialHandler.damagePoints.Max<Vector4>((Func<Vector4, float>)(c => c.z)) < 50.0)
                    {
                        for (int i = 0; i < limb.SkinMaterialHandler.damagePoints.Length; i++)
                        {
                            Vector4[] damagePoints = limb.SkinMaterialHandler.damagePoints;
                            int num = i;
                            damagePoints[num].z = damagePoints[num].z - Time.deltaTime * 6f;
                        }

                        limb.SkinMaterialHandler.Sync();
                    }
                }
            }
        }
    }

    public class ExponentialGrowth : MonoBehaviour
    {
        private MultipliersAndStuffs Multipliers;
        private KiSystem KiSys;
        private TransformationContextMenu Transformation;
        private PersonBehaviour person;

        public float Limit = 7000f;

        public float Health = 1f;

        public void OnDestroy()
        {
            if (Multipliers != null) Multipliers.ExponentialMultiplier = 1f;

            if (person == null) person = GetComponent<PersonBehaviour>();
            if (person == null) return;

            foreach (var limb in person.Limbs)
            {
                limb.InitialHealth /= Health;
                limb.Health /= Health;
            }

            person.ChangeWeightBasedOnHealth();
        }

        public void Kickstart()
        {
            if (person == null) person = GetComponent<PersonBehaviour>();
            if (Multipliers == null)
            {
                if (!transform.root.GetComponent<MultipliersAndStuffs>()) transform.root.gameObject.AddComponent<MultipliersAndStuffs>();
                Multipliers = transform.root.GetComponent<MultipliersAndStuffs>();
            }

            if (Transformation == null)
            {
                var head = transform.Find("Head");
                if (head != null) Transformation = head.GetComponent<TransformationContextMenu>();
            }

            StopAllCoroutines();
            StartCoroutine(Evolve());
        }

        public void Start()
        {
            if (!GetComponent<KiSystem>()) gameObject.AddComponent<KiSystem>();
            KiSys = GetComponent<KiSystem>();

            if (!transform.root.GetComponent<MultipliersAndStuffs>()) transform.root.gameObject.AddComponent<MultipliersAndStuffs>();
            Multipliers = transform.root.GetComponent<MultipliersAndStuffs>();

            person = GetComponent<PersonBehaviour>();

            var head = transform.Find("Head");
            if (head != null) Transformation = head.GetComponent<TransformationContextMenu>();
        }

        public IEnumerator Evolve()
        {
            if (Transformation == null || Multipliers == null || person == null) yield break;

            string PreviousForm = Transformation.Form;

            while (true)
            {
                if (Transformation.Form == "Ikari") Limit = 7000f;
                else if (Transformation.Form == "SSJ1") Limit = 800000f;
                else if (Transformation.Form == "FPSSJ") Limit = 1000000000f;

                while (Multipliers.ExponentialMultiplier < Limit)
                {
                    if (Transformation.Form == "Ikari") Limit = 7000f;
                    else if (Transformation.Form == "SSJ1") Limit = 800000f;
                    else if (Transformation.Form == "FPSSJ") Limit = 1000000000f;

                    yield return new WaitForSecondsRealtime(0.1f);

                    if (Multipliers.ExponentialMultiplier * DBPU.Special_ExponentialGrowthSpeed < Limit)
                    {
                        foreach (var limb in person.Limbs)
                        {
                            if (!float.IsInfinity(limb.InitialHealth * DBPU.Special_ExponentialGrowthSpeed)) limb.InitialHealth *= DBPU.Special_ExponentialGrowthSpeed;
                            if (!float.IsInfinity(limb.Health * DBPU.Special_ExponentialGrowthSpeed)) limb.Health *= DBPU.Special_ExponentialGrowthSpeed;
                        }

                        Health *= DBPU.Special_ExponentialGrowthSpeed;
                        Multipliers.ExponentialMultiplier *= DBPU.Special_ExponentialGrowthSpeed;
                    }

                    else
                    {
                        foreach (var limb in person.Limbs)
                        {
                            if (!float.IsInfinity(limb.InitialHealth * DBPU.Special_ExponentialGrowthSpeed)) limb.InitialHealth *= Limit / Multipliers.ExponentialMultiplier;
                            if (!float.IsInfinity(limb.Health * DBPU.Special_ExponentialGrowthSpeed)) limb.Health *= Limit / Multipliers.ExponentialMultiplier;
                        }

                        Health *= Limit / Multipliers.ExponentialMultiplier;
                        Multipliers.ExponentialMultiplier *= Limit / Multipliers.ExponentialMultiplier;
                    }

                    person.ChangeWeightBasedOnHealth();
                }

                yield return new WaitUntil(() => Transformation.Form != PreviousForm);
                PreviousForm = Transformation.Form;
            }
        }
    }

    public class OozaruFormBehaviour : MonoBehaviour
    {
        struct JointState
        {
            public bool HadJoint;
            public Vector2 Anchor;
            public Vector2 ConnectedAnchor;
            public bool AutoConfigureConnectedAnchor;
            public bool UseLimits;
            public float MinLimit;
            public float MaxLimit;
            public Rigidbody2D ConnectedBody;
            public float Drag;
            public float AngularDrag;
        }

        struct LimbState
        {
            public Vector3 Scale;
            public float TrueInitialMass;
            public float Health;
            public float InitialHealth;
            public float BreakingThreshold;
            public float BaseStrength;
            public float ImpactDamageMultiplier;
            public float ImpactPainMultiplier;
            public float GForcePassoutThreshold;
            public float ShotDamageMultiplier;
            public float FreezingTemperature;
            public float DiscomfortingHeatTemperature;
            public bool IsAndroid;
            public PhysicalProperties Properties;
            public Sprite Sprite;
            public Texture FleshTex;
            public Texture BoneTex;
            public bool ShouldRecolourWhenCold;
        }

        PersonBehaviour person;
        JointState[] jointStates;
        LimbState[] limbStates;
        bool[] hairEnabled;
        float previousFormMultiplier;
        float previousHeightMeters = 1.64f;
        bool applied;

        void OnEnable()
        {
            ApplyOozaru();
        }

        void Start()
        {
            ApplyOozaru();
        }

        void ApplyOozaru()
        {
            if (applied) return;
            person = GetComponent<PersonBehaviour>();
            if (person == null) person = GetComponentInParent<PersonBehaviour>();
            if (person == null || person.Limbs == null || person.Limbs.Length < 14) return;

            CacheState();

            GameObject sizeLimb = null;
            if (person.Limbs.Length > 2 && person.Limbs[2] != null)
                sizeLimb = person.Limbs[2].gameObject;
            previousHeightMeters = Mathf.Abs(person.transform.localScale.y) * 1.68f;
            if (sizeLimb != null)
                person.transform.root.SetHeight(person, sizeLimb, 1.68f);

            DBPU.ApplyFullOozaruBodySetup(person, person.transform.root.gameObject);

            var multipliers = person.GetComponent<MultipliersAndStuffs>();
            if (multipliers == null) multipliers = person.transform.root.GetComponent<MultipliersAndStuffs>();
            if (multipliers != null)
            {
                previousFormMultiplier = multipliers.FormMultiplier;
                multipliers.FormMultiplier = 25000f;
            }

            Transform head = person.transform.Find("Head");
            if (head != null)
                DBPU.ApplyGohanImmunities(head, person);

            applied = true;
        }

        void CacheState()
        {
            int n = person.Limbs.Length;
            jointStates = new JointState[n];
            limbStates = new LimbState[n];

            for (int i = 0; i < n; i++)
            {
                LimbBehaviour limb = person.Limbs[i];
                if (limb == null) continue;

                var ls = new LimbState
                {
                    Scale = limb.transform.localScale,
                    Health = limb.Health,
                    InitialHealth = limb.InitialHealth,
                    BreakingThreshold = limb.BreakingThreshold,
                    BaseStrength = limb.BaseStrength,
                    ImpactDamageMultiplier = limb.ImpactDamageMultiplier,
                    ImpactPainMultiplier = limb.ImpactPainMultiplier,
                    GForcePassoutThreshold = limb.GForcePassoutThreshold,
                    ShotDamageMultiplier = limb.ShotDamageMultiplier,
                    FreezingTemperature = limb.FreezingTemperature,
                    DiscomfortingHeatTemperature = limb.DiscomfortingHeatTemperature,
                    IsAndroid = limb.IsAndroid
                };

                PhysicalBehaviour phys = limb.GetComponent<PhysicalBehaviour>();
                if (phys != null)
                {
                    ls.TrueInitialMass = phys.TrueInitialMass;
                    ls.Properties = phys.Properties;
                }

                var renderer = limb.GetComponent<SpriteRenderer>();
                if (renderer != null)
                {
                    ls.Sprite = renderer.sprite;
                    if (renderer.material != null)
                    {
                        ls.FleshTex = renderer.material.GetTexture("_FleshTex");
                        ls.BoneTex = renderer.material.GetTexture("_BoneTex");
                    }
                }
                if (limb.SkinMaterialHandler != null)
                    ls.ShouldRecolourWhenCold = limb.SkinMaterialHandler.ShouldRecolourWhenCold;
                limbStates[i] = ls;

                HingeJoint2D joint = limb.GetComponent<HingeJoint2D>();
                var state = new JointState();
                if (joint != null)
                {
                    state.HadJoint = true;
                    state.Anchor = joint.anchor;
                    state.ConnectedAnchor = joint.connectedAnchor;
                    state.AutoConfigureConnectedAnchor = joint.autoConfigureConnectedAnchor;
                    state.UseLimits = joint.useLimits;
                    state.MinLimit = joint.limits.min;
                    state.MaxLimit = joint.limits.max;
                    state.ConnectedBody = joint.connectedBody;
                }
                Rigidbody2D rb = limb.GetComponent<Rigidbody2D>();
                if (rb != null)
                {
                    state.Drag = rb.drag;
                    state.AngularDrag = rb.angularDrag;
                }
                jointStates[i] = state;
            }

            Transform head = person.transform.Find("Head");
            if (head != null)
            {
                var renderers = head.GetComponentsInChildren<SpriteRenderer>(true);
                hairEnabled = new bool[renderers.Length];
                for (int i = 0; i < renderers.Length; i++)
                {
                    bool isHair = renderers[i] != null && renderers[i].gameObject != null
                        && renderers[i].gameObject.name.IndexOf("Hair", StringComparison.OrdinalIgnoreCase) >= 0;
                    hairEnabled[i] = isHair && renderers[i].enabled;
                }
            }

            var multipliers = person.GetComponent<MultipliersAndStuffs>();
            if (multipliers == null) multipliers = person.transform.root.GetComponent<MultipliersAndStuffs>();
            if (multipliers != null)
                previousFormMultiplier = multipliers.FormMultiplier;
        }

        void SetHairVisible(bool visible)
        {
            Transform head = person != null ? person.transform.Find("Head") : null;
            if (head == null) return;
            var renderers = head.GetComponentsInChildren<SpriteRenderer>(true);
            for (int i = 0; i < renderers.Length; i++)
            {
                var sr = renderers[i];
                if (sr == null || sr.gameObject == null) continue;
                if (sr.gameObject.name.IndexOf("Hair", StringComparison.OrdinalIgnoreCase) < 0) continue;
                bool restore = visible && hairEnabled != null && i < hairEnabled.Length && hairEnabled[i];
                sr.enabled = restore;
                if (!visible) sr.enabled = false;
            }
        }

        void OnDestroy()
        {
            if (!applied || person == null || person.Limbs == null) return;
            try
            {
                RestoreState();
            }
            catch { }
        }

        void RestoreState()
        {
            if (jointStates == null || limbStates == null) return;
            int n = Mathf.Min(person.Limbs.Length, jointStates.Length);
            for (int i = 0; i < n; i++)
            {
                LimbBehaviour limb = person.Limbs[i];
                if (limb == null) continue;
                LimbState ls = limbStates[i];

                limb.transform.localScale = ls.Scale;
                limb.gameObject.FixColliders();
                limb.IsAndroid = ls.IsAndroid;
                limb.Health = ls.Health;
                limb.InitialHealth = ls.InitialHealth;
                limb.BreakingThreshold = ls.BreakingThreshold;
                limb.BaseStrength = ls.BaseStrength;
                limb.ImpactDamageMultiplier = ls.ImpactDamageMultiplier;
                limb.ImpactPainMultiplier = ls.ImpactPainMultiplier;
                limb.GForcePassoutThreshold = ls.GForcePassoutThreshold;
                limb.ShotDamageMultiplier = ls.ShotDamageMultiplier;
                limb.FreezingTemperature = ls.FreezingTemperature;
                limb.DiscomfortingHeatTemperature = ls.DiscomfortingHeatTemperature;
                if (limb.SkinMaterialHandler != null)
                    limb.SkinMaterialHandler.ShouldRecolourWhenCold = ls.ShouldRecolourWhenCold;

                PhysicalBehaviour phys = limb.GetComponent<PhysicalBehaviour>();
                if (phys != null)
                {
                    if (ls.TrueInitialMass > 0f)
                    {
                        phys.TrueInitialMass = ls.TrueInitialMass;
                        phys.RecalculateMassBasedOnSize();
                    }
                    if (ls.Properties != null)
                        phys.Properties = ls.Properties;
                }

                JointState state = jointStates[i];
                HingeJoint2D joint = limb.GetComponent<HingeJoint2D>();
                if (state.HadJoint)
                {
                    if (joint == null) joint = limb.gameObject.AddComponent<HingeJoint2D>();
                    joint.anchor = state.Anchor;
                    joint.connectedAnchor = state.ConnectedAnchor;
                    joint.autoConfigureConnectedAnchor = state.AutoConfigureConnectedAnchor;
                    joint.useLimits = state.UseLimits;
                    if (state.UseLimits)
                        joint.limits = new JointAngleLimits2D { min = state.MinLimit, max = state.MaxLimit };
                    if (state.ConnectedBody != null)
                        joint.connectedBody = state.ConnectedBody;
                }
                else if (joint != null)
                {
                    UnityEngine.Object.Destroy(joint);
                }

                Rigidbody2D rb = limb.GetComponent<Rigidbody2D>();
                if (rb != null)
                {
                    rb.drag = state.Drag;
                    rb.angularDrag = state.AngularDrag;
                }
            }

            var multipliers = person.GetComponent<MultipliersAndStuffs>();
            if (multipliers == null) multipliers = person.transform.root.GetComponent<MultipliersAndStuffs>();
            if (multipliers != null && previousFormMultiplier > 0f)
                multipliers.FormMultiplier = previousFormMultiplier;

            SetHairVisible(true);

            GameObject sizeLimb = null;
            if (person.Limbs != null && person.Limbs.Length > 2 && person.Limbs[2] != null)
                sizeLimb = person.Limbs[2].gameObject;
            if (sizeLimb != null && previousHeightMeters > 0.01f)
                person.transform.root.SetHeight(person, sizeLimb, previousHeightMeters);

            DBPU.BakeOozaruStandingPoses(person);
        }
    }

    public class PersonLimbLayout : MonoBehaviour
    {
        private PersonBehaviour person;
        private float defaultHeadScale;
        private readonly Dictionary<string, Vector3> defaultPositions = new Dictionary<string, Vector3>();
        private readonly Dictionary<string, Vector2> defaultAnchors = new Dictionary<string, Vector2>();
        private bool cached;

        public bool CustomLayoutActive { get; private set; }

        private static readonly string[] PositionKeys =
        {
            "Head", "Upper", "Middle", "Lower",
            "UArmF", "UArmB", "LArmF", "LArmB",
            "ULegF", "ULegB", "LLegF", "LLegB",
            "FootF", "FootB"
        };

        private static readonly string[] AnchorKeys =
        {
            "Head", "Upper", "Middle", "Lower",
            "UArmF", "UArmB", "LArmF", "LArmB",
            "ULegF", "ULegB", "LLegF", "LLegB",
            "FootF", "FootB"
        };

        private void Awake()
        {
            person = GetComponent<PersonBehaviour>();
        }

        public void Apply(CharacterTransformations.Transformations.LimbLayoutData layout)
        {
            EnsureCached();
            if (layout == null)
            {
                Restore();
                return;
            }

            float bodyScale = Mathf.Abs(person.transform.localScale.x);
            if (layout.HeadScale > 0f)
            {
                Transform head = person.transform.Find("Head");
                if (head != null) head.localScale = Vector3.one * (layout.HeadScale / bodyScale);
            }

            if (layout.Positions != null)
            {
                foreach (var kvp in layout.Positions)
                    SetLocalPosition(kvp.Key, kvp.Value);
            }

            if (layout.Anchors != null)
            {
                foreach (var kvp in layout.Anchors)
                    SetJointAnchor(kvp.Key, kvp.Value);
            }

            person.SyncLimbsPhysics();
            person.ForceAllLimbsClearViaExit();
            CustomLayoutActive = true;
        }

        public void Restore()
        {
            EnsureCached();

            Transform head = person.transform.Find("Head");
            if (head != null) head.localScale = Vector3.one * defaultHeadScale;

            foreach (var kvp in defaultPositions)
                SetLocalPosition(kvp.Key, kvp.Value);

            foreach (var kvp in defaultAnchors)
                SetJointAnchor(kvp.Key, kvp.Value);

            person.SyncLimbsPhysics();
            person.ForceAllLimbsClearViaExit();
            CustomLayoutActive = false;
        }

        private void EnsureCached()
        {
            if (cached) return;

            Transform head = person.transform.Find("Head");
            if (head != null) defaultHeadScale = head.localScale.x;

            foreach (string key in PositionKeys)
            {
                Transform limb = GetLimb(key);
                if (limb != null) defaultPositions[key] = limb.localPosition;
            }

            foreach (string key in AnchorKeys)
            {
                Transform limb = GetLimb(key);
                if (limb == null) continue;
                HingeJoint2D joint = limb.GetComponent<HingeJoint2D>();
                if (joint != null) defaultAnchors[key] = joint.anchor;
            }

            cached = true;
        }

        private Transform GetLimb(string key)
        {
            Transform root = person.transform;
            switch (key)
            {
                case "Head": return root.Find("Head");
                case "Upper": return root.Find("Body/UpperBody");
                case "Middle": return root.Find("Body/MiddleBody");
                case "Lower": return root.Find("Body/LowerBody");
                case "UArmF": return root.Find("FrontArm/UpperArmFront");
                case "UArmB": return root.Find("BackArm/UpperArm");
                case "LArmF": return root.Find("FrontArm/LowerArmFront");
                case "LArmB": return root.Find("BackArm/LowerArm");
                case "ULegF": return root.Find("FrontLeg/UpperLegFront");
                case "ULegB": return root.Find("BackLeg/UpperLeg");
                case "LLegF": return root.Find("FrontLeg/LowerLegFront");
                case "LLegB": return root.Find("BackLeg/LowerLeg");
                case "FootF": return root.Find("FrontLeg/FootFront");
                case "FootB": return root.Find("BackLeg/Foot");
                default: return null;
            }
        }

        private void SetLocalPosition(string key, Vector3 position)
        {
            Transform limb = GetLimb(key);
            if (limb != null) limb.localPosition = position;
        }

        private void SetJointAnchor(string key, Vector2 anchor)
        {
            Transform limb = GetLimb(key);
            if (limb == null) return;
            HingeJoint2D joint = limb.GetComponent<HingeJoint2D>();
            if (joint != null) joint.anchor = anchor;
        }
    }

