    public class AuraOutlineController : MonoBehaviour
    {
        public string AuraLayerName = "TransparentFX";
        public static Material softEdgeMaterial;
        public float sigma = 40.0f;
        public int downsample = 2;

        private RenderTexture SourceRT;
        private RenderTexture temp1;
        private RenderTexture temp2;
        private Camera captureCam;
        private Camera sourceCamera;
        private int captureLayer;

        public static AuraOutlineController main;
        public static Material FlameMat;

        void Awake()
        {
            int width = Screen.width / downsample;
            int height = Screen.height / downsample;
            SourceRT = new RenderTexture(width, height, 0, RenderTextureFormat.ARGBFloat);
            temp1 = new RenderTexture(width, height, 0, RenderTextureFormat.ARGBFloat);
            temp2 = new RenderTexture(width, height, 0, RenderTextureFormat.ARGBFloat);

            captureLayer = LayerMask.NameToLayer(AuraLayerName);

            sourceCamera = FindObjectOfType<Camera>();
            GameObject camGO = new GameObject("CaptureCam");
            captureCam = camGO.AddComponent<Camera>();

            captureCam.clearFlags = CameraClearFlags.SolidColor;
            captureCam.backgroundColor = new Color(0, 0, 0, 0);
            captureCam.transform.localEulerAngles = new Vector3(180f, 0f, 0f);
            captureCam.orthographic = true;
            captureCam.orthographicSize = 5f;
            captureCam.nearClipPlane = -20;
            captureCam.farClipPlane = 1000;
            captureCam.cullingMask = 1 << captureLayer;
            captureCam.enabled = false;

            main = this;
        }

        void LateUpdate()
        {
            if (SourceRT == null || captureCam == null) return;

            captureCam.targetTexture = SourceRT;
            captureCam.transform.position = sourceCamera.transform.position;
            captureCam.orthographicSize = sourceCamera.orthographicSize;
            captureCam.Render();

            RenderTexture blurred = Blur(SourceRT, sigma);
            Shader.SetGlobalTexture("_AuraBlurRT", blurred);
        }

        public RenderTexture Blur(RenderTexture source, float sigma)
        {
            if (softEdgeMaterial == null) return source;

            softEdgeMaterial.SetFloat("_Sigma", sigma / captureCam.orthographicSize);
            softEdgeMaterial.SetVector("_Direction", new Vector2(1f, 0f));
            Graphics.Blit(source, temp1, softEdgeMaterial);
            softEdgeMaterial.SetVector("_Direction", new Vector2(0f, 1f));
            Graphics.Blit(temp1, temp2, softEdgeMaterial);

            return temp2;
        }

        void OnDestroy()
        {
            if (temp1) temp1.Release();
            if (temp2) temp2.Release();

            if (captureCam != null)
            {
                DestroyImmediate(captureCam.gameObject);
            }
        }
    }

    public class SetAuraBase : MonoBehaviour
    {
        public Material AuraOutlineMaterial;
        public bool isCustomSize;
        public Vector2 customSize = new Vector2(512, 512);
        SpriteRenderer originalSR;
        internal SpriteRenderer bgSR;
        internal SpriteRenderer cpSR;

        public float AuraBgScale = 2.5f;
        public float AuraStrength = 0f;
        protected float MaxAuraStrength = 0.7f;
        protected float DisplayAlpha = 1f;
        protected float CaptureAlpha = 1f;
        protected int AuraBgSortOrder = -1;
        internal bool ReadedData = false;
        public bool AuraOn = false;

        private void Awake()
        {
            SetMaterial();
        }

        void Start()
        {
            originalSR = GetComponent<SpriteRenderer>();
            if (originalSR == null || originalSR.sprite == null) return;
            if (AuraOutlineController.main == null || AuraOutlineController.FlameMat == null) return;

            Sprite originalSprite = originalSR.sprite;

            GameObject captureObj = new GameObject("CaptureSprite");
            captureObj.layer = LayerMask.NameToLayer(AuraOutlineController.main.AuraLayerName);
            captureObj.transform.SetParent(transform, false);

            cpSR = captureObj.AddComponent<SpriteRenderer>();
            cpSR.sprite = originalSprite;
            cpSR.material = originalSR.material;
            cpSR.sortingLayerName = "Bottom";
            cpSR.sortingOrder = -10;

            GameObject bgObj = new GameObject("BackgroundSprite");
            bgObj.transform.SetParent(transform, false);
            bgObj.transform.localScale = Vector2.one * AuraBgScale;

            bgSR = bgObj.AddComponent<SpriteRenderer>();
            bgSR.sprite = originalSprite;
            bgSR.material = AuraOutlineMaterial;
            bgSR.sortingLayerName = "Background";
            bgSR.sortingOrder = AuraBgSortOrder;

            if (!ReadedData)
            {
                ReadDataFromMaterial();
                ReadedData = true;
            }

            LateUpdate();
        }

        public void EnableAura()
        {
            if (originalSR.color == Color.clear) return;

            StopAllCoroutines();
            AuraOn = true;
            StartCoroutine(DoEnableAura());
        }

        public void DisableAura()
        {
            StopAllCoroutines();
            AuraOn = false;
            StartCoroutine(DoDisableAura());
        }

        public void SetAuraState(bool state)
        {
            AuraOn = state;
            if (!AuraOn) DisableAura();
            else EnableAura();
        }

        private IEnumerator DoEnableAura()
        {
            while (AuraOn == true && AuraStrength < MaxAuraStrength)
            {
                AuraStrength += 0.025f;
                yield return new WaitForSeconds(0.025f);
            }

            yield return null;
        }

        private IEnumerator DoDisableAura()
        {
            while (AuraOn == false && AuraStrength > 0f)
            {
                AuraStrength -= 0.025f;
                yield return new WaitForSeconds(0.025f);
            }

            yield return null;
        }

        private void LateUpdate()
        {
            if (originalSR == null || cpSR == null || bgSR == null) return;

            AuraStrength = Mathf.Clamp(AuraStrength, 0f, MaxAuraStrength);
            float alpha = AuraStrength * DisplayAlpha;
            cpSR.color = new Color(1f, 1f, 1f, AuraStrength * CaptureAlpha);
            bgSR.color = new Color(1f, 1f, 1f, alpha);
            cpSR.sprite = originalSR.sprite;
            bgSR.sprite = originalSR.sprite;
            bgSR.material = AuraOutlineMaterial;
            bgSR.sortingLayerName = "Background";
            bgSR.sortingOrder = AuraBgSortOrder;
            cpSR.material = originalSR.material;

            MaterialPropertyBlock block = new MaterialPropertyBlock();
            originalSR.GetPropertyBlock(block);
            cpSR.SetPropertyBlock(block);

            SetDataToMaterial();
        }

        public virtual void SetMaterial()
        {
        }

        public virtual void ReadDataFromMaterial()
        {
        }

        public virtual void SetDataToMaterial()
        {
        }

        void OnDestroy()
        {
            if (bgSR != null) Destroy(bgSR.gameObject);
            if (cpSR != null) Destroy(cpSR.gameObject);
        }
    }

    public class FlameAura : SetAuraBase
    {
        public float Tile = 25.0f;
        public Color Tint = Color.yellow;
        public float OutlinePower = 0.15f;
        public float OutlineStrength = 1.15f;
        public float FlameSpeed = 1.5f;
        public float VerticleSpeed = 2.5f;
        public float EvolveSpeed = 1.5f;
        public float MaskThreshold = 0.5f;

        public override void SetMaterial()
        {
            AuraOutlineMaterial = AuraOutlineController.FlameMat;
        }

        public override void ReadDataFromMaterial()
        {
            ReadedData = true;

            if (AuraOutlineMaterial == null) return;

            Tile = AuraOutlineMaterial.GetFloat("_Tile");
            Tint = AuraOutlineMaterial.GetColor("_Tint");
            OutlinePower = AuraOutlineMaterial.GetFloat("_OutlinePower");
            OutlineStrength = AuraOutlineMaterial.GetFloat("_OutlineStrength");
            FlameSpeed = AuraOutlineMaterial.GetFloat("_FlameSpeed");
            VerticleSpeed = AuraOutlineMaterial.GetFloat("_VerticleSpeed");
            EvolveSpeed = AuraOutlineMaterial.GetFloat("_EvolveSpeed");
            MaskThreshold = AuraOutlineMaterial.GetFloat("_MaskThreshold");
        }

        public override void SetDataToMaterial()
        {
            if (!ReadedData) ReadDataFromMaterial();
            if (bgSR == null) return;

            MaterialPropertyBlock block = new MaterialPropertyBlock();
            bgSR.GetPropertyBlock(block);

            block.SetFloat("_Tile", Tile);
            block.SetColor("_Tint", Tint);
            block.SetFloat("_OutlinePower", OutlinePower);
            block.SetFloat("_OutlineStrength", OutlineStrength);
            block.SetFloat("_FlameSpeed", FlameSpeed);
            block.SetFloat("_VerticleSpeed", VerticleSpeed);
            block.SetFloat("_EvolveSpeed", EvolveSpeed);
            block.SetFloat("_MaskThreshold", MaskThreshold);

            bgSR.SetPropertyBlock(block);
        }
    }

